    def _ensure_message_metadata_table(self) -> None:
        """Ensure the message_metadata table exists for the active backend."""
        if self.backend_type == BackendType.SQLITE:
            self.execute_query(
                """
                CREATE TABLE IF NOT EXISTS message_metadata(
                  message_id TEXT PRIMARY KEY REFERENCES messages(id) ON DELETE CASCADE,
                  tool_calls_json TEXT,
                  extra_json TEXT,
                  last_modified DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
                )
                """,
                script=False,
                commit=True,
            )
            return

        if self.backend_type == BackendType.POSTGRESQL:
            self.backend.execute(
                """
                CREATE TABLE IF NOT EXISTS message_metadata(
                  message_id TEXT PRIMARY KEY REFERENCES messages(id) ON DELETE CASCADE,
                  tool_calls_json TEXT,
                  extra_json TEXT,
                  last_modified TIMESTAMP NOT NULL DEFAULT NOW()
                )
                """
            )
            return

        raise NotImplementedError(
            f"message_metadata table creation not supported for backend {self.backend_type.value}"
        )

    # Message metadata CRUD methods are delegated to MessageStore at module bottom.

    # Persona state CRUD/analytics methods are delegated to PersonaStateStore at module bottom.

    def _convert_sqlite_schema_to_postgres_statements(self, sql: str) -> list[str]:
        """Convert SQLite schema SQL into individual Postgres-compatible statements."""

        filtered_lines: list[str] = []
        in_block_comment = False
        skip_until_semicolon = False
        trigger_buffer: list[str] | None = None

        for raw_line in sql.splitlines():
            stripped = raw_line.strip()

            if not stripped:
                continue

            if trigger_buffer is not None:
                trigger_buffer.append(raw_line)
                upper = stripped.upper()
                is_postgres_trigger = "EXECUTE FUNCTION" in upper and stripped.endswith(";")
                is_sqlite_trigger_end = upper.endswith("END;")
                if is_postgres_trigger or is_sqlite_trigger_end:
                    trigger_sql = "\n".join(trigger_buffer)
                    if "EXECUTE FUNCTION" in trigger_sql.upper():
                        filtered_lines.extend(trigger_buffer)
                    trigger_buffer = None
                continue

            if in_block_comment:
                if '*/' in stripped:
                    in_block_comment = False
                continue

            if stripped.startswith('/*'):
                if '*/' not in stripped:
                    in_block_comment = True
                continue

            if stripped.startswith('--'):
                continue

            upper = stripped.upper()

            if upper.startswith('PRAGMA'):
                continue

            if skip_until_semicolon:
                if stripped.endswith(';'):
                    skip_until_semicolon = False
                continue

            # SQLite FTS maintenance statements have no equivalent Postgres table.
            # Example: INSERT INTO notes_fts(notes_fts) VALUES('rebuild');
            if re.match(
                r"^INSERT\s+INTO\s+([A-Za-z_][A-Za-z0-9_]*)\s*\(\s*\1\s*\)\s*VALUES\s*\(\s*'rebuild'\s*\)\s*;?$",
                stripped,
                flags=re.IGNORECASE,
            ):
                continue

            if 'CREATE VIRTUAL TABLE' in upper:
                if not stripped.endswith(';'):
                    skip_until_semicolon = True
                continue

            if upper.startswith('DROP TRIGGER'):
                if " ON " in upper:
                    filtered_lines.append(raw_line)
                    continue
                if not stripped.endswith(';'):
                    skip_until_semicolon = True
                continue

            if upper.startswith('CREATE TRIGGER'):
                trigger_buffer = [raw_line]
                continue

            filtered_lines.append(raw_line)

        if trigger_buffer is not None:
            trigger_sql = "\n".join(trigger_buffer)
            if "EXECUTE FUNCTION" in trigger_sql.upper():
                filtered_lines.extend(trigger_buffer)

        statements: list[str] = []
        for statement in split_sql_statements("\n".join(filtered_lines)):
            transformed = self._transform_sqlite_schema_statement_for_postgres(statement)
            if transformed:
                statements.append(transformed)

        return statements

    # Message metadata extra / RAG helpers are delegated to MessageStore at module bottom.

    def get_conversation_citations(self, conversation_id: str) -> list[dict[str, Any]]:
        """
        Retrieve all citations from a conversation's messages.

        This aggregates all retrieved_documents from rag_context across
        all messages in a conversation, useful for export and citation
        bibliography generation.

        Returns:
            List of unique retrieved documents with their source message IDs
        """
        try:
            messages = self.get_messages_for_conversation(conversation_id, limit=1000)
            citations_by_id: dict[str, dict[str, Any]] = {}

            for msg in messages:
                msg_id = msg.get('id')
                if not msg_id:
                    continue

                rag_context = self.get_message_rag_context(msg_id)
                if not rag_context:
                    continue

                retrieved_docs = rag_context.get('retrieved_documents', [])
                for doc in retrieved_docs:
                    doc_id = doc.get('id') or doc.get('chunk_id') or f"anon_{len(citations_by_id)}"
                    if doc_id not in citations_by_id:
                        citations_by_id[doc_id] = {
                            **doc,
                            'message_ids': [msg_id],
                            'first_cited_at': msg.get('timestamp')
                        }
                    else:
                        if msg_id not in citations_by_id[doc_id]['message_ids']:
                            citations_by_id[doc_id]['message_ids'].append(msg_id)

            return list(citations_by_id.values())
        except _CHACHA_NONCRITICAL_EXCEPTIONS as e:
            logger.warning(f"get_conversation_citations failed for conversation {conversation_id}: {e}")
            return []

    def backfill_tool_calls_from_inline(self, strip_inline: bool = False, limit: int | None = None) -> dict[str, int]:
        """Scan assistant messages for an inline "[tool_calls]: <json>" suffix and backfill message_metadata.

        - Extracts JSON array/object after the last occurrence of "[tool_calls]:" (case-sensitive).
        - Persists it into `message_metadata.tool_calls_json`.
        - If `strip_inline=True`, removes the suffix from message content using optimistic locking.

        Returns counts: { scanned, matched, backfilled, stripped }
        """
        counts = {"scanned": 0, "matched": 0, "backfilled": 0, "stripped": 0}
        pattern = re.compile(r"\[tool_calls\]\s*:\s*(\{.*|\[.*)$", re.DOTALL)

        def _extract(content: str) -> dict[str, Any] | None:
            if not content:
                return None
            m = pattern.search(content)
            if not m:
                return None
            json_str = m.group(1).strip()
            try:
                data = json.loads(json_str)
                # Normalize: ensure list for tool_calls when object provided
                tool_calls = data.get('tool_calls') if isinstance(data, dict) and 'tool_calls' in data else data
                if isinstance(tool_calls, (list, dict)):
                    return {"tool_calls": tool_calls, "prefix_end": m.start(), "json_end": m.end()}
                return None  # noqa: TRY300
            except _CHACHA_NONCRITICAL_EXCEPTIONS:
                return None

        try:
            rows: list[dict[str, Any]] = []
            if self.backend_type == BackendType.SQLITE:
                query = "SELECT id, content, version FROM messages WHERE sender = ? AND deleted = 0"
                params = ("assistant",)
                if limit and isinstance(limit, int):
                    query += " LIMIT ?"
                    params = ("assistant", limit)
                cur = self.execute_query(query, params)
                rows = [dict(r) for r in cur.fetchall()]
            else:
                q = "SELECT id, content, version FROM messages WHERE sender = %s AND deleted = false"
                params = ("assistant",)
                if limit and isinstance(limit, int):
                    q += " LIMIT %s"
                    params = ("assistant", limit)
                res = self.backend.execute(q, params)
                fetched = res.fetchall()
                # Convert to dicts (backend returns sequence rows)
                for r in fetched:
                    # Row maybe mapping or tuple; try subscripting by name first
                    try:
                        rows.append({"id": r[0], "content": r[1], "version": r[2]})
                    except _CHACHA_NONCRITICAL_EXCEPTIONS:
                        with contextlib.suppress(_CHACHA_NONCRITICAL_EXCEPTIONS):
                            rows.append({"id": r['id'], "content": r['content'], "version": r['version']})

            for row in rows:
                counts["scanned"] += 1
                mid = row.get('id')
                content = row.get('content') or ""
                version = row.get('version') or 1
                extracted = _extract(content)
                if not extracted:
                    continue
                counts["matched"] += 1
                tool_calls = extracted.get('tool_calls')
                # Persist tool_calls array/object
                try:
                    if self.add_message_metadata(mid, tool_calls=tool_calls):
                        counts["backfilled"] += 1
                except _CHACHA_NONCRITICAL_EXCEPTIONS:
                    pass
                # Optionally strip inline suffix
                if strip_inline:
                    try:
                        # Trim content up to prefix_end
                        new_content = content[: int(extracted.get('prefix_end') or len(content))].rstrip()
                        self.update_message(mid, {"content": new_content}, expected_version=version)
                        counts["stripped"] += 1
                    except _CHACHA_NONCRITICAL_EXCEPTIONS:
                        # If version changed, skip silently
                        pass
        except _CHACHA_NONCRITICAL_EXCEPTIONS as e:
            logger.warning(f"backfill_tool_calls_from_inline encountered an error: {e}")
        return counts

    def _transform_sqlite_schema_statement_for_postgres(self, statement: str) -> str | None:
        """Apply token-level rewrites so the statement can run on Postgres."""

        stmt = statement.strip()
        if not stmt:
            return None

        stmt = re.sub(r'INTEGER\s+PRIMARY\s+KEY\s+AUTOINCREMENT', 'BIGSERIAL PRIMARY KEY', stmt, flags=re.IGNORECASE)
        stmt = re.sub(r'INTEGER\s+PRIMARY\s+KEY', 'BIGINT PRIMARY KEY', stmt, flags=re.IGNORECASE)

        def _replace_integer_references(match: re.Match[str]) -> str:
            suffix = match.group(1) or ''
            return f"BIGINT{suffix} REFERENCES"

        stmt = re.sub(
            r'INTEGER(\s+NOT\s+NULL)?\s+REFERENCES',
            _replace_integer_references,
            stmt,
            flags=re.IGNORECASE,
        )

        stmt = re.sub(r'BOOLEAN\s+NOT\s+NULL\s+DEFAULT\s+0', 'BOOLEAN NOT NULL DEFAULT FALSE', stmt, flags=re.IGNORECASE)
        stmt = re.sub(r'BOOLEAN\s+NOT\s+NULL\s+DEFAULT\s+1', 'BOOLEAN NOT NULL DEFAULT TRUE', stmt, flags=re.IGNORECASE)
        stmt = re.sub(r'BOOLEAN\s+DEFAULT\s+0', 'BOOLEAN DEFAULT FALSE', stmt, flags=re.IGNORECASE)
        stmt = re.sub(r'BOOLEAN\s+DEFAULT\s+1', 'BOOLEAN DEFAULT TRUE', stmt, flags=re.IGNORECASE)

        stmt = re.sub(r'DATETIME', 'TIMESTAMPTZ', stmt, flags=re.IGNORECASE)
        stmt = re.sub(r'BLOB', 'BYTEA', stmt, flags=re.IGNORECASE)
        stmt = re.sub(r'COLLATE\s+NOCASE', '', stmt, flags=re.IGNORECASE)

        stmt = re.sub(r'WHERE\s+([A-Za-z_]+)\s*=\s*0', r'WHERE \1 = FALSE', stmt, flags=re.IGNORECASE)
        stmt = re.sub(r'WHERE\s+([A-Za-z_]+)\s*=\s*1', r'WHERE \1 = TRUE', stmt, flags=re.IGNORECASE)

        stmt = replace_insert_or_ignore(stmt)

        # Special-case: seed insert for character_cards uses integer for boolean 'deleted'.
        lower_stmt = stmt.lower()
        if lower_stmt.startswith('insert') and 'into character_cards' in lower_stmt:
            # Convert trailing deleted value 0/1 to boolean FALSE/TRUE for Postgres
            stmt = re.sub(r",\s*0\)\s*;\s*$", ", FALSE);", stmt)
            stmt = re.sub(r",\s*1\)\s*;\s*$", ", TRUE);", stmt)
            stmt = re.sub(r",\s*0\)\s*ON\s+CONFLICT", ", FALSE) ON CONFLICT", stmt, flags=re.IGNORECASE)
            stmt = re.sub(r",\s*1\)\s*ON\s+CONFLICT", ", TRUE) ON CONFLICT", stmt, flags=re.IGNORECASE)

        # Break circular FK between conversations/messages by dropping conversations->messages FK at create time
        if lower_stmt.startswith('create table') and 'create table if not exists conversations' in lower_stmt:
            # Remove the forked_from_message_id FK clause
            stmt = re.sub(
                r"forked_from_message_id\s+TEXT\s+REFERENCES\s+messages\s*\(\s*id\s*\)\s*ON\s+DELETE\s+SET\s+NULL,?",
                "forked_from_message_id TEXT,",
                stmt,
                flags=re.IGNORECASE,
            )

        # Namespace the 'keywords' table to avoid collision with Media DB keywords
        # Only adjust creation/references; triggers and FTS blocks are skipped earlier
        if 'create table if not exists keywords' in lower_stmt:
            stmt = re.sub(
                r"CREATE\s+TABLE\s+IF\s+NOT\s+EXISTS\s+keywords\s*\(",
                "CREATE TABLE IF NOT EXISTS chacha_keywords(",
                stmt,
                flags=re.IGNORECASE,
            )
        stmt = re.sub(
            r"\bON\s+keywords\s*\(",
            "ON chacha_keywords(",
            stmt,
            flags=re.IGNORECASE,
        )
        # Adjust references to keywords in foreign keys/content declarations
        stmt = re.sub(
            r"REFERENCES\s+keywords\s*\(\s*id\s*\)",
            "REFERENCES chacha_keywords(id)",
            stmt,
            flags=re.IGNORECASE,
        )
        stmt = re.sub(
            r"content='keywords'",
            "content='chacha_keywords'",
            stmt,
            flags=re.IGNORECASE,
        )

        if not stmt.endswith(';'):
            stmt = f"{stmt};"
        return stmt

    def _apply_schema_v4_postgres(self, conn) -> None:
        statements = self._convert_sqlite_schema_to_postgres_statements(self._FULL_SCHEMA_SQL_V4)

        deferred_sync_idx_stmt: str | None = None
        for stmt in statements:
            up = stmt.upper().strip()
            if up.startswith("CREATE INDEX IF NOT EXISTS IDX_SYNC_LOG_ENTITY"):
                deferred_sync_idx_stmt = stmt
                continue
            self.backend.execute(stmt, connection=conn)

        # Create sync_log entity index depending on available columns
        try:
            cols = {c.get('name') for c in self.backend.get_table_info('sync_log', connection=conn)}
        except _CHACHA_NONCRITICAL_EXCEPTIONS:
            cols = set()

        if 'entity_id' in cols:
            self.backend.execute(
                "CREATE INDEX IF NOT EXISTS idx_sync_log_entity ON sync_log(entity,entity_id)",
                connection=conn,
            )
        elif 'entity_uuid' in cols:
            self.backend.execute(
                "CREATE INDEX IF NOT EXISTS idx_sync_log_entity ON sync_log(entity,entity_uuid)",
                connection=conn,
            )
        elif deferred_sync_idx_stmt:
            self.backend.execute(deferred_sync_idx_stmt, connection=conn)

        self._set_schema_version_postgres(conn, 4)
        self._sync_postgres_sequences(conn)

    def _ensure_postgres_workspaces_table_base(self, conn) -> None:
        """Create the workspaces table early for legacy Postgres migrations that reference it."""
        self.backend.execute(
            """
            CREATE TABLE IF NOT EXISTS workspaces (
                id            TEXT    PRIMARY KEY NOT NULL,
                name          TEXT    NOT NULL,
                description   TEXT,
                metadata_json TEXT    NOT NULL DEFAULT '{}',
                study_materials_policy TEXT NOT NULL DEFAULT 'general',
                workspace_profile TEXT NOT NULL DEFAULT 'research',
                archived      BOOLEAN NOT NULL DEFAULT false,
                created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
                last_modified TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
                deleted       BOOLEAN NOT NULL DEFAULT false,
                client_id     TEXT    NOT NULL DEFAULT 'unknown',
                version       INTEGER NOT NULL DEFAULT 1,
                assistant_defaults_json TEXT
            )
            """,
            connection=conn,
        )

    def _apply_postgres_migration_script(self, script: str, conn, *, expected_version: int) -> None:
        statements = self._convert_sqlite_schema_to_postgres_statements(script)
        for stmt in statements:
            self.backend.execute(stmt, connection=conn)
        self._set_schema_version_postgres(conn, expected_version)
        self._sync_postgres_sequences(conn)
        # Ensure FTS tsvector for flashcards when schema contains flashcards (v5+)
        try:
            if expected_version >= 5:
                self._ensure_postgres_flashcards_tsvector(conn)
        except _CHACHA_NONCRITICAL_EXCEPTIONS as _e:
            logger.debug(f"Skipping ensure flashcards tsvector after migration to v{expected_version}: {_e}")

    def _get_schema_version_postgres(self, conn, *, lock: bool = False) -> int:
        query = (
            "SELECT version FROM db_schema_version WHERE schema_name = %s LIMIT 1 FOR UPDATE"
            if lock
            else "SELECT version FROM db_schema_version WHERE schema_name = %s LIMIT 1"
        )
        result = self.backend.execute(
            query,
            (self._SCHEMA_NAME,),
            connection=conn,
        )
        value = result.scalar if result else None
        return int(value) if value is not None else 0

    def _set_schema_version_postgres(self, conn, version: int) -> None:
        self.backend.execute(
            """
            INSERT INTO db_schema_version(schema_name, version)
            VALUES (%s, %s)
            ON CONFLICT (schema_name) DO UPDATE SET version = EXCLUDED.version
            """,
            (self._SCHEMA_NAME, version),
            connection=conn,
        )

    def _sync_postgres_sequences(self, conn) -> None:
        """Ensure PostgreSQL sequences match current maxima for managed tables."""

        backend = self.backend
        ident = backend.escape_identifier

        for table_name, column_name in self._POSTGRES_SEQUENCE_TABLES:
            try:
                # Skip tables that may not exist yet at this schema version
                try:
                    if not backend.table_exists(table_name, connection=conn):
                        continue
                except _CHACHA_NONCRITICAL_EXCEPTIONS:
                    continue
                seq_result = backend.execute(
                    "SELECT pg_get_serial_sequence(%s, %s) AS seq",
                    (table_name, column_name),
                    connection=conn,
                )
                sequence_name = seq_result.scalar if seq_result else None
                if not sequence_name:
                    continue

                max_result = backend.execute(
                    (
                        f"SELECT COALESCE(MAX({ident(column_name)}), 0) AS max_id "  # nosec B608
                        f"FROM {ident(table_name)}"
                    ),
                    connection=conn,
                )

                try:
                    max_id = int(max_result.scalar or 0)
                except (TypeError, ValueError):
                    max_id = 0

                if max_id <= 0:
                    backend.execute(
                        "SELECT setval(%s, %s, false)",
                        (sequence_name, 1),
                        connection=conn,
                    )
                else:
                    backend.execute(
                        "SELECT setval(%s, %s)",
                        (sequence_name, max_id),
                        connection=conn,
                    )
            except BackendDatabaseError as exc:  # noqa: BLE001
                logger.warning(
                    'Failed to synchronize PostgreSQL sequence for {}.{}: {}',
                    table_name,
                    column_name,
                    exc,
                )

    # --- Internal Helpers ---
    def _get_current_utc_timestamp_iso(self) -> str:
        """
        Generates the current UTC timestamp in ISO 8601 format with 'Z' for UTC.

        Example: "2023-10-27T10:30:00.123Z"

        Returns:
            A string representing the current UTC timestamp with millisecond precision.
        """
        return datetime.now(timezone.utc).isoformat(timespec='milliseconds').replace('+00:00', 'Z')

    def _generate_uuid(self) -> str:
        """
        Generates a new UUID version 4.

        Returns:
            A string representation of the UUID.
        """
        return str(uuid.uuid4())

    def _map_table_for_backend(self, table_name: str) -> str:
        """Map logical table names to backend-specific physical names.

        This avoids name collisions with other modules when sharing a Postgres database.
        """
        if self.backend_type == BackendType.POSTGRESQL:
            mapping = {
                'keywords': 'chacha_keywords',
            }
            return mapping.get(table_name, table_name)
        return table_name

    # ----------------------
    # Notes Graph: manual edges (note_edges)
    # ----------------------
    def create_manual_note_edge(
        self,
        *,
        user_id: str,
        from_note_id: str,
        to_note_id: str,
        directed: bool = False,
        weight: float | None = 1.0,
        metadata: dict[str, Any] | None = None,
        created_by: str,
    ) -> dict[str, Any]:
        """Create one owner-bound manual link using the canonical lifecycle store."""

        if str(user_id) != str(self.client_id):
            raise InputError("Manual links must use the authenticated owner")
        source_note_id, target_note_id = from_note_id, to_note_id
        if not directed and source_note_id > target_note_id:
            source_note_id, target_note_id = target_note_id, source_note_id
        properties = dict(metadata or {})
        label = properties.pop("label", None)
        if label is not None and not isinstance(label, str):
            raise InputError("Manual link metadata.label must be a string or null")
        timestamp = datetime.fromisoformat(
            self._get_current_utc_timestamp_iso().replace("Z", "+00:00")
        ).astimezone(timezone.utc).isoformat()
        result = self.notes_link_store.upsert(
            edge_id=self._generate_uuid(),
            payload={
                "source_note_id": source_note_id,
                "target_note_id": target_note_id,
                "type": "manual",
                "directed": bool(directed),
                "weight": 1.0 if weight is None else weight,
                "label": label,
                "properties": properties,
                "created_at": timestamp,
                "last_modified": timestamp,
                "created_by": created_by,
            },
            expected_version=None,
        )
        return self.notes_link_store.legacy_dict(result.link)

    def delete_manual_note_edge(self, *, user_id: str, edge_id: str) -> bool:
        """Soft-delete one owner-bound manual link; repeated deletion is idempotent."""

        if str(user_id) != str(self.client_id):
            raise InputError("Manual links must use the authenticated owner")
        existing = self.notes_link_store.get(edge_id)
        if existing is None:
            return False
        if existing.deleted:
            return True
        timestamp = datetime.fromisoformat(
            self._get_current_utc_timestamp_iso().replace("Z", "+00:00")
        ).astimezone(timezone.utc).isoformat()
        self.notes_link_store.tombstone(
            edge_id=edge_id,
            payload={
                "source_note_id": existing.source_note_id,
                "target_note_id": existing.target_note_id,
                "type": existing.type,
                "directed": existing.directed,
                "weight": existing.weight,
                "label": existing.label,
                "properties": dict(existing.properties),
                "created_at": existing.created_at,
                "last_modified": timestamp,
                "created_by": existing.created_by,
                "deleted_at": timestamp,
                "reason": "legacy-api-delete",
            },
            expected_version=existing.version,
        )
        return True

    # ----------------------
    # Notes Graph: batch query helpers
    # ----------------------

    _SQLITE_PARAM_LIMIT = 900  # stay well under 999

    def get_manual_edges_for_notes(self, user_id: str, note_ids: list[str]) -> list[dict[str, Any]]:
        """Return all manual edges touching any of *note_ids* for *user_id*."""
        if str(user_id) != str(self.client_id):
            return []
        return [
            self.notes_link_store.legacy_dict(link)
            for link in self.notes_link_store.list_for_notes(note_ids)
        ]

    # Note graph helper methods are delegated to NoteStore at module bottom.

    @staticmethod
    def _chunk_list(lst: list, size: int) -> list[list]:
        """Split *lst* into sub-lists of at most *size* elements."""
        return [lst[i:i + size] for i in range(0, len(lst), size)]

    def _get_current_db_version(self, conn: sqlite3.Connection, table_name: str, pk_col_name: str,
                                pk_value: Any) -> int:
        """
        Fetches the current version of an active (not soft-deleted) record.

        Used for optimistic locking checks before an update or soft delete.

        Args:
            conn: The active sqlite3.Connection.
            table_name: The name of the table to query.
            pk_col_name: The name of the primary key column.
            pk_value: The value of the primary key for the record.

        Returns:
            The version number (integer) of the record if found and active.

        Raises:
            ConflictError: If the record is not found (with `entity` and `entity_id` attributes
                           set in the exception) or if the record is found but is soft-deleted.
        """
        if not (_SAFE_IDENTIFIER_RE.fullmatch(table_name or "") and _SAFE_IDENTIFIER_RE.fullmatch(pk_col_name or "")):
            raise CharactersRAGDBError(  # noqa: TRY003
                f"Unsafe identifier in version lookup: table={table_name!r}, column={pk_col_name!r}"
            )
        cursor = conn.execute(f"SELECT version, deleted FROM {table_name} WHERE {pk_col_name} = ?", (pk_value,))  # nosec B608
        row = cursor.fetchone()

        if not row:
            logger.warning(f"Record not found in {table_name} with {pk_col_name} = {pk_value} for version check.")
            raise ConflictError(f"Record not found in {table_name}.", entity=table_name, entity_id=pk_value)  # noqa: TRY003

        if row['deleted']:
            logger.warning(f"Record in {table_name} with {pk_col_name} = {pk_value} is soft-deleted.")
            raise ConflictError(f"Record is soft-deleted in {table_name}.", entity=table_name, entity_id=pk_value)  # noqa: TRY003

        return row['version']

    def _ensure_json_string(self, data: list | dict | set | None) -> str | None:
        """
        Serializes Python list, dict, or set to a JSON string.

        If data is None, returns None. Converts sets to lists before serialization.

        Args:
            data: The Python object (list, dict, set) to serialize, or None.

        Returns:
            A JSON string representation of the data, or None if input was None.
        """
        if data is None:
            return None
        if isinstance(data, set):
            data = list(data)  # Convert set to list before dumping
        return json.dumps(data)

    def _is_unique_violation(self, error: Exception) -> bool:
        """Return True if the provided backend error represents a unique constraint violation."""
        message = str(error).lower()
        return "unique constraint" in message or "duplicate key" in message

    # ----------------------
    # Skill registry
    # ----------------------
    def _ensure_skill_registry_table(self) -> None:
        """Ensure the skill_registry table exists for the active backend."""
        if self.backend_type == BackendType.SQLITE:
            self.execute_query(
                """
                CREATE TABLE IF NOT EXISTS skill_registry (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL UNIQUE,
                    description TEXT,
                    argument_hint TEXT,
                    disable_model_invocation BOOLEAN DEFAULT 0,
                    user_invocable BOOLEAN DEFAULT 1,
                    allowed_tools TEXT,
                    model TEXT,
                    context TEXT DEFAULT 'inline',
                    directory_path TEXT NOT NULL,
                    last_modified DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    file_hash TEXT,
                    uuid TEXT UNIQUE NOT NULL,
                    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                    deleted BOOLEAN DEFAULT 0,
                    version INTEGER NOT NULL DEFAULT 1
                )
                """,
                script=False,
                commit=True,
            )
            self.execute_query(
                "CREATE INDEX IF NOT EXISTS idx_skill_name ON skill_registry(name)",
                script=False,
                commit=True,
            )
            self.execute_query(
                "CREATE INDEX IF NOT EXISTS idx_skill_user_invocable ON skill_registry(user_invocable)",
                script=False,
                commit=True,
            )
            self.execute_query(
                "CREATE INDEX IF NOT EXISTS idx_skill_deleted ON skill_registry(deleted)",
                script=False,
                commit=True,
            )
            return

        if self.backend_type == BackendType.POSTGRESQL:
            self.backend.execute(
                """
                CREATE TABLE IF NOT EXISTS skill_registry (
                    id SERIAL PRIMARY KEY,
                    name TEXT NOT NULL UNIQUE,
                    description TEXT,
                    argument_hint TEXT,
                    disable_model_invocation BOOLEAN DEFAULT FALSE,
                    user_invocable BOOLEAN DEFAULT TRUE,
                    allowed_tools TEXT,
                    model TEXT,
                    context TEXT DEFAULT 'inline',
                    directory_path TEXT NOT NULL,
                    last_modified TIMESTAMP NOT NULL DEFAULT NOW(),
                    file_hash TEXT,
                    uuid TEXT UNIQUE NOT NULL,
                    created_at TIMESTAMP DEFAULT NOW(),
                    deleted BOOLEAN DEFAULT FALSE,
                    version INTEGER NOT NULL DEFAULT 1
                )
                """
            )
            self.backend.execute("CREATE INDEX IF NOT EXISTS idx_skill_name ON skill_registry(name)")
            self.backend.execute(
                "CREATE INDEX IF NOT EXISTS idx_skill_user_invocable ON skill_registry(user_invocable)"
            )
            self.backend.execute("CREATE INDEX IF NOT EXISTS idx_skill_deleted ON skill_registry(deleted)")
            return

        raise NotImplementedError(
            f"skill_registry table creation not supported for backend {self.backend_type.value}"
        )

    def _coerce_skill_datetime(self, value: Any) -> datetime | None:
        """Best-effort conversion of database timestamps to datetime."""
        if value is None:
            return None
        if isinstance(value, datetime):
            return value
        if isinstance(value, str):
            try:
                return datetime.fromisoformat(value.replace("Z", "+00:00"))
            except ValueError:
                return None
        return None

    def _skill_row_to_dict(self, row: Any) -> dict[str, Any] | None:
        """Convert a skill_registry row to a dict with JSON fields decoded."""
        if not row:
            return None
        item = dict(row)
        allowed_tools = item.get("allowed_tools")
        if isinstance(allowed_tools, str):
            try:
                item["allowed_tools"] = json.loads(allowed_tools)
            except json.JSONDecodeError:
                item["allowed_tools"] = [tool.strip() for tool in allowed_tools.split(",") if tool.strip()]
        elif allowed_tools is None:
            item["allowed_tools"] = None
        else:
            item["allowed_tools"] = allowed_tools

        item["disable_model_invocation"] = bool(item.get("disable_model_invocation", False))
        item["user_invocable"] = bool(item.get("user_invocable", True))
        item["deleted"] = bool(item.get("deleted", False))
        item["created_at"] = self._coerce_skill_datetime(item.get("created_at"))
        item["last_modified"] = self._coerce_skill_datetime(item.get("last_modified"))
        return item

    def _skill_bool_value(self, value: bool) -> bool | int:
        return value if self.backend_type == BackendType.POSTGRESQL else int(value)

    _SKILL_REGISTRY_CONTEXTS = {"inline", "fork"}
    _SKILL_REGISTRY_SORT_FIELDS = {"name", "context", "created_at", "last_modified"}
    _SKILL_REGISTRY_SORT_DIRECTIONS = {
        "asc",
        "desc",
    }
    _SKILL_REGISTRY_SORT_CLAUSES = {
        ("name", "asc"): "ORDER BY name ASC",
        ("name", "desc"): "ORDER BY name DESC",
        ("context", "asc"): "ORDER BY context ASC, name ASC",
        ("context", "desc"): "ORDER BY context DESC, name ASC",
        ("created_at", "asc"): "ORDER BY created_at ASC, name ASC",
        ("created_at", "desc"): "ORDER BY created_at DESC, name ASC",
        ("last_modified", "asc"): "ORDER BY last_modified ASC, name ASC",
        ("last_modified", "desc"): "ORDER BY last_modified DESC, name ASC",
    }

    @staticmethod
    def _skill_search_like_pattern(query: str | None) -> str | None:
        """Return an escaped SQL LIKE pattern for skill search, or None when blank."""
        normalized = (query or "").strip().lower()
        if not normalized:
            return None
        escaped = (
            normalized
            .replace("\\", "\\\\")
            .replace("%", "\\%")
            .replace("_", "\\_")
        )
        return f"%{escaped}%"

    @staticmethod
    def _normalized_skill_text_filter(value: str | None) -> str | None:
        """Return normalized filter text, or None when blank."""
        normalized = (value or "").strip().lower()
        return normalized or None

    def _skill_registry_sort_clause(self, sort: str, order: str) -> str:
        """Return a safe ORDER BY clause for whitelisted skill registry fields."""
        sort_key = (sort or "name").strip().lower()
        if sort_key not in self._SKILL_REGISTRY_SORT_FIELDS:
            raise InputError("Unsupported skill registry sort field")

        order_key = (order or "asc").strip().lower()
        if order_key not in self._SKILL_REGISTRY_SORT_DIRECTIONS:
            raise InputError("Unsupported skill registry sort order")

        return self._SKILL_REGISTRY_SORT_CLAUSES[(sort_key, order_key)]

    def _skill_registry_filter_clauses(
        self,
        *,
        include_hidden: bool,
        include_deleted: bool,
        q: str | None,
        context: str | None,
        user_invocable: bool | None,
        has_tools: bool | None,
        model: str | None,
    ) -> tuple[list[str], list[Any]]:
        """Build shared skill registry WHERE clauses for list and count queries."""
        clauses: list[str] = []
        params: list[Any] = []
        if not include_deleted:
            clauses.append("deleted = ?")
            params.append(self._skill_bool_value(False))

        if user_invocable is not None:
            clauses.append("user_invocable = ?")
            params.append(self._skill_bool_value(user_invocable))
        elif not include_hidden:
            clauses.append("user_invocable = ?")
            params.append(self._skill_bool_value(True))

        search_pattern = self._skill_search_like_pattern(q)
        if search_pattern is not None:
            clauses.append(
                "("
                "LOWER(name) LIKE ? ESCAPE '\\' "
                "OR LOWER(COALESCE(description, '')) LIKE ? ESCAPE '\\' "
                "OR LOWER(COALESCE(argument_hint, '')) LIKE ? ESCAPE '\\'"
                ")"
            )
            params.extend([search_pattern, search_pattern, search_pattern])

        context_filter = self._normalized_skill_text_filter(context)
        if context_filter is not None:
            if context_filter not in self._SKILL_REGISTRY_CONTEXTS:
                raise InputError("Unsupported skill registry context")
            clauses.append("context = ?")
            params.append(context_filter)

        if has_tools is True:
            clauses.append("allowed_tools IS NOT NULL AND TRIM(allowed_tools) NOT IN ('', '[]')")
        elif has_tools is False:
            clauses.append("(allowed_tools IS NULL OR TRIM(allowed_tools) IN ('', '[]'))")

        model_filter = self._normalized_skill_text_filter(model)
        if model_filter is not None:
            clauses.append("LOWER(COALESCE(model, '')) = ?")
            params.append(model_filter)

        return clauses, params

    def list_skill_registry(
        self,
        *,
        include_hidden: bool = False,
        include_deleted: bool = False,
        q: str | None = None,
        context: str | None = None,
        user_invocable: bool | None = None,
        has_tools: bool | None = None,
        model: str | None = None,
        sort: str = "name",
        order: str = "asc",
        limit: int | None = 100,
        offset: int = 0,
    ) -> list[dict[str, Any]]:
        """List skill registry entries with optional filters."""
        self._ensure_skill_registry_table()
        clauses, params = self._skill_registry_filter_clauses(
            include_hidden=include_hidden,
            include_deleted=include_deleted,
            q=q,
            context=context,
            user_invocable=user_invocable,
            has_tools=has_tools,
            model=model,
        )
        where_sql = f"WHERE {' AND '.join(clauses)}" if clauses else ""
        order_sql = self._skill_registry_sort_clause(sort, order)
        query = (
            "SELECT * FROM skill_registry "  # nosec B608
            f"{where_sql} "
            f"{order_sql}"
        )
        if limit is not None:
            query += " LIMIT ? OFFSET ?"
            params.extend([limit, offset])
        try:
            cursor = self.execute_query(query, tuple(params))
            return [item for row in cursor.fetchall() if (item := self._skill_row_to_dict(row))]
        except CharactersRAGDBError as exc:
            logger.error(f"Database error listing skills: {exc}")
            raise

    def count_skill_registry(
        self,
        *,
        include_hidden: bool = False,
        include_deleted: bool = False,
        q: str | None = None,
        context: str | None = None,
        user_invocable: bool | None = None,
        has_tools: bool | None = None,
        model: str | None = None,
    ) -> int:
        """Return count of skills in registry."""
        self._ensure_skill_registry_table()
        clauses, params = self._skill_registry_filter_clauses(
            include_hidden=include_hidden,
            include_deleted=include_deleted,
            q=q,
            context=context,
            user_invocable=user_invocable,
            has_tools=has_tools,
            model=model,
        )
        where_sql = f"WHERE {' AND '.join(clauses)}" if clauses else ""
        query = f"SELECT COUNT(*) AS cnt FROM skill_registry {where_sql}"  # nosec B608
        try:
            cursor = self.execute_query(query, tuple(params))
            row = cursor.fetchone()
            return int(row["cnt"]) if row else 0
        except CharactersRAGDBError as exc:
            logger.error(f"Database error counting skills: {exc}")
            raise

    def get_skill_registry(self, name: str, *, include_deleted: bool = False) -> dict[str, Any] | None:
        """Fetch a skill registry entry by name."""
        self._ensure_skill_registry_table()
        query = "SELECT * FROM skill_registry WHERE name = ?"
        params: list[Any] = [name]
        if not include_deleted:
            query += " AND deleted = ?"
            params.append(self._skill_bool_value(False))
        try:
            cursor = self.execute_query(query, tuple(params))
            return self._skill_row_to_dict(cursor.fetchone())
        except CharactersRAGDBError as exc:
            logger.error(f"Database error fetching skill '{name}': {exc}")
            raise

    def get_skill_registry_by_uuid(self, skill_uuid: str) -> dict[str, Any] | None:
        """Fetch an active or deleted skill registry entry by immutable UUID."""
        self._ensure_skill_registry_table()
        normalized_uuid = str(skill_uuid or "").strip()
        if not normalized_uuid:
            return None
        try:
            cursor = self.execute_query(
                "SELECT * FROM skill_registry WHERE uuid = ?",
                (normalized_uuid,),
            )
            return self._skill_row_to_dict(cursor.fetchone())
        except CharactersRAGDBError as exc:
            logger.error(f"Database error fetching skill UUID '{normalized_uuid}': {exc}")
            raise

    def insert_skill_registry(self, skill_data: dict[str, Any]) -> str:
        """Insert a new skill registry row and return its UUID."""
        self._ensure_skill_registry_table()
        name = str(skill_data.get("name") or "").strip().lower()
        if not name:
            raise InputError("Skill name is required.")  # noqa: TRY003
        directory_path = str(skill_data.get("directory_path") or "")
        if not directory_path:
            raise InputError("directory_path is required for skill registry.")  # noqa: TRY003

        now = self._get_current_utc_timestamp_iso()
        skill_uuid = str(skill_data.get("uuid") or self._generate_uuid())
        allowed_tools_json = self._ensure_json_string(skill_data.get("allowed_tools"))

        query = (
            "INSERT INTO skill_registry ("
            "name, description, argument_hint, disable_model_invocation, user_invocable, "
            "allowed_tools, model, context, directory_path, last_modified, file_hash, uuid, "
            "created_at, deleted, version"
            ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
        )
        params = (
            name,
            skill_data.get("description"),
            skill_data.get("argument_hint"),
            self._skill_bool_value(bool(skill_data.get("disable_model_invocation", False))),
            self._skill_bool_value(bool(skill_data.get("user_invocable", True))),
            allowed_tools_json,
            skill_data.get("model"),
            skill_data.get("context", "inline"),
            directory_path,
            now,
            skill_data.get("file_hash"),
            skill_uuid,
            skill_data.get("created_at") or now,
            self._skill_bool_value(bool(skill_data.get("deleted", False))),
            int(skill_data.get("version", 1)),
        )
        try:
            self.execute_query(query, params, commit=True)
            return skill_uuid
        except sqlite3.IntegrityError as exc:
            if "unique constraint failed: skill_registry.name" in str(exc).lower():
                raise ConflictError(
                    f"Skill '{name}' already exists.",
                    entity="skill_registry",
                    entity_id=name,
                ) from exc
            if "unique constraint failed: skill_registry.uuid" in str(exc).lower():
                raise ConflictError(
                    "Skill UUID already exists.",
                    entity="skill_registry",
                    entity_id=skill_uuid,
                ) from exc
            raise CharactersRAGDBError(f"Database integrity error adding skill '{name}': {exc}") from exc
        except BackendDatabaseError as exc:
            if self._is_unique_violation(exc):
                raise ConflictError(
                    f"Skill '{name}' already exists.",
                    entity="skill_registry",
                    entity_id=name,
                ) from exc
            raise CharactersRAGDBError(f"Database integrity error adding skill '{name}': {exc}") from exc

    def update_skill_registry(
        self,
        name: str,
        update_data: dict[str, Any],
        expected_version: int,
    ) -> bool:
        """Update a skill registry row using optimistic locking."""
        if not update_data:
            raise InputError(f"No data provided for update of skill '{name}'.")  # noqa: TRY003

        self._ensure_skill_registry_table()
        now = self._get_current_utc_timestamp_iso()
        allowed_fields = {
            "description",
            "argument_hint",
            "disable_model_invocation",
            "user_invocable",
            "allowed_tools",
            "model",
            "context",
            "directory_path",
            "file_hash",
            "deleted",
        }

        set_parts: list[str] = []
        params: list[Any] = []
        for key, value in update_data.items():
            if key not in allowed_fields:
                continue
            if key == "allowed_tools":
                params.append(self._ensure_json_string(value))
                set_parts.append("allowed_tools = ?")
            elif key in {"disable_model_invocation", "user_invocable", "deleted"}:
                params.append(self._skill_bool_value(bool(value)))
                set_parts.append(f"{key} = ?")
            else:
                params.append(value)
                set_parts.append(f"{key} = ?")

        if not set_parts:
            raise InputError(f"No supported data provided for update of skill '{name}'.")  # noqa: TRY003

        set_parts.extend(["last_modified = ?", "version = version + 1"])
        params.append(now)
        params.extend([name, expected_version])
        query = (
            f"UPDATE skill_registry SET {', '.join(set_parts)} "  # nosec B608
            "WHERE name = ? AND version = ? AND deleted = ?"
        )
        params.append(self._skill_bool_value(False))

        try:
            with self.transaction() as conn:
                current_db_version = self._get_current_db_version(conn, "skill_registry", "name", name)
                if current_db_version != expected_version:
                    raise ConflictError(
                        f"Skill '{name}' was modified (db has {current_db_version}, expected {expected_version}).",
                        entity="skill_registry",
                        entity_id=name,
                    )

                prepared_query, prepared_params = self._prepare_backend_statement(query, tuple(params))
                cursor = conn.execute(prepared_query, prepared_params)
                if cursor.rowcount == 0:
                    raise ConflictError(
                        f"Skill '{name}' update affected 0 rows.",
                        entity="skill_registry",
                        entity_id=name,
                    )
                return True
        except ConflictError:
            raise
        except CharactersRAGDBError as exc:
            logger.error(f"Database error updating skill '{name}': {exc}")
            raise

    def mark_skill_registry_deleted(
        self,
        name: str,
        expected_version: int,
        directory_path: str | None = None,
    ) -> bool:
        """Soft-delete a skill registry row and optionally record its archive path."""
        self._ensure_skill_registry_table()
        now = self._get_current_utc_timestamp_iso()
        next_version = expected_version + 1
        if directory_path is None:
            query = (
                "UPDATE skill_registry SET deleted = ?, last_modified = ?, version = ? "
                "WHERE name = ? AND version = ? AND deleted = ?"
            )
            params = (
                self._skill_bool_value(True),
                now,
                next_version,
                name,
                expected_version,
                self._skill_bool_value(False),
            )
        else:
            query = (
                "UPDATE skill_registry SET deleted = ?, directory_path = ?, "
                "last_modified = ?, version = ? "
                "WHERE name = ? AND version = ? AND deleted = ?"
            )
            params = (
                self._skill_bool_value(True),
                directory_path,
                now,
                next_version,
                name,
                expected_version,
                self._skill_bool_value(False),
            )

        try:
            with self.transaction() as conn:
                try:
                    current_db_version = self._get_current_db_version(conn, "skill_registry", "name", name)
                except ConflictError:
                    check_deleted = conn.execute(
                        "SELECT deleted, version FROM skill_registry WHERE name = ?",
                        (name,),
                    ).fetchone()
                    if check_deleted and check_deleted["deleted"]:
                        logger.info("Skill '{}' already deleted; soft-delete is idempotent.", name)
                        return True
                    raise

                if current_db_version != expected_version:
                    raise ConflictError(
                        f"Skill '{name}' version mismatch (db has {current_db_version}, expected {expected_version}).",
                        entity="skill_registry",
                        entity_id=name,
                    )

                prepared_query, prepared_params = self._prepare_backend_statement(query, params)
                cursor = conn.execute(prepared_query, prepared_params)
                if cursor.rowcount == 0:
                    raise ConflictError(
                        f"Skill '{name}' delete affected 0 rows.",
                        entity="skill_registry",
                        entity_id=name,
                    )
                return True
        except ConflictError:
            raise
        except CharactersRAGDBError as exc:
            logger.error(f"Database error deleting skill '{name}': {exc}")
            raise

    def bulk_mark_skill_registry_deleted(
        self,
        items: list[tuple[str, int | None]],
        archive_paths: dict[str, str] | None = None,
    ) -> list[dict[str, Any]]:
        """Soft-delete multiple skill rows and record archive paths atomically."""
        if not items:
            return []

        self._ensure_skill_registry_table()
        now = self._get_current_utc_timestamp_iso()
        deleted_value = self._skill_bool_value(True)
        active_value = self._skill_bool_value(False)
        select_query = "SELECT * FROM skill_registry WHERE name = ?"
        update_query = (
            "UPDATE skill_registry SET deleted = ?, directory_path = ?, "
            "last_modified = ?, version = ? "
            "WHERE name = ? AND version = ? AND deleted = ?"
        )

        try:
            with self.transaction() as conn:
                validated_rows: list[dict[str, Any]] = []
                for name, expected_version in items:
                    prepared_query, prepared_params = self._prepare_backend_statement(select_query, (name,))
                    row = self._skill_row_to_dict(conn.execute(prepared_query, prepared_params).fetchone())
                    if not row:
                        raise InputError(f"Skill not found: {name}")  # noqa: TRY003

                    current_version = int(row.get("version") or 1)
                    if expected_version is not None and current_version != expected_version:
                        raise ConflictError(
                            f"Skill '{name}' version mismatch (db has {current_version}, expected {expected_version}).",
                            entity="skill_registry",
                            entity_id=name,
                        )

                    row["previous_version"] = current_version
                    row["was_deleted"] = bool(row.get("deleted", False))
                    validated_rows.append(row)

                for row in validated_rows:
                    if row["was_deleted"]:
                        continue

                    current_version = int(row["previous_version"])
                    next_version = current_version + 1
                    directory_path = (archive_paths or {}).get(
                        str(row["name"]),
                        row.get("directory_path"),
                    )
                    if not isinstance(directory_path, str) or not directory_path.strip():
                        raise InputError(
                            f"Skill '{row['name']}' has no valid directory path."
                        )
                    params = (
                        deleted_value,
                        directory_path,
                        now,
                        next_version,
                        row["name"],
                        current_version,
                        active_value,
                    )
                    prepared_query, prepared_params = self._prepare_backend_statement(update_query, params)
                    cursor = conn.execute(prepared_query, prepared_params)
                    if cursor.rowcount == 0:
                        raise ConflictError(
                            f"Skill '{row['name']}' delete affected 0 rows.",
                            entity="skill_registry",
                            entity_id=row["name"],
                        )
                    row["version"] = next_version
                    row["deleted"] = True

                return validated_rows
        except (ConflictError, InputError):
            raise
        except CharactersRAGDBError as exc:
            logger.error(f"Database error bulk deleting skills: {exc}")
            raise

    def list_deleted_skill_registry(
        self,
        *,
        limit: int = 100,
        offset: int = 0,
    ) -> list[dict[str, Any]]:
        """List soft-deleted skills newest-first for the Trash view."""
        self._ensure_skill_registry_table()
        query = (
            "SELECT * FROM skill_registry WHERE deleted = ? "
            "ORDER BY last_modified DESC, name ASC LIMIT ? OFFSET ?"
        )
        try:
            cursor = self.execute_query(
                query,
                (self._skill_bool_value(True), limit, offset),
            )
            return [item for row in cursor.fetchall() if (item := self._skill_row_to_dict(row))]
        except CharactersRAGDBError as exc:
            logger.error(f"Database error listing deleted skills: {exc}")
            raise

    def count_deleted_skill_registry(self) -> int:
        """Return the number of soft-deleted skills."""
        self._ensure_skill_registry_table()
        try:
            cursor = self.execute_query(
                "SELECT COUNT(*) AS cnt FROM skill_registry WHERE deleted = ?",
                (self._skill_bool_value(True),),
            )
            row = cursor.fetchone()
            return int(row["cnt"]) if row else 0
        except CharactersRAGDBError as exc:
            logger.error(f"Database error counting deleted skills: {exc}")
            raise

    def purge_skill_registry(self, name: str, expected_version: int) -> bool:
        """Permanently remove one soft-deleted skill using optimistic locking."""
        self._ensure_skill_registry_table()
        try:
            with self.transaction() as conn:
                select_query, select_params = self._prepare_backend_statement(
                    "SELECT version, deleted FROM skill_registry WHERE name = ?",
                    (name,),
                )
                row = conn.execute(select_query, select_params).fetchone()
                if not row:
                    raise InputError(f"Skill not found: {name}")  # noqa: TRY003

                current_version = int(row["version"])
                if not bool(row["deleted"]):
                    raise ConflictError(
                        f"Skill '{name}' must be deleted before it can be purged.",
                        entity="skill_registry",
                        entity_id=name,
                    )
                if current_version != expected_version:
                    raise ConflictError(
                        f"Skill '{name}' version mismatch (db has {current_version}, expected {expected_version}).",
                        entity="skill_registry",
                        entity_id=name,
                    )

                delete_query, delete_params = self._prepare_backend_statement(
                    "DELETE FROM skill_registry WHERE name = ? AND version = ? AND deleted = ?",
                    (name, expected_version, self._skill_bool_value(True)),
                )
                cursor = conn.execute(delete_query, delete_params)
                if cursor.rowcount == 0:
                    raise ConflictError(
                        f"Skill '{name}' purge affected 0 rows.",
                        entity="skill_registry",
                        entity_id=name,
                    )
                return True
        except (ConflictError, InputError):
            raise
        except CharactersRAGDBError as exc:
            logger.error(f"Database error purging skill '{name}': {exc}")
            raise

    def restore_skill_registry(
        self,
        name: str,
        update_data: dict[str, Any] | None,
        expected_version: int,
    ) -> bool:
        """Restore a soft-deleted skill registry row using optimistic locking."""
        self._ensure_skill_registry_table()
        now = self._get_current_utc_timestamp_iso()
        allowed_fields = {
            "description",
            "argument_hint",
            "disable_model_invocation",
            "user_invocable",
            "allowed_tools",
            "model",
            "context",
            "directory_path",
            "file_hash",
        }

        set_parts: list[str] = []
        params: list[Any] = []
        for key, value in (update_data or {}).items():
            if key not in allowed_fields:
                continue
            if key == "allowed_tools":
                params.append(self._ensure_json_string(value))
                set_parts.append("allowed_tools = ?")
            elif key in {"disable_model_invocation", "user_invocable"}:
                params.append(self._skill_bool_value(bool(value)))
                set_parts.append(f"{key} = ?")
            else:
                params.append(value)
                set_parts.append(f"{key} = ?")

        set_parts.extend(["deleted = ?", "last_modified = ?", "version = version + 1"])
        params.extend([self._skill_bool_value(False), now, name, expected_version])
        query = (
            f"UPDATE skill_registry SET {', '.join(set_parts)} "  # nosec B608
            "WHERE name = ? AND version = ? AND deleted = ?"
        )
        params.append(self._skill_bool_value(True))

        try:
            with self.transaction() as conn:
                row = conn.execute(
                    "SELECT version, deleted FROM skill_registry WHERE name = ?",
                    (name,),
                ).fetchone()
                if not row:
                    raise ConflictError(
                        f"Skill '{name}' restore target was not found.",
                        entity="skill_registry",
                        entity_id=name,
                    )

                current_db_version = int(row["version"])
                if current_db_version != expected_version:
                    raise ConflictError(
                        f"Skill '{name}' version mismatch (db has {current_db_version}, expected {expected_version}).",
                        entity="skill_registry",
                        entity_id=name,
                    )

                if not row["deleted"]:
                    logger.info("Skill '{}' already active; restore is idempotent.", name)
                    return True

                prepared_query, prepared_params = self._prepare_backend_statement(query, tuple(params))
                cursor = conn.execute(prepared_query, prepared_params)
                if cursor.rowcount == 0:
                    raise ConflictError(
                        f"Skill '{name}' restore affected 0 rows.",
                        entity="skill_registry",
                        entity_id=name,
                    )
                return True
        except ConflictError:
            raise
        except CharactersRAGDBError as exc:
            logger.error(f"Database error restoring skill '{name}': {exc}")
            raise

    def _deserialize_row_fields(self, row: sqlite3.Row, json_fields: list[str]) -> dict[str, Any] | None:
        """
        Converts a sqlite3.Row object to a dictionary, deserializing specified JSON fields.

        If a field listed in `json_fields` contains a string, it attempts to
        parse it as JSON. If parsing fails, the field value is set to None
        and a warning is logged.

        Args:
            row: The sqlite3.Row object to convert. If None, returns None.
            json_fields: A list of field names that should be treated as JSON strings
                         and deserialized.

        Returns:
            A dictionary representing the row with specified fields deserialized,
            or None if the input `row` is None.
        """
        if not row:
            return None
        item = dict(row)
        for field in json_fields:
            if field in item and isinstance(item[field], str):
                try:
                    item[field] = json.loads(item[field])
                except json.JSONDecodeError:
                    pk_val = item.get('id') or item.get('uuid', 'N/A')  # Try to get an identifier
                    logger.warning(
                        f"Failed to decode JSON for field '{field}' in row (ID: {pk_val}). Value: '{item[field][:100]}...'")
                    item[field] = None  # Or sensible default
        return item

    _CHARACTER_CARD_JSON_FIELDS = ['alternate_greetings', 'tags', 'extensions']
    _STUDY_PACK_JSON_FIELDS = ['source_bundle_json', 'generation_options_json']
    _SUGGESTION_SNAPSHOT_JSON_FIELDS = ('payload_json', 'user_selection_json')
    _CHARACTER_FOLDER_TAG_PREFIX = "__tldw_folder_id:"
    _CHARACTER_EXEMPLAR_JSON_FIELDS = ['rhetorical', 'safety_allowed', 'safety_blocked']
    _PERSONA_EXEMPLAR_JSON_FIELDS = ['scenario_tags_json', 'capability_tags_json']
    _ALLOWED_EXEMPLAR_SOURCE_TYPES = ('audio_transcript', 'video_transcript', 'article', 'other')
    _ALLOWED_EXEMPLAR_NOVELTY_HINTS = ('post_cutoff', 'unknown', 'pre_cutoff')
    _ALLOWED_EXEMPLAR_EMOTIONS = ('angry', 'neutral', 'happy', 'other')
    _ALLOWED_EXEMPLAR_SCENARIOS = ('press_challenge', 'fan_banter', 'debate', 'boardroom', 'small_talk', 'other')

    # --- Character Card Methods ---
    @staticmethod
    def _ensure_json_string_from_mixed(data: list | dict | set | str | None) -> str | None:
        """
        Serializes Python list, dict, or set to a JSON string, or passes through an existing string.

        - If data is None, returns None.
        - If data is a list, dict, or set (converted to list), it is serialized to JSON.
        - If data is already a string, it attempts to validate it as JSON.
          - If valid JSON, the string is returned as is.
          - If not valid JSON, the string is returned as is (logged with DEBUG level).
          This behavior assumes that if a string is passed, it is either pre-formatted JSON
          or a plain string intended for a text field that happens to be JSON-serializable.

        Args:
            data: The Python object (list, dict, set, str) to process, or None.

        Returns:
            A JSON string representation of the data, the original string if it is
            valid JSON or a plain string, or None if input `data` was None.
        """
        if data is None:
            return None
        if isinstance(data, str):  # If it's already a string, assume it's valid JSON or pass it through
            try:
                json.loads(data)  # Validate if it's a JSON string
                return data  # noqa: TRY300
            except json.JSONDecodeError:
                logger.debug(f"Input string is not valid JSON, passing through: '{data[:100]}...'")
                return data
        if isinstance(data, set):
            new_data = list(data)
            return json.dumps(new_data)
        return json.dumps(data)

    # Character card CRUD / tag-search methods are delegated to CharacterStore at module bottom.

    @staticmethod
    def _normalize_nullable_text(value: Any) -> str | None:
        """Normalize optional text fields; returns None for empty/whitespace."""
        if value is None:
            return None
        if isinstance(value, str):
            stripped = value.strip()
            return stripped if stripped else None
        return str(value)

    _ALLOWED_SCOPE_TYPES: tuple[str, ...] = ("global", "workspace")

    # Message count/query helpers are delegated to MessageStore at module bottom.

    def upsert_conversation_cluster(
        self,
        cluster_id: str,
        *,
        title: str | None = None,
        centroid: str | None = None,
        size: int = 0,
    ) -> bool:
        """Insert or update a conversation cluster metadata row."""
        now = self._get_current_utc_timestamp_iso()
        try:
            if self.backend_type == BackendType.SQLITE:
                query = (
                    "INSERT INTO conversation_clusters "
                    "(cluster_id, title, centroid, size, created_at, updated_at) "
                    "VALUES (?, ?, ?, ?, ?, ?) "
                    "ON CONFLICT(cluster_id) DO UPDATE SET "
                    "title = excluded.title, centroid = excluded.centroid, size = excluded.size, "
                    "updated_at = excluded.updated_at"
                )
                self.execute_query(query, (cluster_id, title, centroid, int(size), now, now), commit=True)
                return True

            query = (
                "INSERT INTO conversation_clusters "
                "(cluster_id, title, centroid, size, created_at, updated_at) "
                "VALUES (%s, %s, %s, %s, NOW(), NOW()) "
                "ON CONFLICT (cluster_id) DO UPDATE SET "
                "title = EXCLUDED.title, centroid = EXCLUDED.centroid, size = EXCLUDED.size, "
                "updated_at = NOW()"
            )
            self.backend.execute(query, (cluster_id, title, centroid, int(size)))
            return True  # noqa: TRY300
        except _CHACHA_NONCRITICAL_EXCEPTIONS as exc:
            logger.error("Failed to upsert conversation cluster {}: {}", cluster_id, exc)
            return False

    # Conversation CRUD/search methods are delegated to ConversationStore at module bottom.

    # --- Workspace Methods ---

    @staticmethod
    def _validate_workspace_profile(workspace_profile: str) -> str:
        """Validate a persisted workspace profile value."""
        normalized = str(workspace_profile or "").strip().lower()
        if normalized not in _WORKSPACE_PROFILES:
            raise InputError("workspace_profile must be 'research' or 'project'")  # noqa: TRY003
        return normalized

    @staticmethod
    def _validate_workspace_clone_identifier(value: Any, field_name: str) -> str:
        """Validate one clone lifecycle identifier using the clone request contract."""
        if not isinstance(value, str) or not value:
            raise InputError(f"{field_name} must be a non-empty ASCII string")  # noqa: TRY003
        if len(value) > 255:
            raise InputError(f"{field_name} must be at most 255 characters")  # noqa: TRY003
        if not value.isascii() or any(ord(character) < 0x21 or ord(character) > 0x7E for character in value):
            raise InputError(f"{field_name} must contain only printable ASCII characters")  # noqa: TRY003
        return value

    @staticmethod
    def _normalize_workspace_clone_name(value: Any) -> str:
        """Normalize a clone target name using the immutable clone request contract."""
        if not isinstance(value, str):
            raise InputError("name must be a non-empty string")  # noqa: TRY003
        normalized = " ".join(value.split())
        if not normalized:
            raise InputError("name must be non-empty after normalization")  # noqa: TRY003
        if len(normalized) > 255:
            raise InputError("name must be at most 255 characters")  # noqa: TRY003
        return normalized

    @staticmethod
    def _validate_workspace_project_root_backend(backend: Any) -> str:
        """Validate a Workspace-owned project-root backend."""
        normalized = str(backend or "").strip().lower()
        if normalized not in _WORKSPACE_PROJECT_ROOT_BACKENDS:
            raise InputError("workspace project root backend must be 'host_local' or 'sandbox_volume'")  # noqa: TRY003
        return normalized

    @staticmethod
    def _serialize_workspace_project_root_metadata(value: Any) -> str:
        """Serialize project-root metadata while rejecting malformed JSON strings."""
        if value is None:
            return "{}"
        if isinstance(value, str):
            try:
                json.loads(value)
            except json.JSONDecodeError as exc:
                raise InputError("metadata_json must be valid JSON when provided as a string.") from exc  # noqa: TRY003
            return value
        try:
            return json.dumps(value, ensure_ascii=True)
        except TypeError as exc:
            raise InputError("metadata_json must be JSON-serializable.") from exc  # noqa: TRY003

    def _workspace_active_deleted_value(self) -> bool | int:
        return False if self.backend_type == BackendType.POSTGRESQL else 0

    def _workspace_primary_root_value(self) -> bool | int:
        return True if self.backend_type == BackendType.POSTGRESQL else 1

    def _workspace_project_root_row_by_id(
        self,
        conn: sqlite3.Connection | BackendConnectionWrapper,
        workspace_id: str,
        root_id: str,
    ) -> dict[str, Any] | None:
        row = conn.execute(
            """
            SELECT r.*
              FROM workspace_project_roots r
              JOIN workspaces w ON w.id = r.workspace_id
             WHERE r.workspace_id = ?
               AND r.root_id = ?
               AND w.deleted = ?
            """,
            (workspace_id, root_id, self._workspace_active_deleted_value()),
        ).fetchone()
        return dict(row) if row else None

    def _workspace_project_root_integrity_error(self, exc: Exception) -> CharactersRAGDBError:
        message = str(exc).lower()
        if "unique" in message or "duplicate" in message or "foreign key" in message or "constraint" in message:
            return ConflictError(
                f"Workspace project root write conflicted: {exc}",
                entity="workspace_project_roots",
            )
        return CharactersRAGDBError(f"Workspace project root write failed: {exc}")  # noqa: TRY003

    @classmethod
    def _serialize_workspace_assistant_defaults_json(cls, value: Any) -> str | None:
        """Serialize Workspace Assistant Defaults for DB storage."""
        if value is None:
            return None
        if isinstance(value, str):
            stripped = value.strip()
            if not stripped:
                return None
            try:
                parsed = json.loads(stripped)
            except (json.JSONDecodeError, ValueError) as exc:
                raise InputError("assistant_defaults_json must be valid JSON when provided as a string.") from exc
            if not isinstance(parsed, Mapping):
                raise InputError("assistant_defaults_json must be a JSON object or null.")  # noqa: TRY003
            return stripped
        if not isinstance(value, Mapping):
            raise InputError("assistant_defaults_json must be a mapping, JSON object string, or null.")  # noqa: TRY003
        try:
            return json.dumps(dict(value), ensure_ascii=True, sort_keys=True, separators=(",", ":"))
        except (TypeError, ValueError) as exc:
            raise InputError("assistant_defaults_json must be JSON serializable.") from exc

    @classmethod
    def _load_workspace_assistant_defaults_json(cls, value: Any) -> dict[str, Any] | None:
        """Load Workspace Assistant Defaults from DB storage."""
        if value is None:
            return None
        if isinstance(value, Mapping):
            return dict(value)
        if not isinstance(value, str) or not value.strip():
            return None
        try:
            parsed = json.loads(value)
        except (json.JSONDecodeError, ValueError):
            logger.warning("Ignoring malformed workspace assistant_defaults_json stored in the database.")
            return None
        if not isinstance(parsed, Mapping):
            logger.warning("Ignoring non-object workspace assistant_defaults_json stored in the database.")
            return None
        return dict(parsed)

    @classmethod
    def _workspace_row_to_dict(cls, row: Any) -> dict[str, Any]:
        """Convert a workspace DB row to the public DB-layer dict shape."""
        workspace = dict(row)
        if "assistant_defaults_json" in workspace:
            workspace["assistant_defaults_json"] = cls._load_workspace_assistant_defaults_json(
                workspace["assistant_defaults_json"]
            )
        return workspace

    def _get_workspace_internal(
        self,
        workspace_id: str,
        *,
        include_deleted: bool = False,
    ) -> dict[str, Any] | None:
        """Read a Workspace without public lifecycle-marker filtering."""
        query = "SELECT * FROM workspaces WHERE id = ?"
        if not include_deleted:
            query += " AND deleted = 0"
        row = self.execute_query(query, (workspace_id,)).fetchone()
        return self._workspace_row_to_dict(row) if row else None

    def _get_workspace_internal_with_conn(
        self,
        conn: Any,
        workspace_id: str,
        *,
        include_deleted: bool = False,
    ) -> dict[str, Any] | None:
        """Read a Workspace through an existing lifecycle transaction."""
        query = "SELECT * FROM workspaces WHERE id = ?"
        if not include_deleted:
            query += " AND deleted = 0"
        row = conn.execute(query, (workspace_id,)).fetchone()
        return self._workspace_row_to_dict(row) if row else None

    @classmethod
    def _clone_reservation_matches(
        cls,
        row: Mapping[str, Any],
        *,
        operation_id: str,
        request_fingerprint: str,
        name: str,
        description: str | None,
        workspace_profile: str,
    ) -> bool:
        """Return whether an existing row is the exact reusable reservation."""
        return (
            not bool(row.get("deleted"))
            and row.get("system_operation_kind") == cls._WORKSPACE_CLONE_OPERATION_KIND
            and row.get("system_operation_state") in {"staged", "publication_pending"}
            and row.get("system_operation_id") == operation_id
            and row.get("system_request_fingerprint") == request_fingerprint
            and row.get("name") == name
            and row.get("description") == description
            and row.get("workspace_profile") == workspace_profile
        )

    @staticmethod
    def _clone_target_conflict(workspace_id: str) -> ConflictError:
        """Build the controlled collision error for a deterministic target id."""
        return ConflictError(
            f"Workspace clone target '{workspace_id}' is already reserved.",
            entity="workspaces",
            entity_id=workspace_id,
        )

    def reserve_clone_target(
        self,
        *,
        workspace_id: str,
        operation_id: str,
        request_fingerprint: str,
        name: str,
        description: str | None,
        workspace_profile: str,
    ) -> dict[str, Any]:
        """Reserve a deterministic hidden Workspace target for one clone operation."""
        validated_workspace_id = self._validate_workspace_clone_identifier(workspace_id, "workspace_id")
        validated_operation_id = self._validate_workspace_clone_identifier(operation_id, "operation_id")
        validated_fingerprint = self._validate_workspace_clone_identifier(
            request_fingerprint,
            "request_fingerprint",
        )
        normalized_name = self._normalize_workspace_clone_name(name)
        normalized_profile = self._validate_workspace_profile(workspace_profile)
        now = self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                conn.execute(
                    """
                    INSERT INTO workspaces (
                        id, name, description, metadata_json, study_materials_policy,
                        workspace_profile, archived, created_at, last_modified, deleted,
                        client_id, version, system_operation_id, system_operation_kind,
                        system_operation_state, system_request_fingerprint
                    ) VALUES (?, ?, ?, '{}', 'general', ?, ?, ?, ?, ?, ?, 1, ?, ?, 'staged', ?)
                    ON CONFLICT(id) DO NOTHING
                    """,
                    (
                        validated_workspace_id,
                        normalized_name,
                        description,
                        normalized_profile,
                        True,
                        now,
                        now,
                        False,
                        self.client_id or "unknown",
                        validated_operation_id,
                        self._WORKSPACE_CLONE_OPERATION_KIND,
                        validated_fingerprint,
                    ),
                )
                workspace = self._get_workspace_internal_with_conn(
                    conn,
                    validated_workspace_id,
                    include_deleted=True,
                )
                if workspace is None:  # pragma: no cover - defensive database invariant
                    raise CharactersRAGDBError("Failed to load reserved Workspace clone target.")  # noqa: TRY003
                if not self._clone_reservation_matches(
                    workspace,
                    operation_id=validated_operation_id,
                    request_fingerprint=validated_fingerprint,
                    name=normalized_name,
                    description=description,
                    workspace_profile=normalized_profile,
                ):
                    raise self._clone_target_conflict(validated_workspace_id)
                return workspace
        except ConflictError:
            raise
        except (sqlite3.IntegrityError, BackendDatabaseError) as exc:
            raise CharactersRAGDBError("Workspace clone target reservation failed.") from exc  # noqa: TRY003

    def _transition_clone_target(
        self,
        *,
        workspace_id: str,
        operation_id: str,
        expected_state: str,
        set_clause: str,
        set_params: tuple[Any, ...],
    ) -> dict[str, Any]:
        """Apply one exact operation-owned clone lifecycle transition."""
        now = self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                cursor = conn.execute(
                    f"""
                    UPDATE workspaces
                       SET {set_clause}, last_modified = ?, version = version + 1
                     WHERE id = ?
                       AND deleted = ?
                       AND system_operation_id = ?
                       AND system_operation_kind = ?
                       AND system_operation_state = ?
                    """,  # nosec B608 - set_clause is fixed at internal call sites.
                    (
                        *set_params,
                        now,
                        workspace_id,
                        False,
                        operation_id,
                        self._WORKSPACE_CLONE_OPERATION_KIND,
                        expected_state,
                    ),
                )
                if cursor.rowcount != 1:
                    raise self._clone_target_conflict(workspace_id)
                workspace = self._get_workspace_internal_with_conn(conn, workspace_id)
                if workspace is None:  # pragma: no cover - defensive database invariant
                    raise CharactersRAGDBError("Failed to load transitioned Workspace clone target.")  # noqa: TRY003
                return workspace
        except ConflictError:
            raise
        except (sqlite3.IntegrityError, BackendDatabaseError) as exc:
            raise CharactersRAGDBError("Workspace clone target transition failed.") from exc  # noqa: TRY003

    def publish_clone_target(
        self,
        *,
        workspace_id: str,
        operation_id: str,
    ) -> dict[str, Any]:
        """Move an exact owned staged target into hidden publication-pending state."""
        validated_workspace_id = self._validate_workspace_clone_identifier(workspace_id, "workspace_id")
        validated_operation_id = self._validate_workspace_clone_identifier(operation_id, "operation_id")
        return self._transition_clone_target(
            workspace_id=validated_workspace_id,
            operation_id=validated_operation_id,
            expected_state="staged",
            set_clause="archived = ?, system_operation_state = ?",
            set_params=(False, "publication_pending"),
        )

    def confirm_clone_target_publication(
        self,
        *,
        workspace_id: str,
        operation_id: str,
    ) -> dict[str, Any]:
        """Expose an exact owned publication-pending target by clearing all markers."""
        validated_workspace_id = self._validate_workspace_clone_identifier(workspace_id, "workspace_id")
        validated_operation_id = self._validate_workspace_clone_identifier(operation_id, "operation_id")
        return self._transition_clone_target(
            workspace_id=validated_workspace_id,
            operation_id=validated_operation_id,
            expected_state="publication_pending",
            set_clause=(
                "system_operation_id = NULL, system_operation_kind = NULL, "
                "system_operation_state = NULL, system_request_fingerprint = NULL"
            ),
            set_params=(),
        )

    def discard_clone_target(
        self,
        *,
        workspace_id: str,
        operation_id: str,
    ) -> bool:
        """Soft-delete only an exact operation-owned staged or pending clone target."""
        validated_workspace_id = self._validate_workspace_clone_identifier(workspace_id, "workspace_id")
        validated_operation_id = self._validate_workspace_clone_identifier(operation_id, "operation_id")
        now = self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                cursor = conn.execute(
                    """
                    UPDATE workspaces
                       SET deleted = ?, last_modified = ?, version = version + 1
                     WHERE id = ?
                       AND deleted = ?
                       AND system_operation_id = ?
                       AND system_operation_kind = ?
                       AND system_operation_state IN ('staged', 'publication_pending')
                    """,
                    (
                        True,
                        now,
                        validated_workspace_id,
                        False,
                        validated_operation_id,
                        self._WORKSPACE_CLONE_OPERATION_KIND,
                    ),
                )
                return cursor.rowcount == 1
        except (sqlite3.IntegrityError, BackendDatabaseError) as exc:
            raise CharactersRAGDBError("Workspace clone target discard failed.") from exc  # noqa: TRY003

    def list_clone_targets_for_reconciliation(
        self,
        *,
        operation_ids: Sequence[str],
        limit: int = 100,
    ) -> list[dict[str, Any]]:
        """Return a bounded set of caller-correlated staged clone targets."""
        if isinstance(limit, bool) or not isinstance(limit, int) or not 1 <= limit <= 100:
            raise InputError("limit must be an integer between 1 and 100")  # noqa: TRY003
        if isinstance(operation_ids, (str, bytes)) or not isinstance(operation_ids, Sequence):
            raise InputError("operation_ids must be a sequence of identifiers")  # noqa: TRY003
        if len(operation_ids) > self._WORKSPACE_CLONE_RECONCILIATION_MAX:
            raise InputError("operation_ids may contain at most 100 identifiers")  # noqa: TRY003
        if not operation_ids:
            return []
        validated_ids = [
            self._validate_workspace_clone_identifier(operation_id, "operation_id")
            for operation_id in operation_ids
        ]
        placeholders = ", ".join("?" for _ in validated_ids)
        cursor = self.execute_query(
            f"""
            SELECT *
              FROM workspaces
             WHERE deleted = ?
               AND system_operation_kind = ?
               AND system_operation_state IN ('staged', 'publication_pending')
               AND system_operation_id IN ({placeholders})
             ORDER BY system_operation_id ASC, id ASC
             LIMIT ?
            """,  # nosec B608 - placeholders are generated from bounded validated inputs.
            (
                False,
                self._WORKSPACE_CLONE_OPERATION_KIND,
                *validated_ids,
                limit,
            ),
        )
        return [self._workspace_row_to_dict(row) for row in cursor.fetchall()]

    def upsert_workspace(
        self,
        workspace_id: str,
        name: str,
        *,
        description: str | None = None,
        metadata_json: str | None = None,
        study_materials_policy: str = "general",
        workspace_profile: str | None = None,
    ) -> dict[str, Any]:
        """Create a workspace or update the existing row in place.

        If the workspace already exists (and is not deleted), the provided
        mutable fields are applied to the existing row using optimistic locking.

        Returns:
            A dict representing the workspace row.

        Raises:
            InputError: If *workspace_id* or *name* are empty.
            CharactersRAGDBError: On database errors.
        """
        if not workspace_id or not name:
            raise InputError("workspace_id and name are required.")  # noqa: TRY003

        normalized_policy = study_materials_policy or "general"
        normalized_profile = (
            self._validate_workspace_profile(workspace_profile)
            if workspace_profile is not None
            else "research"
        )
        existing = self.get_workspace(workspace_id)
        if existing is not None:
            updates: dict[str, Any] = {}
            if existing.get("name") != name:
                updates["name"] = name
            if description is not None and existing.get("description") != description:
                updates["description"] = description
            if metadata_json is not None and existing.get("metadata_json") != metadata_json:
                updates["metadata_json"] = metadata_json
            if existing.get("study_materials_policy") != normalized_policy:
                updates["study_materials_policy"] = normalized_policy
            if (
                workspace_profile is not None
                and existing.get("workspace_profile", "research") != normalized_profile
            ):
                updates["workspace_profile"] = normalized_profile
            if not updates:
                return existing
            return self.update_workspace(workspace_id, updates, expected_version=int(existing["version"]))

        now = self._get_current_utc_timestamp_iso()
        client_id = self.client_id or "unknown"
        query = (
            "INSERT INTO workspaces "
            "(id, name, description, metadata_json, study_materials_policy, workspace_profile, "
            "created_at, last_modified, deleted, client_id, version) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0, ?, 1)"
        )
        params = (
            workspace_id,
            name,
            description,
            metadata_json or "{}",
            normalized_policy,
            normalized_profile,
            now,
            now,
            client_id,
        )
        try:
            with self.transaction() as conn:
                conn.execute(query, params)
        except (sqlite3.IntegrityError, BackendDatabaseError) as exc:
            # Race condition: another thread inserted between our check and insert.
            existing = self.get_workspace(workspace_id)
            if existing is not None:
                return existing
            if self._get_workspace_internal(workspace_id, include_deleted=True) is not None:
                raise ConflictError(  # noqa: TRY003
                    f"Workspace '{workspace_id}' already exists.",
                    entity="workspaces",
                    entity_id=workspace_id,
                ) from exc
            raise CharactersRAGDBError("Workspace creation failed.") from exc  # noqa: TRY003
        return self.get_workspace(workspace_id)  # type: ignore[return-value]

    def get_workspace(
        self,
        workspace_id: str,
        *,
        include_deleted: bool = False,
    ) -> dict[str, Any] | None:
        """Retrieve a workspace by id, optionally including soft-deleted rows."""
        if include_deleted:
            cursor = self.execute_query(
                "SELECT * FROM workspaces WHERE id = ? AND system_operation_state IS NULL",
                (workspace_id,),
            )
        else:
            cursor = self.execute_query(
                "SELECT * FROM workspaces "
                "WHERE id = ? AND deleted = 0 AND system_operation_state IS NULL",
                (workspace_id,),
            )
        row = cursor.fetchone()
        return self._workspace_row_to_dict(row) if row else None

    def list_workspaces(self) -> list[dict[str, Any]]:
        """Return all non-deleted workspaces ordered by name."""
        query = (
            "SELECT * FROM workspaces "
            "WHERE deleted = 0 AND system_operation_state IS NULL ORDER BY name"
        )
        cursor = self.execute_query(query, ())
        return [self._workspace_row_to_dict(row) for row in cursor.fetchall()]

    def read_workspace_clone_snapshot(self, workspace_id: str) -> WorkspaceCloneSnapshot:
        """Read one active Workspace and its cloneable rows from one source snapshot."""
        from tldw_Server_API.app.core.Sharing.clone_models import (
            CloneSnapshotUnavailable,
            WorkspaceCloneSnapshot,
        )

        if not isinstance(workspace_id, str) or not workspace_id.strip():
            raise CloneSnapshotUnavailable(cleanup_state="complete")

        backend = self.backend
        connection: Any | None = None
        pool: Any | None = None
        committed = False
        primary_error: BaseException | None = None
        cleanup_error: BaseException | None = None
        snapshot: WorkspaceCloneSnapshot | None = None

        try:
            if backend.backend_type == BackendType.SQLITE:
                sqlite_path = str(getattr(backend.config, "sqlite_path", "") or "").strip()
                lowered_path = sqlite_path.lower()
                private_memory = sqlite_path == ":memory:" or (
                    "mode=memory" in lowered_path and "cache=shared" not in lowered_path
                )
                if not sqlite_path or private_memory:
                    raise CloneSnapshotUnavailable(cleanup_state="complete")
                connection = backend.connect()
                connection.execute("PRAGMA query_only = ON")
                query_only_row = connection.execute("PRAGMA query_only").fetchone()
                if query_only_row is None or int(query_only_row[0]) != 1:
                    raise RuntimeError("SQLite query-only mode unavailable")
                connection.execute("BEGIN")
                if not bool(getattr(connection, "in_transaction", False)):
                    raise RuntimeError("SQLite snapshot transaction unavailable")
            else:
                pool = backend.get_pool()
                connection = pool.get_connection()
                connection.rollback()
                backend.apply_and_verify_scope(
                    connection,
                    fallback_user_id=self.client_id,
                )
                with connection.cursor() as cursor:
                    cursor.execute("BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY")
                isolation_rows = backend.execute(
                    "SHOW transaction_isolation",
                    connection=connection,
                    log_errors=False,
                ).rows
                read_only_rows = backend.execute(
                    "SHOW transaction_read_only",
                    connection=connection,
                    log_errors=False,
                ).rows
                isolation = next(iter(isolation_rows[0].values()), None) if isolation_rows else None
                read_only = next(iter(read_only_rows[0].values()), None) if read_only_rows else None
                if str(isolation).lower() != "repeatable read" or str(read_only).lower() not in {
                    "on",
                    "true",
                }:
                    raise RuntimeError("PostgreSQL repeatable read unavailable")

            active_value = False if backend.backend_type == BackendType.POSTGRESQL else 0

            def read_rows(query: str, params: tuple[Any, ...]) -> list[dict[str, Any]]:
                result = backend.execute(
                    query,
                    params,
                    connection=connection,
                    log_errors=False,
                )
                return [dict(row) for row in result.rows]

            workspace_rows = read_rows(
                "SELECT * FROM workspaces "
                "WHERE id = ? AND deleted = ? AND system_operation_state IS NULL",
                (workspace_id, active_value),
            )
            if len(workspace_rows) != 1:
                raise CloneSnapshotUnavailable(cleanup_state="complete")

            membership_rows = read_rows(
                "SELECT * FROM workspace_resource_memberships "
                "WHERE workspace_id = ? AND deleted = ? "
                "ORDER BY updated_at DESC, resource_type ASC, resource_id ASC",
                (workspace_id, active_value),
            )
            source_rows = read_rows(
                "SELECT * FROM workspace_sources WHERE workspace_id = ? "
                "ORDER BY position, added_at",
                (workspace_id,),
            )
            note_rows = read_rows(
                "SELECT * FROM workspace_notes WHERE workspace_id = ? AND deleted = ? "
                "ORDER BY last_modified DESC",
                (workspace_id, active_value),
            )
            artifact_rows = read_rows(
                "SELECT * FROM workspace_artifacts WHERE workspace_id = ? ORDER BY created_at DESC",
                (workspace_id,),
            )

            normalized_memberships = []
            for row in membership_rows:
                normalized = self._normalize_workspace_membership_row(row)
                if normalized is None:
                    raise RuntimeError("Workspace membership row unavailable")
                normalized_memberships.append(normalized)
            normalized_artifacts = []
            for row in artifact_rows:
                normalized = self._normalize_workspace_artifact_row(row)
                if normalized is None:
                    raise RuntimeError("Workspace artifact row unavailable")
                normalized_artifacts.append(normalized)

            snapshot = WorkspaceCloneSnapshot.from_rows(
                workspace=self._workspace_row_to_dict(workspace_rows[0]),
                memberships=normalized_memberships,
                sources=source_rows,
                notes=note_rows,
                artifacts=normalized_artifacts,
            )
            connection.commit()
            committed = True
        except BaseException as exc:  # noqa: BLE001 - cleanup must run for every path
            primary_error = exc

        if connection is not None:
            if not committed:
                try:
                    connection.rollback()
                except BaseException as exc:  # noqa: BLE001 - preserve primary failure
                    cleanup_error = exc
            try:
                if backend.backend_type == BackendType.SQLITE:
                    backend.disconnect(connection)
                else:
                    (pool or backend.get_pool()).return_connection(connection)
            except BaseException as exc:  # noqa: BLE001 - convert cleanup failures below
                cleanup_error = cleanup_error or exc

        if primary_error is not None and not isinstance(primary_error, Exception):
            raise primary_error
        if primary_error is not None or cleanup_error is not None or snapshot is None:
            failure = primary_error or cleanup_error
            logger.bind(
                backend=backend.backend_type.value,
                exception_type=type(failure).__name__ if failure is not None else "Unknown",
            ).warning("Workspace clone snapshot read failed")
            raise CloneSnapshotUnavailable(cleanup_state="complete") from None
        return snapshot

    def update_workspace(
        self,
        workspace_id: str,
        update_data: dict[str, Any],
        expected_version: int,
    ) -> dict[str, Any]:
        """Update a workspace with optimistic locking.

        Returns:
            The updated workspace row dict.

        Raises:
            ConflictError: If the workspace is not found or version mismatch.
        """
        existing = self.get_workspace(workspace_id)
        if existing is None:
            raise ConflictError(  # noqa: TRY003
                f"Workspace '{workspace_id}' not found.",
                entity="workspaces",
                entity_id=workspace_id,
            )
        if existing["version"] != expected_version:
            raise ConflictError(  # noqa: TRY003
                f"Workspace '{workspace_id}' version mismatch (db={existing['version']}, expected={expected_version}).",
                entity="workspaces",
                entity_id=workspace_id,
            )

        now = self._get_current_utc_timestamp_iso()
        workspace_update_columns = (
            "name", "description", "metadata_json", "study_materials_policy", "workspace_profile", "archived", "tag",
            "banner_title", "banner_subtitle", "banner_color",
            "audio_provider", "audio_model", "audio_voice", "audio_speed",
            "assistant_defaults_json",
        )
        if not any(col in update_data for col in workspace_update_columns):
            raise InputError("No recognized workspace fields to update.")  # noqa: TRY003

        set_clauses = ["last_modified = ?", "version = ?"]
        params: list[Any] = [now, expected_version + 1]

        for col in workspace_update_columns:
            if col in update_data:
                set_clauses.append(f"{col} = ?")
                if col == "workspace_profile":
                    params.append(self._validate_workspace_profile(update_data[col]))
                elif col == "assistant_defaults_json":
                    params.append(self._serialize_workspace_assistant_defaults_json(update_data[col]))
                else:
                    params.append(update_data[col])

        query = f"UPDATE workspaces SET {', '.join(set_clauses)} WHERE id = ? AND version = ?"  # nosec B608
        params.extend([workspace_id, expected_version])

        with self.transaction() as conn:
            cursor = conn.execute(query, tuple(params))
            if cursor.rowcount == 0:
                raise ConflictError(  # noqa: TRY003
                    f"Workspace '{workspace_id}' concurrent update detected.",
                    entity="workspaces",
                    entity_id=workspace_id,
                )
        return self.get_workspace(workspace_id)  # type: ignore[return-value]

    def delete_workspace(
        self,
        workspace_id: str,
        expected_version: int,
    ) -> bool:
        """Soft-delete a workspace and cascade soft-delete its scoped conversations.

        Returns:
            True on success.

        Raises:
            ConflictError: If not found or version mismatch.
        """
        existing = self.get_workspace(workspace_id)
        if existing is None:
            raise ConflictError(  # noqa: TRY003
                f"Workspace '{workspace_id}' not found.",
                entity="workspaces",
                entity_id=workspace_id,
            )
        if existing["version"] != expected_version:
            raise ConflictError(  # noqa: TRY003
                f"Workspace '{workspace_id}' version mismatch.",
                entity="workspaces",
                entity_id=workspace_id,
            )

        conversations = self.execute_query(
            "SELECT id, version FROM conversations WHERE workspace_id = ? AND scope_type = ? AND deleted = 0",
            (workspace_id, "workspace"),
        ).fetchall()
        for conversation in conversations:
            conversation_id = conversation["id"] if isinstance(conversation, dict) else conversation[0]
            conversation_version = conversation["version"] if isinstance(conversation, dict) else conversation[1]
            failed_message_ids: set[str] = set()
            while True:
                batch = self.get_messages_for_conversation(conversation_id, limit=100, offset=0)
                batch = [m for m in batch if m.get("id") not in failed_message_ids]
                if not batch:
                    break
                deleted_this_batch = 0
                for message in batch:
                    message_id = message.get("id")
                    if not message_id:
                        continue
                    try:
                        self.soft_delete_message(message_id, message.get("version", 1))
                        deleted_this_batch += 1
                    except _CHACHA_NONCRITICAL_EXCEPTIONS:
                        logger.warning(
                            "Failed to soft-delete message {} during workspace delete {}.",
                            message_id,
                            workspace_id,
                        )
                        failed_message_ids.add(str(message_id))
                if deleted_this_batch == 0:
                    break
            self.soft_delete_conversation(conversation_id, int(conversation_version))

        now = self._get_current_utc_timestamp_iso()
        with self.transaction() as conn:
            conn.execute(
                "UPDATE quizzes "
                "SET workspace_id = NULL, last_modified = ?, version = version + 1, client_id = ? "
                "WHERE workspace_id = ? AND deleted = 0",
                (now, self.client_id, workspace_id),
            )
            conn.execute(
                "UPDATE decks "
                "SET workspace_id = NULL, last_modified = ?, version = version + 1, client_id = ? "
                "WHERE workspace_id = ? AND deleted = 0",
                (now, self.client_id, workspace_id),
            )
            cursor = conn.execute(
                "UPDATE workspaces SET deleted = 1, last_modified = ?, version = ? WHERE id = ? AND version = ?",
                (now, expected_version + 1, workspace_id, expected_version),
            )
            if cursor.rowcount == 0:
                raise ConflictError(  # noqa: TRY003
                    f"Workspace '{workspace_id}' concurrent delete detected.",
                    entity="workspaces",
                    entity_id=workspace_id,
                )
        return True

    def hard_delete_workspace(self, workspace_id: str) -> None:
        """Permanently delete a workspace row. FK CASCADE handles sub-resources."""
        conversations = self.execute_query(
            "SELECT id FROM conversations WHERE workspace_id = ? AND scope_type = ?",
            (workspace_id, "workspace"),
        ).fetchall()
        for conversation in conversations:
            conversation_id = conversation["id"] if isinstance(conversation, dict) else conversation[0]
            self.hard_delete_conversation(str(conversation_id))
        with self.transaction() as conn:
            conn.execute("DELETE FROM workspace_resource_memberships WHERE workspace_id = ?", (workspace_id,))
            conn.execute("DELETE FROM workspace_project_roots WHERE workspace_id = ?", (workspace_id,))
            conn.execute("DELETE FROM workspaces WHERE id = ?", (workspace_id,))

    @staticmethod
    def _normalize_workspace_source_saved_view_name(name: str) -> tuple[str, str]:
        """Return the trimmed display name and Python NFKC/casefold key."""
        if not isinstance(name, str):
            raise InputError("Saved view name must be a string.")  # noqa: TRY003
        CharactersRAGDB._validate_workspace_source_saved_view_utf8_text(name, "name")
        display_name = name.strip()
        if not SOURCE_VIEW_MIN_NAME_LENGTH <= len(display_name) <= SOURCE_VIEW_MAX_NAME_LENGTH:
            raise InputError(  # noqa: TRY003
                f"Saved view name must contain {SOURCE_VIEW_MIN_NAME_LENGTH} to "
                f"{SOURCE_VIEW_MAX_NAME_LENGTH} characters after trimming."
            )
        return display_name, unicodedata.normalize("NFKC", display_name).casefold()

    @staticmethod
    def _validate_workspace_source_saved_view_state_json(state_json: str) -> str:
        """Validate only the raw UTF-8 storage bound; parsing belongs to the API."""
        if not isinstance(state_json, str):
            raise InputError("Saved view state_json must be a string.")  # noqa: TRY003
        encoded = CharactersRAGDB._validate_workspace_source_saved_view_utf8_text(
            state_json,
            "state_json",
        )
        if len(encoded) > SOURCE_VIEW_MAX_STATE_BYTES:
            raise InputError(  # noqa: TRY003
                f"Saved view state_json must not exceed {SOURCE_VIEW_MAX_STATE_BYTES} UTF-8 bytes."
            )
        return state_json

    @staticmethod
    def _validate_workspace_source_saved_view_utf8_text(value: str, field_name: str) -> bytes:
        """Return strict UTF-8 bytes after rejecting database-incompatible NUL text."""
        if "\x00" in value:
            raise InputError(f"Saved view {field_name} must not contain NUL characters.")  # noqa: TRY003
        try:
            return value.encode("utf-8")
        except UnicodeEncodeError as exc:
            raise InputError(f"Saved view {field_name} must contain valid UTF-8 text.") from exc  # noqa: TRY003

    @staticmethod
    def _validate_workspace_source_saved_view_schema_version(schema_version: int) -> int:
        """Require a positive portable integer without interpreting its schema."""
        if (
            isinstance(schema_version, bool)
            or not isinstance(schema_version, int)
            or not 1 <= schema_version <= SOURCE_VIEW_MAX_INTEGER
        ):
            raise InputError(  # noqa: TRY003
                f"Saved view schema_version must be an integer from 1 to {SOURCE_VIEW_MAX_INTEGER}."
            )
        return schema_version

    @staticmethod
    def _validate_workspace_source_saved_view_expected_version(expected_version: int) -> int:
        """Require a positive optimistic-lock version."""
        if (
            isinstance(expected_version, bool)
            or not isinstance(expected_version, int)
            or not 1 <= expected_version <= SOURCE_VIEW_MAX_INTEGER
        ):
            raise InputError(  # noqa: TRY003
                f"Saved view expected_version must be an integer from 1 to {SOURCE_VIEW_MAX_INTEGER}."
            )
        return expected_version

    def _require_workspace_source_saved_view_workspace(
        self,
        conn: Any,
        owner_user_id: str,
        workspace_id: str,
        *,
        lock: bool = False,
    ) -> None:
        """Require an active workspace owned by the explicitly supplied principal."""
        query = "SELECT id FROM workspaces WHERE id = ? AND client_id = ? AND deleted = ?"
        if lock and self.backend_type == BackendType.POSTGRESQL:
            query += " FOR UPDATE"
        row = conn.execute(
            query,
            (workspace_id, owner_user_id, self._workspace_active_deleted_value()),
        ).fetchone()
        if row is None:
            raise WorkspaceSourceSavedViewNotFoundError

    @staticmethod
    def _workspace_source_saved_view_row(row: Any) -> dict[str, Any]:
        """Convert a saved-view database row without parsing state_json."""
        return dict(row)

    def _get_workspace_source_saved_view_with_conn(
        self,
        conn: Any,
        owner_user_id: str,
        workspace_id: str,
        view_id: str,
    ) -> dict[str, Any] | None:
        """Load one row through the complete owner/workspace/view predicate."""
        row = conn.execute(
            """
            SELECT id, workspace_id, owner_user_id, name, name_key, schema_version,
                   state_json, version, created_at, updated_at
              FROM workspace_source_saved_views
             WHERE owner_user_id = ? AND workspace_id = ? AND id = ?
            """,
            (owner_user_id, workspace_id, view_id),
        ).fetchone()
        return self._workspace_source_saved_view_row(row) if row is not None else None

    def _find_workspace_source_saved_view_name_with_conn(
        self,
        conn: Any,
        owner_user_id: str,
        workspace_id: str,
        name_key: str,
        *,
        exclude_view_id: str | None = None,
    ) -> dict[str, Any] | None:
        """Find an owned name conflict and return only safe response metadata."""
        query = (
            "SELECT id, version FROM workspace_source_saved_views "
            "WHERE owner_user_id = ? AND workspace_id = ? AND name_key = ?"
        )
        params: tuple[Any, ...] = (owner_user_id, workspace_id, name_key)
        if exclude_view_id is not None:
            query += " AND id <> ?"
            params += (exclude_view_id,)
        row = conn.execute(query, params).fetchone()
        return dict(row) if row is not None else None

    @staticmethod
    def _raise_workspace_source_saved_view_name_conflict(row: Mapping[str, Any]) -> None:
        """Raise the stable duplicate-name conflict using owned row metadata."""
        raise WorkspaceSourceSavedViewConflictError(
            SOURCE_VIEW_NAME_EXISTS,
            {"view_id": str(row["id"]), "version": int(row["version"])},
        )

    @staticmethod
    def _is_workspace_source_saved_view_sqlite_unique_error(exc: sqlite3.IntegrityError) -> bool:
        """Match only the saved-view owner/workspace/name SQLite unique key."""
        expected_columns = (
            "workspace_source_saved_views.owner_user_id, "
            "workspace_source_saved_views.workspace_id, "
            "workspace_source_saved_views.name_key"
        )
        return (
            getattr(exc, "sqlite_errorname", None) == "SQLITE_CONSTRAINT_UNIQUE"
            and expected_columns in str(exc)
        )

    @staticmethod
    def _is_workspace_source_saved_view_postgres_unique_error(exc: Exception) -> bool:
        """Match only SQLSTATE 23505 for the named saved-view unique constraint."""
        current: BaseException | None = exc
        while current is not None:
            sqlstate = getattr(current, "sqlstate", None) or getattr(current, "pgcode", None)
            diagnostics = getattr(current, "diag", None)
            constraint_name = getattr(diagnostics, "constraint_name", None)
            if (
                sqlstate == "23505"
                and constraint_name == "uq_workspace_source_saved_views_owner_name"
            ):
                return True
            current = current.__cause__
        return False

    def _is_workspace_source_saved_view_unique_error(self, exc: Exception) -> bool:
        """Dispatch precise unique-constraint detection by active backend."""
        if isinstance(exc, sqlite3.IntegrityError):
            return self._is_workspace_source_saved_view_sqlite_unique_error(exc)
        return self._is_workspace_source_saved_view_postgres_unique_error(exc)

    def _raise_workspace_source_saved_view_duplicate_from_fresh_transaction(
        self,
        owner_user_id: str,
        workspace_id: str,
        name_key: str,
    ) -> None:
        """Resolve duplicate metadata through a backend-appropriate fresh transaction."""
        def find_scoped_conflict(conn: Any) -> dict[str, Any]:
            self._require_workspace_source_saved_view_workspace(conn, owner_user_id, workspace_id)
            conflict = self._find_workspace_source_saved_view_name_with_conn(
                conn,
                owner_user_id,
                workspace_id,
                name_key,
            )
            if conflict is None:
                raise WorkspaceSourceSavedViewNotFoundError
            return conflict

        if self.backend_type == BackendType.POSTGRESQL:
            backend = self.backend
            raw_conn = backend.connect()
            conflict: dict[str, Any] | None = None
            workspace_found = False
            try:
                conn = BackendConnectionWrapper(self, raw_conn, backend)
                conn.execute(
                    "SELECT set_config('app.current_user_id', ?, true)",
                    (str(owner_user_id),),
                )
                workspace_found = conn.execute(
                    "SELECT id FROM workspaces WHERE id = ? AND client_id = ? AND deleted = ?",
                    (workspace_id, owner_user_id, self._workspace_active_deleted_value()),
                ).fetchone() is not None
                if workspace_found:
                    conflict = self._find_workspace_source_saved_view_name_with_conn(
                        conn,
                        owner_user_id,
                        workspace_id,
                        name_key,
                    )
                raw_conn.commit()
            except BaseException:
                with contextlib.suppress(_CHACHA_NONCRITICAL_EXCEPTIONS):
                    raw_conn.rollback()
                raise
            finally:
                backend.disconnect(raw_conn)
            if not workspace_found or conflict is None:
                raise WorkspaceSourceSavedViewNotFoundError
            self._raise_workspace_source_saved_view_name_conflict(conflict)

        with self.transaction() as conn:
            conflict = find_scoped_conflict(conn)
        self._raise_workspace_source_saved_view_name_conflict(conflict)

    def create_workspace_source_saved_view(
        self,
        owner_user_id: str,
        workspace_id: str,
        *,
        name: str,
        schema_version: int,
        state_json: str,
    ) -> dict[str, Any]:
        """Create one raw saved view for an active owned workspace."""
        display_name, name_key = self._normalize_workspace_source_saved_view_name(name)
        stored_schema_version = self._validate_workspace_source_saved_view_schema_version(schema_version)
        stored_state_json = self._validate_workspace_source_saved_view_state_json(state_json)
        view_id = str(uuid.uuid4())
        now = self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                self._require_workspace_source_saved_view_workspace(
                    conn,
                    owner_user_id,
                    workspace_id,
                    lock=True,
                )
                conflict = self._find_workspace_source_saved_view_name_with_conn(
                    conn,
                    owner_user_id,
                    workspace_id,
                    name_key,
                )
                if conflict is not None:
                    self._raise_workspace_source_saved_view_name_conflict(conflict)
                count_row = conn.execute(
                    "SELECT COUNT(*) AS total FROM workspace_source_saved_views "
                    "WHERE owner_user_id = ? AND workspace_id = ?",
                    (owner_user_id, workspace_id),
                ).fetchone()
                if count_row is not None and int(count_row["total"]) >= SOURCE_VIEW_MAX_COUNT:
                    raise WorkspaceSourceSavedViewConflictError(
                        SOURCE_VIEW_LIMIT_REACHED,
                        {"limit": SOURCE_VIEW_MAX_COUNT},
                    )
                conn.execute(
                    """
                    INSERT INTO workspace_source_saved_views (
                        id, workspace_id, owner_user_id, name, name_key, schema_version,
                        state_json, version, created_at, updated_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?, ?)
                    """,
                    (
                        view_id,
                        workspace_id,
                        owner_user_id,
                        display_name,
                        name_key,
                        stored_schema_version,
                        stored_state_json,
                        now,
                        now,
                    ),
                )
                created = self._get_workspace_source_saved_view_with_conn(
                    conn,
                    owner_user_id,
                    workspace_id,
                    view_id,
                )
                if created is None:  # pragma: no cover - defensive database invariant
                    raise CharactersRAGDBError("Failed to load created workspace source saved view.")
                return created
        except (sqlite3.IntegrityError, BackendDatabaseError) as exc:
            if not self._is_workspace_source_saved_view_unique_error(exc):
                raise
            self._raise_workspace_source_saved_view_duplicate_from_fresh_transaction(
                owner_user_id,
                workspace_id,
                name_key,
            )
            raise AssertionError("unreachable") from exc  # pragma: no cover

    def list_workspace_source_saved_views(
        self,
        owner_user_id: str,
        workspace_id: str,
    ) -> list[dict[str, Any]]:
        """List raw owned saved views in stable newest-first order."""
        with self.transaction() as conn:
            self._require_workspace_source_saved_view_workspace(conn, owner_user_id, workspace_id)
            rows = conn.execute(
                """
                SELECT id, workspace_id, owner_user_id, name, name_key, schema_version,
                       state_json, version, created_at, updated_at
                  FROM workspace_source_saved_views
                 WHERE owner_user_id = ? AND workspace_id = ?
                 ORDER BY updated_at DESC, name_key ASC, id ASC
                """,
                (owner_user_id, workspace_id),
            ).fetchall()
            return [self._workspace_source_saved_view_row(row) for row in rows]

    def get_workspace_source_saved_view(
        self,
        owner_user_id: str,
        workspace_id: str,
        view_id: str,
    ) -> dict[str, Any]:
        """Get one raw owned saved view or raise the focused not-found error."""
        with self.transaction() as conn:
            self._require_workspace_source_saved_view_workspace(conn, owner_user_id, workspace_id)
            row = self._get_workspace_source_saved_view_with_conn(
                conn,
                owner_user_id,
                workspace_id,
                view_id,
            )
            if row is None:
                raise WorkspaceSourceSavedViewNotFoundError
            return row

    def update_workspace_source_saved_view(
        self,
        owner_user_id: str,
        workspace_id: str,
        view_id: str,
        *,
        expected_version: int,
        name: str | None = None,
        schema_version: int | None = None,
        state_json: str | None = None,
    ) -> dict[str, Any]:
        """Version-update the supplied raw saved-view fields in one transaction."""
        stored_expected_version = self._validate_workspace_source_saved_view_expected_version(expected_version)
        if name is None and schema_version is None and state_json is None:
            raise InputError("Saved view update requires name, schema_version, or state_json.")  # noqa: TRY003
        display_name: str | None = None
        name_key: str | None = None
        if name is not None:
            display_name, name_key = self._normalize_workspace_source_saved_view_name(name)
        stored_schema_version = (
            self._validate_workspace_source_saved_view_schema_version(schema_version)
            if schema_version is not None
            else None
        )
        stored_state_json = (
            self._validate_workspace_source_saved_view_state_json(state_json)
            if state_json is not None
            else None
        )
        try:
            with self.transaction() as conn:
                self._require_workspace_source_saved_view_workspace(
                    conn,
                    owner_user_id,
                    workspace_id,
                    lock=True,
                )
                current = self._get_workspace_source_saved_view_with_conn(
                    conn,
                    owner_user_id,
                    workspace_id,
                    view_id,
                )
                if current is None:
                    raise WorkspaceSourceSavedViewNotFoundError
                current_version = int(current["version"])
                if current_version != stored_expected_version:
                    raise WorkspaceSourceSavedViewConflictError(
                        SOURCE_VIEW_VERSION_CONFLICT,
                        {"view_id": view_id, "current_version": current_version},
                    )
                if current_version >= SOURCE_VIEW_MAX_INTEGER:
                    raise InputError(  # noqa: TRY003
                        "Saved view version has reached the maximum supported value."
                    )
                if name_key is not None:
                    conflict = self._find_workspace_source_saved_view_name_with_conn(
                        conn,
                        owner_user_id,
                        workspace_id,
                        name_key,
                        exclude_view_id=view_id,
                    )
                    if conflict is not None:
                        self._raise_workspace_source_saved_view_name_conflict(conflict)

                assignments = ["updated_at = ?", "version = version + 1"]
                params: list[Any] = [self._get_current_utc_timestamp_iso()]
                if display_name is not None and name_key is not None:
                    assignments.extend(("name = ?", "name_key = ?"))
                    params.extend((display_name, name_key))
                if stored_schema_version is not None:
                    assignments.append("schema_version = ?")
                    params.append(stored_schema_version)
                if stored_state_json is not None:
                    assignments.append("state_json = ?")
                    params.append(stored_state_json)
                params.extend((owner_user_id, workspace_id, view_id, stored_expected_version))
                cursor = conn.execute(
                    f"UPDATE workspace_source_saved_views SET {', '.join(assignments)} "  # nosec B608
                    "WHERE owner_user_id = ? AND workspace_id = ? AND id = ? AND version = ?",
                    tuple(params),
                )
                if cursor.rowcount != 1:
                    latest = self._get_workspace_source_saved_view_with_conn(
                        conn,
                        owner_user_id,
                        workspace_id,
                        view_id,
                    )
                    if latest is None:
                        raise WorkspaceSourceSavedViewNotFoundError
                    raise WorkspaceSourceSavedViewConflictError(
                        SOURCE_VIEW_VERSION_CONFLICT,
                        {"view_id": view_id, "current_version": int(latest["version"])},
                    )
                updated = self._get_workspace_source_saved_view_with_conn(
                    conn,
                    owner_user_id,
                    workspace_id,
                    view_id,
                )
                if updated is None:  # pragma: no cover - defensive database invariant
                    raise WorkspaceSourceSavedViewNotFoundError
                return updated
        except (sqlite3.IntegrityError, BackendDatabaseError) as exc:
            if name_key is None or not self._is_workspace_source_saved_view_unique_error(exc):
                raise
            self._raise_workspace_source_saved_view_duplicate_from_fresh_transaction(
                owner_user_id,
                workspace_id,
                name_key,
            )
            raise AssertionError("unreachable") from exc  # pragma: no cover

    def delete_workspace_source_saved_view(
        self,
        owner_user_id: str,
        workspace_id: str,
        view_id: str,
    ) -> None:
        """Unconditionally delete one owned view after active-workspace validation."""
        with self.transaction() as conn:
            self._require_workspace_source_saved_view_workspace(
                conn,
                owner_user_id,
                workspace_id,
                lock=True,
            )
            cursor = conn.execute(
                "DELETE FROM workspace_source_saved_views "
                "WHERE owner_user_id = ? AND workspace_id = ? AND id = ?",
                (owner_user_id, workspace_id, view_id),
            )
            if cursor.rowcount != 1:
                raise WorkspaceSourceSavedViewNotFoundError

    def upsert_workspace_primary_root(self, workspace_id: str, data: dict[str, Any]) -> dict[str, Any]:
        """Create or replace the primary project root for a workspace."""
        if not workspace_id:
            raise InputError("workspace_id is required.")  # noqa: TRY003
        root_id = str(data.get("root_id") or "").strip()
        if not root_id:
            raise InputError("root_id is required.")  # noqa: TRY003
        backend = self._validate_workspace_project_root_backend(data.get("backend"))
        expected_workspace_version_raw = data.get("expected_workspace_version")
        expected_workspace_version: int | None = None
        if expected_workspace_version_raw is not None:
            if isinstance(expected_workspace_version_raw, bool):
                raise InputError("expected_workspace_version must be an integer when provided.")  # noqa: TRY003
            if isinstance(expected_workspace_version_raw, int):
                expected_workspace_version = expected_workspace_version_raw
            elif isinstance(expected_workspace_version_raw, str):
                normalized_expected_version = expected_workspace_version_raw.strip()
                if not normalized_expected_version or not normalized_expected_version.isdecimal():
                    raise InputError("expected_workspace_version must be an integer when provided.")  # noqa: TRY003
                expected_workspace_version = int(normalized_expected_version)
            else:
                raise InputError("expected_workspace_version must be an integer when provided.")  # noqa: TRY003
        replace_existing = bool(data.get("replace_existing", False))
        metadata_json = (
            self._serialize_workspace_project_root_metadata(data.get("metadata_json"))
            if "metadata_json" in data
            else None
        )
        now = self._get_current_utc_timestamp_iso()
        primary_value = self._workspace_primary_root_value()
        deleted_value = self._workspace_active_deleted_value()

        values = {
            "root_id": root_id,
            "workspace_id": workspace_id,
            "is_primary": primary_value,
            "backend": backend,
            "absolute_root": data.get("absolute_root"),
            "sandbox_volume_id": data.get("sandbox_volume_id"),
            "display_name": data.get("display_name"),
            "root_state": data.get("root_state") or "not_configured",
            "git_state": data.get("git_state") or "absent",
            "file_inventory_state": data.get("file_inventory_state") or "not_started",
            "indexing_state": data.get("indexing_state") or "disabled",
            "sandbox_mount_state": data.get("sandbox_mount_state") or "not_configured",
            "mcp_trust_state": data.get("mcp_trust_state") or "not_configured",
            "metadata_json": metadata_json or "{}",
            "created_at": now,
            "updated_at": now,
            "version": 1,
        }

        try:
            with self.transaction() as conn:
                def update_workspace_for_root_attach() -> None:
                    if expected_workspace_version is None:
                        conn.execute(
                            """
                            UPDATE workspaces
                               SET workspace_profile = 'project',
                                   last_modified = ?,
                                   version = version + 1
                             WHERE id = ? AND deleted = ?
                            """,
                            (now, workspace_id, deleted_value),
                        )
                        return

                    cursor = conn.execute(
                        """
                        UPDATE workspaces
                           SET workspace_profile = 'project',
                               last_modified = ?,
                               version = version + 1
                         WHERE id = ? AND deleted = ? AND version = ?
                        """,
                        (now, workspace_id, deleted_value, expected_workspace_version),
                    )
                    if cursor.rowcount == 0:
                        raise ConflictError(
                            f"Workspace '{workspace_id}' concurrent root attach detected.",
                            entity="workspaces",
                            entity_id=workspace_id,
                        )

                workspace_row = conn.execute(
                    "SELECT id, workspace_profile, version FROM workspaces WHERE id = ? AND deleted = ?",
                    (workspace_id, deleted_value),
                ).fetchone()
                if workspace_row is None:
                    raise ConflictError(
                        f"Workspace '{workspace_id}' not found.",
                        entity="workspaces",
                        entity_id=workspace_id,
                    )
                workspace = dict(workspace_row)
                if (
                    expected_workspace_version is not None
                    and int(workspace["version"]) != expected_workspace_version
                ):
                    raise ConflictError(
                        f"Workspace '{workspace_id}' version mismatch "
                        f"(db={workspace['version']}, expected={expected_workspace_version}).",
                        entity="workspaces",
                        entity_id=workspace_id,
                    )
                existing_primary_row = conn.execute(
                    """
                    SELECT *
                      FROM workspace_project_roots
                     WHERE workspace_id = ?
                       AND is_primary = ?
                    """,
                    (workspace_id, primary_value),
                ).fetchone()
                existing_primary = dict(existing_primary_row) if existing_primary_row else None
                root_binding_changed = existing_primary is None or existing_primary.get("root_id") != root_id

                if existing_primary is not None and existing_primary.get("root_id") == root_id:
                    if existing_primary.get("backend") != backend:
                        if not replace_existing:
                            raise ConflictError(
                                f"Workspace project root '{root_id}' backend mismatch.",
                                entity="workspace_project_roots",
                                entity_id=root_id,
                            )
                        root_binding_changed = True
                    else:
                        binding_columns = (
                            "absolute_root",
                            "sandbox_volume_id",
                            "display_name",
                            "metadata_json",
                        )
                        operational_columns = (
                            "root_state",
                            "git_state",
                            "file_inventory_state",
                            "indexing_state",
                            "sandbox_mount_state",
                            "mcp_trust_state",
                        )
                        root_updates: dict[str, Any] = {}
                        for column in binding_columns:
                            if column not in data:
                                continue
                            new_value = metadata_json if column == "metadata_json" else values[column]
                            if existing_primary.get(column) != new_value:
                                root_updates[column] = new_value
                        for column in operational_columns:
                            if column not in data:
                                continue
                            new_value = values[column]
                            if existing_primary.get(column) != new_value:
                                root_updates[column] = new_value
                        if root_updates:
                            root_binding_changed = True
                            set_clauses = ["updated_at = ?", "version = ?"]
                            params: list[Any] = [now, int(existing_primary["version"]) + 1]
                            for column, value in root_updates.items():
                                set_clauses.append(f"{column} = ?")
                                params.append(value)
                            params.extend([workspace_id, root_id])
                            conn.execute(
                                f"""
                                UPDATE workspace_project_roots
                                   SET {', '.join(set_clauses)}
                                 WHERE workspace_id = ?
                                   AND root_id = ?
                                """,  # nosec B608
                                tuple(params),
                            )
                        root = self._workspace_project_root_row_by_id(conn, workspace_id, root_id)
                        if root is None:
                            raise CharactersRAGDBError(  # noqa: TRY003
                                f"Failed to reload workspace project root '{root_id}'."
                            )
                        if root_binding_changed or workspace.get("workspace_profile") != "project":
                            update_workspace_for_root_attach()
                        return root
                if existing_primary is None or existing_primary.get("root_id") != root_id or replace_existing:
                    conn.execute(
                        "DELETE FROM workspace_project_roots WHERE workspace_id = ? AND is_primary = ?",
                        (workspace_id, primary_value),
                    )
                    conn.execute(
                        """
                        INSERT INTO workspace_project_roots (
                            root_id, workspace_id, is_primary, backend, absolute_root, sandbox_volume_id,
                            display_name, root_state, git_state, file_inventory_state, indexing_state,
                            sandbox_mount_state, mcp_trust_state, metadata_json, created_at, updated_at, version
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                        """,
                        (
                            values["root_id"],
                            values["workspace_id"],
                            values["is_primary"],
                            values["backend"],
                            values["absolute_root"],
                            values["sandbox_volume_id"],
                            values["display_name"],
                            values["root_state"],
                            values["git_state"],
                            values["file_inventory_state"],
                            values["indexing_state"],
                            values["sandbox_mount_state"],
                            values["mcp_trust_state"],
                            values["metadata_json"],
                            values["created_at"],
                            values["updated_at"],
                            values["version"],
                        ),
                    )
                if root_binding_changed or workspace.get("workspace_profile") != "project":
                    update_workspace_for_root_attach()
                root = self._workspace_project_root_row_by_id(conn, workspace_id, root_id)
                if root is None:
                    raise CharactersRAGDBError(  # noqa: TRY003
                        f"Failed to reload workspace project root '{root_id}'."
                    )
                return root
        except ConflictError:
            raise
        except sqlite3.IntegrityError as exc:
            raise self._workspace_project_root_integrity_error(exc) from exc
        except BackendDatabaseError as exc:
            raise self._workspace_project_root_integrity_error(exc) from exc
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Workspace project root write failed: {exc}") from exc  # noqa: TRY003

    def get_workspace_primary_root(self, workspace_id: str) -> dict[str, Any] | None:
        """Return the active primary project root for a non-deleted workspace."""
        if not workspace_id:
            return None
        cursor = self.execute_query(
            """
            SELECT r.*
              FROM workspace_project_roots r
              JOIN workspaces w ON w.id = r.workspace_id
             WHERE r.workspace_id = ?
               AND r.is_primary = ?
               AND w.deleted = ?
             ORDER BY r.created_at DESC
             LIMIT 1
            """,
            (workspace_id, self._workspace_primary_root_value(), self._workspace_active_deleted_value()),
        )
        row = cursor.fetchone()
        return dict(row) if row else None

    def list_workspace_project_roots(self, workspace_id: str) -> list[dict[str, Any]]:
        """Return project roots for a non-deleted workspace."""
        if not workspace_id:
            return []
        cursor = self.execute_query(
            """
            SELECT r.*
              FROM workspace_project_roots r
              JOIN workspaces w ON w.id = r.workspace_id
             WHERE r.workspace_id = ?
               AND w.deleted = ?
             ORDER BY r.is_primary DESC, r.created_at ASC, r.root_id ASC
            """,
            (workspace_id, self._workspace_active_deleted_value()),
        )
        return [dict(row) for row in cursor.fetchall()]

    def update_workspace_project_root_state(
        self,
        workspace_id: str,
        root_id: str,
        updates: dict[str, Any],
        expected_version: int,
    ) -> dict[str, Any]:
        """Update mutable project-root state with optimistic locking."""
        if not workspace_id or not root_id:
            raise InputError("workspace_id and root_id are required.")  # noqa: TRY003
        operational_updates = {
            "root_state",
            "git_state",
            "file_inventory_state",
            "indexing_state",
            "sandbox_mount_state",
            "mcp_trust_state",
        }
        clean_updates: dict[str, Any] = {}
        for key, value in (updates or {}).items():
            if key not in operational_updates:
                raise InputError(f"Unsupported workspace project root state field: {key}")  # noqa: TRY003
            clean_updates[key] = value
        existing = self.get_workspace_primary_root(workspace_id)
        if existing is None or existing.get("root_id") != root_id:
            raise ConflictError(
                f"Workspace project root '{root_id}' not found.",
                entity="workspace_project_roots",
                entity_id=root_id,
            )
        if int(existing["version"]) != int(expected_version):
            raise ConflictError(
                f"Workspace project root '{root_id}' version mismatch.",
                entity="workspace_project_roots",
                entity_id=root_id,
            )
        if not clean_updates:
            return existing

        now = self._get_current_utc_timestamp_iso()
        set_clauses = ["updated_at = ?", "version = ?"]
        params: list[Any] = [now, int(expected_version) + 1]
        for key, value in clean_updates.items():
            set_clauses.append(f"{key} = ?")
            params.append(value)
        params.extend([workspace_id, root_id, int(expected_version)])

        try:
            with self.transaction() as conn:
                cursor = conn.execute(
                    f"""
                    UPDATE workspace_project_roots
                       SET {', '.join(set_clauses)}
                     WHERE workspace_id = ?
                       AND root_id = ?
                       AND version = ?
                    """,  # nosec B608
                    tuple(params),
                )
                if cursor.rowcount == 0:
                    raise ConflictError(
                        f"Workspace project root '{root_id}' concurrent update detected.",
                        entity="workspace_project_roots",
                        entity_id=root_id,
                    )
                root = self._workspace_project_root_row_by_id(conn, workspace_id, root_id)
                if root is None:
                    raise CharactersRAGDBError(  # noqa: TRY003
                        f"Failed to reload workspace project root '{root_id}'."
                    )
                return root
        except ConflictError:
            raise
        except sqlite3.IntegrityError as exc:
            raise self._workspace_project_root_integrity_error(exc) from exc
        except BackendDatabaseError as exc:
            raise self._workspace_project_root_integrity_error(exc) from exc
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Workspace project root update failed: {exc}") from exc  # noqa: TRY003

    @staticmethod
    def _validate_workspace_operation_status(status: Any) -> str:
        normalized = str(status or "").strip().lower()
        if normalized not in WORKSPACE_OPERATION_STATUSES:
            raise InputError("workspace operation status is invalid.")  # noqa: TRY003
        return normalized

    @staticmethod
    def _workspace_operation_json(value: Any, *, diagnostics: bool = False) -> str:
        payload = redact_operation_diagnostics(value) if diagnostics else (value or {})
        if isinstance(payload, str):
            try:
                json.loads(payload)
            except json.JSONDecodeError as exc:
                raise InputError("workspace operation JSON fields must contain valid JSON.") from exc  # noqa: TRY003
            return payload
        try:
            return json.dumps(payload, ensure_ascii=True)
        except TypeError as exc:
            raise InputError("workspace operation values must be JSON serializable.") from exc  # noqa: TRY003

    @staticmethod
    def _workspace_operation_json_load(value: Any) -> dict[str, Any]:
        if isinstance(value, dict):
            return dict(value)
        if value is None:
            return {}
        try:
            loaded = json.loads(str(value))
        except (TypeError, ValueError, json.JSONDecodeError):
            return {}
        return dict(loaded) if isinstance(loaded, dict) else {}

    def _workspace_operation_row(self, row: Any) -> dict[str, Any] | None:
        if row is None:
            return None
        payload = dict(row)
        payload["result_ref"] = self._workspace_operation_json_load(payload.pop("result_ref_json", None))
        payload["diagnostics"] = redact_operation_diagnostics(
            self._workspace_operation_json_load(payload.pop("diagnostics_json", None))
        )
        return payload

    @staticmethod
    def _workspace_operation_integrity_error(exc: Exception) -> CharactersRAGDBError:
        message = str(exc).lower()
        if "unique" in message or "duplicate" in message or "foreign key" in message or "constraint" in message:
            return ConflictError(
                f"Workspace operation write conflicted: {exc}",
                entity="workspace_operations",
            )
        return CharactersRAGDBError(f"Workspace operation write failed: {exc}")  # noqa: TRY003

    @staticmethod
    def _workspace_operation_timestamp(value: datetime | str | None) -> str | None:
        if value is None:
            return None
        if isinstance(value, datetime):
            return value.astimezone(timezone.utc).isoformat()
        text = str(value).strip()
        return text or None

    def create_workspace_operation(
        self,
        *,
        workspace_id: str,
        user_id: str,
        command: str,
        idempotency_key: str,
        request_fingerprint: str,
        linked_idempotency_key: str | None = None,
        status: str = "queued",
        result_ref: Mapping[str, Any] | None = None,
        diagnostics: Mapping[str, Any] | None = None,
        expires_at: datetime | str | None = None,
    ) -> dict[str, Any]:
        """Create an idempotent Workspace operation or return the matching existing row."""
        workspace_key = str(workspace_id or "").strip()
        user_key = str(user_id or "").strip()
        command_key = str(command or "").strip()
        key = str(idempotency_key or "").strip()
        fingerprint = str(request_fingerprint or "").strip()
        if not workspace_key or not user_key or not command_key or not key or not fingerprint:
            raise InputError(
                "workspace_id, user_id, command, idempotency_key, and request_fingerprint are required."
            )  # noqa: TRY003
        normalized_status = self._validate_workspace_operation_status(status)
        self._delete_expired_workspace_operation_idempotency(
            workspace_id=workspace_key,
            user_id=user_key,
            command=command_key,
            idempotency_key=key,
        )
        existing = self.get_workspace_operation_by_idempotency(
            workspace_id=workspace_key,
            user_id=user_key,
            command=command_key,
            idempotency_key=key,
        )
        if existing is not None:
            if existing.get("request_fingerprint") != fingerprint:
                raise ConflictError(
                    "Workspace operation idempotency key was reused with a different request.",
                    entity="workspace_operations",
                    entity_id=str(existing.get("id") or ""),
                )
            return existing
        if self.get_workspace(workspace_key) is None:
            raise ConflictError(
                f"Workspace '{workspace_key}' not found.",
                entity="workspaces",
                entity_id=workspace_key,
            )

        now = self._get_current_utc_timestamp_iso()
        operation_id = f"wop_{uuid.uuid4().hex}"
        expiry = self._workspace_operation_timestamp(expires_at)
        if expiry is None:
            expiry = (datetime.now(timezone.utc) + timedelta(hours=24)).isoformat()
        params = (
            operation_id,
            workspace_key,
            user_key,
            command_key,
            key,
            fingerprint,
            linked_idempotency_key,
            normalized_status,
            self._workspace_operation_json(result_ref),
            self._workspace_operation_json(diagnostics, diagnostics=True),
            now,
            now,
            expiry,
        )
        try:
            with self.transaction() as conn:
                conn.execute(
                    """
                    INSERT INTO workspace_operations (
                        id, workspace_id, user_id, command, idempotency_key,
                        request_fingerprint, linked_idempotency_key, status,
                        result_ref_json, diagnostics_json, created_at, updated_at, expires_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    params,
                )
        except (sqlite3.IntegrityError, BackendDatabaseError) as exc:
            raced = self.get_workspace_operation_by_idempotency(
                workspace_id=workspace_key,
                user_id=user_key,
                command=command_key,
                idempotency_key=key,
            )
            if raced is not None:
                if raced.get("request_fingerprint") == fingerprint:
                    return raced
                raise ConflictError(
                    "Workspace operation idempotency key was reused with a different request.",
                    entity="workspace_operations",
                    entity_id=str(raced.get("id") or ""),
                ) from exc
            raise self._workspace_operation_integrity_error(exc) from exc
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Workspace operation create failed: {exc}") from exc  # noqa: TRY003
        created = self.get_workspace_operation(workspace_key, operation_id)
        if created is None:
            raise CharactersRAGDBError("Failed to reload created workspace operation.")  # noqa: TRY003
        return created

    def _delete_expired_workspace_operation_idempotency(
        self,
        *,
        workspace_id: str,
        user_id: str,
        command: str,
        idempotency_key: str,
    ) -> int:
        """Remove an expired operation envelope before reusing an idempotency tuple."""
        now = self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                cursor = conn.execute(
                    """
                    DELETE FROM workspace_operations
                     WHERE workspace_id = ?
                       AND user_id = ?
                       AND command = ?
                       AND idempotency_key = ?
                       AND expires_at IS NOT NULL
                       AND expires_at < ?
                    """,
                    (workspace_id, user_id, command, idempotency_key, now),
                )
                return int(getattr(cursor, "rowcount", 0) or 0)
        except (sqlite3.Error, BackendDatabaseError) as exc:
            raise self._workspace_operation_integrity_error(exc) from exc

    def get_workspace_operation(self, workspace_id: str, operation_id: str) -> dict[str, Any] | None:
        """Return a Workspace operation by id."""
        workspace_key = str(workspace_id or "").strip()
        operation_key = str(operation_id or "").strip()
        if not workspace_key or not operation_key:
            return None
        cursor = self.execute_query(
            """
            SELECT *
              FROM workspace_operations
             WHERE workspace_id = ?
               AND id = ?
            """,
            (workspace_key, operation_key),
        )
        return self._workspace_operation_row(cursor.fetchone())

    def get_workspace_operation_by_idempotency(
        self,
        *,
        workspace_id: str,
        user_id: str,
        command: str,
        idempotency_key: str,
    ) -> dict[str, Any] | None:
        """Return a Workspace operation by command idempotency key."""
        workspace_key = str(workspace_id or "").strip()
        user_key = str(user_id or "").strip()
        command_key = str(command or "").strip()
        key = str(idempotency_key or "").strip()
        if not workspace_key or not user_key or not command_key or not key:
            return None
        cursor = self.execute_query(
            """
            SELECT *
              FROM workspace_operations
             WHERE workspace_id = ?
               AND user_id = ?
               AND command = ?
               AND idempotency_key = ?
            """,
            (workspace_key, user_key, command_key, key),
        )
        return self._workspace_operation_row(cursor.fetchone())

    def update_workspace_operation(
        self,
        workspace_id: str,
        operation_id: str,
        *,
        status: str | None = None,
        result_ref: Mapping[str, Any] | None = None,
        diagnostics: Mapping[str, Any] | None = None,
        expires_at: datetime | str | None = None,
    ) -> dict[str, Any]:
        """Update mutable Workspace operation fields."""
        existing = self.get_workspace_operation(workspace_id, operation_id)
        if existing is None:
            raise ConflictError(
                f"Workspace operation '{operation_id}' not found.",
                entity="workspace_operations",
                entity_id=operation_id,
            )
        set_clauses = ["updated_at = ?"]
        params: list[Any] = [self._get_current_utc_timestamp_iso()]
        if status is not None:
            set_clauses.append("status = ?")
            params.append(self._validate_workspace_operation_status(status))
        if result_ref is not None:
            set_clauses.append("result_ref_json = ?")
            params.append(self._workspace_operation_json(result_ref))
        if diagnostics is not None:
            set_clauses.append("diagnostics_json = ?")
            params.append(self._workspace_operation_json(diagnostics, diagnostics=True))
        if expires_at is not None:
            set_clauses.append("expires_at = ?")
            params.append(self._workspace_operation_timestamp(expires_at))
        params.extend([workspace_id, operation_id])
        try:
            with self.transaction() as conn:
                cursor = conn.execute(
                    f"""
                    UPDATE workspace_operations
                       SET {', '.join(set_clauses)}
                     WHERE workspace_id = ?
                       AND id = ?
                    """,  # nosec B608
                    tuple(params),
                )
                if cursor.rowcount == 0:
                    raise ConflictError(
                        f"Workspace operation '{operation_id}' concurrent update detected.",
                        entity="workspace_operations",
                        entity_id=operation_id,
                    )
        except ConflictError:
            raise
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Workspace operation update failed: {exc}") from exc  # noqa: TRY003
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Workspace operation update failed: {exc}") from exc  # noqa: TRY003
        updated = self.get_workspace_operation(workspace_id, operation_id)
        if updated is None:
            raise CharactersRAGDBError("Failed to reload updated workspace operation.")  # noqa: TRY003
        return updated

    def cleanup_expired_workspace_operations(self, *, now: datetime | str | None = None) -> int:
        """Delete expired operation envelopes without touching linked Workspace roots."""
        now_iso = self._workspace_operation_timestamp(now) or datetime.now(timezone.utc).isoformat()
        try:
            with self.transaction() as conn:
                cursor = conn.execute(
                    """
                    DELETE FROM workspace_operations
                     WHERE expires_at IS NOT NULL
                       AND expires_at <= ?
                    """,
                    (now_iso,),
                )
                return int(getattr(cursor, "rowcount", 0) or 0)
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Workspace operation cleanup failed: {exc}") from exc  # noqa: TRY003
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Workspace operation cleanup failed: {exc}") from exc  # noqa: TRY003

    def list_active_workspace_operations(self, workspace_id: str) -> list[dict[str, Any]]:
        """Return non-expired active operations for a workspace."""
        workspace_key = str(workspace_id or "").strip()
        if not workspace_key:
            return []
        now_iso = datetime.now(timezone.utc).isoformat()
        active_statuses = sorted(WORKSPACE_OPERATION_ACTIVE_STATUSES)
        cursor = self.execute_query(
            """
            SELECT *
              FROM workspace_operations
             WHERE workspace_id = ?
               AND status IN (?, ?)
               AND (expires_at IS NULL OR expires_at > ?)
             ORDER BY created_at ASC, id ASC
            """,
            (workspace_key, active_statuses[0], active_statuses[1], now_iso),
        )
        return [
            operation
            for row in cursor.fetchall()
            if (operation := self._workspace_operation_row(row)) is not None
        ]

    # --- Workspace File Inventory Methods ---

    def _workspace_file_inventory_bool_value(self, value: bool) -> bool | int:
        return bool(value) if self.backend_type == BackendType.POSTGRESQL else int(bool(value))

    @staticmethod
    def _workspace_file_inventory_integrity_error(exc: Exception) -> CharactersRAGDBError:
        message = str(exc).lower()
        if "unique" in message or "duplicate" in message or "foreign key" in message or "constraint" in message:
            return ConflictError(
                f"Workspace file inventory write conflicted: {exc}",
                entity="workspace_file_inventory",
            )
        return CharactersRAGDBError(f"Workspace file inventory write failed: {exc}")  # noqa: TRY003

    @staticmethod
    def _workspace_file_inventory_int(value: Any, *, field_name: str, required: bool = False) -> int | None:
        if value is None:
            if required:
                raise InputError(f"{field_name} is required.")  # noqa: TRY003
            return None
        if isinstance(value, bool):
            raise InputError(f"{field_name} must be an integer.")  # noqa: TRY003
        if isinstance(value, int):
            return value
        if isinstance(value, str):
            stripped = value.strip()
            if stripped and (stripped.isdecimal() or (stripped.startswith("-") and stripped[1:].isdecimal())):
                return int(stripped)
        raise InputError(f"{field_name} must be an integer.")  # noqa: TRY003

    @staticmethod
    def _workspace_file_inventory_json(value: Any, *, default: Any) -> str:
        if value is None:
            value = default
        if isinstance(value, str):
            try:
                json.loads(value)
            except json.JSONDecodeError as exc:
                raise InputError("workspace file inventory JSON fields must contain valid JSON.") from exc  # noqa: TRY003
            return value
        try:
            return json.dumps(value, ensure_ascii=True)
        except TypeError as exc:
            raise InputError("workspace file inventory values must be JSON serializable.") from exc  # noqa: TRY003

    @staticmethod
    def _workspace_file_inventory_json_load(value: Any, *, fallback: Any) -> Any:
        if isinstance(value, (dict, list)):
            return value
        if not isinstance(value, str) or not value.strip():
            return fallback
        try:
            return json.loads(value)
        except json.JSONDecodeError:
            return fallback

    def _workspace_file_inventory_counts_json(self, value: Any) -> str:
        return json.dumps(normalize_inventory_counts(value), ensure_ascii=True)

    def _workspace_file_inventory_diagnostics_json(self, value: Any) -> str:
        return json.dumps(bounded_inventory_diagnostics(value), ensure_ascii=True)

    def _workspace_file_inventory_scan_by_id(
        self,
        scan_id: str,
        *,
        conn: sqlite3.Connection | BackendConnectionWrapper | None = None,
    ) -> dict[str, Any] | None:
        query = "SELECT * FROM workspace_file_inventory_scans WHERE scan_id = ?"
        if conn is None:
            row = self.execute_query(query, (scan_id,)).fetchone()
        else:
            row = conn.execute(query, (scan_id,)).fetchone()
        return dict(row) if row else None

    def _workspace_file_inventory_require_scan(
        self,
        scan_id: str,
        *,
        conn: sqlite3.Connection | BackendConnectionWrapper,
    ) -> dict[str, Any]:
        scan = self._workspace_file_inventory_scan_by_id(scan_id, conn=conn)
        if scan is None:
            raise ConflictError(
                f"Workspace file inventory scan '{scan_id}' not found.",
                entity="workspace_file_inventory_scans",
                entity_id=scan_id,
            )
        return scan

    def _workspace_file_inventory_update_root_state(
        self,
        conn: sqlite3.Connection | BackendConnectionWrapper,
        *,
        workspace_id: str,
        root_id: str,
        state: str,
        updated_at: str,
    ) -> None:
        conn.execute(
            """
            UPDATE workspace_project_roots
               SET file_inventory_state = ?,
                   updated_at = ?
             WHERE workspace_id = ?
               AND root_id = ?
            """,
            (state, updated_at, workspace_id, root_id),
        )

    @staticmethod
    def _workspace_file_inventory_relative_path(value: Any) -> str:
        try:
            return sort_inventory_relative_paths([str(value or "")])[0]
        except ValueError as exc:
            raise InputError("relative_path must be a safe project-root-relative path.") from exc  # noqa: TRY003

    @staticmethod
    def _workspace_file_inventory_prefix(value: Any) -> str | None:
        if value is None:
            return None
        raw = str(value).strip().replace("\\", "/")
        if not raw:
            return None
        if raw.startswith("/") or raw.startswith("~"):
            raise InputError("prefix must be project-root-relative.")  # noqa: TRY003
        had_trailing_slash = raw.endswith("/")
        parts: list[str] = []
        for part in raw.split("/"):
            if not part or part == ".":
                continue
            if part == "..":
                raise InputError("prefix must not contain parent directory traversal.")  # noqa: TRY003
            parts.append(part)
        if not parts:
            return None
        normalized = "/".join(parts)
        return f"{normalized}/" if had_trailing_slash else normalized

    def begin_workspace_file_inventory_scan(
        self,
        workspace_id: str,
        root_id: str,
        root_version: int,
        policy_fingerprint: str,
        *,
        requested_by: str | None = None,
    ) -> dict[str, Any]:
        """Create a queued Workspace file inventory scan or reuse an active scan with an attached job."""
        normalized_workspace_id = str(workspace_id or "").strip()
        normalized_root_id = str(root_id or "").strip()
        normalized_policy = str(policy_fingerprint or "").strip()
        normalized_root_version = self._workspace_file_inventory_int(
            root_version,
            field_name="root_version",
            required=True,
        )
        if not normalized_workspace_id or not normalized_root_id or not normalized_policy:
            raise InputError("workspace_id, root_id, and policy_fingerprint are required.")  # noqa: TRY003

        now = self._get_current_utc_timestamp_iso()
        scan_id = f"ws-file-scan-{uuid.uuid4().hex}"
        try:
            with self.transaction() as conn:
                root = self._workspace_project_root_row_by_id(conn, normalized_workspace_id, normalized_root_id)
                if root is None:
                    raise ConflictError(
                        f"Workspace project root '{normalized_root_id}' not found.",
                        entity="workspace_project_roots",
                        entity_id=normalized_root_id,
                    )
                if int(root["version"]) != int(normalized_root_version):
                    raise ConflictError(
                        f"Workspace project root '{normalized_root_id}' version mismatch.",
                        entity="workspace_project_roots",
                        entity_id=normalized_root_id,
                    )
                active = conn.execute(
                    """
                    SELECT *
                      FROM workspace_file_inventory_scans
                     WHERE workspace_id = ?
                       AND root_id = ?
                       AND root_version = ?
                       AND ignore_policy_fingerprint = ?
                       AND state IN ('queued', 'scanning')
                       AND job_id IS NOT NULL
                     ORDER BY created_at DESC, scan_id DESC
                     LIMIT 1
                    """,
                    (
                        normalized_workspace_id,
                        normalized_root_id,
                        normalized_root_version,
                        normalized_policy,
                    ),
                ).fetchone()
                if active is not None:
                    return dict(active)

                conn.execute(
                    """
                    INSERT INTO workspace_file_inventory_scans (
                        scan_id, workspace_id, root_id, root_version, state, requested_by,
                        ignore_policy_fingerprint, counts_json, diagnostics_json, created_at, updated_at, version
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)
                    """,
                    (
                        scan_id,
                        normalized_workspace_id,
                        normalized_root_id,
                        normalized_root_version,
                        "queued",
                        str(requested_by).strip() if requested_by is not None else None,
                        normalized_policy,
                        self._workspace_file_inventory_counts_json({}),
                        self._workspace_file_inventory_diagnostics_json([]),
                        now,
                        now,
                    ),
                )
                self._workspace_file_inventory_update_root_state(
                    conn,
                    workspace_id=normalized_workspace_id,
                    root_id=normalized_root_id,
                    state="queued",
                    updated_at=now,
                )
                created = self._workspace_file_inventory_scan_by_id(scan_id, conn=conn)
                if created is None:
                    raise CharactersRAGDBError(  # noqa: TRY003
                        f"Failed to read workspace file inventory scan '{scan_id}' after create."
                    )
                return created
        except ConflictError:
            raise
        except sqlite3.IntegrityError as exc:
            raise self._workspace_file_inventory_integrity_error(exc) from exc
        except BackendDatabaseError as exc:
            raise self._workspace_file_inventory_integrity_error(exc) from exc
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Workspace file inventory scan create failed: {exc}") from exc  # noqa: TRY003

    def attach_workspace_file_inventory_job(self, scan_id: str, job_row: Mapping[str, Any]) -> dict[str, Any]:
        """Attach a Jobs row to a queued Workspace file inventory scan idempotently."""
        normalized_scan_id = str(scan_id or "").strip()
        if not normalized_scan_id:
            raise InputError("scan_id is required.")  # noqa: TRY003
        if not isinstance(job_row, Mapping):
            raise InputError("job_row must be a mapping.")  # noqa: TRY003
        job_id = self._workspace_file_inventory_int(
            job_row.get("job_id", job_row.get("id")),
            field_name="job_id",
            required=True,
        )
        job_uuid = str(job_row.get("job_uuid") or job_row.get("uuid") or job_id).strip()
        now = self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                scan = self._workspace_file_inventory_require_scan(normalized_scan_id, conn=conn)
                if scan.get("job_id") is not None:
                    if int(scan["job_id"]) == int(job_id) and str(scan.get("job_uuid") or "") == job_uuid:
                        return scan
                    raise ConflictError(
                        f"Workspace file inventory scan '{normalized_scan_id}' already has a different job.",
                        entity="workspace_file_inventory_scans",
                        entity_id=normalized_scan_id,
                    )
                conn.execute(
                    """
                    UPDATE workspace_file_inventory_scans
                       SET job_id = ?,
                           job_uuid = ?,
                           updated_at = ?,
                           version = version + 1
                     WHERE scan_id = ?
                    """,
                    (job_id, job_uuid, now, normalized_scan_id),
                )
                updated = self._workspace_file_inventory_scan_by_id(normalized_scan_id, conn=conn)
                if updated is None:
                    raise CharactersRAGDBError(  # noqa: TRY003
                        f"Failed to read workspace file inventory scan '{normalized_scan_id}' after job attach."
                    )
                return updated
        except ConflictError:
            raise
        except sqlite3.IntegrityError as exc:
            raise self._workspace_file_inventory_integrity_error(exc) from exc
        except BackendDatabaseError as exc:
            raise self._workspace_file_inventory_integrity_error(exc) from exc
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Workspace file inventory job attach failed: {exc}") from exc  # noqa: TRY003

    def mark_workspace_file_inventory_enqueue_failed(
        self,
        scan_id: str,
        diagnostics: Any,
    ) -> dict[str, Any]:
        """Mark a queued scan failed when Jobs enqueue fails after scan-row creation."""
        return self._transition_workspace_file_inventory_scan(
            scan_id,
            state="failed",
            diagnostics=diagnostics,
            set_completed=True,
            set_started=False,
        )

    def mark_workspace_file_inventory_scanning(self, scan_id: str) -> dict[str, Any]:
        """Mark a Workspace file inventory scan as acquired by a worker."""
        return self._transition_workspace_file_inventory_scan(
            scan_id,
            state="scanning",
            diagnostics=None,
            set_completed=False,
            set_started=True,
        )

    def _transition_workspace_file_inventory_scan(
        self,
        scan_id: str,
        *,
        state: str,
        diagnostics: Any,
        set_completed: bool,
        set_started: bool,
    ) -> dict[str, Any]:
        normalized_scan_id = str(scan_id or "").strip()
        normalized_state = normalize_durable_inventory_state(state)
        if not normalized_scan_id:
            raise InputError("scan_id is required.")  # noqa: TRY003
        now = self._get_current_utc_timestamp_iso()
        diagnostics_json = self._workspace_file_inventory_diagnostics_json(diagnostics)
        try:
            with self.transaction() as conn:
                scan = self._workspace_file_inventory_require_scan(normalized_scan_id, conn=conn)
                set_clauses = ["state = ?", "updated_at = ?", "version = version + 1"]
                params: list[Any] = [normalized_state, now]
                if diagnostics is not None:
                    set_clauses.append("diagnostics_json = ?")
                    params.append(diagnostics_json)
                if set_started:
                    set_clauses.append("started_at = COALESCE(started_at, ?)")
                    params.append(now)
                if set_completed:
                    set_clauses.append("completed_at = ?")
                    params.append(now)
                params.append(normalized_scan_id)
                conn.execute(
                    f"""
                    UPDATE workspace_file_inventory_scans
                       SET {', '.join(set_clauses)}
                     WHERE scan_id = ?
                    """,  # nosec B608
                    tuple(params),
                )
                self._workspace_file_inventory_update_root_state(
                    conn,
                    workspace_id=str(scan["workspace_id"]),
                    root_id=str(scan["root_id"]),
                    state=normalized_state,
                    updated_at=now,
                )
                updated = self._workspace_file_inventory_scan_by_id(normalized_scan_id, conn=conn)
                if updated is None:
                    raise CharactersRAGDBError(  # noqa: TRY003
                        f"Failed to read workspace file inventory scan '{normalized_scan_id}' after update."
                    )
                return updated
        except ConflictError:
            raise
        except sqlite3.IntegrityError as exc:
            raise self._workspace_file_inventory_integrity_error(exc) from exc
        except BackendDatabaseError as exc:
            raise self._workspace_file_inventory_integrity_error(exc) from exc
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Workspace file inventory scan update failed: {exc}") from exc  # noqa: TRY003

    def complete_workspace_file_inventory_scan(
        self,
        scan_id: str,
        state: str,
        counts: Any,
        diagnostics: Any,
        *,
        root_snapshot_token: str | None = None,
    ) -> dict[str, Any]:
        """Complete a Workspace file inventory scan with durable counts and diagnostics."""
        normalized_state = str(state or "").strip().lower()
        if normalized_state not in {"current", "partial", "failed"}:
            raise InputError("completed inventory state must be current, partial, or failed.")  # noqa: TRY003
        normalized_scan_id = str(scan_id or "").strip()
        if not normalized_scan_id:
            raise InputError("scan_id is required.")  # noqa: TRY003
        now = self._get_current_utc_timestamp_iso()
        counts_json = self._workspace_file_inventory_counts_json(counts)
        diagnostics_json = self._workspace_file_inventory_diagnostics_json(diagnostics)
        try:
            with self.transaction() as conn:
                scan = self._workspace_file_inventory_require_scan(normalized_scan_id, conn=conn)
                conn.execute(
                    """
                    UPDATE workspace_file_inventory_scans
                       SET state = ?,
                           root_snapshot_token = ?,
                           completed_at = ?,
                           counts_json = ?,
                           diagnostics_json = ?,
                           updated_at = ?,
                           version = version + 1
                     WHERE scan_id = ?
                    """,
                    (
                        normalized_state,
                        root_snapshot_token,
                        now,
                        counts_json,
                        diagnostics_json,
                        now,
                        normalized_scan_id,
                    ),
                )
                self._workspace_file_inventory_update_root_state(
                    conn,
                    workspace_id=str(scan["workspace_id"]),
                    root_id=str(scan["root_id"]),
                    state=normalized_state,
                    updated_at=now,
                )
                updated = self._workspace_file_inventory_scan_by_id(normalized_scan_id, conn=conn)
                if updated is None:
                    raise CharactersRAGDBError(  # noqa: TRY003
                        f"Failed to read workspace file inventory scan '{normalized_scan_id}' after completion."
                    )
                return updated
        except ConflictError:
            raise
        except sqlite3.IntegrityError as exc:
            raise self._workspace_file_inventory_integrity_error(exc) from exc
        except BackendDatabaseError as exc:
            raise self._workspace_file_inventory_integrity_error(exc) from exc
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Workspace file inventory scan completion failed: {exc}") from exc  # noqa: TRY003

    def replace_workspace_file_inventory_items(
        self,
        workspace_id: str,
        root_id: str,
        scan_id: str,
        items: list[Mapping[str, Any]],
        *,
        scan_coverage_complete: bool,
    ) -> int:
        """Replace the current item projection for seen paths from one scan."""
        normalized_workspace_id = str(workspace_id or "").strip()
        normalized_root_id = str(root_id or "").strip()
        normalized_scan_id = str(scan_id or "").strip()
        if not normalized_workspace_id or not normalized_root_id or not normalized_scan_id:
            raise InputError("workspace_id, root_id, and scan_id are required.")  # noqa: TRY003
        now = self._get_current_utc_timestamp_iso()
        false_value = self._workspace_file_inventory_bool_value(False)
        true_value = self._workspace_file_inventory_bool_value(True)
        normalized_items: list[dict[str, Any]] = []
        for item in items or []:
            if not isinstance(item, Mapping):
                raise InputError("inventory items must be mappings.")  # noqa: TRY003
            relative_path = self._workspace_file_inventory_relative_path(item.get("relative_path"))
            entry_kind = str(item.get("entry_kind") or "file").strip() or "file"
            normalized_items.append(
                {
                    "relative_path": relative_path,
                    "entry_kind": entry_kind,
                    "size_bytes": self._workspace_file_inventory_int(item.get("size_bytes"), field_name="size_bytes"),
                    "mtime_ns": self._workspace_file_inventory_int(item.get("mtime_ns"), field_name="mtime_ns"),
                    "mode_bits": self._workspace_file_inventory_int(item.get("mode_bits"), field_name="mode_bits"),
                    "extension": item.get("extension"),
                    "mime_hint": item.get("mime_hint"),
                    "language_hint": item.get("language_hint"),
                    "ignored": self._workspace_file_inventory_bool_value(bool(item.get("ignored", False))),
                    "ignore_reason": item.get("ignore_reason"),
                    "indexing_candidate": self._workspace_file_inventory_bool_value(
                        bool(item.get("indexing_candidate", False))
                    ),
                    "metadata_json": self._workspace_file_inventory_json(item.get("metadata"), default={}),
                }
            )
        try:
            with self.transaction() as conn:
                scan = self._workspace_file_inventory_require_scan(normalized_scan_id, conn=conn)
                if scan["workspace_id"] != normalized_workspace_id or scan["root_id"] != normalized_root_id:
                    raise ConflictError(
                        "Workspace file inventory scan does not match workspace/root.",
                        entity="workspace_file_inventory_scans",
                        entity_id=normalized_scan_id,
                    )
                for item in normalized_items:
                    conn.execute(
                        """
                        INSERT INTO workspace_file_inventory_items (
                            workspace_id, root_id, relative_path, scan_id, entry_kind, size_bytes,
                            mtime_ns, mode_bits, extension, mime_hint, language_hint, ignored,
                            ignore_reason, indexing_candidate, coverage_state, last_seen_at, deleted,
                            metadata_json
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'current', ?, ?, ?)
                        ON CONFLICT(workspace_id, root_id, relative_path) DO UPDATE SET
                            scan_id = excluded.scan_id,
                            entry_kind = excluded.entry_kind,
                            size_bytes = excluded.size_bytes,
                            mtime_ns = excluded.mtime_ns,
                            mode_bits = excluded.mode_bits,
                            extension = excluded.extension,
                            mime_hint = excluded.mime_hint,
                            language_hint = excluded.language_hint,
                            ignored = excluded.ignored,
                            ignore_reason = excluded.ignore_reason,
                            indexing_candidate = excluded.indexing_candidate,
                            coverage_state = 'current',
                            last_seen_at = excluded.last_seen_at,
                            deleted = excluded.deleted,
                            metadata_json = excluded.metadata_json
                        """,
                        (
                            normalized_workspace_id,
                            normalized_root_id,
                            item["relative_path"],
                            normalized_scan_id,
                            item["entry_kind"],
                            item["size_bytes"],
                            item["mtime_ns"],
                            item["mode_bits"],
                            item["extension"],
                            item["mime_hint"],
                            item["language_hint"],
                            item["ignored"],
                            item["ignore_reason"],
                            item["indexing_candidate"],
                            now,
                            false_value,
                            item["metadata_json"],
                        ),
                    )
                if scan_coverage_complete:
                    conn.execute(
                        """
                        UPDATE workspace_file_inventory_items
                           SET coverage_state = 'previous',
                               deleted = ?,
                               metadata_json = metadata_json
                         WHERE workspace_id = ?
                           AND root_id = ?
                           AND scan_id <> ?
                        """,
                        (true_value, normalized_workspace_id, normalized_root_id, normalized_scan_id),
                    )
                else:
                    conn.execute(
                        """
                        UPDATE workspace_file_inventory_items
                           SET coverage_state = 'previous'
                         WHERE workspace_id = ?
                           AND root_id = ?
                           AND scan_id <> ?
                           AND deleted = ?
                        """,
                        (normalized_workspace_id, normalized_root_id, normalized_scan_id, false_value),
                    )
                return len(normalized_items)
        except ConflictError:
            raise
        except sqlite3.IntegrityError as exc:
            raise self._workspace_file_inventory_integrity_error(exc) from exc
        except BackendDatabaseError as exc:
            raise self._workspace_file_inventory_integrity_error(exc) from exc
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Workspace file inventory item replacement failed: {exc}") from exc  # noqa: TRY003

    def get_workspace_file_inventory_status(
        self,
        workspace_id: str,
        *,
        policy_fingerprint: str | None = None,
    ) -> dict[str, Any]:
        """Return the latest Workspace file inventory status projection."""
        normalized_workspace_id = str(workspace_id or "").strip()
        if not normalized_workspace_id:
            raise InputError("workspace_id is required.")  # noqa: TRY003
        root = self.get_workspace_primary_root(normalized_workspace_id)
        zero_counts = normalize_inventory_counts({})
        if root is None:
            return {
                "workspace_id": normalized_workspace_id,
                "root_id": None,
                "scan_id": None,
                "state": "not_started",
                "durable_state": None,
                "stale": False,
                "counts": zero_counts,
                "diagnostics": [],
            }
        cursor = self.execute_query(
            """
            SELECT *
              FROM workspace_file_inventory_scans
             WHERE workspace_id = ?
               AND root_id = ?
             ORDER BY created_at DESC, scan_id DESC
             LIMIT 1
            """,
            (normalized_workspace_id, root["root_id"]),
        )
        row = cursor.fetchone()
        if row is None:
            return {
                "workspace_id": normalized_workspace_id,
                "root_id": root["root_id"],
                "scan_id": None,
                "state": "not_started",
                "durable_state": None,
                "stale": False,
                "counts": zero_counts,
                "diagnostics": [],
            }

        scan = dict(row)
        latest_diagnostics = bounded_inventory_diagnostics(
            self._workspace_file_inventory_json_load(scan.get("diagnostics_json"), fallback=[])
        )
        if normalize_durable_inventory_state(scan.get("state")) == "failed" and any(
            diagnostic.get("code") == "root_version_mismatch"
            for diagnostic in latest_diagnostics
        ):
            completed_row = self.execute_query(
                """
                SELECT *
                  FROM workspace_file_inventory_scans
                 WHERE workspace_id = ?
                   AND root_id = ?
                   AND state IN ('current', 'partial')
                 ORDER BY completed_at DESC, created_at DESC, scan_id DESC
                 LIMIT 1
                """,
                (normalized_workspace_id, root["root_id"]),
            ).fetchone()
            if completed_row is not None:
                scan = dict(completed_row)

        durable_state = normalize_durable_inventory_state(scan.get("state"))
        counts = normalize_inventory_counts(
            self._workspace_file_inventory_json_load(scan.get("counts_json"), fallback={})
        )
        diagnostics = bounded_inventory_diagnostics(
            self._workspace_file_inventory_json_load(scan.get("diagnostics_json"), fallback=[])
        )
        policy_mismatch = (
            policy_fingerprint is not None
            and str(scan.get("ignore_policy_fingerprint") or "") != str(policy_fingerprint)
        )
        stale = durable_state in {"current", "partial"} and (
            int(scan["root_version"]) != int(root["version"]) or policy_mismatch
        )
        return {
            "workspace_id": normalized_workspace_id,
            "root_id": root["root_id"],
            "scan_id": scan["scan_id"],
            "state": "stale" if stale else durable_state,
            "durable_state": durable_state,
            "stale": stale,
            "counts": counts,
            "diagnostics": diagnostics,
            "root_version": root["version"],
            "scan_root_version": scan["root_version"],
            "ignore_policy_fingerprint": scan.get("ignore_policy_fingerprint"),
            "root_snapshot_token": scan.get("root_snapshot_token"),
            "job_id": scan.get("job_id"),
            "job_uuid": scan.get("job_uuid"),
            "started_at": scan.get("started_at"),
            "completed_at": scan.get("completed_at"),
            "updated_at": scan.get("updated_at"),
        }

    def list_workspace_file_inventory_items(
        self,
        workspace_id: str,
        *,
        prefix: str | None = None,
        cursor: str | None = None,
        limit: int = 100,
        include_ignored: bool = False,
        entry_kind: str | None = None,
    ) -> dict[str, Any]:
        """List non-deleted inventory items sorted by project-root-relative path."""
        normalized_workspace_id = str(workspace_id or "").strip()
        if not normalized_workspace_id:
            raise InputError("workspace_id is required.")  # noqa: TRY003
        bounded_limit = max(1, min(int(limit), 500))
        root = self.get_workspace_primary_root(normalized_workspace_id)
        if root is None:
            return {"items": [], "next_cursor": None}

        normalized_prefix = self._workspace_file_inventory_prefix(prefix)
        normalized_entry_kind = str(entry_kind or "").strip().lower() or None
        try:
            cursor_path = decode_inventory_cursor(cursor) if cursor else None
        except ValueError as exc:
            raise InputError("cursor must be a valid workspace file inventory cursor.") from exc  # noqa: TRY003
        false_value = self._workspace_file_inventory_bool_value(False)
        clauses = ["workspace_id = ?", "root_id = ?", "deleted = ?"]
        params: list[Any] = [normalized_workspace_id, root["root_id"], false_value]
        if not include_ignored:
            clauses.append("ignored = ?")
            params.append(false_value)
        if normalized_prefix is not None:
            clauses.append("relative_path LIKE ?")
            params.append(f"{normalized_prefix}%")
        if normalized_entry_kind is not None:
            clauses.append("entry_kind = ?")
            params.append(normalized_entry_kind)
        if cursor_path is not None:
            clauses.append("relative_path > ?")
            params.append(cursor_path)
        params.append(bounded_limit + 1)
        query = f"""
            SELECT workspace_id, root_id, relative_path, scan_id, entry_kind, size_bytes,
                   mtime_ns, mode_bits, extension, mime_hint, language_hint, ignored,
                   ignore_reason, indexing_candidate, coverage_state, last_seen_at, deleted,
                   metadata_json
              FROM workspace_file_inventory_items
             WHERE {' AND '.join(clauses)}
             ORDER BY relative_path ASC
             LIMIT ?
        """  # nosec B608
        rows = [dict(row) for row in self.execute_query(query, tuple(params)).fetchall()]
        has_more = len(rows) > bounded_limit
        visible_rows = rows[:bounded_limit]
        next_cursor = encode_inventory_cursor(visible_rows[-1]["relative_path"]) if has_more and visible_rows else None
        for item in visible_rows:
            item["ignored"] = bool(item.get("ignored"))
            item["indexing_candidate"] = bool(item.get("indexing_candidate"))
            item["deleted"] = bool(item.get("deleted"))
            item["metadata"] = self._workspace_file_inventory_json_load(item.get("metadata_json"), fallback={})
        return {"items": visible_rows, "next_cursor": next_cursor}

    # --- Workspace Migration Methods ---

    @staticmethod
    def _serialize_workspace_migration_json(value: Any, field_name: str, *, default: Any) -> str:
        if value is None:
            value = default
        if isinstance(value, str):
            try:
                json.loads(value)
            except json.JSONDecodeError as exc:
                raise InputError(f"{field_name} must be valid JSON when provided as a string.") from exc  # noqa: TRY003
            return value
        try:
            return json.dumps(value, ensure_ascii=True)
        except TypeError as exc:
            raise InputError(f"{field_name} must be JSON serializable.") from exc  # noqa: TRY003

    @staticmethod
    def _parse_workspace_migration_json(value: Any, *, fallback: Any) -> Any:
        if value is None:
            return fallback
        if isinstance(value, (dict, list)):
            return value
        if not isinstance(value, str) or not value.strip():
            return fallback
        try:
            return json.loads(value)
        except json.JSONDecodeError:
            return fallback

    def _get_workspace_migration_session_by_idempotency_key(self, idempotency_key: str) -> dict[str, Any] | None:
        cursor = self.execute_query(
            "SELECT * FROM workspace_migration_sessions WHERE idempotency_key = ?",
            (idempotency_key,),
        )
        row = cursor.fetchone()
        if row is None:
            return None
        session = dict(row)
        session["_chunks"] = self._list_workspace_migration_chunks(str(session["id"]))
        return session

    def _list_workspace_migration_chunks(self, migration_id: str) -> list[dict[str, Any]]:
        cursor = self.execute_query(
            "SELECT * FROM workspace_migration_chunks WHERE migration_id = ? ORDER BY accepted_at, id",
            (migration_id,),
        )
        return [dict(row) for row in cursor.fetchall()]

    def get_workspace_migration_session(self, migration_id: str) -> dict[str, Any] | None:
        """Return a Research Workspace migration session and accepted chunk receipts."""
        cursor = self.execute_query(
            "SELECT * FROM workspace_migration_sessions WHERE id = ?",
            (migration_id,),
        )
        row = cursor.fetchone()
        if row is None:
            return None
        session = dict(row)
        session["_chunks"] = self._list_workspace_migration_chunks(migration_id)
        return session

    def list_workspace_migration_sessions(self, *, limit: int = 100) -> list[dict[str, Any]]:
        """Return recent Research Workspace migration sessions with accepted chunk receipts."""
        bounded_limit = max(1, min(int(limit), 500))
        cursor = self.execute_query(
            "SELECT * FROM workspace_migration_sessions ORDER BY updated_at DESC, created_at DESC LIMIT ?",
            (bounded_limit,),
        )
        sessions: list[dict[str, Any]] = []
        for row in cursor.fetchall():
            session = dict(row)
            session["_chunks"] = self._list_workspace_migration_chunks(str(session["id"]))
            sessions.append(session)
        return sessions

    def _get_workspace_migration_chunk(self, migration_id: str, chunk_id: str) -> dict[str, Any] | None:
        cursor = self.execute_query(
            "SELECT * FROM workspace_migration_chunks WHERE migration_id = ? AND id = ?",
            (migration_id, chunk_id),
        )
        row = cursor.fetchone()
        return dict(row) if row else None

    def upsert_workspace_migration_session(self, data: dict[str, Any]) -> tuple[dict[str, Any], bool]:
        """Create a workspace migration session or return the existing idempotent session."""
        migration_id = str(data.get("id") or "").strip()
        idempotency_key = str(data.get("idempotency_key") or "").strip()
        target_workspace_id = str(data.get("target_workspace_id") or "").strip()
        target_workspace_name = str(data.get("target_workspace_name") or "").strip()
        manifest_hash = str(data.get("manifest_hash") or "").strip().lower()
        source_product = str(data.get("source_product") or "research-workspace-webui").strip()
        if not all((migration_id, idempotency_key, target_workspace_id, target_workspace_name, manifest_hash)):
            raise InputError(  # noqa: TRY003
                "id, idempotency_key, target_workspace_id, target_workspace_name, and manifest_hash are required."
            )

        existing = self.get_workspace_migration_session(migration_id)
        existing_by_key = self._get_workspace_migration_session_by_idempotency_key(idempotency_key)
        if existing_by_key is not None and existing_by_key["id"] != migration_id:
            raise ConflictError(  # noqa: TRY003
                "Workspace migration idempotency key is already used by another migration.",
                entity="workspace_migration_sessions",
                entity_id=idempotency_key,
            )
        if existing is not None:
            if existing["idempotency_key"] != idempotency_key or existing["manifest_hash"] != manifest_hash:
                raise ConflictError(  # noqa: TRY003
                    "Workspace migration already exists with different idempotency data.",
                    entity="workspace_migration_sessions",
                    entity_id=migration_id,
                )
            return existing, False

        self.upsert_workspace(
            target_workspace_id,
            target_workspace_name,
            study_materials_policy="workspace",
        )

        now = self._get_current_utc_timestamp_iso()
        manifest_json = self._serialize_workspace_migration_json(data.get("manifest"), "manifest", default={})
        diagnostics_json = self._serialize_workspace_migration_json(
            data.get("diagnostics"),
            "diagnostics",
            default={},
        )
        declared_chunks_json = self._serialize_workspace_migration_json(
            data.get("declared_chunks"),
            "declared_chunks",
            default=[],
        )
        false_value = False if self.backend_type == BackendType.POSTGRESQL else 0
        params = (
            migration_id,
            target_workspace_id,
            target_workspace_name,
            source_product,
            idempotency_key,
            manifest_hash,
            manifest_json,
            diagnostics_json,
            declared_chunks_json,
            "created",
            false_value,
            now,
            now,
            1,
        )
        with self.transaction() as conn:
            try:
                conn.execute(
                    "INSERT INTO workspace_migration_sessions ("
                    "id, target_workspace_id, target_workspace_name, source_product, idempotency_key, "
                    "manifest_hash, manifest_json, diagnostics_json, declared_chunks_json, status, "
                    "client_delete_eligible, created_at, updated_at, version"
                    ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    params,
                )
            except sqlite3.IntegrityError as exc:
                raced = self.get_workspace_migration_session(migration_id)
                if raced is not None and raced["idempotency_key"] == idempotency_key and raced["manifest_hash"] == manifest_hash:
                    return raced, False
                raise ConflictError(  # noqa: TRY003
                    "Workspace migration could not be created due to a uniqueness conflict.",
                    entity="workspace_migration_sessions",
                    entity_id=migration_id,
                ) from exc
        created = self.get_workspace_migration_session(migration_id)
        if created is None:
            raise CharactersRAGDBError(f"Failed to read workspace migration '{migration_id}' after create.")  # noqa: TRY003
        return created, True

    def _declared_workspace_migration_chunks(self, session: dict[str, Any]) -> list[dict[str, Any]]:
        parsed = self._parse_workspace_migration_json(session.get("declared_chunks_json"), fallback=[])
        return parsed if isinstance(parsed, list) else []

    def _workspace_migration_missing_chunk_ids(self, session: dict[str, Any]) -> list[str]:
        accepted = {str(chunk.get("id")) for chunk in session.get("_chunks", [])}
        return [
            str(chunk.get("id"))
            for chunk in self._declared_workspace_migration_chunks(session)
            if str(chunk.get("id")) not in accepted
        ]

    def _verify_workspace_migration_delete_eligibility(self, session: dict[str, Any]) -> dict[str, Any]:
        """Verify accepted chunk receipts match declarations before browser-local deletion."""
        declared = self._declared_workspace_migration_chunks(session)
        accepted_chunks = session.get("_chunks", [])
        accepted = {str(chunk.get("id")): chunk for chunk in accepted_chunks}
        if not declared:
            return {
                "eligible": False,
                "status": "no_declared_chunks",
                "missing_chunk_ids": [],
                "mismatch_chunk_ids": [],
                "undeclared_chunk_ids": sorted(accepted.keys()),
            }

        declared_by_id = {str(chunk.get("id")): chunk for chunk in declared}
        missing = [
            chunk_id
            for chunk_id in declared_by_id
            if chunk_id not in accepted
        ]
        undeclared = [
            chunk_id
            for chunk_id in accepted
            if chunk_id not in declared_by_id
        ]
        mismatched: list[str] = []
        for chunk_id, expected in declared_by_id.items():
            receipt = accepted.get(chunk_id)
            if receipt is None:
                continue
            try:
                expected_byte_count = int(expected.get("byte_count"))
                receipt_byte_count = int(receipt.get("byte_count"))
            except (TypeError, ValueError):
                mismatched.append(chunk_id)
                continue
            expected_kind = str(expected.get("chunk_kind") or "workspace_bundle")
            receipt_kind = str(receipt.get("chunk_kind") or "workspace_bundle")
            expected_hash = str(expected.get("sha256") or "").lower()
            receipt_hash = str(receipt.get("sha256") or "").lower()
            if (
                expected_hash != receipt_hash
                or expected_byte_count != receipt_byte_count
                or expected_kind != receipt_kind
            ):
                mismatched.append(chunk_id)

        eligible = not missing and not mismatched and not undeclared
        if eligible:
            status = "verified"
        elif missing:
            status = "missing_chunks"
        else:
            status = "verification_failed"
        return {
            "eligible": eligible,
            "status": status,
            "missing_chunk_ids": sorted(missing),
            "mismatch_chunk_ids": sorted(mismatched),
            "undeclared_chunk_ids": sorted(undeclared),
        }

    def add_workspace_migration_chunk(
        self,
        migration_id: str,
        chunk_id: str,
        data: dict[str, Any],
    ) -> dict[str, Any]:
        """Record an idempotent chunk receipt for a workspace migration."""
        normalized_migration_id = str(migration_id or "").strip()
        normalized_chunk_id = str(chunk_id or "").strip()
        sha256 = str(data.get("sha256") or "").strip().lower()
        chunk_kind = str(data.get("chunk_kind") or "workspace_bundle").strip()
        try:
            byte_count = int(data.get("byte_count"))
        except (TypeError, ValueError) as exc:
            raise InputError("byte_count must be an integer.") from exc  # noqa: TRY003
        if not all((normalized_migration_id, normalized_chunk_id, sha256, chunk_kind)):
            raise InputError("migration_id, chunk_id, sha256, and chunk_kind are required.")  # noqa: TRY003

        session = self.get_workspace_migration_session(normalized_migration_id)
        if session is None:
            raise ConflictError(  # noqa: TRY003
                "Workspace migration not found.",
                entity="workspace_migration_sessions",
                entity_id=normalized_migration_id,
            )
        if session.get("status") == "finalized":
            raise ConflictError(  # noqa: TRY003
                "Workspace migration is already finalized.",
                entity="workspace_migration_sessions",
                entity_id=normalized_migration_id,
            )

        declared = self._declared_workspace_migration_chunks(session)
        declared_by_id = {str(chunk.get("id")): chunk for chunk in declared}
        if declared_by_id:
            expected = declared_by_id.get(normalized_chunk_id)
            if expected is None:
                raise ConflictError(  # noqa: TRY003
                    "Workspace migration chunk was not declared in the manifest.",
                    entity="workspace_migration_chunks",
                    entity_id=normalized_chunk_id,
                )
            try:
                expected_byte_count = int(expected.get("byte_count"))
            except (TypeError, ValueError) as exc:
                raise ConflictError(  # noqa: TRY003
                    "Workspace migration chunk declaration has an invalid byte count.",
                    entity="workspace_migration_chunks",
                    entity_id=normalized_chunk_id,
                ) from exc
            if (
                str(expected.get("sha256") or "").lower() != sha256
                or expected_byte_count != byte_count
                or str(expected.get("chunk_kind") or "workspace_bundle") != chunk_kind
            ):
                raise ConflictError(  # noqa: TRY003
                    "Workspace migration chunk receipt does not match the declared manifest.",
                    entity="workspace_migration_chunks",
                    entity_id=normalized_chunk_id,
                )

        existing = self._get_workspace_migration_chunk(normalized_migration_id, normalized_chunk_id)
        if existing is not None:
            if existing["sha256"] == sha256 and int(existing["byte_count"]) == byte_count:
                return existing
            raise ConflictError(  # noqa: TRY003
                "Workspace migration chunk already exists with different content.",
                entity="workspace_migration_chunks",
                entity_id=normalized_chunk_id,
            )

        metadata_json = self._serialize_workspace_migration_json(data.get("metadata"), "metadata", default={})
        now = self._get_current_utc_timestamp_iso()
        with self.transaction() as conn:
            try:
                conn.execute(
                    "INSERT INTO workspace_migration_chunks ("
                    "migration_id, id, sha256, byte_count, chunk_kind, metadata_json, accepted_at"
                    ") VALUES (?, ?, ?, ?, ?, ?, ?)",
                    (
                        normalized_migration_id,
                        normalized_chunk_id,
                        sha256,
                        byte_count,
                        chunk_kind,
                        metadata_json,
                        now,
                    ),
                )
                conn.execute(
                    "UPDATE workspace_migration_sessions SET updated_at = ?, version = version + 1 WHERE id = ?",
                    (now, normalized_migration_id),
                )
            except sqlite3.IntegrityError as exc:
                raced = self._get_workspace_migration_chunk(normalized_migration_id, normalized_chunk_id)
                if raced is not None and raced["sha256"] == sha256 and int(raced["byte_count"]) == byte_count:
                    return raced
                raise ConflictError(  # noqa: TRY003
                    "Workspace migration chunk could not be accepted due to a uniqueness conflict.",
                    entity="workspace_migration_chunks",
                    entity_id=normalized_chunk_id,
                ) from exc
        accepted = self._get_workspace_migration_chunk(normalized_migration_id, normalized_chunk_id)
        if accepted is None:
            raise CharactersRAGDBError(  # noqa: TRY003
                f"Failed to read workspace migration chunk '{normalized_chunk_id}' after insert."
            )
        return accepted

    def finalize_workspace_migration(
        self,
        migration_id: str,
        data: dict[str, Any],
    ) -> dict[str, Any]:
        """Finalize a workspace migration after all declared chunks have receipts."""
        normalized_migration_id = str(migration_id or "").strip()
        manifest_hash = str(data.get("manifest_hash") or "").strip().lower()
        session = self.get_workspace_migration_session(normalized_migration_id)
        if session is None:
            raise ConflictError(  # noqa: TRY003
                "Workspace migration not found.",
                entity="workspace_migration_sessions",
                entity_id=normalized_migration_id,
            )
        if session["manifest_hash"] != manifest_hash:
            raise ConflictError(  # noqa: TRY003
                "Workspace migration manifest hash mismatch.",
                entity="workspace_migration_sessions",
                entity_id=normalized_migration_id,
            )
        if session.get("status") == "finalized":
            return session

        missing = self._workspace_migration_missing_chunk_ids(session)
        if missing:
            raise ConflictError(  # noqa: TRY003
                f"Workspace migration is missing declared chunks: {', '.join(missing)}",
                entity="workspace_migration_sessions",
                entity_id=normalized_migration_id,
            )

        now = self._get_current_utc_timestamp_iso()
        declared_count = len(self._declared_workspace_migration_chunks(session))
        accepted_count = len(session.get("_chunks", []))
        verification = self._verify_workspace_migration_delete_eligibility(session)
        client_delete_eligible = bool(verification["eligible"])
        recovery_manifest = {
            "migration_id": normalized_migration_id,
            "target_workspace_id": session["target_workspace_id"],
            "source_product": session["source_product"],
            "manifest_hash": session["manifest_hash"],
            "status": "finalized",
            "declared_chunk_count": declared_count,
            "accepted_chunk_count": accepted_count,
            "missing_chunk_ids": verification["missing_chunk_ids"],
            "client_delete_eligible": client_delete_eligible,
            "can_delete_legacy_storage": client_delete_eligible,
            "server_readback_verified": client_delete_eligible,
            "verification_status": verification["status"],
            "mismatch_chunk_ids": verification["mismatch_chunk_ids"],
            "undeclared_chunk_ids": verification["undeclared_chunk_ids"],
            "next_step": "enqueue_workspace_source_ingestion_jobs",
            "finalized_at": now,
        }
        recovery_json = self._serialize_workspace_migration_json(
            recovery_manifest,
            "recovery_manifest",
            default={},
        )
        eligible_value = client_delete_eligible if self.backend_type == BackendType.POSTGRESQL else int(client_delete_eligible)
        with self.transaction() as conn:
            conn.execute(
                "UPDATE workspace_migration_sessions "
                "SET status = ?, finalized_at = ?, recovery_manifest_json = ?, "
                "client_delete_eligible = ?, updated_at = ?, version = version + 1 "
                "WHERE id = ?",
                ("finalized", now, recovery_json, eligible_value, now, normalized_migration_id),
            )
        finalized = self.get_workspace_migration_session(normalized_migration_id)
        if finalized is None:
            raise CharactersRAGDBError(  # noqa: TRY003
                f"Failed to read workspace migration '{normalized_migration_id}' after finalize."
            )
        return finalized

    def record_workspace_migration_client_delete_ack(
        self,
        migration_id: str,
        data: dict[str, Any],
    ) -> bool:
        """Record client deletion acknowledgement only after deletion eligibility is explicitly enabled."""
        normalized_migration_id = str(migration_id or "").strip()
        manifest_hash = str(data.get("acknowledged_manifest_hash") or "").strip().lower()
        session = self.get_workspace_migration_session(normalized_migration_id)
        if session is None:
            raise ConflictError(  # noqa: TRY003
                "Workspace migration not found.",
                entity="workspace_migration_sessions",
                entity_id=normalized_migration_id,
            )
        if session["manifest_hash"] != manifest_hash:
            raise ConflictError(  # noqa: TRY003
                "Workspace migration manifest hash mismatch.",
                entity="workspace_migration_sessions",
                entity_id=normalized_migration_id,
            )
        if session.get("status") != "finalized":
            raise ConflictError(  # noqa: TRY003
                "Workspace migration must be finalized before client deletion can be acknowledged.",
                entity="workspace_migration_sessions",
                entity_id=normalized_migration_id,
            )
        if not bool(session.get("client_delete_eligible")):
            raise ConflictError(  # noqa: TRY003
                "Client deletion is not enabled for Research Workspace migrations.",
                entity="workspace_migration_sessions",
                entity_id=normalized_migration_id,
            )

        now = self._get_current_utc_timestamp_iso()
        with self.transaction() as conn:
            conn.execute(
                "UPDATE workspace_migration_sessions "
                "SET client_delete_ack_at = ?, updated_at = ?, version = version + 1 "
                "WHERE id = ?",
                (now, now, normalized_migration_id),
            )
        return True

    # --- Workspace Source Methods ---

    def _normalize_workspace_source_review_state(self, value: Any, *, for_create: bool) -> str:
        if value is None:
            state = ""
        elif isinstance(value, str):
            state = value.strip().lower()
        else:
            raise InputError("Workspace source review state must be a string.")  # noqa: TRY003
        if for_create and not state:
            state = "unset"
        allowed_states = (
            self._ALLOWED_WORKSPACE_SOURCE_CREATE_REVIEW_STATES
            if for_create
            else self._ALLOWED_WORKSPACE_SOURCE_REVIEW_STATES
        )
        if state not in allowed_states:
            raise InputError(f"Unsupported workspace source review state '{state}'.")  # noqa: TRY003
        return state

    def _build_workspace_source_review_transition(
        self,
        review_state: Any,
        *,
        actor_user_id: str | None = None,
        for_create: bool = False,
    ) -> dict[str, Any]:
        state = self._normalize_workspace_source_review_state(review_state, for_create=for_create)
        actor = None
        if state == "reviewed":
            if not isinstance(actor_user_id, str) or not actor_user_id.strip():
                raise InputError("A non-empty actor_user_id is required to review a workspace source.")  # noqa: TRY003
            actor = actor_user_id.strip()
        now = self._get_current_utc_timestamp_iso()
        return {
            "review_state": state,
            "review_state_updated_at": now,
            "reviewed_at": now if state == "reviewed" else None,
            "reviewed_by_user_id": actor if state == "reviewed" else None,
        }

    def add_workspace_source(self, workspace_id: str, data: dict[str, Any]) -> dict[str, Any]:
        """Add a source to a workspace."""
        source_id = data.get("id")
        if not source_id:
            raise InputError("Source id is required.")  # noqa: TRY003
        now = self._get_current_utc_timestamp_iso()
        review_transition = self._build_workspace_source_review_transition(
            data.get("review_state"),
            for_create=True,
        )
        query = (
            "INSERT INTO workspace_sources "
            "(id, workspace_id, media_id, title, source_type, url, position, selected, added_at, "
            "review_state, review_state_updated_at, reviewed_at, reviewed_by_user_id, version) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)"
        )
        params = (
            source_id,
            workspace_id,
            data.get("media_id", 0),
            data.get("title", ""),
            data.get("source_type", ""),
            data.get("url"),
            data.get("position", 0),
            1 if data.get("selected", True) else 0,
            now,
            review_transition["review_state"],
            review_transition["review_state_updated_at"],
            review_transition["reviewed_at"],
            review_transition["reviewed_by_user_id"],
        )
        with self.transaction() as conn:
            try:
                conn.execute(query, params)
            except sqlite3.IntegrityError as exc:
                existing = conn.execute(
                    "SELECT * FROM workspace_sources WHERE workspace_id = ? AND id = ?",
                    (workspace_id, source_id),
                ).fetchone()
                if existing is not None:
                    return dict(existing)
                raise ConflictError(  # noqa: TRY003
                    f"Workspace source '{source_id}' could not be added.",
                    entity="workspace_sources",
                    entity_id=source_id,
                ) from exc
        return self._get_workspace_source(workspace_id, source_id)  # type: ignore[return-value]

    def _get_workspace_source(
        self,
        workspace_id: str,
        source_id: str,
        *,
        include_deleted: bool = False,
    ) -> dict[str, Any] | None:
        cursor = self.execute_query(
            "SELECT * FROM workspace_sources WHERE workspace_id = ? AND id = ?",
            (workspace_id, source_id),
        )
        row = cursor.fetchone()
        return dict(row) if row else None

    def get_workspace_source(
        self,
        workspace_id: str,
        source_id: str,
        *,
        include_deleted: bool = False,
    ) -> dict[str, Any] | None:
        """Fetch a workspace source by id."""
        return self._get_workspace_source(workspace_id, source_id, include_deleted=include_deleted)

    def list_workspace_sources(self, workspace_id: str) -> list[dict[str, Any]]:
        """List all sources for a workspace ordered by position."""
        cursor = self.execute_query(
            "SELECT * FROM workspace_sources WHERE workspace_id = ? ORDER BY position, added_at",
            (workspace_id,),
        )
        return [dict(row) for row in cursor.fetchall()]

    @classmethod
    def _redact_workspace_activity_metadata(cls, value: Any, *, key: str | None = None) -> Any:
        if isinstance(value, Mapping):
            redacted: dict[str, Any] = {}
            for raw_key, raw_value in value.items():
                item_key = str(raw_key)
                if cls._WORKSPACE_ACTIVITY_SECRET_KEY_RE.search(item_key):
                    continue
                redacted[item_key] = cls._redact_workspace_activity_metadata(raw_value, key=item_key)
            return redacted
        if isinstance(value, list):
            return [cls._redact_workspace_activity_metadata(item, key=key) for item in value]
        if isinstance(value, tuple):
            return [cls._redact_workspace_activity_metadata(item, key=key) for item in value]
        if isinstance(value, str):
            if cls._WORKSPACE_ACTIVITY_SECRET_VALUE_RE.search(value):
                return "[redacted]"
            if key and cls._WORKSPACE_ACTIVITY_PATH_KEY_RE.search(key):
                from tldw_Server_API.app.core.Workspaces.runtime_bindings import redacted_path_hint

                return redacted_path_hint(value)
        return value

    @classmethod
    def _workspace_activity_metadata_json(cls, value: Any) -> tuple[dict[str, Any], str]:
        if value is None:
            normalized: dict[str, Any] = {}
        elif isinstance(value, str):
            if not value.strip():
                normalized = {}
            else:
                try:
                    parsed = json.loads(value)
                except json.JSONDecodeError as exc:
                    raise InputError("metadata must be valid JSON.") from exc  # noqa: TRY003
                if not isinstance(parsed, Mapping):
                    raise InputError("metadata must be a JSON object.")  # noqa: TRY003
                normalized = dict(parsed)
        elif isinstance(value, Mapping):
            normalized = dict(value)
        else:
            raise InputError("metadata must be a JSON object.")  # noqa: TRY003

        redacted = cls._redact_workspace_activity_metadata(normalized)
        try:
            dumped = json.dumps(
                redacted,
                ensure_ascii=True,
                allow_nan=False,
                separators=(",", ":"),
                sort_keys=True,
            )
        except (TypeError, ValueError) as exc:
            raise InputError("metadata must be JSON serializable.") from exc  # noqa: TRY003
        if len(dumped.encode("utf-8")) > cls._WORKSPACE_ACTIVITY_MAX_METADATA_BYTES:
            raise InputError(
                f"metadata exceeds {cls._WORKSPACE_ACTIVITY_MAX_METADATA_BYTES} bytes."
            ) from None  # noqa: TRY003
        return redacted, dumped

    @staticmethod
    def _normalize_workspace_activity_required_string(value: Any, field_name: str) -> str:
        normalized = str(value or "").strip()
        if not normalized:
            raise InputError(f"{field_name} is required.")  # noqa: TRY003
        return normalized

    @staticmethod
    def _normalize_workspace_activity_optional_string(value: Any, *, max_length: int) -> str | None:
        if value is None:
            return None
        normalized = str(value).strip()
        if not normalized:
            return None
        return normalized[:max_length]

    @staticmethod
    def _normalize_workspace_activity_limit(limit: int) -> int:
        if isinstance(limit, bool) or not isinstance(limit, int):
            raise InputError("limit must be an integer.")  # noqa: TRY003
        if limit < 1 or limit > 100:
            raise InputError("limit must be between 1 and 100.")  # noqa: TRY003
        return limit

    def _normalize_workspace_activity_row(self, row: Mapping[str, Any] | None) -> dict[str, Any] | None:
        if row is None:
            return None
        item = dict(row)
        raw_metadata = item.pop("metadata_json", None)
        if isinstance(raw_metadata, Mapping):
            metadata = dict(raw_metadata)
        elif isinstance(raw_metadata, str) and raw_metadata.strip():
            try:
                parsed = json.loads(raw_metadata)
                metadata = dict(parsed) if isinstance(parsed, Mapping) else {}
            except json.JSONDecodeError:
                logger.warning(
                    "Failed to decode workspace activity metadata_json for workspace={} event={} ({} chars); raw value omitted.",
                    item.get("workspace_id"),
                    item.get("event_id"),
                    len(raw_metadata),
                )
                metadata = {}
        else:
            metadata = {}
        item["metadata"] = metadata
        item["version"] = int(item.get("version") or 1)
        return item

    def record_workspace_activity_event(
        self,
        workspace_id: str,
        data: Mapping[str, Any],
        *,
        user_id: str | None = None,
        return_row: bool = True,
    ) -> dict[str, Any] | None:
        """Append a bounded, secret-safe activity event for a workspace."""
        normalized_workspace_id = self._normalize_workspace_activity_required_string(workspace_id, "workspace_id")
        event_type = self._normalize_workspace_activity_required_string(data.get("event_type"), "event_type")
        category = self._normalize_workspace_activity_required_string(data.get("category"), "category")
        event_id = self._normalize_workspace_activity_optional_string(data.get("event_id"), max_length=128)
        if event_id is None:
            event_id = f"wae_{time.time_ns():020d}_{uuid.uuid4().hex}"
        actor = self._normalize_workspace_membership_actor(user_id)
        resource_type = self._normalize_workspace_activity_optional_string(data.get("resource_type"), max_length=80)
        resource_id = self._normalize_workspace_activity_optional_string(data.get("resource_id"), max_length=512)
        summary = self._normalize_workspace_activity_optional_string(data.get("summary"), max_length=512)
        metadata, metadata_json = self._workspace_activity_metadata_json(data.get("metadata"))
        _ = metadata
        now = self._get_current_utc_timestamp_iso()

        try:
            with self.transaction() as conn:
                conn.execute(
                    """
                    INSERT INTO workspace_activity_events (
                        workspace_id,
                        event_id,
                        event_type,
                        category,
                        actor_user_id,
                        resource_type,
                        resource_id,
                        summary,
                        metadata_json,
                        created_at,
                        client_id,
                        version
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)
                    """,
                    (
                        normalized_workspace_id,
                        event_id,
                        event_type,
                        category,
                        actor,
                        resource_type,
                        resource_id,
                        summary,
                        metadata_json,
                        now,
                        self.client_id or "unknown",
                    ),
                )
        except (sqlite3.IntegrityError, BackendDatabaseError) as exc:
            raise CharactersRAGDBError(f"Workspace activity event write failed: {exc}") from exc  # noqa: TRY003

        if not return_row:
            return None

        cursor = self.execute_query(
            "SELECT * FROM workspace_activity_events WHERE workspace_id = ? AND event_id = ?",
            (normalized_workspace_id, event_id),
        )
        row = self._normalize_workspace_activity_row(cursor.fetchone())
        if row is not None:
            return row
        raise CharactersRAGDBError("Created workspace activity event could not be reloaded.")  # noqa: TRY003

    def list_workspace_activity_events(
        self,
        workspace_id: str,
        *,
        limit: int = 50,
        category: str | None = None,
    ) -> list[dict[str, Any]]:
        """List recent workspace activity events in deterministic newest-first order."""
        normalized_workspace_id = self._normalize_workspace_activity_required_string(workspace_id, "workspace_id")
        normalized_limit = self._normalize_workspace_activity_limit(limit)
        if category is None:
            cursor = self.execute_query(
                """
                SELECT *
                  FROM workspace_activity_events
                 WHERE workspace_id = ?
                 ORDER BY created_at DESC, event_id DESC
                 LIMIT ?
                """,
                (normalized_workspace_id, normalized_limit),
            )
        else:
            normalized_category = self._normalize_workspace_activity_required_string(category, "category")
            cursor = self.execute_query(
                """
                SELECT *
                  FROM workspace_activity_events
                 WHERE workspace_id = ?
                   AND category = ?
                 ORDER BY created_at DESC, event_id DESC
                 LIMIT ?
                """,
                (normalized_workspace_id, normalized_category, normalized_limit),
            )
        return [
            item
            for row in cursor.fetchall()
            if (item := self._normalize_workspace_activity_row(row)) is not None
        ]

    def update_workspace_source(
        self,
        workspace_id: str,
        source_id: str,
        updates: dict[str, Any],
        *,
        expected_version: int,
        actor_user_id: str | None = None,
    ) -> dict[str, Any]:
        """Update a workspace source with optimistic locking."""
        existing = self._get_workspace_source(workspace_id, source_id)
        if existing is None:
            raise ConflictError(  # noqa: TRY003
                f"Workspace source '{source_id}' not found.",
                entity="workspace_sources",
                entity_id=source_id,
            )
        if existing["version"] != expected_version:
            raise ConflictError(  # noqa: TRY003
                f"Source '{source_id}' version mismatch (db={existing['version']}, expected={expected_version}).",
                entity="workspace_sources",
                entity_id=source_id,
            )
        set_clauses = ["version = ?"]
        params: list[Any] = [expected_version + 1]
        for col in ("title", "source_type", "url", "position", "selected"):
            if col in updates:
                set_clauses.append(f"{col} = ?")
                params.append(updates[col])
        if "review_state" in updates:
            review_transition = self._build_workspace_source_review_transition(
                updates["review_state"],
                actor_user_id=actor_user_id,
            )
            for col in (
                "review_state",
                "review_state_updated_at",
                "reviewed_at",
                "reviewed_by_user_id",
            ):
                set_clauses.append(f"{col} = ?")
                params.append(review_transition[col])
        query = f"UPDATE workspace_sources SET {', '.join(set_clauses)} WHERE workspace_id = ? AND id = ? AND version = ?"  # nosec B608
        params.extend([workspace_id, source_id, expected_version])
        with self.transaction() as conn:
            cursor = conn.execute(query, tuple(params))
            if cursor.rowcount == 0:
                raise ConflictError(  # noqa: TRY003
                    f"Source '{source_id}' concurrent update detected.",
                    entity="workspace_sources",
                    entity_id=source_id,
                )
        return self._get_workspace_source(workspace_id, source_id)  # type: ignore[return-value]

    def update_workspace_source_review_states(
        self,
        workspace_id: str,
        source_ids: list[str],
        review_state: Any,
        actor_user_id: str | None,
    ) -> list[dict[str, Any]]:
        """Atomically transition workspace sources to one review state."""
        normalized_ids: list[str] = []
        seen_ids: set[str] = set()
        for source_id in source_ids:
            if not isinstance(source_id, str) or not source_id.strip():
                raise InputError("source_ids entries must be non-empty strings.")  # noqa: TRY003
            if source_id not in seen_ids:
                seen_ids.add(source_id)
                normalized_ids.append(source_id)
        review_transition = self._build_workspace_source_review_transition(
            review_state,
            actor_user_id=actor_user_id,
        )
        if not normalized_ids:
            return []

        placeholders = ", ".join("?" for _ in normalized_ids)
        with self.transaction() as conn:
            rows = conn.execute(
                f"SELECT id FROM workspace_sources WHERE workspace_id = ? AND id IN ({placeholders})",  # nosec B608  # Placeholders are generated "?" tokens; IDs remain bound parameters.
                (workspace_id, *normalized_ids),
            ).fetchall()
            found_ids = {str(row["id"]) for row in rows}
            missing_ids = [source_id for source_id in normalized_ids if source_id not in found_ids]
            if missing_ids:
                raise ConflictError(  # noqa: TRY003
                    f"Workspace sources not found: {', '.join(repr(source_id) for source_id in missing_ids)}.",
                    entity="workspace_sources",
                    entity_id=missing_ids[0],
                )

            cursor = conn.execute(
                "UPDATE workspace_sources "
                "SET review_state = ?, review_state_updated_at = ?, reviewed_at = ?, "
                f"reviewed_by_user_id = ?, version = version + 1 WHERE workspace_id = ? AND id IN ({placeholders})",  # nosec B608  # Placeholders are generated "?" tokens; IDs remain bound parameters.
                (
                    review_transition["review_state"],
                    review_transition["review_state_updated_at"],
                    review_transition["reviewed_at"],
                    review_transition["reviewed_by_user_id"],
                    workspace_id,
                    *normalized_ids,
                ),
            )
            if cursor.rowcount != len(normalized_ids):
                raise ConflictError(  # noqa: TRY003
                    "Workspace source review-state update was incomplete.",
                    entity="workspace_sources",
                    entity_id=workspace_id,
                )

            updated_rows = conn.execute(
                f"SELECT * FROM workspace_sources WHERE workspace_id = ? AND id IN ({placeholders})",  # nosec B608  # Placeholders are generated "?" tokens; IDs remain bound parameters.
                (workspace_id, *normalized_ids),
            ).fetchall()

        updated_by_id = {str(row["id"]): dict(row) for row in updated_rows}
        return [updated_by_id[source_id] for source_id in normalized_ids]

    def delete_workspace_source(self, workspace_id: str, source_id: str) -> None:
        """Hard-delete a workspace source."""
        with self.transaction() as conn:
            conn.execute(
                "DELETE FROM workspace_sources WHERE workspace_id = ? AND id = ?",
                (workspace_id, source_id),
            )

    def update_workspace_source_selection(self, workspace_id: str, *, selected_ids: list[str]) -> None:
        """Batch-update selection: mark listed ids as selected, all others as unselected.

        Bumps the version of every affected row so clients holding stale versions
        will see a conflict on their next individual update.
        """
        with self.transaction() as conn:
            conn.execute(
                "UPDATE workspace_sources SET selected = 0, version = version + 1 WHERE workspace_id = ?",
                (workspace_id,),
            )
            if selected_ids:
                placeholders = ", ".join("?" for _ in selected_ids)
                conn.execute(
                    f"UPDATE workspace_sources SET selected = 1, version = version + 1 WHERE workspace_id = ? AND id IN ({placeholders})",  # nosec B608
                    (workspace_id, *selected_ids),
                )

    def reorder_workspace_sources(self, workspace_id: str, ordered_ids: list[str]) -> None:
        """Set position of sources based on list order.

        Bumps the version of every reordered row for conflict detection.
        """
        with self.transaction() as conn:
            for idx, source_id in enumerate(ordered_ids):
                conn.execute(
                    "UPDATE workspace_sources SET position = ?, version = version + 1 WHERE workspace_id = ? AND id = ?",
                    (idx, workspace_id, source_id),
                )

    # --- Workspace Runtime Binding Methods ---

    @staticmethod
    def _normalize_workspace_runtime_binding_actor(user_id: str | None) -> str | None:
        if user_id is None:
            return None
        normalized = str(user_id).strip()
        return normalized or None

    @staticmethod
    def _workspace_runtime_binding_is_constraint_error(exc: Exception) -> bool:
        message = str(exc).lower()
        return any(
            token in message
            for token in (
                "unique",
                "duplicate",
                "constraint",
                "foreign key",
            )
        )

    def _workspace_runtime_binding_write_error(self, exc: Exception) -> CharactersRAGDBError:
        if self._workspace_runtime_binding_is_constraint_error(exc):
            return ConflictError(
                f"Workspace runtime binding write conflicted: {exc}",
                entity="workspace_runtime_bindings",
            )
        return CharactersRAGDBError(f"Workspace runtime binding write failed: {exc}")  # noqa: TRY003

    @staticmethod
    def _normalize_runtime_binding_limit(limit: int) -> int:
        if isinstance(limit, bool) or not isinstance(limit, int):
            raise InputError("limit must be an integer.")  # noqa: TRY003
        if limit < 1 or limit > 1000:
            raise InputError("limit must be between 1 and 1000.")  # noqa: TRY003
        return limit

    @staticmethod
    def _normalize_workspace_runtime_binding_required_string(value: Any, field_name: str) -> str:
        normalized = str(value if value is not None else "").strip()
        if not normalized:
            raise InputError(f"{field_name} is required.")  # noqa: TRY003
        return normalized

    @staticmethod
    def _workspace_runtime_binding_filter_value(value: Any, field_name: str) -> str:
        normalized = str(value if value is not None else "").strip().lower()
        if not normalized:
            raise InputError(f"{field_name} is required.")  # noqa: TRY003
        return normalized

    def _normalize_workspace_runtime_binding_input(self, data: Mapping[str, Any]) -> dict[str, Any]:
        from tldw_Server_API.app.core.Workspaces.runtime_bindings import (
            normalize_runtime_binding_payload,
        )

        return normalize_runtime_binding_payload(data)

    def _normalize_workspace_runtime_binding_row(self, row: Mapping[str, Any] | None) -> dict[str, Any] | None:
        if not row:
            return None
        from tldw_Server_API.app.core.Workspaces.runtime_bindings import (
            runtime_binding_response_payload,
        )

        return runtime_binding_response_payload(row)

    @staticmethod
    def _workspace_runtime_binding_fields_match(
        existing: Mapping[str, Any],
        requested: Mapping[str, Any],
    ) -> bool:
        return all(
            existing.get(field_name) == requested.get(field_name)
            for field_name in (
                "binding_kind",
                "owner_domain",
                "locator_ref",
                "label",
                "status",
                "path_hint",
                "portability",
                "metadata",
                "redaction_report",
            )
        )

    def _require_workspace_runtime_binding_workspace(
        self,
        conn: sqlite3.Connection | BackendConnectionWrapper,
        workspace_id: str,
    ) -> None:
        row = conn.execute(
            "SELECT id FROM workspaces WHERE id = ? AND deleted = ?",
            (workspace_id, self._workspace_active_deleted_value()),
        ).fetchone()
        if row is None:
            raise ConflictError(
                "Workspace not found or deleted.",
                entity="workspaces",
                entity_id=workspace_id,
            )

    def _get_workspace_runtime_binding_with_conn(
        self,
        conn: sqlite3.Connection | BackendConnectionWrapper,
        workspace_id: str,
        binding_id: str,
        *,
        include_deleted: bool,
    ) -> dict[str, Any] | None:
        include_deleted_flag = 1 if include_deleted else 0
        row = conn.execute(
            """
            SELECT *
              FROM workspace_runtime_bindings
             WHERE workspace_id = ?
               AND binding_id = ?
               AND (? = 1 OR deleted = ?)
            """,
            (
                workspace_id,
                binding_id,
                include_deleted_flag,
                self._workspace_active_deleted_value(),
            ),
        ).fetchone()
        return self._normalize_workspace_runtime_binding_row(row)

    def upsert_workspace_runtime_binding(
        self,
        workspace_id: str,
        data: Mapping[str, Any],
        *,
        user_id: str | None = None,
    ) -> dict[str, Any]:
        """Create, update, or restore a Workspace runtime binding descriptor."""
        normalized_workspace_id = self._normalize_workspace_runtime_binding_required_string(
            workspace_id,
            "workspace_id",
        )
        values = self._normalize_workspace_runtime_binding_input(data)
        actor = self._normalize_workspace_runtime_binding_actor(user_id)
        now = self._get_current_utc_timestamp_iso()
        active_deleted_value = self._workspace_active_deleted_value()

        try:
            with self.transaction() as conn:
                self._require_workspace_runtime_binding_workspace(conn, normalized_workspace_id)
                existing = self._get_workspace_runtime_binding_with_conn(
                    conn,
                    normalized_workspace_id,
                    values["binding_id"],
                    include_deleted=True,
                )
                if existing is not None:
                    if (
                        existing.get("deleted") not in (True, 1)
                        and self._workspace_runtime_binding_fields_match(existing, values)
                    ):
                        return existing
                    cursor = conn.execute(
                        """
                        UPDATE workspace_runtime_bindings
                           SET binding_kind = ?,
                               owner_domain = ?,
                               locator_ref = ?,
                               label = ?,
                               status = ?,
                               path_hint = ?,
                               portability = ?,
                               metadata_json = ?,
                               redaction_report_json = ?,
                               updated_by_user_id = ?,
                               updated_at = ?,
                               deleted = ?,
                               client_id = ?,
                               version = version + 1
                         WHERE workspace_id = ?
                           AND binding_id = ?
                        """,
                        (
                            values["binding_kind"],
                            values["owner_domain"],
                            values["locator_ref"],
                            values["label"],
                            values["status"],
                            values["path_hint"],
                            values["portability"],
                            values["metadata_json"],
                            values["redaction_report_json"],
                            actor,
                            now,
                            active_deleted_value,
                            self.client_id or "unknown",
                            normalized_workspace_id,
                            values["binding_id"],
                        ),
                    )
                    if cursor.rowcount == 1:
                        updated = self._get_workspace_runtime_binding_with_conn(
                            conn,
                            normalized_workspace_id,
                            values["binding_id"],
                            include_deleted=False,
                        )
                        if updated is None:
                            raise CharactersRAGDBError("Updated runtime binding row could not be reloaded.")  # noqa: TRY003
                        return updated
                    raise CharactersRAGDBError("Runtime binding update changed no rows.")  # noqa: TRY003

                conn.execute(
                    """
                    INSERT INTO workspace_runtime_bindings (
                        workspace_id,
                        binding_id,
                        binding_kind,
                        owner_domain,
                        locator_ref,
                        label,
                        status,
                        path_hint,
                        portability,
                        metadata_json,
                        redaction_report_json,
                        created_by_user_id,
                        updated_by_user_id,
                        created_at,
                        updated_at,
                        deleted,
                        client_id,
                        version
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)
                    """,
                    (
                        normalized_workspace_id,
                        values["binding_id"],
                        values["binding_kind"],
                        values["owner_domain"],
                        values["locator_ref"],
                        values["label"],
                        values["status"],
                        values["path_hint"],
                        values["portability"],
                        values["metadata_json"],
                        values["redaction_report_json"],
                        actor,
                        actor,
                        now,
                        now,
                        active_deleted_value,
                        self.client_id or "unknown",
                    ),
                )
                created = self._get_workspace_runtime_binding_with_conn(
                    conn,
                    normalized_workspace_id,
                    values["binding_id"],
                    include_deleted=False,
                )
                if created is None:
                    raise CharactersRAGDBError("Created runtime binding row could not be reloaded.")  # noqa: TRY003
                return created
        except ConflictError:
            raise
        except (sqlite3.IntegrityError, BackendDatabaseError) as exc:
            raise self._workspace_runtime_binding_write_error(exc) from exc

    def get_workspace_runtime_binding(
        self,
        workspace_id: str,
        binding_id: str,
        *,
        include_deleted: bool = False,
    ) -> dict[str, Any] | None:
        """Fetch one Workspace runtime binding descriptor."""
        normalized_workspace_id = self._normalize_workspace_runtime_binding_required_string(
            workspace_id,
            "workspace_id",
        )
        normalized_binding_id = self._normalize_workspace_runtime_binding_required_string(
            binding_id,
            "binding_id",
        )
        try:
            if include_deleted:
                cursor = self.execute_query(
                    "SELECT * FROM workspace_runtime_bindings WHERE workspace_id = ? AND binding_id = ?",
                    (normalized_workspace_id, normalized_binding_id),
                )
                return self._normalize_workspace_runtime_binding_row(cursor.fetchone())
            cursor = self.execute_query(
                "SELECT * FROM workspace_runtime_bindings WHERE workspace_id = ? AND binding_id = ? AND deleted = ?",
                (
                    normalized_workspace_id,
                    normalized_binding_id,
                    self._workspace_active_deleted_value(),
                ),
            )
            return self._normalize_workspace_runtime_binding_row(cursor.fetchone())
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed fetching workspace runtime binding: {exc}") from exc  # noqa: TRY003

    def list_workspace_runtime_bindings(
        self,
        workspace_id: str,
        *,
        binding_kind: str | None = None,
        owner_domain: str | None = None,
        include_deleted: bool = False,
        limit: int = 100,
    ) -> list[dict[str, Any]]:
        """List runtime binding descriptors for one Workspace."""
        normalized_workspace_id = self._normalize_workspace_runtime_binding_required_string(
            workspace_id,
            "workspace_id",
        )
        normalized_limit = self._normalize_runtime_binding_limit(limit)
        normalized_kind = (
            self._workspace_runtime_binding_filter_value(binding_kind, "binding_kind")
            if binding_kind is not None
            else None
        )
        normalized_owner = (
            self._workspace_runtime_binding_filter_value(owner_domain, "owner_domain")
            if owner_domain is not None
            else None
        )
        include_deleted_flag = 1 if include_deleted else 0
        cursor = self.execute_query(
            """
            SELECT *
              FROM workspace_runtime_bindings
             WHERE workspace_id = ?
               AND (? = 1 OR deleted = ?)
               AND (? IS NULL OR binding_kind = ?)
               AND (? IS NULL OR owner_domain = ?)
             ORDER BY updated_at DESC, binding_id ASC
             LIMIT ?
            """,
            (
                normalized_workspace_id,
                include_deleted_flag,
                self._workspace_active_deleted_value(),
                normalized_kind,
                normalized_kind,
                normalized_owner,
                normalized_owner,
                normalized_limit,
            ),
        )
        return [
            normalized
            for row in cursor.fetchall()
            if (normalized := self._normalize_workspace_runtime_binding_row(row)) is not None
        ]

    def workspace_runtime_binding_summary(
        self,
        workspace_id: str,
        *,
        include_deleted: bool = False,
    ) -> dict[str, Any]:
        """Return unpaginated runtime binding counts for one Workspace."""
        normalized_workspace_id = self._normalize_workspace_runtime_binding_required_string(
            workspace_id,
            "workspace_id",
        )
        include_deleted_flag = 1 if include_deleted else 0
        cursor = self.execute_query(
            """
            SELECT binding_kind, status, COUNT(*) AS count
              FROM workspace_runtime_bindings
             WHERE workspace_id = ?
               AND (? = 1 OR deleted = ?)
             GROUP BY binding_kind, status
            """,
            (
                normalized_workspace_id,
                include_deleted_flag,
                self._workspace_active_deleted_value(),
            ),
        )
        by_kind: Counter[str] = Counter()
        by_status: Counter[str] = Counter()
        total = 0
        for row in cursor.fetchall():
            count = int(row["count"] if isinstance(row, Mapping) else row[2])
            binding_kind = str((row["binding_kind"] if isinstance(row, Mapping) else row[0]) or "")
            status = str((row["status"] if isinstance(row, Mapping) else row[1]) or "")
            total += count
            if binding_kind:
                by_kind[binding_kind] += count
            if status:
                by_status[status] += count
        return {
            "total": total,
            "by_kind": dict(sorted(by_kind.items())),
            "by_status": dict(sorted(by_status.items())),
        }

    def archive_workspace_runtime_binding(
        self,
        workspace_id: str,
        binding_id: str,
        *,
        user_id: str | None = None,
    ) -> dict[str, Any] | None:
        """Soft-delete one Workspace runtime binding descriptor."""
        normalized_workspace_id = self._normalize_workspace_runtime_binding_required_string(
            workspace_id,
            "workspace_id",
        )
        normalized_binding_id = self._normalize_workspace_runtime_binding_required_string(
            binding_id,
            "binding_id",
        )
        actor = self._normalize_workspace_runtime_binding_actor(user_id)
        now = self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                existing = self._get_workspace_runtime_binding_with_conn(
                    conn,
                    normalized_workspace_id,
                    normalized_binding_id,
                    include_deleted=True,
                )
                if existing is None or existing.get("deleted") in (True, 1):
                    return None
                deleted_value = True if self.backend_type == BackendType.POSTGRESQL else 1
                cursor = conn.execute(
                    """
                    UPDATE workspace_runtime_bindings
                       SET deleted = ?,
                           status = ?,
                           updated_at = ?,
                           updated_by_user_id = ?,
                           client_id = ?,
                           version = version + 1
                     WHERE workspace_id = ?
                       AND binding_id = ?
                       AND deleted = ?
                    """,
                    (
                        deleted_value,
                        "archived",
                        now,
                        actor,
                        self.client_id or "unknown",
                        normalized_workspace_id,
                        normalized_binding_id,
                        self._workspace_active_deleted_value(),
                    ),
                )
                if cursor.rowcount == 1:
                    return self._get_workspace_runtime_binding_with_conn(
                        conn,
                        normalized_workspace_id,
                        normalized_binding_id,
                        include_deleted=True,
                    )
                raced = self._get_workspace_runtime_binding_with_conn(
                    conn,
                    normalized_workspace_id,
                    normalized_binding_id,
                    include_deleted=True,
                )
                if raced is None or raced.get("deleted") in (True, 1):
                    return raced
                raise CharactersRAGDBError("Archive race left runtime binding active.")  # noqa: TRY003
        except (sqlite3.IntegrityError, BackendDatabaseError) as exc:
            raise self._workspace_runtime_binding_write_error(exc) from exc

    # --- Workspace Resource Membership Methods ---

    @staticmethod
    def _normalize_workspace_membership_required_string(value: Any, field_name: str) -> str:
        normalized = str(value if value is not None else "").strip()
        if not normalized:
            raise InputError(f"{field_name} is required.")  # noqa: TRY003
        return normalized

    @staticmethod
    def _normalize_workspace_membership_optional_string(value: Any) -> str | None:
        if value is None:
            return None
        normalized = str(value).strip()
        return normalized or None

    @classmethod
    def _normalize_workspace_membership_json_object(cls, value: Any, field_name: str) -> tuple[dict[str, Any], str]:
        max_bytes = (
            WORKSPACE_MEMBERSHIP_MAX_PROVENANCE_BYTES
            if field_name == "provenance"
            else WORKSPACE_MEMBERSHIP_MAX_METADATA_BYTES
        )
        try:
            return dump_membership_json_object(value, field_name=field_name, max_bytes=max_bytes)
        except ValueError as exc:
            raise InputError(str(exc)) from exc  # noqa: TRY003

    @classmethod
    def _load_workspace_membership_json_object(cls, value: Any, *, field_name: str) -> dict[str, Any]:
        if value is None:
            return {}
        if isinstance(value, Mapping):
            return dict(value)
        if isinstance(value, str):
            if not value.strip():
                return {}
            try:
                parsed = json.loads(value)
            except json.JSONDecodeError:
                logger.warning(
                    "Failed to decode workspace resource membership JSON field {} ({} chars)",
                    field_name,
                    len(value),
                )
                return {}
            return parsed if isinstance(parsed, dict) else {}
        return {}

    def _normalize_workspace_membership_input(self, data: Mapping[str, Any]) -> dict[str, Any]:
        resource_type = self._normalize_workspace_membership_required_string(
            data.get("resource_type"),
            "resource_type",
        )
        resource_id = self._normalize_workspace_membership_required_string(
            data.get("resource_id"),
            "resource_id",
        )
        role = self._normalize_workspace_membership_optional_string(data.get("role")) or "member"
        transfer_policy = (
            self._normalize_workspace_membership_optional_string(data.get("transfer_policy"))
            or "link"
        )
        label = self._normalize_workspace_membership_optional_string(data.get("label"))
        provenance, provenance_json = self._normalize_workspace_membership_json_object(
            data.get("provenance", data.get("provenance_json")),
            "provenance",
        )
        metadata, metadata_json = self._normalize_workspace_membership_json_object(
            data.get("metadata", data.get("metadata_json")),
            "metadata",
        )
        return {
            "resource_type": resource_type,
            "resource_id": resource_id,
            "role": role,
            "label": label,
            "transfer_policy": transfer_policy,
            "provenance": provenance,
            "provenance_json": provenance_json,
            "metadata": metadata,
            "metadata_json": metadata_json,
        }

    def _normalize_workspace_membership_actor(self, user_id: str | None) -> str | None:
        if user_id is None:
            return None
        normalized = str(user_id).strip()
        return normalized or None

    def _normalize_workspace_membership_row(self, row: Mapping[str, Any] | None) -> dict[str, Any] | None:
        if not row:
            return None
        item = dict(row)
        item["provenance"] = self._load_workspace_membership_json_object(
            item.get("provenance_json"),
            field_name="provenance_json",
        )
        item["metadata"] = self._load_workspace_membership_json_object(
            item.get("metadata_json"),
            field_name="metadata_json",
        )
        item["version"] = int(item.get("version") or 1)
        return item

    @staticmethod
    def _workspace_membership_fields_match(
        existing: Mapping[str, Any],
        requested: Mapping[str, Any],
    ) -> bool:
        return (
            existing.get("role") == requested.get("role")
            and existing.get("label") == requested.get("label")
            and existing.get("transfer_policy") == requested.get("transfer_policy")
            and existing.get("provenance") == requested.get("provenance")
            and existing.get("metadata") == requested.get("metadata")
        )

    @staticmethod
    def _workspace_membership_is_constraint_error(exc: Exception) -> bool:
        message = str(exc).lower()
        return any(
            token in message
            for token in (
                "unique",
                "duplicate",
                "constraint",
                "foreign key",
            )
        )

    def _workspace_membership_write_error(self, exc: Exception) -> CharactersRAGDBError:
        if self._workspace_membership_is_constraint_error(exc):
            return ConflictError(
                f"Workspace resource membership write conflicted: {exc}",
                entity="workspace_resource_memberships",
            )
        return CharactersRAGDBError(f"Workspace resource membership write failed: {exc}")  # noqa: TRY003

    def _get_workspace_resource_membership_with_conn(
        self,
        conn: sqlite3.Connection | BackendConnectionWrapper,
        workspace_id: str,
        resource_type: str,
        resource_id: str,
        *,
        include_deleted: bool,
    ) -> dict[str, Any] | None:
        clauses = [
            "workspace_id = ?",
            "resource_type = ?",
            "resource_id = ?",
        ]
        params: list[Any] = [workspace_id, resource_type, resource_id]
        if not include_deleted:
            clauses.append("deleted = ?")
            params.append(self._workspace_active_deleted_value())
        row = conn.execute(
            f"SELECT * FROM workspace_resource_memberships WHERE {' AND '.join(clauses)}",  # nosec B608
            tuple(params),
        ).fetchone()
        return self._normalize_workspace_membership_row(row)

    def add_workspace_resource_membership(
        self,
        workspace_id: str,
        data: dict[str, Any],
        *,
        user_id: str | None = None,
    ) -> dict[str, Any]:
        """Create or restore a Workspace resource membership."""
        normalized_workspace_id = self._normalize_workspace_membership_required_string(
            workspace_id,
            "workspace_id",
        )
        values = self._normalize_workspace_membership_input(data)
        actor = self._normalize_workspace_membership_actor(user_id)
        restore_deleted = bool(data.get("restore_deleted") is True)
        now = self._get_current_utc_timestamp_iso()
        active_deleted_value = self._workspace_active_deleted_value()

        try:
            with self.transaction() as conn:
                existing = self._get_workspace_resource_membership_with_conn(
                    conn,
                    normalized_workspace_id,
                    values["resource_type"],
                    values["resource_id"],
                    include_deleted=True,
                )
                if existing is not None:
                    if existing.get("deleted") in (True, 1):
                        if not restore_deleted:
                            raise ConflictError(
                                "Workspace resource membership exists but is deleted.",
                                entity="workspace_resource_memberships",
                                entity_id=values["resource_id"],
                            )
                        deleted_value = True if self.backend_type == BackendType.POSTGRESQL else 1
                        cursor = conn.execute(
                            """
                            UPDATE workspace_resource_memberships
                               SET role = ?,
                                   label = ?,
                                   transfer_policy = ?,
                                   provenance_json = ?,
                                   metadata_json = ?,
                                   updated_by_user_id = ?,
                                   updated_at = ?,
                                   deleted = ?,
                                   client_id = ?,
                                   version = version + 1
                             WHERE workspace_id = ?
                               AND resource_type = ?
                               AND resource_id = ?
                               AND deleted = ?
                            """,
                            (
                                values["role"],
                                values["label"],
                                values["transfer_policy"],
                                values["provenance_json"],
                                values["metadata_json"],
                                actor,
                                now,
                                active_deleted_value,
                                self.client_id or "unknown",
                                normalized_workspace_id,
                                values["resource_type"],
                                values["resource_id"],
                                deleted_value,
                            ),
                        )
                        if cursor.rowcount == 1:
                            restored = self._get_workspace_resource_membership_with_conn(
                                conn,
                                normalized_workspace_id,
                                values["resource_type"],
                                values["resource_id"],
                                include_deleted=False,
                            )
                            if restored is None:
                                raise CharactersRAGDBError("Restored membership row could not be reloaded.")  # noqa: TRY003
                            return restored

                        raced = self._get_workspace_resource_membership_with_conn(
                            conn,
                            normalized_workspace_id,
                            values["resource_type"],
                            values["resource_id"],
                            include_deleted=True,
                        )
                        if raced is None or raced.get("deleted") in (True, 1):
                            raise CharactersRAGDBError("Restore race left membership unavailable.")  # noqa: TRY003
                        if self._workspace_membership_fields_match(raced, values):
                            return raced
                        raise ConflictError(
                            "Workspace resource membership already restored with different fields.",
                            entity="workspace_resource_memberships",
                            entity_id=values["resource_id"],
                        )

                    if self._workspace_membership_fields_match(existing, values):
                        return existing
                    raise ConflictError(
                        "Workspace resource membership already exists with different fields.",
                        entity="workspace_resource_memberships",
                        entity_id=values["resource_id"],
                    )

                conn.execute(
                    """
                    INSERT INTO workspace_resource_memberships (
                        workspace_id,
                        resource_type,
                        resource_id,
                        role,
                        label,
                        transfer_policy,
                        provenance_json,
                        metadata_json,
                        created_by_user_id,
                        updated_by_user_id,
                        created_at,
                        updated_at,
                        deleted,
                        client_id,
                        version
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)
                    """,
                    (
                        normalized_workspace_id,
                        values["resource_type"],
                        values["resource_id"],
                        values["role"],
                        values["label"],
                        values["transfer_policy"],
                        values["provenance_json"],
                        values["metadata_json"],
                        actor,
                        actor,
                        now,
                        now,
                        active_deleted_value,
                        self.client_id or "unknown",
                    ),
                )
                created = self._get_workspace_resource_membership_with_conn(
                    conn,
                    normalized_workspace_id,
                    values["resource_type"],
                    values["resource_id"],
                    include_deleted=False,
                )
                if created is None:
                    raise CharactersRAGDBError("Created membership row could not be reloaded.")  # noqa: TRY003
                return created
        except ConflictError:
            raise
        except (sqlite3.IntegrityError, BackendDatabaseError) as exc:
            existing = self.get_workspace_resource_membership(
                normalized_workspace_id,
                values["resource_type"],
                values["resource_id"],
                include_deleted=True,
            )
            if existing is not None and not existing.get("deleted") and self._workspace_membership_fields_match(
                existing,
                values,
            ):
                return existing
            raise self._workspace_membership_write_error(exc) from exc

    def get_workspace_resource_membership(
        self,
        workspace_id: str,
        resource_type: str,
        resource_id: str,
        *,
        include_deleted: bool = False,
    ) -> dict[str, Any] | None:
        """Fetch one Workspace resource membership by composite id."""
        normalized_workspace_id = self._normalize_workspace_membership_required_string(
            workspace_id,
            "workspace_id",
        )
        normalized_resource_type = self._normalize_workspace_membership_required_string(
            resource_type,
            "resource_type",
        )
        normalized_resource_id = self._normalize_workspace_membership_required_string(
            resource_id,
            "resource_id",
        )
        try:
            if include_deleted:
                cursor = self.execute_query(
                    "SELECT * FROM workspace_resource_memberships "
                    "WHERE workspace_id = ? AND resource_type = ? AND resource_id = ?",
                    (
                        normalized_workspace_id,
                        normalized_resource_type,
                        normalized_resource_id,
                    ),
                )
                return self._normalize_workspace_membership_row(cursor.fetchone())
            cursor = self.execute_query(
                "SELECT * FROM workspace_resource_memberships "
                "WHERE workspace_id = ? AND resource_type = ? AND resource_id = ? AND deleted = ?",
                (
                    normalized_workspace_id,
                    normalized_resource_type,
                    normalized_resource_id,
                    self._workspace_active_deleted_value(),
                ),
            )
            return self._normalize_workspace_membership_row(cursor.fetchone())
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed fetching workspace resource membership: {exc}") from exc  # noqa: TRY003

    @staticmethod
    def _normalize_membership_limit(limit: int) -> int:
        if isinstance(limit, bool) or not isinstance(limit, int):
            raise InputError("limit must be an integer.")  # noqa: TRY003
        if limit < 1 or limit > 1000:
            raise InputError("limit must be between 1 and 1000.")  # noqa: TRY003
        return limit

    def list_workspace_resource_memberships(
        self,
        workspace_id: str,
        *,
        resource_type: str | None = None,
        role: str | None = None,
        include_deleted: bool = False,
        limit: int = 100,
        cursor: tuple[str, str, str] | None = None,
    ) -> list[dict[str, Any]]:
        """List resource memberships for a workspace in deterministic order."""
        normalized_workspace_id = self._normalize_workspace_membership_required_string(
            workspace_id,
            "workspace_id",
        )
        normalized_limit = self._normalize_membership_limit(limit)
        clauses = ["workspace_id = ?"]
        params: list[Any] = [normalized_workspace_id]
        if resource_type is not None:
            clauses.append("resource_type = ?")
            params.append(
                self._normalize_workspace_membership_required_string(
                    resource_type,
                    "resource_type",
                )
            )
        if role is not None:
            clauses.append("role = ?")
            params.append(self._normalize_workspace_membership_required_string(role, "role"))
        if not include_deleted:
            clauses.append("deleted = ?")
            params.append(self._workspace_active_deleted_value())
        if cursor is not None:
            if len(cursor) != 3:
                raise InputError("cursor must be a tuple of (updated_at, resource_type, resource_id).")  # noqa: TRY003
            cursor_updated_at, cursor_resource_type, cursor_resource_id = cursor
            clauses.append(
                "(updated_at < ? "
                "OR (updated_at = ? AND resource_type > ?) "
                "OR (updated_at = ? AND resource_type = ? AND resource_id > ?))"
            )
            params.extend(
                [
                    cursor_updated_at,
                    cursor_updated_at,
                    cursor_resource_type,
                    cursor_updated_at,
                    cursor_resource_type,
                    cursor_resource_id,
                ]
            )
        params.append(normalized_limit + 1)
        cursor_obj = self.execute_query(
            f"SELECT * FROM workspace_resource_memberships WHERE {' AND '.join(clauses)} "  # nosec B608
            "ORDER BY updated_at DESC, resource_type ASC, resource_id ASC LIMIT ?",
            tuple(params),
        )
        return [
            normalized
            for row in cursor_obj.fetchall()
            if (normalized := self._normalize_workspace_membership_row(row)) is not None
        ]

    def list_resource_workspace_memberships(
        self,
        resource_type: str,
        resource_id: str,
        *,
        include_deleted: bool = False,
        limit: int = 100,
        cursor: tuple[str, str] | None = None,
    ) -> list[dict[str, Any]]:
        """List all workspace memberships for one resource."""
        normalized_resource_type = self._normalize_workspace_membership_required_string(
            resource_type,
            "resource_type",
        )
        normalized_resource_id = self._normalize_workspace_membership_required_string(
            resource_id,
            "resource_id",
        )
        normalized_limit = self._normalize_membership_limit(limit)
        clauses = ["resource_type = ?", "resource_id = ?"]
        params: list[Any] = [normalized_resource_type, normalized_resource_id]
        if not include_deleted:
            clauses.append("deleted = ?")
            params.append(self._workspace_active_deleted_value())
        if cursor is not None:
            if len(cursor) != 2:
                raise InputError("cursor must be a tuple of (updated_at, workspace_id).")  # noqa: TRY003
            cursor_updated_at, cursor_workspace_id = cursor
            clauses.append(
                "(updated_at < ? OR (updated_at = ? AND workspace_id > ?))"
            )
            params.extend([cursor_updated_at, cursor_updated_at, cursor_workspace_id])
        params.append(normalized_limit + 1)
        cursor_obj = self.execute_query(
            f"SELECT * FROM workspace_resource_memberships WHERE {' AND '.join(clauses)} "  # nosec B608
            "ORDER BY updated_at DESC, workspace_id ASC LIMIT ?",
            tuple(params),
        )
        return [
            normalized
            for row in cursor_obj.fetchall()
            if (normalized := self._normalize_workspace_membership_row(row)) is not None
        ]

    def workspace_resource_membership_summary(self, workspace_id: str) -> dict[str, Any]:
        """Return compact active membership counts for one Workspace."""
        normalized_workspace_id = self._normalize_workspace_membership_required_string(
            workspace_id,
            "workspace_id",
        )
        active_deleted_value = self._workspace_active_deleted_value()

        def _row_value(row: Any, key: str, index: int, default: Any = 0) -> Any:
            if row is None:
                return default
            try:
                return row[key]
            except (KeyError, IndexError, TypeError):
                try:
                    return row[index]
                except (IndexError, TypeError):
                    return default

        try:
            total_cursor = self.execute_query(
                """
                SELECT COUNT(*) AS total
                  FROM workspace_resource_memberships
                 WHERE workspace_id = ? AND deleted = ?
                """,
                (normalized_workspace_id, active_deleted_value),
            )
            total_row = total_cursor.fetchone()
            resource_cursor = self.execute_query(
                """
                SELECT resource_type, COUNT(*) AS count
                  FROM workspace_resource_memberships
                 WHERE workspace_id = ? AND deleted = ?
                 GROUP BY resource_type
                 ORDER BY resource_type ASC
                """,
                (normalized_workspace_id, active_deleted_value),
            )
            role_cursor = self.execute_query(
                """
                SELECT role, COUNT(*) AS count
                  FROM workspace_resource_memberships
                 WHERE workspace_id = ? AND deleted = ?
                 GROUP BY role
                 ORDER BY role ASC
                """,
                (normalized_workspace_id, active_deleted_value),
            )
            by_resource_type = {
                str(_row_value(row, "resource_type", 0)): int(_row_value(row, "count", 1))
                for row in resource_cursor.fetchall()
                if _row_value(row, "resource_type", 0, None) is not None
            }
            by_role = {
                str(_row_value(row, "role", 0)): int(_row_value(row, "count", 1))
                for row in role_cursor.fetchall()
                if _row_value(row, "role", 0, None) is not None
            }
            return {
                "total": int(_row_value(total_row, "total", 0)),
                "by_resource_type": by_resource_type,
                "by_role": by_role,
            }
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(
                f"Failed summarizing workspace resource memberships: {exc}"
            ) from exc  # noqa: TRY003

    def delete_workspace_resource_membership(
        self,
        workspace_id: str,
        resource_type: str,
        resource_id: str,
        *,
        user_id: str | None = None,
    ) -> dict[str, Any] | None:
        """Soft-delete one Workspace resource membership.

        Missing rows and already deleted rows are idempotent no-ops.
        """
        normalized_workspace_id = self._normalize_workspace_membership_required_string(
            workspace_id,
            "workspace_id",
        )
        normalized_resource_type = self._normalize_workspace_membership_required_string(
            resource_type,
            "resource_type",
        )
        normalized_resource_id = self._normalize_workspace_membership_required_string(
            resource_id,
            "resource_id",
        )
        actor = self._normalize_workspace_membership_actor(user_id)
        now = self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                existing = self._get_workspace_resource_membership_with_conn(
                    conn,
                    normalized_workspace_id,
                    normalized_resource_type,
                    normalized_resource_id,
                    include_deleted=True,
                )
                if existing is None or existing.get("deleted") in (True, 1):
                    return None
                deleted_value = True if self.backend_type == BackendType.POSTGRESQL else 1
                active_deleted_value = self._workspace_active_deleted_value()
                cursor = conn.execute(
                    """
                    UPDATE workspace_resource_memberships
                       SET deleted = ?,
                           updated_at = ?,
                           updated_by_user_id = ?,
                           client_id = ?,
                           version = version + 1
                     WHERE workspace_id = ?
                       AND resource_type = ?
                       AND resource_id = ?
                       AND deleted = ?
                    """,
                    (
                        deleted_value,
                        now,
                        actor,
                        self.client_id or "unknown",
                        normalized_workspace_id,
                        normalized_resource_type,
                        normalized_resource_id,
                        active_deleted_value,
                    ),
                )
                if cursor.rowcount == 1:
                    return self._get_workspace_resource_membership_with_conn(
                        conn,
                        normalized_workspace_id,
                        normalized_resource_type,
                        normalized_resource_id,
                        include_deleted=True,
                    )

                raced = self._get_workspace_resource_membership_with_conn(
                    conn,
                    normalized_workspace_id,
                    normalized_resource_type,
                    normalized_resource_id,
                    include_deleted=True,
                )
                if raced is None or raced.get("deleted") in (True, 1):
                    return None
                raise CharactersRAGDBError("Delete race left membership active.")  # noqa: TRY003
        except (sqlite3.IntegrityError, BackendDatabaseError) as exc:
            raise self._workspace_membership_write_error(exc) from exc

    def get_conversation_for_workspace_membership(
        self,
        conversation_id: str,
        *,
        include_deleted: bool = False,
    ) -> dict[str, Any] | None:
        """Fetch the compact conversation row needed by Workspace membership adapters."""
        normalized_conversation_id = self._normalize_workspace_membership_required_string(
            conversation_id,
            "conversation_id",
        )
        deleted_clause = ""
        params: list[Any] = [normalized_conversation_id]
        if not include_deleted:
            deleted_clause = " AND deleted = ?"
            params.append(self._workspace_active_deleted_value())
        cursor = self.execute_query(
            "SELECT id, title, workspace_id, scope_type, last_modified, deleted, version "
            f"FROM conversations WHERE id = ?{deleted_clause}",  # nosec B608
            tuple(params),
        )
        row = cursor.fetchone()
        return dict(row) if row else None

    # --- Workspace Artifact Methods ---

    _WORKSPACE_ARTIFACT_JSON_FIELDS: tuple[tuple[str, str, Any], ...] = (
        ("producer_metadata_json", "producer_metadata", {}),
        ("source_lineage_json", "source_lineage", {}),
        ("review_metadata_json", "review_metadata", {}),
        ("version_metadata_json", "version_metadata", {}),
        ("export_refs_json", "export_refs", []),
        ("redaction_json", "redaction", {"support_safe": True, "redacted": False}),
    )

    @staticmethod
    def _copy_workspace_artifact_default(default: Any) -> Any:
        if isinstance(default, (dict, list)):
            return json.loads(json.dumps(default))
        return default

    @classmethod
    def _load_workspace_artifact_json(
        cls,
        raw: Any,
        default: Any,
        *,
        field_name: str = "workspace_artifact_json",
    ) -> Any:
        if raw is None:
            return cls._copy_workspace_artifact_default(default)
        if isinstance(raw, (dict, list)):
            return raw
        if isinstance(raw, str):
            if not raw.strip():
                return cls._copy_workspace_artifact_default(default)
            try:
                return json.loads(raw)
            except json.JSONDecodeError:
                preview = raw[:120].replace("\n", "\\n")
                logger.warning(
                    "Failed to decode workspace artifact JSON field {} ({} chars): {}",
                    field_name,
                    len(raw),
                    preview,
                )
                return cls._copy_workspace_artifact_default(default)
        return cls._copy_workspace_artifact_default(default)

    @classmethod
    def _dump_workspace_artifact_json(cls, value: Any, default: Any) -> str:
        if value is None:
            value = cls._copy_workspace_artifact_default(default)
        return json.dumps(value, ensure_ascii=True)

    @staticmethod
    def _workspace_artifact_version_id(artifact_id: str, version: int) -> str:
        return f"{artifact_id}:v{version}"

    def _normalize_workspace_artifact_review_state(self, value: Any) -> str:
        state = str(value or "draft").strip().lower()
        if state not in self._ALLOWED_WORKSPACE_ARTIFACT_REVIEW_STATES:
            raise InputError(f"Unsupported workspace artifact review state '{state}'.")  # noqa: TRY003
        return state

    def _normalize_workspace_artifact_row(self, row: Mapping[str, Any] | None) -> dict[str, Any] | None:
        if not row:
            return None
        item = dict(row)
        artifact_id = str(item.get("id") or "")
        version = int(item.get("version") or 1)
        item["content_type"] = item.get("content_type") or "text/markdown"
        item["review_state"] = item.get("review_state") or "draft"
        item["owner_scope"] = item.get("owner_scope") or "user"
        item["root_artifact_id"] = item.get("root_artifact_id") or artifact_id
        item["artifact_version_id"] = item.get("artifact_version_id") or self._workspace_artifact_version_id(artifact_id, version)
        item["previous_version_id"] = item.get("previous_version_id")
        item["schema_version"] = int(item.get("schema_version") or 1)
        for column_name, response_name, default in self._WORKSPACE_ARTIFACT_JSON_FIELDS:
            item[response_name] = self._load_workspace_artifact_json(
                item.get(column_name),
                default,
                field_name=column_name,
            )
        return item

    def _insert_workspace_artifact_version(
        self,
        conn: Any,
        *,
        workspace_id: str,
        artifact_id: str,
        artifact_version_id: str,
        root_artifact_id: str,
        previous_version_id: str | None,
        version: int,
        review_state: str,
        title: str,
        content: str | None,
        producer_metadata_json: str,
        source_lineage_json: str,
        review_metadata_json: str,
        version_metadata_json: str,
        export_refs_json: str,
        redaction_json: str,
        created_at: str,
    ) -> None:
        query = (
            "INSERT INTO workspace_artifact_versions (workspace_id, artifact_id, artifact_version_id, "
            "root_artifact_id, previous_version_id, version, review_state, title, content, "
            "producer_metadata_json, source_lineage_json, review_metadata_json, version_metadata_json, "
            "export_refs_json, redaction_json, created_at) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
        )
        conn.execute(
            query,
            (
                workspace_id,
                artifact_id,
                artifact_version_id,
                root_artifact_id,
                previous_version_id,
                version,
                review_state,
                title,
                content,
                producer_metadata_json,
                source_lineage_json,
                review_metadata_json,
                version_metadata_json,
                export_refs_json,
                redaction_json,
                created_at,
            ),
        )

    def add_workspace_artifact(self, workspace_id: str, data: dict[str, Any]) -> dict[str, Any]:
        """Add an artifact to a workspace."""
        artifact_id = data.get("id")
        if not artifact_id:
            raise InputError("Artifact id is required.")  # noqa: TRY003
        artifact_id = str(artifact_id)
        now = self._get_current_utc_timestamp_iso()
        review_state = self._normalize_workspace_artifact_review_state(data.get("review_state"))
        root_artifact_id = artifact_id
        artifact_version_id = self._workspace_artifact_version_id(artifact_id, 1)
        previous_version_id = None
        content_type = str(data.get("content_type") or "text/markdown")
        producer_metadata_json = self._dump_workspace_artifact_json(data.get("producer_metadata"), {})
        source_lineage_json = self._dump_workspace_artifact_json(data.get("source_lineage"), {})
        review_metadata_json = self._dump_workspace_artifact_json(data.get("review_metadata"), {})
        version_metadata_json = self._dump_workspace_artifact_json(data.get("version_metadata"), {})
        export_refs_json = self._dump_workspace_artifact_json(data.get("export_refs"), [])
        redaction_json = self._dump_workspace_artifact_json(data.get("redaction"), {"support_safe": True, "redacted": False})
        schema_version = int(data.get("schema_version") or 1)
        query = (
            "INSERT INTO workspace_artifacts (id, workspace_id, artifact_type, title, status, content, "
            "total_tokens, total_cost_usd, created_at, completed_at, version, content_type, preview_text, summary, "
            "review_state, owner_scope, owner_id, project_id, task_id, source_collection_id, root_artifact_id, "
            "artifact_version_id, previous_version_id, producer_metadata_json, source_lineage_json, review_metadata_json, "
            "version_metadata_json, export_refs_json, redaction_json, schema_version) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
        )
        params = (
            artifact_id,
            workspace_id,
            data.get("artifact_type", ""),
            data.get("title", ""),
            data.get("status", "pending"),
            data.get("content"),
            data.get("total_tokens"),
            data.get("total_cost_usd"),
            now,
            data.get("completed_at"),
            content_type,
            data.get("preview_text"),
            data.get("summary"),
            review_state,
            data.get("owner_scope") or "user",
            data.get("owner_id"),
            data.get("project_id"),
            data.get("task_id"),
            data.get("source_collection_id"),
            root_artifact_id,
            artifact_version_id,
            previous_version_id,
            producer_metadata_json,
            source_lineage_json,
            review_metadata_json,
            version_metadata_json,
            export_refs_json,
            redaction_json,
            schema_version,
        )
        with self.transaction() as conn:
            conn.execute(query, params)
            self._insert_workspace_artifact_version(
                conn,
                workspace_id=workspace_id,
                artifact_id=artifact_id,
                artifact_version_id=artifact_version_id,
                root_artifact_id=root_artifact_id,
                previous_version_id=previous_version_id,
                version=1,
                review_state=review_state,
                title=str(data.get("title", "")),
                content=data.get("content"),
                producer_metadata_json=producer_metadata_json,
                source_lineage_json=source_lineage_json,
                review_metadata_json=review_metadata_json,
                version_metadata_json=version_metadata_json,
                export_refs_json=export_refs_json,
                redaction_json=redaction_json,
                created_at=now,
            )
            row = conn.execute(
                "SELECT * FROM workspace_artifacts WHERE workspace_id = ? AND id = ?",
                (workspace_id, artifact_id),
            ).fetchone()
            artifact = self._normalize_workspace_artifact_row(row)
            if artifact is None:
                raise CharactersRAGDBError("Workspace artifact insert could not be verified.")  # noqa: TRY003
        return artifact

    def _get_workspace_artifact(
        self,
        workspace_id: str,
        artifact_id: str,
        *,
        include_deleted: bool = False,
    ) -> dict[str, Any] | None:
        cursor = self.execute_query(
            "SELECT * FROM workspace_artifacts WHERE workspace_id = ? AND id = ?",
            (workspace_id, artifact_id),
        )
        row = cursor.fetchone()
        return self._normalize_workspace_artifact_row(row)

    def get_workspace_artifact(
        self,
        workspace_id: str,
        artifact_id: str,
        *,
        include_deleted: bool = False,
    ) -> dict[str, Any] | None:
        """Fetch a workspace artifact by id."""
        return self._get_workspace_artifact(workspace_id, artifact_id, include_deleted=include_deleted)

    def list_workspace_artifacts(self, workspace_id: str) -> list[dict[str, Any]]:
        """List all artifacts for a workspace."""
        cursor = self.execute_query(
            "SELECT * FROM workspace_artifacts WHERE workspace_id = ? ORDER BY created_at DESC",
            (workspace_id,),
        )
        return [
            normalized
            for row in cursor.fetchall()
            if (normalized := self._normalize_workspace_artifact_row(row)) is not None
        ]

    def list_workspace_artifact_versions(self, workspace_id: str, artifact_id: str) -> list[dict[str, Any]]:
        """List version history for a workspace artifact."""
        cursor = self.execute_query(
            "SELECT * FROM workspace_artifact_versions WHERE workspace_id = ? AND artifact_id = ? ORDER BY version ASC",
            (workspace_id, artifact_id),
        )
        versions: list[dict[str, Any]] = []
        for row in cursor.fetchall():
            item = dict(row)
            for column_name, response_name, default in self._WORKSPACE_ARTIFACT_JSON_FIELDS:
                item[response_name] = self._load_workspace_artifact_json(
                    item.get(column_name),
                    default,
                    field_name=column_name,
                )
            versions.append(item)
        return versions

    def get_workspace_artifact_version(
        self,
        workspace_id: str,
        artifact_id: str,
        artifact_version_id: str,
    ) -> dict[str, Any] | None:
        """Fetch one workspace artifact version snapshot by stable version id."""
        cursor = self.execute_query(
            "SELECT * FROM workspace_artifact_versions "
            "WHERE workspace_id = ? AND artifact_id = ? AND artifact_version_id = ?",
            (workspace_id, artifact_id, artifact_version_id),
        )
        row = cursor.fetchone()
        if row is None:
            return None
        item = dict(row)
        for column_name, response_name, default in self._WORKSPACE_ARTIFACT_JSON_FIELDS:
            item[response_name] = self._load_workspace_artifact_json(
                item.get(column_name),
                default,
                field_name=column_name,
            )
        return item

    def append_workspace_artifact_export_ref(
        self,
        workspace_id: str,
        artifact_id: str,
        export_ref: Mapping[str, Any],
    ) -> dict[str, Any]:
        """Append an export reference without creating a new artifact content version."""
        for _attempt in range(3):
            with self.transaction() as conn:
                artifact_row = conn.execute(
                    "SELECT artifact_version_id, export_refs_json FROM workspace_artifacts "
                    "WHERE workspace_id = ? AND id = ?",
                    (workspace_id, artifact_id),
                ).fetchone()
                if artifact_row is None:
                    raise ConflictError(  # noqa: TRY003
                        f"Workspace artifact '{artifact_id}' not found.",
                        entity="workspace_artifacts",
                        entity_id=artifact_id,
                    )

                artifact_export_refs_json = artifact_row["export_refs_json"]
                artifact_version_id = str(
                    export_ref.get("artifact_version_id") or artifact_row["artifact_version_id"] or ""
                )
                if not artifact_version_id:
                    raise InputError("Workspace artifact export_ref artifact_version_id is required.")  # noqa: TRY003

                artifact_export_refs = self._load_workspace_artifact_json(
                    artifact_export_refs_json,
                    [],
                    field_name="workspace_artifacts.export_refs_json",
                )
                if not isinstance(artifact_export_refs, list):
                    raise InputError("Workspace artifact export_refs must be a list.")  # noqa: TRY003
                artifact_export_refs = list(artifact_export_refs)
                artifact_export_refs.append(dict(export_ref))
                updated_artifact_export_refs_json = self._dump_workspace_artifact_json(artifact_export_refs, [])

                if artifact_export_refs_json is None:
                    artifact_cursor = conn.execute(
                        "UPDATE workspace_artifacts SET export_refs_json = ? "
                        "WHERE workspace_id = ? AND id = ? AND export_refs_json IS NULL",
                        (updated_artifact_export_refs_json, workspace_id, artifact_id),
                    )
                else:
                    artifact_cursor = conn.execute(
                        "UPDATE workspace_artifacts SET export_refs_json = ? "
                        "WHERE workspace_id = ? AND id = ? AND export_refs_json = ?",
                        (updated_artifact_export_refs_json, workspace_id, artifact_id, artifact_export_refs_json),
                    )
                if artifact_cursor.rowcount == 0:
                    continue

                version_row = conn.execute(
                    "SELECT export_refs_json FROM workspace_artifact_versions "
                    "WHERE workspace_id = ? AND artifact_id = ? AND artifact_version_id = ?",
                    (workspace_id, artifact_id, artifact_version_id),
                ).fetchone()
                if version_row is None:
                    raise ConflictError(  # noqa: TRY003
                        f"Workspace artifact version '{artifact_version_id}' missing for artifact '{artifact_id}'.",
                        entity="workspace_artifact_versions",
                        entity_id=artifact_version_id,
                    )

                version_export_refs = self._load_workspace_artifact_json(
                    version_row["export_refs_json"],
                    [],
                    field_name="workspace_artifact_versions.export_refs_json",
                )
                if not isinstance(version_export_refs, list):
                    raise InputError("Workspace artifact version export_refs must be a list.")  # noqa: TRY003
                version_export_refs = list(version_export_refs)
                version_export_refs.append(dict(export_ref))
                version_export_refs_json = self._dump_workspace_artifact_json(version_export_refs, [])
                version_cursor = conn.execute(
                    "UPDATE workspace_artifact_versions SET export_refs_json = ? "
                    "WHERE workspace_id = ? AND artifact_id = ? AND artifact_version_id = ?",
                    (version_export_refs_json, workspace_id, artifact_id, artifact_version_id),
                )
                if version_cursor.rowcount == 0:
                    raise ConflictError(  # noqa: TRY003
                        f"Artifact version '{artifact_version_id}' export ref update failed.",
                        entity="workspace_artifact_versions",
                        entity_id=artifact_version_id,
                    )
                return self._get_workspace_artifact(workspace_id, artifact_id)  # type: ignore[return-value]

        raise ConflictError(  # noqa: TRY003
            f"Artifact '{artifact_id}' export ref update conflicted with another writer.",
            entity="workspace_artifacts",
            entity_id=artifact_id,
        )

    def update_workspace_artifact(
        self,
        workspace_id: str,
        artifact_id: str,
        updates: dict[str, Any],
        *,
        expected_version: int,
    ) -> dict[str, Any]:
        """Update a workspace artifact with optimistic locking."""
        existing = self._get_workspace_artifact(workspace_id, artifact_id)
        if existing is None:
            raise ConflictError(  # noqa: TRY003
                f"Workspace artifact '{artifact_id}' not found.",
                entity="workspace_artifacts",
                entity_id=artifact_id,
            )
        if existing["version"] != expected_version:
            raise ConflictError(  # noqa: TRY003
                f"Artifact '{artifact_id}' version mismatch (db={existing['version']}, expected={expected_version}).",
                entity="workspace_artifacts",
                entity_id=artifact_id,
            )
        next_version = expected_version + 1
        next_root_artifact_id = str(existing.get("root_artifact_id") or artifact_id)
        previous_version_id = self._workspace_artifact_version_id(artifact_id, expected_version)
        next_artifact_version_id = self._workspace_artifact_version_id(artifact_id, next_version)
        review_state = self._normalize_workspace_artifact_review_state(
            updates.get("review_state") if "review_state" in updates else existing.get("review_state")
        )
        set_clauses = ["version = ?"]
        params: list[Any] = [next_version]
        forced_updates: dict[str, Any] = {
            "root_artifact_id": next_root_artifact_id,
            "artifact_version_id": next_artifact_version_id,
            "previous_version_id": previous_version_id,
            "review_state": review_state,
        }
        for col, value in forced_updates.items():
            set_clauses.append(f"{col} = ?")
            params.append(value)
        for col in (
            "title",
            "status",
            "content",
            "content_type",
            "preview_text",
            "summary",
            "owner_scope",
            "owner_id",
            "project_id",
            "task_id",
            "source_collection_id",
            "total_tokens",
            "total_cost_usd",
            "completed_at",
            "schema_version",
        ):
            if col in updates:
                set_clauses.append(f"{col} = ?")
                params.append(updates[col])
        json_updates: dict[str, tuple[str, Any]] = {
            "producer_metadata": ("producer_metadata_json", {}),
            "source_lineage": ("source_lineage_json", {}),
            "review_metadata": ("review_metadata_json", {}),
            "version_metadata": ("version_metadata_json", {}),
            "export_refs": ("export_refs_json", []),
            "redaction": ("redaction_json", {"support_safe": True, "redacted": False}),
        }
        next_json_values: dict[str, str] = {}
        for field_name, (column_name, default) in json_updates.items():
            value = updates[field_name] if field_name in updates else existing.get(field_name)
            dumped = self._dump_workspace_artifact_json(value, default)
            next_json_values[column_name] = dumped
            if field_name in updates:
                set_clauses.append(f"{column_name} = ?")
                params.append(dumped)
        query = f"UPDATE workspace_artifacts SET {', '.join(set_clauses)} WHERE workspace_id = ? AND id = ? AND version = ?"  # nosec B608
        params.extend([workspace_id, artifact_id, expected_version])
        with self.transaction() as conn:
            cursor = conn.execute(query, tuple(params))
            if cursor.rowcount == 0:
                raise ConflictError(  # noqa: TRY003
                    f"Artifact '{artifact_id}' concurrent update detected.",
                    entity="workspace_artifacts",
                    entity_id=artifact_id,
                )
            self._insert_workspace_artifact_version(
                conn,
                workspace_id=workspace_id,
                artifact_id=artifact_id,
                artifact_version_id=next_artifact_version_id,
                root_artifact_id=next_root_artifact_id,
                previous_version_id=previous_version_id,
                version=next_version,
                review_state=review_state,
                title=str(updates.get("title") if "title" in updates else existing.get("title") or ""),
                content=updates.get("content") if "content" in updates else existing.get("content"),
                producer_metadata_json=next_json_values["producer_metadata_json"],
                source_lineage_json=next_json_values["source_lineage_json"],
                review_metadata_json=next_json_values["review_metadata_json"],
                version_metadata_json=next_json_values["version_metadata_json"],
                export_refs_json=next_json_values["export_refs_json"],
                redaction_json=next_json_values["redaction_json"],
                created_at=self._get_current_utc_timestamp_iso(),
            )
        return self._get_workspace_artifact(workspace_id, artifact_id)  # type: ignore[return-value]

    def delete_workspace_artifact(self, workspace_id: str, artifact_id: str) -> None:
        """Hard-delete a workspace artifact."""
        with self.transaction() as conn:
            conn.execute(
                "DELETE FROM workspace_artifact_versions WHERE workspace_id = ? AND artifact_id = ?",
                (workspace_id, artifact_id),
            )
            conn.execute(
                "DELETE FROM workspace_artifacts WHERE workspace_id = ? AND id = ?",
                (workspace_id, artifact_id),
            )

    # --- Workspace Note Methods ---

    def add_workspace_note(self, workspace_id: str, data: dict[str, Any]) -> dict[str, Any]:
        """Add a note to a workspace."""
        now = self._get_current_utc_timestamp_iso()
        import json as _json
        keywords_json = _json.dumps(data.get("keywords", []))
        query = (
            "INSERT INTO workspace_notes (workspace_id, title, content, keywords_json, created_at, last_modified, deleted, version) "
            "VALUES (?, ?, ?, ?, ?, ?, 0, 1)"
        )
        params = (
            workspace_id,
            data.get("title", ""),
            data.get("content", ""),
            keywords_json,
            now,
            now,
        )
        with self.transaction() as conn:
            if self.backend_type == BackendType.POSTGRESQL:
                cursor = conn.execute(query + " RETURNING id", params)
                inserted = cursor.fetchone()
                note_id = int(inserted["id"]) if inserted else None
            else:
                cursor = conn.execute(query, params)
                note_id = cursor.lastrowid
            if note_id is None:
                raise CharactersRAGDBError("Workspace note insert ID was unavailable.")  # noqa: TRY003
            row = conn.execute(
                "SELECT * FROM workspace_notes WHERE workspace_id = ? AND id = ?",
                (workspace_id, note_id),
            ).fetchone()
            if row is None:
                raise CharactersRAGDBError("Workspace note insert could not be verified.")  # noqa: TRY003
            note = dict(row)
        return note

    def _get_workspace_note(
        self,
        workspace_id: str,
        note_id: int,
        *,
        include_deleted: bool = False,
    ) -> dict[str, Any] | None:
        deleted_clause = "" if include_deleted else " AND deleted = 0"
        cursor = self.execute_query(
            f"SELECT * FROM workspace_notes WHERE workspace_id = ? AND id = ?{deleted_clause}",  # nosec B608
            (workspace_id, note_id),
        )
        row = cursor.fetchone()
        return dict(row) if row else None

    def get_workspace_note(
        self,
        workspace_id: str,
        note_id: int,
        *,
        include_deleted: bool = False,
    ) -> dict[str, Any] | None:
        """Fetch a workspace note by id."""
        return self._get_workspace_note(workspace_id, note_id, include_deleted=include_deleted)

    def list_workspace_notes(self, workspace_id: str) -> list[dict[str, Any]]:
        """List all non-deleted notes for a workspace."""
        cursor = self.execute_query(
            "SELECT * FROM workspace_notes WHERE workspace_id = ? AND deleted = 0 ORDER BY last_modified DESC",
            (workspace_id,),
        )
        return [dict(row) for row in cursor.fetchall()]

    def update_workspace_note(
        self,
        workspace_id: str,
        note_id: int,
        updates: dict[str, Any],
        *,
        expected_version: int,
    ) -> dict[str, Any]:
        """Update a workspace note with optimistic locking."""
        existing = self._get_workspace_note(workspace_id, note_id)
        if existing is None:
            raise ConflictError(  # noqa: TRY003
                f"Workspace note '{note_id}' not found.",
                entity="workspace_notes",
                entity_id=str(note_id),
            )
        if existing["version"] != expected_version:
            raise ConflictError(  # noqa: TRY003
                f"Note '{note_id}' version mismatch (db={existing['version']}, expected={expected_version}).",
                entity="workspace_notes",
                entity_id=str(note_id),
            )
        now = self._get_current_utc_timestamp_iso()
        set_clauses = ["last_modified = ?", "version = ?"]
        params: list[Any] = [now, expected_version + 1]
        for col in ("title", "content", "keywords_json"):
            if col in updates:
                set_clauses.append(f"{col} = ?")
                params.append(updates[col])
        query = f"UPDATE workspace_notes SET {', '.join(set_clauses)} WHERE workspace_id = ? AND id = ? AND version = ?"  # nosec B608
        params.extend([workspace_id, note_id, expected_version])
        with self.transaction() as conn:
            cursor = conn.execute(query, tuple(params))
            if cursor.rowcount == 0:
                raise ConflictError(  # noqa: TRY003
                    f"Note '{note_id}' concurrent update detected.",
                    entity="workspace_notes",
                    entity_id=str(note_id),
                )
        return self._get_workspace_note(workspace_id, note_id)  # type: ignore[return-value]

    def delete_workspace_note(self, workspace_id: str, note_id: int) -> None:
        """Soft-delete a workspace note."""
        now = self._get_current_utc_timestamp_iso()
        with self.transaction() as conn:
            conn.execute(
                "UPDATE workspace_notes SET deleted = 1, last_modified = ? WHERE workspace_id = ? AND id = ?",
                (now, workspace_id, note_id),
            )

    # --- Message Methods ---
    # Message CRUD/search methods are delegated to MessageStore at module bottom.

    # --- Keyword, KeywordCollection, Note Methods (CRUD + Search) ---
    # These follow similar patterns to CharacterCard, Conversation, Message methods:
    # - add: INSERT with default version 1, set last_modified, client_id.
    # - get_by_id/name: SELECT WHERE deleted = 0.
    # - list: SELECT WHERE deleted = 0.
    # - update: UPDATE SET fields, last_modified, version, client_id WHERE id/name = ? AND version = ? AND deleted = 0.
    # - soft_delete: UPDATE SET deleted = 1, last_modified, version, client_id WHERE id/name = ? AND version = ? AND deleted = 0.
    # - search: Use respective FTS table.

    def _add_generic_item(self, table_name: str, unique_col_name: str, item_data: dict[str, Any], main_col_value: str,
                          other_fields_map: dict[str, str]) -> int | None:
        """
        Internal helper to add items to tables with an auto-increment ID and a unique text column.

        Handles creation or undeletion if an item with the `main_col_value` exists
        but is soft-deleted. `version` is set to 1 on new creation or incremented on undelete.
        `last_modified` and `client_id` (from `item_data` or instance) are set.
        `created_at` is set on new creation or remains from original on undelete (implicitly).

        FTS and sync_log entries are expected to be handled by SQL triggers for these tables.

        Args:
            table_name: Name of the database table (e.g., "keywords").
            unique_col_name: Name of the column that must be unique (e.g., "keyword").
                             This column usually has `COLLATE NOCASE` in schema.
            item_data: Dictionary possibly containing 'client_id' or other values
                       mapped by `other_fields_map`.
            main_col_value: The value for the `unique_col_name` (e.g., the keyword text).
                            This value is typically stripped of whitespace before use.
            other_fields_map: A map of DB column names to keys in `item_data` for additional fields.
                              Example: {"parent_id_db_col": "parent_id_item_data_key"}.

        Returns:
            The integer ID of the added or undeleted item.

        Raises:
            ConflictError: If an active item with `main_col_value` already exists,
                           or if undelete fails due to version mismatch or concurrent activation.
            CharactersRAGDBError: For other database errors.
        """
        now = self._get_current_utc_timestamp_iso()
        client_id_to_use = item_data.get('client_id', self.client_id)

        other_cols = list(other_fields_map.keys())
        other_placeholders_list = ['?'] * len(other_cols)
        other_values = [item_data.get(other_fields_map[col_db]) for col_db in other_cols]

        cols_str_list = [unique_col_name]
        placeholders_str_list = ["?"]
        if other_cols:
            cols_str_list.extend(other_cols)
            placeholders_str_list.extend(other_placeholders_list)

        # Add created_at for new inserts
        cols_str_list_insert = cols_str_list + ['created_at', 'last_modified', 'client_id', 'version', 'deleted']
        if self.backend_type == BackendType.POSTGRESQL:
            placeholders_str_list_insert = placeholders_str_list + ['?', '?', '?', '?', '?']
            version_value = 1
            deleted_value = False
        else:
            placeholders_str_list_insert = placeholders_str_list + ['?', '?', '?', '1', '0']
            version_value = 1
            deleted_value = 0

        table_name = self._map_table_for_backend(table_name)
        insert_cols_sql = ', '.join(cols_str_list_insert)
        insert_placeholders_sql = ', '.join(placeholders_str_list_insert)
        query = """
            INSERT INTO {table_name} (
                {insert_cols_sql}
            ) VALUES ({insert_placeholders_sql})
        """.format_map(locals())  # nosec B608
        # Params for INSERT: main_value, other_values..., created_at, last_modified, client_id
        if self.backend_type == BackendType.POSTGRESQL:
            params_tuple_insert = tuple([main_col_value] + other_values + [now, now, client_id_to_use, version_value, deleted_value])
        else:
            params_tuple_insert = tuple([main_col_value] + other_values + [now, now, client_id_to_use])


        try:
            with self.transaction() as conn:
                # Check if a soft-deleted item exists and undelete it
                undelete_cursor = conn.execute(
                    f"SELECT id, version FROM {table_name} WHERE {unique_col_name} = ? AND deleted = 1",  # nosec B608
                    (main_col_value,))
                existing_deleted = undelete_cursor.fetchone()
                if existing_deleted:
                    item_id, current_version = existing_deleted['id'], existing_deleted['version']
                    next_version = current_version + 1

                    update_set_parts = [f"{unique_col_name} = ?"]
                    update_params_list = [main_col_value]
                    for i, col_db in enumerate(other_cols):
                        if col_db == "sync_id":
                            continue
                        update_set_parts.append(f"{col_db} = ?")
                        update_params_list.append(other_values[i])
                    update_set_parts.extend(["deleted = 0", "last_modified = ?", "version = ?", "client_id = ?"])
                    # WHERE clause params for undelete
                    undelete_where_params = [item_id, current_version]
                    full_undelete_params = tuple(update_params_list + [now, next_version, client_id_to_use] + undelete_where_params)

                    undelete_query = f"UPDATE {table_name} SET {', '.join(update_set_parts)} WHERE id = ? AND version = ?"  # nosec B608

                    row_count_undelete = conn.execute(undelete_query, full_undelete_params).rowcount
                    if row_count_undelete == 0:
                        raise ConflictError(  # noqa: TRY003, TRY301
                            f"Failed to undelete {table_name} '{main_col_value}' due to version mismatch or it became active/disappeared.",
                            entity=table_name, entity_id=main_col_value)
                    logger.info(
                        f"Undeleted and updated {table_name} '{main_col_value}' with ID: {item_id}, new version {next_version}.")
                    return item_id

                # If not undeleting, proceed with insert
                cursor_insert = conn.execute(query, params_tuple_insert)
                item_id_insert = cursor_insert.lastrowid if hasattr(cursor_insert, 'lastrowid') else None
                if item_id_insert is None and self.backend_type == BackendType.POSTGRESQL:
                    sel = conn.execute(
                        f"SELECT id FROM {table_name} WHERE {unique_col_name} = ?",  # nosec B608
                        (main_col_value,)
                    )
                    row = sel.fetchone()
                    if row is not None:
                        item_id_insert = int(row['id'] if isinstance(row, dict) else row[0])
                logger.info(f"Added {table_name} '{main_col_value}' with ID: {item_id_insert}.")
                return item_id_insert
        except sqlite3.IntegrityError as e:
             if f"unique constraint failed: {table_name}.{unique_col_name}" in str(e).lower(): # Use lower for robustness
                logger.warning(f"{table_name} with {unique_col_name} '{main_col_value}' already exists and is active.")
                raise ConflictError(f"{table_name} '{main_col_value}' already exists and is active.", entity=table_name,  # noqa: TRY003
                                    entity_id=main_col_value) from e
             raise CharactersRAGDBError(f"Database integrity error adding {table_name}: {e}") from e  # noqa: TRY003
        except ConflictError: # From undelete path
            raise
        except CharactersRAGDBError as e:
            logger.error(f"Database error adding {table_name} '{main_col_value}': {e}")
            raise
        return None  # Should not be reached if exceptions are raised properly

    def _get_generic_item_by_id(self, table_name: str, item_id: int) -> dict[str, Any] | None:
        """
        Internal helper: Retrieves a non-deleted item by its auto-increment integer ID.

        Args:
            table_name: The database table name.
            item_id: The integer ID of the item.

        Returns:
            A dictionary of the item's data if found and active, else None.

        Raises:
            CharactersRAGDBError: For database errors.
        """
        table_name = self._map_table_for_backend(table_name)
        query = f"SELECT * FROM {table_name} WHERE id = ? AND deleted = 0"  # nosec B608
        try:
            cursor = self.execute_query(query, (item_id,))
            row = cursor.fetchone()
            return dict(row) if row else None
        except CharactersRAGDBError as e:
            logger.error(f"Database error fetching {table_name} ID {item_id}: {e}")
            raise

    def _get_generic_item_by_unique_text(self, table_name: str, unique_col_name: str, value: str) -> dict[str, Any] | None:
        """
        Internal helper: Retrieves a non-deleted item by a unique text column value.
        Assumes the column has `COLLATE NOCASE` if case-insensitive search is desired.

        Args:
            table_name: The database table name.
            unique_col_name: The name of the unique text column.
            value: The text value to search for.

        Returns:
            A dictionary of the item's data if found and active, else None.

        Raises:
            CharactersRAGDBError: For database errors.
        """
        table_name = self._map_table_for_backend(table_name)
        query = f"SELECT * FROM {table_name} WHERE {unique_col_name} = ? AND deleted = 0"  # nosec B608
        try:
            cursor = self.execute_query(query, (value,))
            row = cursor.fetchone()
            return dict(row) if row else None
        except CharactersRAGDBError as e:
            logger.error(f"Database error fetching {table_name} by {unique_col_name} '{value}': {e}")
            raise

    def _case_insensitive_order_expression(self, column: str, direction: str | None = None) -> str:
        column_clean = (column or '').strip()
        if not _ORDER_BY_COLUMN_RE.match(column_clean):
            raise InputError(f"Invalid order-by column: {column!r}")  # noqa: TRY003
        direction_clean = (direction or '').strip()
        direction_clause = f" {direction_clean}" if direction_clean else ""
        if self.backend_type == BackendType.POSTGRESQL:
            return f"LOWER({column_clean}){direction_clause}"
        return f"{column_clean} COLLATE NOCASE{direction_clause}"

    def _case_insensitive_order_clause(self, column: str, direction: str | None = None) -> str:
        return f"ORDER BY {self._case_insensitive_order_expression(column, direction)}"

    def _list_generic_items(self, table_name: str, order_by_col: str, limit: int = 100, offset: int = 0) -> list[dict[str, Any]]:
        """
        Internal helper: Lists non-deleted items from a table, with specified ordering.

        Args:
            table_name: The database table name.
            order_by_col: The column (and direction) to order by (e.g., "name ASC", "keyword COLLATE NOCASE DESC").
            limit: Maximum number of items.
            offset: Number of items to skip.

        Returns:
            A list of item dictionaries.

        Raises:
            CharactersRAGDBError: For database errors.
        """
        order_by_clean = (order_by_col or "").strip()
        if not _ORDER_BY_EXPR_RE.match(order_by_clean):
            raise InputError(f"Invalid order-by expression: {order_by_col!r}")  # noqa: TRY003
        order_expression = order_by_clean
        collate_match = re.search(r"\s+COLLATE\s+NOCASE", order_by_clean, flags=re.IGNORECASE)
        if collate_match:
            base = order_by_clean[:collate_match.start()]
            direction = order_by_clean[collate_match.end():]
            order_expression = self._case_insensitive_order_expression(base.strip(), direction.strip() or None)

        table_name = self._map_table_for_backend(table_name)
        query = f"SELECT * FROM {table_name} WHERE deleted = 0 ORDER BY {order_expression} LIMIT ? OFFSET ?"  # nosec B608
        try:
            cursor = self.execute_query(query, (limit, offset))
            return [dict(row) for row in cursor.fetchall()]
        except CharactersRAGDBError as e:
            logger.error(f"Database error listing {table_name}: {e}")
            raise

    def _update_generic_item(self, table_name: str, item_id: int | str,
                             update_data: dict[str, Any], expected_version: int,
                             allowed_fields: list[str], pk_col_name: str = "id",
                             unique_col_name_in_data: str | None = None) -> bool | None:
        """
        Internal helper: Updates an item in a table using optimistic locking.

        Args:
            table_name: The table to update.
            item_id: The ID (PK) of the item to update (int or str for UUIDs).
            update_data: Dictionary containing data to update. Must not be empty.
            expected_version: Client's expected version for optimistic locking.
            allowed_fields: List of field names that are permitted to be updated from `update_data`.
            pk_col_name: Name of the primary key column. Defaults to "id".
            unique_col_name_in_data: If an updatable field has a unique constraint
                                     (e.g., 'name' for collections), specify its data key name
                                     here for targeted ConflictError on unique violation.

        Returns:
            True if the update was successful.

        Raises:
            InputError: If `update_data` is empty or contains no allowed fields to update.
            ConflictError: For version mismatch, record not found/deleted, or unique constraint violation
                           if `unique_col_name_in_data` is specified and violated.
            CharactersRAGDBError: For other database errors.
        """
        if not update_data:
            raise InputError(f"No data provided for update of {table_name} ID {item_id}.")  # noqa: TRY003

        now = self._get_current_utc_timestamp_iso()
        fields_to_update_sql = []
        params_for_set_clause = []

        for key, value in update_data.items():
            if key in allowed_fields:
                fields_to_update_sql.append(f"{key} = ?")
                # Special handling for specific field types if necessary, e.g., stripping title
                if table_name == "notes" and key == "title" and isinstance(value, str):
                    params_for_set_clause.append(value.strip())
                else:
                    params_for_set_clause.append(value)
            elif key not in [pk_col_name, 'created_at', 'last_modified', 'version', 'client_id', 'deleted']:
                logger.warning(
                    f"Attempted to update immutable or unknown field '{key}' in {table_name} ID {item_id}, skipping.")

        if not fields_to_update_sql:
            # This means update_data either was empty (caught above) or contained only non-allowed fields.
            # Depending on desired behavior, this could be an error or a "no fields to update" success.
            # Current behavior implies if allowed_fields are updated, it proceeds. If not, it may not update anything.
            # For safety, ensure metadata is only updated if there are actual field changes or if it's an explicit "touch".
            # The calling methods (e.g., update_note) handle this: "if not fields_to_update_sql: return True"
            # This helper should proceed if there's anything to set.
            logger.info(f"No recognized updatable fields provided in update_data for {table_name} ID {item_id}. Will only update metadata if version matches.")
            # If we must update metadata anyway if version matches:
            # Fall through to add metadata updates. The query will work fine.


        next_version_val = expected_version + 1
        current_fields_to_update_sql = list(fields_to_update_sql) # clone
        current_params_for_set_clause = list(params_for_set_clause) # clone

        current_fields_to_update_sql.extend(["last_modified = ?", "version = ?", "client_id = ?"])
        current_params_for_set_clause.extend([now, next_version_val, self.client_id])

        # Values for the WHERE clause
        where_clause_values = [item_id, expected_version]
        final_query_params = tuple(current_params_for_set_clause + where_clause_values)

        query = f"UPDATE {table_name} SET {', '.join(current_fields_to_update_sql)} WHERE {pk_col_name} = ? AND version = ? AND deleted = 0"  # nosec B608

        try:
            with self.transaction() as conn:
                # Explicit pre-check. _get_current_db_version raises ConflictError if not found or soft-deleted.
                current_db_version = self._get_current_db_version(conn, table_name, pk_col_name, item_id)

                if current_db_version != expected_version:
                    raise ConflictError(  # noqa: TRY003, TRY301
                        f"{table_name} ID {item_id} was modified: version mismatch (db has {current_db_version}, client expected {expected_version}).",
                        entity=table_name, entity_id=item_id
                    )

                # If current_db_version == expected_version, proceed with the update.
                cursor = conn.execute(query, final_query_params)

                if cursor.rowcount == 0:
                    # This state implies the record was active with expected_version during the _get_current_db_version check,
                    # but was either deleted or its version changed *just before* the UPDATE SQL executed.
                    check_again_cursor = conn.execute(
                        f"SELECT version, deleted FROM {table_name} WHERE {pk_col_name} = ?", (item_id,))  # nosec B608
                    final_state = check_again_cursor.fetchone()
                    msg = f"Update for {table_name} ID {item_id} (expected version {expected_version}) affected 0 rows."
                    if not final_state:
                        msg = f"{table_name} ID {item_id} disappeared before update completion (was version {expected_version})."
                    elif final_state['deleted']:
                        msg = f"{table_name} ID {item_id} was soft-deleted concurrently (expected version {expected_version} for update)."
                    elif final_state['version'] != expected_version:
                        msg = f"{table_name} ID {item_id} version changed to {final_state['version']} concurrently (expected {expected_version} for update)."
                    raise ConflictError(msg, entity=table_name, entity_id=item_id)  # noqa: TRY301

                logger.info(
                    f"Updated {table_name} ID {item_id} from version {expected_version} to version {next_version_val}.")
                return True
        except sqlite3.IntegrityError as e:
            if unique_col_name_in_data and unique_col_name_in_data in update_data:
                # More specific check for the unique column mentioned
                db_unique_col_name = unique_col_name_in_data # Assuming it matches DB col name for this check
                if f"UNIQUE constraint failed: {table_name}.{db_unique_col_name}".lower() in str(e).lower():
                    val = update_data[unique_col_name_in_data]
                    logger.warning(
                        f"Update failed for {table_name} ID {item_id}: {db_unique_col_name} '{val}' already exists.")
                    raise ConflictError(  # noqa: TRY003
                        f"Cannot update {table_name} ID {item_id}: {db_unique_col_name} '{val}' already exists.",
                        entity=table_name, entity_id=val) from e
            logger.error(
                f"SQLite integrity error during update of {table_name} ID {item_id} (expected version {expected_version}): {e}",
                exc_info=True)
            raise CharactersRAGDBError(f"Database integrity error updating {table_name} ({item_id}): {e}") from e  # noqa: TRY003
        except ConflictError:
            raise
        except InputError: # Should be caught by callers if they check 'update_data' emptiness first
            raise
        except CharactersRAGDBError as e:
            logger.error(
                f"Database error updating {table_name} ID {item_id} (expected version {expected_version}): {e}",
                exc_info=True)
            raise
        # No implicit return None, function should return True or raise.

    def _soft_delete_generic_item(self, table_name: str, item_id: int | str,
                                  expected_version: int, pk_col_name: str = "id") -> bool | None:
        """
        Internal helper: Soft-deletes an item in a table using optimistic locking.

        Sets `deleted = 1`, updates `last_modified`, `version`, `client_id`.

        Args:
            table_name: The table to update.
            item_id: The ID (PK) of the item to soft-delete (int or str).
            expected_version: Client's expected version for optimistic locking.
            pk_col_name: Name of the primary key column. Defaults to "id".

        Returns:
            True if successful or if the item was already soft-deleted.

        Raises:
            ConflictError: For version mismatch if active, or if record not found (and not already deleted),
                           or if a concurrent modification prevents the update.
            CharactersRAGDBError: For other database errors.
        """
        logical_table_name = table_name
        table_name = self._map_table_for_backend(table_name)
        now = self._get_current_utc_timestamp_iso()
        next_version_val = expected_version + 1

        query = f"UPDATE {table_name} SET deleted = 1, last_modified = ?, version = ?, client_id = ? WHERE {pk_col_name} = ? AND version = ? AND deleted = 0"  # nosec B608
        params = (now, next_version_val, self.client_id, item_id, expected_version)

        try:
            with self.transaction() as conn:
                try:
                    current_db_version = self._get_current_db_version(conn, table_name, pk_col_name, item_id)
                    # If we are here, record is active and current_db_version is its version.
                except ConflictError:
                    # Check if the ConflictError is because it's already soft-deleted.
                    # Query again to be absolutely sure of the 'deleted' status.
                    check_deleted_cursor = conn.execute(
                        f"SELECT deleted, version FROM {table_name} WHERE {pk_col_name} = ?", (item_id,))  # nosec B608
                    record_status = check_deleted_cursor.fetchone()

                    if record_status and record_status['deleted']:
                        logger.info(
                            f"{logical_table_name} ID {item_id} already soft-deleted. Operation considered successful (idempotent).")
                        return True
                    raise # Re-raise if not found or other conflict

                if current_db_version != expected_version:
                    raise ConflictError(  # noqa: TRY003, TRY301
                        f"Soft delete failed for {logical_table_name} ID {item_id}: version mismatch (db has {current_db_version}, client expected {expected_version}).",
                        entity=logical_table_name, entity_id=item_id
                    )

                cursor = conn.execute(query, params)

                if cursor.rowcount == 0:
                    # This means the record (which was active with expected_version) changed state
                    # between the _get_current_db_version check and the UPDATE execution.
                    check_again_cursor = conn.execute(
                        f"SELECT deleted, version FROM {table_name} WHERE {pk_col_name} = ?", (item_id,))  # nosec B608
                    changed_record = check_again_cursor.fetchone()
                    if not changed_record:
                        raise ConflictError(  # noqa: TRY003, TRY301
                            f"{logical_table_name} ID {item_id} disappeared before soft-delete completion (expected version {expected_version}).",
                            entity=logical_table_name, entity_id=item_id)

                    if changed_record['deleted']:
                        # If it got deleted by another process, and the new version matches what we intended, it's fine.
                        if changed_record['version'] == next_version_val:
                            logger.info(
                                f"{logical_table_name} ID {item_id} was soft-deleted concurrently to version {next_version_val}. Operation successful.")
                            return True
                        else:
                            raise ConflictError(  # noqa: TRY003, TRY301
                                f"{logical_table_name} ID {item_id} was soft-deleted concurrently to an unexpected version {changed_record['version']} (expected to set to {next_version_val}).",
                                entity=logical_table_name, entity_id=item_id)

                    if changed_record['version'] != expected_version:  # Still active, but version changed
                        raise ConflictError(  # noqa: TRY003, TRY301
                            f"Soft delete failed for {logical_table_name} ID {item_id}: version changed to {changed_record['version']} concurrently (expected {expected_version}).",
                            entity=logical_table_name, entity_id=item_id)

                    raise ConflictError(  # noqa: TRY003, TRY301
                        f"Soft delete for {logical_table_name} ID {item_id} (expected version {expected_version}) affected 0 rows for an unknown reason after passing initial checks.",
                        entity=logical_table_name, entity_id=item_id)

                logger.info(
                    f"Soft-deleted {logical_table_name} ID {item_id} (was version {expected_version}), new version {next_version_val}.")
                return True
        except ConflictError:
            raise
        except CharactersRAGDBError as e:  # Catches sqlite3.Error from conn.execute
            logger.error(
                f"Database error soft-deleting {logical_table_name} ID {item_id} (expected version {expected_version}): {e}",
                exc_info=True)
            raise
        # No implicit return None.

    def _search_generic_items_fts(self, fts_table_name: str, main_table_name: str, fts_match_cols_or_table: str,
                                  search_term: str, limit: int = 10) -> list[dict[str, Any]]:
        """
        Internal helper: Performs FTS search on tables like keywords, notes, collections.

        Assumes the main table's PK is `id` (for keywords, collections) or `rowid` maps
        correctly (for notes via `content_rowid='rowid'`).
        The join condition is `fts.rowid = main.id` or `fts.rowid = main.rowid` depending on FTS setup.
        Schema shows `content_rowid='id'` for keywords/collections and `content_rowid='rowid'` for notes.
        This helper uses `fts.rowid = main.id` which is fine for keywords/collections.
        For notes, `search_notes` uses `fts.rowid = main.rowid` which is correct.
        This helper is mainly for tables where PK `id` is the FTS `rowid`.

        Args:
            fts_table_name: Name of the FTS virtual table.
            main_table_name: Name of the main content table.
            fts_match_cols_or_table: The column(s) in FTS table to match against (e.g., "keyword"),
                                     or the FTS table name if using table-name matching
                                     (e.g., "notes_fts MATCH ?").
            search_term: The FTS search query string.
            limit: Max number of results.

        Returns:
            List of matching item dictionaries from the main table. Can be empty.

        Raises:
            CharactersRAGDBError: For database search errors.
        """
        # The join condition ON fts.rowid = main.id is generally for tables where 'id' is an alias for rowid
        # or FTS is configured with content_rowid='id'.
        # For tables like 'notes' where 'id' is TEXT UUID and FTS uses 'rowid', the join is different.
        # This helper as written is best for keywords and keyword_collections.
        if self.backend_type == BackendType.POSTGRESQL:
            tsquery = FTSQueryTranslator.normalize_query(search_term, 'postgresql')
            if not tsquery:
                logger.debug(
                    "Generic FTS query normalized to empty tsquery for table '{}' with input '{}'",
                    main_table_name,
                    search_term,
                )
                return []

            fts_column = f"{fts_table_name}_tsv"
            query = """
                SELECT main.*, ts_rank(main.{fts_column}, to_tsquery('english', ?)) AS rank
                FROM {main_table_name} main
                WHERE main.deleted = FALSE
                  AND main.{fts_column} @@ to_tsquery('english', ?)
                ORDER BY rank DESC, main.last_modified DESC
                LIMIT ?
            """.format_map(locals())  # nosec B608
            try:
                cursor = self.execute_query(query, (tsquery, tsquery, limit))
                return [dict(row) for row in cursor.fetchall()]
            except CharactersRAGDBError as exc:
                logger.error("PostgreSQL FTS search failed for table '{}': {}", main_table_name, exc)
                raise

        # Use explicit table-name for MATCH and bm25() for SQLite FTS5 compatibility
        query = """
            SELECT main.*
            FROM {fts_table_name}, {main_table_name} main
            WHERE {fts_table_name}.rowid = main.id
              AND {fts_table_name} MATCH ? AND main.deleted = 0
            ORDER BY bm25({fts_table_name})
            LIMIT ?
        """.format_map(locals())  # nosec B608
        try:
            cursor = self.execute_query(query, (search_term, limit))
            return [dict(row) for row in cursor.fetchall()]
        except CharactersRAGDBError as e:
            logger.error(f"Error searching {main_table_name} for '{search_term}': {e}")
            raise

    # Keywords
    # Keyword CRUD/search methods and note-count helper are delegated to extracted stores at module bottom.

    # Notes (Now with UUID and specific methods)
    # Note CRUD/search methods are delegated to NoteStore at module bottom.


    def count_notes_matching(self, search_term: str) -> int:
        """Returns the total number of active notes matching the FTS query."""
        if self.backend_type == BackendType.POSTGRESQL:
            tsquery = FTSQueryTranslator.normalize_query(search_term, 'postgresql')
            if not tsquery:
                return 0
            query = """
                SELECT COUNT(*) AS cnt
                FROM notes n
                WHERE n.deleted = FALSE
                  AND n.notes_fts_tsv @@ to_tsquery('english', ?)
            """
            try:
                cursor = self.execute_query(query, (tsquery,))
                row = cursor.fetchone()
                return int(row["cnt"]) if row else 0
            except CharactersRAGDBError as exc:
                logger.error("PostgreSQL FTS count failed for notes term '{}': {}", search_term, exc)
                raise

        safe_literal = search_term.replace('"', '""')
        safe_search_term = f'"{safe_literal}"'
        query = """
                SELECT COUNT(*) AS cnt
                FROM notes_fts
                JOIN notes AS main ON notes_fts.rowid = main.rowid
                WHERE notes_fts MATCH ?
                  AND main.deleted = 0
        """
        try:
            cursor = self.execute_query(query, (safe_search_term,))
            row = cursor.fetchone()
            return int(row["cnt"]) if row else 0
        except CharactersRAGDBError as exc:
            logger.error("SQLite FTS count failed for notes term '{}': {}", search_term, exc)
            raise

    def count_chatbook_scope_category(self, category: str) -> int:
        """Return the active row count for a Chatbooks account-scope category."""
        queries = {
            "conversations": "SELECT COUNT(*) AS count FROM conversations WHERE deleted = 0",
            "notes": "SELECT COUNT(*) AS count FROM notes WHERE deleted = 0",
            "characters": "SELECT COUNT(*) AS count FROM character_cards WHERE deleted = 0",
            "world_books": "SELECT COUNT(*) AS count FROM world_books WHERE deleted = 0",
            "dictionaries": "SELECT COUNT(*) AS count FROM chat_dictionaries WHERE deleted = 0",
            "generated_documents": "SELECT COUNT(*) AS count FROM generated_documents",
            "tags_categories_relationships": "SELECT COUNT(*) AS count FROM keywords WHERE deleted = 0",
        }
        query = queries.get(category)
        if query is None:
            return 0
        try:
            # Category selects a fixed allowlisted query; no user input enters SQL.
            cursor = self.execute_query(query)  # nosec B608
            row = cursor.fetchone()
            if not row:
                return 0
            try:
                value = row["count"]
            except (TypeError, KeyError, IndexError):
                value = row[0]
            return max(0, int(value or 0))
        except CharactersRAGDBError as exc:
            logger.error("Failed counting Chatbooks account-scope category '{}': {}", category, exc)
            raise
        except (TypeError, ValueError):
            return 0

    def list_chatbook_scope_ids(self, category: str) -> list[str]:
        """Return active row IDs for a Chatbooks account-scope category."""
        queries = {
            "conversations": "SELECT id FROM conversations WHERE deleted = 0 ORDER BY id ASC",
            "notes": "SELECT id FROM notes WHERE deleted = 0 ORDER BY id ASC",
            "characters": "SELECT id FROM character_cards WHERE deleted = 0 ORDER BY id ASC",
            "world_books": "SELECT id FROM world_books WHERE deleted = 0 ORDER BY id ASC",
            "dictionaries": "SELECT id FROM chat_dictionaries WHERE deleted = 0 ORDER BY id ASC",
            "generated_documents": "SELECT id FROM generated_documents ORDER BY id ASC",
        }
        query = queries.get(category)
        if query is None:
            return []
        try:
            # Category selects a fixed allowlisted query; no user input enters SQL.
            cursor = self.execute_query(query)  # nosec B608
            ids: list[str] = []
            for row in cursor.fetchall() or []:
                try:
                    value = row["id"]
                except (TypeError, KeyError, IndexError):
                    value = row[0]
                if value is not None:
                    ids.append(str(value))
            return ids
        except CharactersRAGDBError as exc:
            logger.error("Failed listing Chatbooks account-scope IDs for '{}': {}", category, exc)
            raise

    # Moodboards
    @staticmethod
    def _normalize_moodboard_name(name: str) -> str:
        text = str(name or "").strip()
        if not text:
            raise InputError("Moodboard name cannot be empty.")  # noqa: TRY003
        return text

    @staticmethod
    def _serialize_moodboard_smart_rule(smart_rule: Any) -> str | None:
        if smart_rule is None:
            return None
        if isinstance(smart_rule, str):
            text = smart_rule.strip()
            if not text:
                return None
            try:
                parsed = json.loads(text)
            except json.JSONDecodeError as exc:
                raise InputError("smart_rule must be valid JSON if provided as a string.") from exc  # noqa: TRY003
            return json.dumps(parsed, ensure_ascii=False)
        if not isinstance(smart_rule, (dict, list)):
            raise InputError("smart_rule must be a JSON object/array or JSON string.")  # noqa: TRY003

        def _json_default(value: Any) -> str:
            if isinstance(value, datetime):
                if value.tzinfo is None:
                    return value.replace(tzinfo=timezone.utc).isoformat()
                return value.astimezone(timezone.utc).isoformat()
            return str(value)

        return json.dumps(smart_rule, ensure_ascii=False, default=_json_default)

    def _deserialize_moodboard_row(self, row: Any) -> dict[str, Any] | None:
        item = self._deserialize_row_fields(row, ["smart_rule_json", "canvas_json"])
        if not item:
            return None
        item["smart_rule"] = item.pop("smart_rule_json", None)
        return item

    def _canonical_moodboard_state_v61(
        self,
        conn: sqlite3.Connection | BackendConnectionWrapper,
        *,
        sync_id: str,
        name: str,
        description: str | None,
        raw_smart_rule: object,
        raw_canvas: object,
        owner_user_id: str,
        revision: int,
        deleted: bool,
    ) -> tuple[str | None, str, str, str | None, str | None]:
        """Normalize one complete compatibility row and rebuild its whole-object lineage."""
        rule, diagnostic_code, diagnostic_hash = self._legacy_moodboard_rule_v61(
            conn,
            raw_smart_rule,
            owner_user_id=owner_user_id,
        )
        raw_rule_text = (
            None
            if raw_smart_rule is None
            else (
                str(raw_smart_rule)
                if isinstance(raw_smart_rule, str)
                else self._canonical_json_text_v61(raw_smart_rule)
            )
        )
        try:
            canvas_value = (
                json.loads(raw_canvas)
                if isinstance(raw_canvas, str)
                else raw_canvas
            )
            if not isinstance(canvas_value, Mapping):
                raise ValueError("moodboard canvas must be an object")
            parsed = parse_notes_moodboard_v1(
                {
                    "moodboard_id": sync_id,
                    "name": name,
                    "description": description,
                    "smart_rule": rule,
                    "canvas": dict(canvas_value),
                }
            )
            if diagnostic_code is not None:
                raise NotesMoodboardStudioContractError(
                    "moodboard smart rule is not canonical"
                )
            smart_rule_text = (
                None
                if parsed.smart_rule is None
                else self._canonical_json_text_v61(
                    parsed.smart_rule.model_dump(mode="json")
                )
            )
            canvas_text = self._canonical_json_text_v61(
                parsed.canvas.model_dump(mode="json")
            )
            canonical_hash = notes_moodboard_object_hash(
                parsed,
                revision=revision,
                deleted=deleted,
            )
            return smart_rule_text, canvas_text, canonical_hash, None, None
        except (
            NotesMoodboardStudioContractError,
            TypeError,
            ValueError,
            json.JSONDecodeError,
        ):
            if diagnostic_code is None:
                diagnostic = moodboard_studio_legacy_source_diagnostic(
                    "legacy_moodboard_payload_invalid",
                    {
                        "moodboard_id": sync_id,
                        "name": name,
                        "description": description,
                        "smart_rule": raw_smart_rule,
                        "canvas": raw_canvas,
                    },
                )
                diagnostic_code = diagnostic["code"]
                diagnostic_hash = diagnostic["source_hash"]
            canvas_text = (
                str(raw_canvas)
                if isinstance(raw_canvas, str)
                else self._canonical_json_text_v61(raw_canvas)
            )
            canonical_hash = self._note_task_v60_hash(
                {
                    "domain": "notes.moodboard.blocked",
                    "moodboard_id": sync_id,
                    "revision": revision,
                    "deleted": deleted,
                    "diagnostic": diagnostic_hash,
                }
            )
            return (
                raw_rule_text,
                canvas_text,
                canonical_hash,
                diagnostic_code,
                diagnostic_hash,
            )

    def _set_notes_moodboard_studio_v61_dataset_scope(
        self,
        conn: sqlite3.Connection | BackendConnectionWrapper,
        dataset_id: str,
    ) -> None:
        if (
            self.backend_type == BackendType.POSTGRESQL
            and self._supports_notes_moodboard_studio_v61()
        ):
            conn.execute(
                "SELECT set_config('app.current_dataset_id', ?, true)",
                (str(dataset_id),),
            )

    def add_moodboard(
        self,
        name: str,
        description: str | None = None,
        smart_rule: Any = None,
    ) -> int | None:
        moodboard_name = self._normalize_moodboard_name(name)
        now = self._get_current_utc_timestamp_iso()
        smart_rule_json = self._serialize_moodboard_smart_rule(smart_rule)
        description_value = self._normalize_nullable_text(description)
        deleted_value = False if self.backend_type == BackendType.POSTGRESQL else 0

        legacy_query = (
            "INSERT INTO moodboards(name,description,smart_rule_json,created_at,last_modified,deleted,client_id,version) "
            "VALUES(?,?,?,?,?,?,?,?)"
        )
        legacy_params = (moodboard_name, description_value, smart_rule_json, now, now, deleted_value, self.client_id, 1)
        try:
            with self.transaction() as conn:
                if not self._supports_notes_moodboard_studio_v61():
                    cursor = conn.execute(legacy_query, legacy_params)
                    return int(cursor.lastrowid)
                owner = str(self.client_id)
                dataset = self.resolve_moodboard_compatibility_dataset_id(
                    owner_user_id=owner, conn=conn
                )
                sync_id = str(uuid.uuid4())
                smart_rule_value, diagnostic_code, diagnostic_hash = self._legacy_moodboard_rule_v61(
                    conn,
                    smart_rule_json,
                    owner_user_id=owner,
                )
                canvas = {"layout_mode": "masonry", "metadata": {}}
                try:
                    parsed = parse_notes_moodboard_v1(
                        {
                            "moodboard_id": sync_id,
                            "name": moodboard_name,
                            "description": description_value,
                            "smart_rule": smart_rule_value,
                            "canvas": canvas,
                        }
                    )
                    canonical_hash = notes_moodboard_object_hash(parsed, revision=1, deleted=False)
                except NotesMoodboardStudioContractError:
                    diagnostic = moodboard_studio_legacy_source_diagnostic(
                        "legacy_moodboard_payload_invalid",
                        {"name": moodboard_name, "smart_rule": smart_rule_value},
                    )
                    diagnostic_code, diagnostic_hash = diagnostic["code"], diagnostic["source_hash"]
                    canonical_hash = self._note_task_v60_hash(
                        {"domain": "notes.moodboard", "moodboard_id": sync_id, "version": 1}
                    )
                query = (
                    "INSERT INTO moodboards("
                    "owner_user_id,dataset_id,sync_id,name,description,smart_rule_json,canvas_json,"
                    "created_at,last_modified,deleted,client_id,version,canonical_revision,canonical_hash,"
                    "source_diagnostic_code,source_diagnostic_hash"
                    ") VALUES(?,?,?,?,?,?,?,?,?,?,?,1,1,?,?,?)"
                )
                params = (
                    owner,
                    dataset,
                    sync_id,
                    moodboard_name,
                    description_value,
                    None if smart_rule_value is None else self._canonical_json_text_v61(smart_rule_value),
                    self._canonical_json_text_v61(canvas),
                    now,
                    now,
                    deleted_value,
                    owner,
                    canonical_hash,
                    diagnostic_code,
                    diagnostic_hash,
                )
                if self.backend_type == BackendType.POSTGRESQL:
                    cursor = conn.execute(query + " RETURNING id", params)
                    row = cursor.fetchone()
                    moodboard_id = int(row["id"]) if row else None
                else:
                    cursor = conn.execute(query, params)
                    moodboard_id = int(cursor.lastrowid)
                if moodboard_id is None:
                    raise CharactersRAGDBError("Failed to determine moodboard ID after insert.")  # noqa: TRY003
                return moodboard_id
        except sqlite3.IntegrityError as exc:
            raise CharactersRAGDBError(f"Database integrity error adding moodboard: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Backend error adding moodboard: {exc}") from exc  # noqa: TRY003

    def get_moodboard_by_id(self, moodboard_id: int, include_deleted: bool = False) -> dict[str, Any] | None:
        params: list[Any] = [moodboard_id]
        scope = ""
        if self._supports_notes_moodboard_studio_v61():
            owner = str(self.client_id)
            with self.transaction() as conn:
                dataset = self.resolve_moodboard_compatibility_dataset_id(
                    owner_user_id=owner,
                    conn=conn,
                )
                scope = " AND owner_user_id=? AND dataset_id=?"
                scoped_params = [*params, owner, dataset]
                where_deleted = ""
                if not include_deleted:
                    where_deleted = " AND deleted = ?"
                    scoped_params.append(
                        False if self.backend_type == BackendType.POSTGRESQL else 0
                    )
                query = f"SELECT * FROM moodboards WHERE id = ?{scope}{where_deleted}"  # nosec B608
                cursor = conn.execute(query, tuple(scoped_params))
                return self._deserialize_moodboard_row(cursor.fetchone())
        where_deleted = ""
        if not include_deleted:
            where_deleted = " AND deleted = ?"
            params.append(False if self.backend_type == BackendType.POSTGRESQL else 0)
        query = f"SELECT * FROM moodboards WHERE id = ?{scope}{where_deleted}"  # nosec B608
        cursor = self.execute_query(query, tuple(params))
        return self._deserialize_moodboard_row(cursor.fetchone())

    def list_moodboards(
        self,
        limit: int = 100,
        offset: int = 0,
        include_deleted: bool = False,
        only_deleted: bool = False,
    ) -> list[dict[str, Any]]:
        if limit <= 0:
            return []

        predicates: list[str] = []
        params: list[Any] = []
        if self._supports_notes_moodboard_studio_v61():
            owner = str(self.client_id)
            with self.transaction() as conn:
                dataset = self.resolve_moodboard_compatibility_dataset_id(
                    owner_user_id=owner,
                    conn=conn,
                )
                predicates.extend(("owner_user_id=?", "dataset_id=?"))
                params.extend((owner, dataset))
                if only_deleted:
                    predicates.append("deleted = ?")
                    params.append(
                        True if self.backend_type == BackendType.POSTGRESQL else 1
                    )
                elif not include_deleted:
                    predicates.append("deleted = ?")
                    params.append(
                        False if self.backend_type == BackendType.POSTGRESQL else 0
                    )
                where_clause = " WHERE " + " AND ".join(predicates)
                query = (
                    f"SELECT * FROM moodboards{where_clause} "  # nosec B608
                    "ORDER BY last_modified DESC, id DESC "
                    "LIMIT ? OFFSET ?"
                )
                params.extend([limit, offset])
                cursor = conn.execute(query, tuple(params))
                rows = cursor.fetchall()
                return [self._deserialize_moodboard_row(row) for row in rows if row]
        if only_deleted:
            predicates.append("deleted = ?")
            params.append(True if self.backend_type == BackendType.POSTGRESQL else 1)
        elif not include_deleted:
            predicates.append("deleted = ?")
            params.append(False if self.backend_type == BackendType.POSTGRESQL else 0)
        where_clause = " WHERE " + " AND ".join(predicates) if predicates else ""

        query = (
            f"SELECT * FROM moodboards{where_clause} "  # nosec B608
            "ORDER BY last_modified DESC, id DESC "
            "LIMIT ? OFFSET ?"
        )
        params.extend([limit, offset])
        cursor = self.execute_query(query, tuple(params))
        rows = cursor.fetchall()
        return [self._deserialize_moodboard_row(row) for row in rows if row]

    def count_moodboards(
        self,
        include_deleted: bool = False,
        only_deleted: bool = False,
    ) -> int:
        predicates: list[str] = []
        params: list[Any] = []
        if self._supports_notes_moodboard_studio_v61():
            owner = str(self.client_id)
            with self.transaction() as conn:
                dataset = self.resolve_moodboard_compatibility_dataset_id(
                    owner_user_id=owner,
                    conn=conn,
                )
                predicates.extend(("owner_user_id=?", "dataset_id=?"))
                params.extend((owner, dataset))
                if only_deleted:
                    predicates.append("deleted = ?")
                    params.append(
                        True if self.backend_type == BackendType.POSTGRESQL else 1
                    )
                elif not include_deleted:
                    predicates.append("deleted = ?")
                    params.append(
                        False if self.backend_type == BackendType.POSTGRESQL else 0
                    )
                where_clause = " WHERE " + " AND ".join(predicates)
                query = f"SELECT COUNT(*) AS total FROM moodboards{where_clause}"  # nosec B608
                cursor = conn.execute(query, tuple(params))
                row = cursor.fetchone()
                return int(row["total"]) if row and row["total"] is not None else 0
        if only_deleted:
            predicates.append("deleted = ?")
            params.append(True if self.backend_type == BackendType.POSTGRESQL else 1)
        elif not include_deleted:
            predicates.append("deleted = ?")
            params.append(False if self.backend_type == BackendType.POSTGRESQL else 0)
        where_clause = " WHERE " + " AND ".join(predicates) if predicates else ""

        query = f"SELECT COUNT(*) AS total FROM moodboards{where_clause}"  # nosec B608
        cursor = self.execute_query(query, tuple(params))
        row = cursor.fetchone()
        return int(row["total"]) if row and row["total"] is not None else 0

    def update_moodboard(self, moodboard_id: int, update_data: dict[str, Any], expected_version: int) -> bool | None:
        if not update_data:
            raise InputError("No data provided for moodboard update.")  # noqa: TRY003

        if self._supports_notes_moodboard_studio_v61():
            return self._update_moodboard_v61(
                moodboard_id=moodboard_id,
                update_data=update_data,
                expected_version=expected_version,
            )

        now = self._get_current_utc_timestamp_iso()
        fields_to_update_sql: list[str] = []
        params_for_set_clause: list[Any] = []

        for key, value in update_data.items():
            if key == "name":
                fields_to_update_sql.append("name = ?")
                params_for_set_clause.append(self._normalize_moodboard_name(str(value or "")))
            elif key == "description":
                fields_to_update_sql.append("description = ?")
                params_for_set_clause.append(self._normalize_nullable_text(value))
            elif key in {"smart_rule", "smart_rule_json"}:
                fields_to_update_sql.append("smart_rule_json = ?")
                params_for_set_clause.append(self._serialize_moodboard_smart_rule(value))
            elif key not in {"id", "created_at", "last_modified", "version", "client_id", "deleted"}:
                logger.warning(
                    "Attempted to update immutable or unknown field '{}' in moodboard ID {}, skipping.",
                    key,
                    moodboard_id,
                )

        if not fields_to_update_sql:
            logger.info("No updatable fields provided for moodboard ID {}.", moodboard_id)
            return True

        next_version_val = expected_version + 1
        fields_to_update_sql.extend(["last_modified = ?", "version = ?", "client_id = ?"])

        all_set_values = params_for_set_clause[:]
        all_set_values.extend([now, next_version_val, self.client_id])
        scope_clause = ""
        where_values: list[Any] = [moodboard_id, expected_version]
        if self._supports_notes_moodboard_studio_v61():
            owner = str(self.client_id)
            dataset = self.resolve_moodboard_compatibility_dataset_id(owner_user_id=owner)
            fields_to_update_sql.extend(["canonical_revision = ?", "canonical_hash = ?"])
            all_set_values.extend(
                [
                    next_version_val,
                    self._note_task_v60_hash(
                        {"domain": "notes.moodboard", "id": moodboard_id, "revision": next_version_val, "update": update_data}
                    ),
                ]
            )
            scope_clause = " AND owner_user_id=? AND dataset_id=?"
            where_values.extend((owner, dataset))
        final_params_for_execute = tuple(all_set_values + where_values)
        deleted_false = "FALSE" if self.backend_type == BackendType.POSTGRESQL else "0"

        query = (
            f"UPDATE moodboards SET {', '.join(fields_to_update_sql)} "  # nosec B608
            f"WHERE id = ? AND version = ?{scope_clause} AND deleted = {deleted_false}"
        )

        try:
            with self.transaction() as conn:
                current_db_version = self._get_current_db_version(conn, "moodboards", "id", moodboard_id)
                if current_db_version != expected_version:
                    raise ConflictError(  # noqa: TRY003, TRY301
                        f"Moodboard ID {moodboard_id} update failed: version mismatch "
                        f"(db has {current_db_version}, client expected {expected_version}).",
                        entity="moodboards",
                        entity_id=moodboard_id,
                    )

                cursor = conn.execute(query, final_params_for_execute)
                if cursor.rowcount == 0:
                    check_cursor = conn.execute("SELECT version, deleted FROM moodboards WHERE id = ?", (moodboard_id,))
                    final_state = check_cursor.fetchone()
                    if not final_state:
                        msg = f"Moodboard ID {moodboard_id} disappeared."
                    elif final_state["deleted"]:
                        msg = f"Moodboard ID {moodboard_id} was soft-deleted concurrently."
                    elif final_state["version"] != expected_version:
                        msg = (
                            f"Moodboard ID {moodboard_id} version changed "
                            f"to {final_state['version']} concurrently."
                        )
                    else:
                        msg = (
                            f"Update for moodboard ID {moodboard_id} "
                            f"(expected v{expected_version}) affected 0 rows."
                        )
                    raise ConflictError(msg, entity="moodboards", entity_id=moodboard_id)  # noqa: TRY301
                return True
        except ConflictError:
            raise
        except sqlite3.IntegrityError as exc:
            raise CharactersRAGDBError(f"Database integrity error updating moodboard: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Backend error updating moodboard: {exc}") from exc  # noqa: TRY003

    def _update_moodboard_v61(
        self,
        *,
        moodboard_id: int,
        update_data: dict[str, Any],
        expected_version: int,
    ) -> bool:
        allowed = {"name", "description", "smart_rule", "smart_rule_json", "canvas", "canvas_json"}
        if not set(update_data).intersection(allowed):
            return True
        now = self._get_current_utc_timestamp_iso()
        owner = str(self.client_id)
        try:
            with self.transaction() as conn:
                dataset = self.resolve_moodboard_compatibility_dataset_id(
                    owner_user_id=owner,
                    conn=conn,
                )
                row = conn.execute(
                    "SELECT * FROM moodboards WHERE id=? AND owner_user_id=? "
                    "AND dataset_id=? AND deleted=?",
                    (
                        moodboard_id,
                        owner,
                        dataset,
                        False if self.backend_type == BackendType.POSTGRESQL else 0,
                    ),
                ).fetchone()
                if row is None:
                    raise ConflictError(
                        f"Moodboard ID {moodboard_id} not found or deleted.",
                        entity="moodboards",
                        entity_id=moodboard_id,
                    )  # noqa: TRY003
                if int(row["version"]) != expected_version:
                    raise ConflictError(
                        f"Moodboard ID {moodboard_id} update failed: version mismatch "
                        f"(db has {row['version']}, client expected {expected_version}).",
                        entity="moodboards",
                        entity_id=moodboard_id,
                    )  # noqa: TRY003

                name = (
                    self._normalize_moodboard_name(str(update_data["name"] or ""))
                    if "name" in update_data
                    else str(row["name"])
                )
                description = (
                    self._normalize_nullable_text(update_data["description"])
                    if "description" in update_data
                    else row["description"]
                )
                smart_key = (
                    "smart_rule"
                    if "smart_rule" in update_data
                    else "smart_rule_json"
                    if "smart_rule_json" in update_data
                    else None
                )
                raw_rule = (
                    self._serialize_moodboard_smart_rule(update_data[smart_key])
                    if smart_key is not None
                    else row["smart_rule_json"]
                )
                canvas_key = (
                    "canvas"
                    if "canvas" in update_data
                    else "canvas_json"
                    if "canvas_json" in update_data
                    else None
                )
                raw_canvas = (
                    update_data[canvas_key]
                    if canvas_key is not None
                    else row["canvas_json"]
                )
                revision = int(row["canonical_revision"]) + 1
                (
                    smart_rule_text,
                    canvas_text,
                    canonical_hash,
                    diagnostic_code,
                    diagnostic_hash,
                ) = self._canonical_moodboard_state_v61(
                    conn,
                    sync_id=str(row["sync_id"]),
                    name=name,
                    description=description,
                    raw_smart_rule=raw_rule,
                    raw_canvas=raw_canvas,
                    owner_user_id=owner,
                    revision=revision,
                    deleted=False,
                )
                cursor = conn.execute(
                    "UPDATE moodboards SET name=?,description=?,smart_rule_json=?,canvas_json=?,"
                    "last_modified=?,version=?,client_id=?,canonical_revision=?,canonical_hash=?,"
                    "source_diagnostic_code=?,source_diagnostic_hash=? "
                    "WHERE id=? AND owner_user_id=? AND dataset_id=? AND version=? AND deleted=?",
                    (
                        name,
                        description,
                        smart_rule_text,
                        canvas_text,
                        now,
                        expected_version + 1,
                        owner,
                        revision,
                        canonical_hash,
                        diagnostic_code,
                        diagnostic_hash,
                        moodboard_id,
                        owner,
                        dataset,
                        expected_version,
                        False if self.backend_type == BackendType.POSTGRESQL else 0,
                    ),
                )
                if cursor.rowcount != 1:
                    raise ConflictError(
                        f"Moodboard ID {moodboard_id} changed concurrently.",
                        entity="moodboards",
                        entity_id=moodboard_id,
                    )  # noqa: TRY003
                return True
        except (sqlite3.IntegrityError, BackendDatabaseError) as exc:
            raise CharactersRAGDBError(
                f"Database error updating moodboard: {exc}"
            ) from exc  # noqa: TRY003

    def delete_moodboard(self, moodboard_id: int, expected_version: int | None = None, hard_delete: bool = False) -> bool:
        now = self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                scope_clause = ""
                scope_params: tuple[Any, ...] = ()
                if self._supports_notes_moodboard_studio_v61():
                    owner = str(self.client_id)
                    dataset = self.resolve_moodboard_compatibility_dataset_id(
                        owner_user_id=owner, conn=conn
                    )
                    scope_clause = " AND owner_user_id=? AND dataset_id=?"
                    scope_params = (owner, dataset)
                row = conn.execute(
                    f"SELECT * FROM moodboards WHERE id=?{scope_clause}",  # nosec B608
                    (moodboard_id, *scope_params),
                ).fetchone()
                if not row:
                    return False
                current_version = int(row["version"])
                deleted = bool(row["deleted"])
                if hard_delete:
                    conn.execute(
                        f"DELETE FROM moodboards WHERE id=?{scope_clause}",  # nosec B608
                        (moodboard_id, *scope_params),
                    )
                    return True
                if deleted:
                    return True
                if expected_version is not None and current_version != expected_version:
                    raise ConflictError(  # noqa: TRY003
                        "Version mismatch deleting moodboard",
                        entity="moodboards",
                        identifier=moodboard_id,
                    )
                deleted_val = True if self.backend_type == BackendType.POSTGRESQL else 1
                lineage_sql = ""
                lineage_params: tuple[Any, ...] = ()
                if self._supports_notes_moodboard_studio_v61():
                    revision = int(row["canonical_revision"]) + 1
                    try:
                        smart_rule = (
                            None
                            if row["smart_rule_json"] is None
                            else json.loads(str(row["smart_rule_json"]))
                        )
                        canvas = json.loads(str(row["canvas_json"]))
                        canonical_hash = notes_moodboard_object_hash(
                            parse_notes_moodboard_v1(
                                {
                                    "moodboard_id": row["sync_id"],
                                    "name": row["name"],
                                    "description": row["description"],
                                    "smart_rule": smart_rule,
                                    "canvas": canvas,
                                }
                            ),
                            revision=revision,
                            deleted=True,
                        )
                    except (NotesMoodboardStudioContractError, TypeError, ValueError, json.JSONDecodeError):
                        canonical_hash = self._note_task_v60_hash(
                            {
                                "domain": "notes.moodboard",
                                "sync_id": row["sync_id"],
                                "revision": revision,
                                "deleted": True,
                            }
                        )
                    lineage_sql = ", canonical_revision = ?, canonical_hash = ?"
                    lineage_params = (revision, canonical_hash)
                rowcount = conn.execute(
                    "UPDATE moodboards SET deleted = ?, last_modified = ?, version = ?, client_id = ? "
                    f"{lineage_sql} "
                    f"WHERE id = ?{scope_clause} AND deleted = ?",  # nosec B608
                    (
                        deleted_val,
                        now,
                        current_version + 1,
                        self.client_id,
                        *lineage_params,
                        moodboard_id,
                        *scope_params,
                        False if self.backend_type == BackendType.POSTGRESQL else 0,
                    ),
                ).rowcount
                return rowcount > 0
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to delete moodboard: {exc}") from exc  # noqa: TRY003
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to delete moodboard: {exc}") from exc  # noqa: TRY003

    def link_note_to_moodboard(self, moodboard_id: int, note_id: str) -> bool:
        moodboard = self.get_moodboard_by_id(moodboard_id)
        if not moodboard:
            raise ConflictError("Moodboard not found.", entity="moodboards", entity_id=moodboard_id)  # noqa: TRY003
        note = self.get_note_by_id(note_id=note_id)
        if not note:
            raise ConflictError("Note not found.", entity="notes", entity_id=note_id)  # noqa: TRY003
        if not self._supports_notes_moodboard_studio_v61():
            return self._manage_link("moodboard_notes", "moodboard_id", moodboard_id, "note_id", note_id, "link")
        owner = str(self.client_id)
        dataset = str(moodboard["dataset_id"])
        now = self._get_current_utc_timestamp_iso()
        placement_source = {
            "moodboard_id": moodboard["sync_id"],
            "note_id": note_id,
            "x": 0,
            "y": 0,
            "width": 320,
            "height": 220,
            "order_index": 0,
            "display": {},
        }
        diagnostic_code = diagnostic_hash = None
        try:
            parsed = parse_notes_moodboard_note_v1(placement_source)
            placement_id = placement_object_id(parsed)
            canonical_hash = notes_moodboard_note_object_hash(parsed, revision=1, deleted=False)
        except NotesMoodboardStudioContractError:
            digest = hashlib.sha256(canonical_moodboard_studio_json_bytes(placement_source)).hexdigest()
            placement_id = f"notes.moodboard_note:sha256:{digest}"
            canonical_hash = self._note_task_v60_hash(
                {"domain": "notes.moodboard_note", "source": placement_source}
            )
            diagnostic = moodboard_studio_legacy_source_diagnostic(
                "legacy_moodboard_placement_identity_invalid", placement_source
            )
            diagnostic_code, diagnostic_hash = diagnostic["code"], diagnostic["source_hash"]
        with self.transaction() as conn:
            self._set_notes_moodboard_studio_v61_dataset_scope(conn, dataset)
            existing = conn.execute(
                "SELECT * FROM moodboard_notes "
                "WHERE owner_user_id=? AND dataset_id=? AND moodboard_id=? AND note_id=?",
                (owner, dataset, moodboard_id, note_id),
            ).fetchone()
            if existing is not None and not bool(existing["deleted"]):
                return False
            if existing is not None:
                revision = int(existing["canonical_revision"]) + 1
                version = int(existing["version"]) + 1
                placement_source.update(
                    {
                        "x": int(existing["x"]),
                        "y": int(existing["y"]),
                        "width": int(existing["width"]),
                        "height": int(existing["height"]),
                        "order_index": int(existing["order_index"]),
                        "display": json.loads(str(existing["display_json"])),
                    }
                )
                try:
                    parsed = parse_notes_moodboard_note_v1(placement_source)
                    canonical_hash = notes_moodboard_note_object_hash(
                        parsed,
                        revision=revision,
                        deleted=False,
                    )
                except NotesMoodboardStudioContractError:
                    canonical_hash = self._note_task_v60_hash(
                        {"domain": "notes.moodboard_note", "source": placement_source, "revision": revision}
                    )
                conn.execute(
                    "UPDATE moodboard_notes SET deleted=?,last_modified=?,version=?,canonical_revision=?,canonical_hash=? "
                    "WHERE owner_user_id=? AND dataset_id=? AND moodboard_id=? AND note_id=? AND deleted=?",
                    (
                        False,
                        now,
                        version,
                        revision,
                        canonical_hash,
                        owner,
                        dataset,
                        moodboard_id,
                        note_id,
                        True,
                    ),
                )
                return True
            order_row = conn.execute(
                "SELECT COALESCE(MAX(order_index),-1)+1 AS next_order_index "
                "FROM moodboard_notes "
                "WHERE owner_user_id=? AND dataset_id=? AND moodboard_id=?",
                (owner, dataset, moodboard_id),
            ).fetchone()
            order_index = int(
                order_row["next_order_index"]
                if isinstance(order_row, Mapping)
                else order_row[0]
            )
            placement_source["order_index"] = order_index
            try:
                parsed = parse_notes_moodboard_note_v1(placement_source)
                placement_id = placement_object_id(parsed)
                canonical_hash = notes_moodboard_note_object_hash(parsed, revision=1, deleted=False)
            except NotesMoodboardStudioContractError:
                digest = hashlib.sha256(canonical_moodboard_studio_json_bytes(placement_source)).hexdigest()
                placement_id = f"notes.moodboard_note:sha256:{digest}"
            conn.execute(
                "INSERT INTO moodboard_notes("
                "owner_user_id,dataset_id,moodboard_id,note_id,placement_id,x,y,width,height,order_index,"
                "display_json,created_at,last_modified,deleted,version,canonical_revision,canonical_hash,"
                "source_diagnostic_code,source_diagnostic_hash"
                ") VALUES(?,?,?,?,?,0,0,320,220,?,'{}',?,?,?,1,1,?,?,?)",
                (
                    owner,
                    dataset,
                    moodboard_id,
                    note_id,
                    placement_id,
                    order_index,
                    now,
                    now,
                    False,
                    canonical_hash,
                    diagnostic_code,
                    diagnostic_hash,
                ),
            )
            return True

    def unlink_note_from_moodboard(self, moodboard_id: int, note_id: str) -> bool:
        moodboard = self.get_moodboard_by_id(moodboard_id)
        if not moodboard:
            raise ConflictError("Moodboard not found.", entity="moodboards", entity_id=moodboard_id)  # noqa: TRY003
        if not self._supports_notes_moodboard_studio_v61():
            return self._manage_link("moodboard_notes", "moodboard_id", moodboard_id, "note_id", note_id, "unlink")
        owner = str(self.client_id)
        dataset = str(moodboard["dataset_id"])
        now = self._get_current_utc_timestamp_iso()
        with self.transaction() as conn:
            self._set_notes_moodboard_studio_v61_dataset_scope(conn, dataset)
            row = conn.execute(
                "SELECT * FROM moodboard_notes WHERE owner_user_id=? AND dataset_id=? "
                "AND moodboard_id=? AND note_id=?",
                (owner, dataset, moodboard_id, note_id),
            ).fetchone()
            if row is None or bool(row["deleted"]):
                return False
            revision = int(row["canonical_revision"]) + 1
            source = {
                "moodboard_id": moodboard["sync_id"], "note_id": note_id,
                "x": int(row["x"]), "y": int(row["y"]), "width": int(row["width"]),
                "height": int(row["height"]), "order_index": int(row["order_index"]),
                "display": json.loads(str(row["display_json"])),
            }
            try:
                canonical_hash = notes_moodboard_note_object_hash(
                    parse_notes_moodboard_note_v1(source), revision=revision, deleted=True
                )
            except NotesMoodboardStudioContractError:
                canonical_hash = self._note_task_v60_hash(
                    {"domain": "notes.moodboard_note", "source": source, "revision": revision, "deleted": True}
                )
            cursor = conn.execute(
                "UPDATE moodboard_notes SET deleted=?,last_modified=?,version=version+1,"
                "canonical_revision=?,canonical_hash=? WHERE owner_user_id=? AND dataset_id=? "
                "AND moodboard_id=? AND note_id=? AND deleted=?",
                (
                    True if self.backend_type == BackendType.POSTGRESQL else 1,
                    now,
                    revision,
                    canonical_hash,
                    owner,
                    dataset,
                    moodboard_id,
                    note_id,
                    False if self.backend_type == BackendType.POSTGRESQL else 0,
                ),
            )
            return cursor.rowcount == 1

    @staticmethod
    def _moodboard_content_preview_expr(note_alias: str = "n") -> str:
        return (
            f"CASE "
            f"WHEN {note_alias}.content IS NULL OR {note_alias}.content = '' THEN NULL "
            f"WHEN LENGTH({note_alias}.content) <= 280 THEN {note_alias}.content "
            f"ELSE SUBSTR({note_alias}.content, 1, 277) || '...' "
            f"END"
        )

    def _build_moodboard_smart_rule_sql_parts(
        self,
        smart_rule: dict[str, Any],
        *,
        owner_user_id: str,
        note_alias: str = "n",
    ) -> tuple[list[str], list[str], list[Any]]:
        if not isinstance(smart_rule, dict):
            return [], [], []

        query_text = self._normalize_nullable_text(smart_rule.get("query"))
        keyword_tokens = [
            str(token).strip().lower()
            for token in (smart_rule.get("keyword_tokens") or [])
            if str(token).strip()
        ]
        sources = [
            str(source).strip().lower()
            for source in (smart_rule.get("sources") or [])
            if str(source).strip()
        ]

        updated_after = None
        updated_before = None
        updated = smart_rule.get("updated")
        if isinstance(updated, dict):
            updated_after = self._normalize_nullable_text(updated.get("after"))
            updated_before = self._normalize_nullable_text(updated.get("before"))
        if not updated_after:
            updated_after = self._normalize_nullable_text(smart_rule.get("updated_after"))
        if not updated_before:
            updated_before = self._normalize_nullable_text(smart_rule.get("updated_before"))

        joins: list[str] = []
        where_clauses: list[str] = []
        params: list[Any] = []
        deleted_false = "FALSE" if self.backend_type == BackendType.POSTGRESQL else "0"
        where_clauses.append(f"{note_alias}.deleted = {deleted_false}")
        where_clauses.append(f"{note_alias}.client_id = ?")
        params.append(owner_user_id)

        if query_text:
            like_value = f"%{query_text.lower()}%"
            where_clauses.append(f"(LOWER({note_alias}.title) LIKE ? OR LOWER({note_alias}.content) LIKE ?)")
            params.extend([like_value, like_value])

        if sources:
            joins.append(f"JOIN conversations c ON c.id = {note_alias}.conversation_id")
            placeholders = ",".join(["?"] * len(sources))
            where_clauses.append(f"LOWER(COALESCE(c.source, '')) IN ({placeholders})")
            params.extend(sources)

        if keyword_tokens:
            keyword_table = self._map_table_for_backend("keywords")
            joins.append(f"JOIN note_keywords nk ON nk.note_id = {note_alias}.id")
            joins.append(f"JOIN {keyword_table} k ON k.id = nk.keyword_id")  # nosec B608
            where_clauses.append(f"k.deleted = {deleted_false}")
            keyword_match = " OR ".join(["LOWER(k.keyword) LIKE ?"] * len(keyword_tokens))
            where_clauses.append(f"({keyword_match})")
            params.extend([f"%{token}%" for token in keyword_tokens])

        if updated_after:
            where_clauses.append(f"{note_alias}.last_modified >= ?")
            params.append(updated_after)
        if updated_before:
            where_clauses.append(f"{note_alias}.last_modified <= ?")
            params.append(updated_before)

        return joins, where_clauses, params

    def _build_moodboard_note_union_query(
        self,
        moodboard_id: int,
        smart_rule: dict[str, Any] | None,
        *,
        owner_user_id: str,
        dataset_id: str | None,
    ) -> tuple[str, tuple[Any, ...]]:
        preview_expr = self._moodboard_content_preview_expr("n")
        deleted_false_value = False if self.backend_type == BackendType.POSTGRESQL else 0

        # preview_expr is derived from a fixed internal alias and does not include user input.
        manual_select = (  # nosec B608
            "SELECT n.id AS id, n.title AS title, n.last_modified AS last_modified, "
            f"{preview_expr} AS content_preview, "  # nosec B608
            "1 AS manual_hit, 0 AS smart_hit "
            "FROM moodboard_notes mn "
            "JOIN notes n ON n.id = mn.note_id "
            "WHERE mn.moodboard_id = ? AND mn.deleted = ? AND n.deleted = ? "
            "AND n.client_id = ?"
        )
        select_queries: list[str] = [manual_select]
        params: list[Any] = [
            moodboard_id,
            deleted_false_value,
            deleted_false_value,
            owner_user_id,
        ]
        if self._supports_notes_moodboard_studio_v61():
            manual_select += " AND mn.owner_user_id = ? AND mn.dataset_id = ?"
            select_queries[0] = manual_select
            params.extend((owner_user_id, dataset_id))

        if isinstance(smart_rule, dict) and smart_rule:
            joins, where_clauses, smart_params = self._build_moodboard_smart_rule_sql_parts(
                smart_rule,
                owner_user_id=owner_user_id,
                note_alias="n",
            )
            if where_clauses:
                smart_select = (
                    "SELECT DISTINCT n.id AS id, n.title AS title, n.last_modified AS last_modified, "
                    f"{preview_expr} AS content_preview, "
                    "0 AS manual_hit, 1 AS smart_hit "
                    f"FROM notes n {' '.join(joins)} "  # nosec B608
                    f"WHERE {' AND '.join(where_clauses)}"  # nosec B608
                )
                select_queries.append(smart_select)
                params.extend(smart_params)

        union_query = " UNION ALL ".join(select_queries)
        return union_query, tuple(params)

    def _list_notes_matching_moodboard_rule(self, smart_rule: dict[str, Any]) -> list[dict[str, Any]]:
        joins, where_clauses, params = self._build_moodboard_smart_rule_sql_parts(
            smart_rule,
            owner_user_id=str(self.client_id),
            note_alias="n",
        )
        if not where_clauses:
            return []

        query = (
            f"SELECT DISTINCT n.* FROM notes n {' '.join(joins)} "  # nosec B608
            f"WHERE {' AND '.join(where_clauses)} "
            "ORDER BY n.last_modified DESC, n.id DESC"
        )
        cursor = self.execute_query(query, tuple(params))
        return [dict(row) for row in cursor.fetchall()]

    def count_moodboard_notes(self, moodboard_id: int) -> int:
        moodboard = self.get_moodboard_by_id(moodboard_id)
        if not moodboard:
            raise ConflictError("Moodboard not found.", entity="moodboards", entity_id=moodboard_id)  # noqa: TRY003

        union_query, union_params = self._build_moodboard_note_union_query(
            moodboard_id=moodboard_id,
            smart_rule=moodboard.get("smart_rule"),
            owner_user_id=str(moodboard.get("owner_user_id") or self.client_id),
            dataset_id=(
                None
                if moodboard.get("dataset_id") is None
                else str(moodboard["dataset_id"])
            ),
        )
        count_query = (
            f"WITH combined AS ({union_query}) "  # nosec B608
            "SELECT COUNT(DISTINCT id) AS total FROM combined"
        )
        if self._supports_notes_moodboard_studio_v61():
            with self.transaction() as conn:
                dataset = moodboard.get("dataset_id")
                if dataset is not None:
                    self._set_notes_moodboard_studio_v61_dataset_scope(
                        conn,
                        str(dataset),
                    )
                cursor = conn.execute(count_query, union_params)
                row = cursor.fetchone()
                return int(row["total"]) if row and row["total"] is not None else 0
        cursor = self.execute_query(count_query, union_params)
        row = cursor.fetchone()
        return int(row["total"]) if row and row["total"] is not None else 0

    def list_moodboard_notes(self, moodboard_id: int, limit: int = 100, offset: int = 0) -> list[dict[str, Any]]:
        if limit <= 0:
            return []

        moodboard = self.get_moodboard_by_id(moodboard_id)
        if not moodboard:
            raise ConflictError("Moodboard not found.", entity="moodboards", entity_id=moodboard_id)  # noqa: TRY003

        union_query, union_params = self._build_moodboard_note_union_query(
            moodboard_id=moodboard_id,
            smart_rule=moodboard.get("smart_rule"),
            owner_user_id=str(moodboard.get("owner_user_id") or self.client_id),
            dataset_id=(
                None
                if moodboard.get("dataset_id") is None
                else str(moodboard["dataset_id"])
            ),
        )
        page_query = (
            f"WITH combined AS ({union_query}), "  # nosec B608
            "collapsed AS ("
            "    SELECT "
            "      id, "
            "      MAX(title) AS title, "
            "      MAX(last_modified) AS last_modified, "
            "      MAX(content_preview) AS content_preview, "
            "      MAX(manual_hit) AS manual_hit, "
            "      MAX(smart_hit) AS smart_hit "
            "    FROM combined "
            "    GROUP BY id"
            ") "
            "SELECT "
            "  id, "
            "  title, "
            "  content_preview, "
            "  last_modified, "
            "  CASE "
            "    WHEN manual_hit = 1 AND smart_hit = 1 THEN 'both' "
            "    WHEN smart_hit = 1 THEN 'smart' "
            "    ELSE 'manual' "
            "  END AS membership_source "
            "FROM collapsed "
            "ORDER BY last_modified DESC, id DESC "
            "LIMIT ? OFFSET ?"
        )
        page_params = (*union_params, limit, offset)
        if self._supports_notes_moodboard_studio_v61():
            with self.transaction() as conn:
                dataset = moodboard.get("dataset_id")
                if dataset is not None:
                    self._set_notes_moodboard_studio_v61_dataset_scope(
                        conn,
                        str(dataset),
                    )
                cursor = conn.execute(page_query, page_params)
                paged = [dict(row) for row in cursor.fetchall()]
        else:
            cursor = self.execute_query(page_query, page_params)
            paged = [dict(row) for row in cursor.fetchall()]

        note_ids = [str(item.get("id")) for item in paged if item.get("id") is not None]
        keywords_by_note = self.get_keywords_for_notes(note_ids) if note_ids else {}
        for row in paged:
            note_id = str(row.get("id"))
            keywords = keywords_by_note.get(note_id, [])
            row["keywords"] = [str(item.get("keyword")) for item in keywords if item.get("keyword")]
            preview = row.get("content_preview")
            row["content_preview"] = preview if isinstance(preview, str) and preview else None
            row["updated_at"] = row.get("last_modified")
            row["cover_image_url"] = None
        return paged


    # --- Linking Table Methods (with manual sync_log entries) ---
    def _manage_link(self, link_table: str, col1_name: str, col1_val: Any, col2_name: str, col2_val: Any,
                     operation: str) -> bool:
        """Helper to add ('link') or remove ('unlink') entries from a linking table."""
        now_iso = self._get_current_utc_timestamp_iso()
        sync_payload_dict: dict[str, Any] = {}
        log_sync_entry = False
        rows_affected = 0

        try:
            with self.transaction() as conn:
                if operation == "link":
                    if self.backend_type == BackendType.POSTGRESQL:
                        query = (
                            f"INSERT INTO {link_table} ({col1_name}, {col2_name}, created_at) "  # nosec B608
                            f"VALUES (?, ?, ?) ON CONFLICT ({col1_name}, {col2_name}) DO NOTHING"
                        )
                    else:
                        query = (
                            f"INSERT OR IGNORE INTO {link_table} ({col1_name}, {col2_name}, created_at) "
                            "VALUES (?, ?, ?)"
                        )
                    params = (col1_val, col2_val, now_iso)
                    cursor = conn.execute(query, params)
                    rows_affected = cursor.rowcount
                    if rows_affected > 0:  # Link was actually created
                        log_sync_entry = True
                        sync_payload_dict = {col1_name: col1_val, col2_name: col2_val, 'created_at': now_iso}
                elif operation == "unlink":
                    query = f"DELETE FROM {link_table} WHERE {col1_name} = ? AND {col2_name} = ?"  # nosec B608
                    params = (col1_val, col2_val)
                    cursor = conn.execute(query, params)
                    rows_affected = cursor.rowcount
                    if rows_affected > 0:  # Link was actually deleted
                        log_sync_entry = True
                        sync_payload_dict = {col1_name: col1_val, col2_name: col2_val}
                else:
                    raise InputError("Invalid operation for link management.")  # noqa: TRY003

                if log_sync_entry:
                    sync_entity_id = f"{col1_val}_{col2_val}"
                    sync_op = 'create' if operation == 'link' else 'delete'
                    sync_timestamp = now_iso # Use now_iso for create, and also for delete event time

                    entity_col = 'entity_id'
                    if self.backend_type == BackendType.POSTGRESQL:
                        try:
                            cols = {c.get('name') for c in self.backend.get_table_info('sync_log', connection=conn)}
                            if 'entity_uuid' in cols and 'entity_id' not in cols:
                                entity_col = 'entity_uuid'
                        except _CHACHA_NONCRITICAL_EXCEPTIONS as e:
                            logger.debug("sync_log column introspection failed on {}: {}", self.backend_type.value, e)
                    if entity_col not in ("entity_id", "entity_uuid"):
                        raise CharactersRAGDBError(  # noqa: TRY003
                            f"Unexpected sync_log id column: {entity_col}"
                        )

                    sync_log_query = (
                        f"INSERT INTO sync_log (entity, {entity_col}, operation, timestamp, client_id, version, payload) "  # nosec B608
                        f"VALUES (?, ?, ?, ?, ?, ?, ?)"
                    )
                    sync_log_params = (
                        link_table, sync_entity_id, sync_op, sync_timestamp,
                        self.client_id, 1, # Link table entries don't have their own version, use 1 for sync log
                        json.dumps(sync_payload_dict)
                    )
                    conn.execute(sync_log_query, sync_log_params)
                    logger.debug(f"Logged sync event for {link_table}: {sync_op} on {sync_entity_id}")

            logger.info(
                f"{operation.capitalize()}ed {link_table}: {col1_name}={col1_val}, {col2_name}={col2_val}. Rows affected: {rows_affected}")
            return rows_affected > 0  # noqa: TRY300
        except sqlite3.Error as e:  # Catch SQLite specific errors from conn.execute
            logger.error(
                f"SQLite error during {operation} for {link_table} ({col1_name}={col1_val}, {col2_name}={col2_val}): {e}",
                exc_info=True,
            )
            raise CharactersRAGDBError(f"Database error during {operation} for {link_table}: {e}") from e  # noqa: TRY003
        except BackendDatabaseError as exc:
            logger.error(
                'Backend error during {} for {} ({}={}, {}={}): {}',
                operation,
                link_table,
                col1_name,
                col1_val,
                col2_name,
                col2_val,
                exc,
                exc_info=True,
            )
            raise CharactersRAGDBError(f"Database error during {operation} for {link_table}: {exc}") from exc  # noqa: TRY003
        except CharactersRAGDBError as e:  # Catch custom errors like InputError
            logger.error(f"Application error during {operation} for {link_table}: {e}", exc_info=True)
            raise


    # Conversation <-> Keyword
    # Keyword/note link helper methods are delegated to extracted stores at module bottom.

    @staticmethod
    def _coerce_mapping_row(row: Any) -> dict[str, Any] | None:
        if row is None:
            return None
        if isinstance(row, dict):
            return row
        try:
            return dict(row)
        except (TypeError, ValueError):
            if hasattr(row, "keys"):
                keys = row.keys()
                return {key: row[key] for key in keys}
        return None

    def _normalize_note_folder_path(self, value: Any) -> str | None:
        if value is None:
            return None
        text = str(value).strip().replace("\\", "/").strip("/")
        if not text:
            return None
        parts: list[str] = []
        for raw_part in text.split("/"):
            part = raw_part.strip()
            if not part or part == ".":
                continue
            if part == "..":
                raise InputError("Folder paths cannot contain parent traversal segments.")  # noqa: TRY003
            parts.append(part)
        normalized = "/".join(parts)
        return normalized or None

    def _note_folder_path_key(self, value: Any) -> str | None:
        normalized = self._normalize_note_folder_path(value)
        if not normalized:
            return None
        return normalized.lower()

    def _expand_note_folder_paths(self, folder_paths: list[str] | tuple[str, ...]) -> list[str]:
        expanded: list[str] = []
        seen: set[str] = set()
        for raw_path in folder_paths:
            normalized = self._normalize_note_folder_path(raw_path)
            if not normalized:
                continue
            segments = normalized.split("/")
            for index in range(1, len(segments) + 1):
                candidate = "/".join(segments[:index])
                key = self._note_folder_path_key(candidate)
                if key is None:
                    continue
                if key in seen:
                    continue
                seen.add(key)
                expanded.append(candidate)
        return expanded

    def _ensure_note_exists_for_folder_sync(self, conn: Any, note_id: str) -> None:
        row = conn.execute("SELECT id FROM notes WHERE id = ?", (note_id,)).fetchone()
        if row is None:
            raise ConflictError("Note not found.", entity="notes", entity_id=note_id)  # noqa: TRY003

    def _lookup_note_folder_row_locked(self, conn: Any, folder_path: str) -> dict[str, Any] | None:
        normalized_path = self._normalize_note_folder_path(folder_path)
        if not normalized_path:
            return None
        return self._coerce_mapping_row(
            conn.execute(
                """
                SELECT id, path, deleted, version
                  FROM note_folders
                 WHERE LOWER(path) = LOWER(?)
                 ORDER BY deleted ASC, id ASC
                 LIMIT 1
                """,
                (normalized_path,),
            ).fetchone()
        )

    def _ensure_note_folder_path_locked(self, conn: Any, folder_path: str) -> int:
        normalized_path = self._normalize_note_folder_path(folder_path)
        if not normalized_path:
            raise InputError("Folder path cannot be empty.")  # noqa: TRY003

        existing_row = self._lookup_note_folder_row_locked(conn, normalized_path)
        if existing_row:
            folder_id = int(existing_row["id"])
            if bool(existing_row.get("deleted", False)):
                now = self._get_current_utc_timestamp_iso()
                deleted_value = False if self.backend_type == BackendType.POSTGRESQL else 0
                conn.execute(
                    "UPDATE note_folders SET deleted = ?, last_modified = ?, version = ?, client_id = ? WHERE id = ?",
                    (
                        deleted_value,
                        now,
                        int(existing_row.get("version") or 1) + 1,
                        self.client_id,
                        folder_id,
                    ),
                )
            return folder_id

        parent_path = normalized_path.rsplit("/", 1)[0] if "/" in normalized_path else None
        parent_id = self._ensure_note_folder_path_locked(conn, parent_path) if parent_path else None
        stored_path = normalized_path
        if parent_id is not None:
            parent_row = self._coerce_mapping_row(
                conn.execute(
                    "SELECT path FROM note_folders WHERE id = ?",
                    (parent_id,),
                ).fetchone()
            ) or {}
            parent_display_path = self._normalize_note_folder_path(parent_row.get("path")) or parent_path
            stored_path = f"{parent_display_path}/{normalized_path.rsplit('/', 1)[-1]}"
        now = self._get_current_utc_timestamp_iso()
        deleted_value = False if self.backend_type == BackendType.POSTGRESQL else 0
        conn.execute(
            """
            INSERT INTO note_folders(
              sync_id, name, path, parent_id, created_at, last_modified, deleted, client_id, version
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                self._generate_uuid(),
                stored_path.rsplit("/", 1)[-1],
                stored_path,
                parent_id,
                now,
                now,
                deleted_value,
                self.client_id,
                1,
            ),
        )
        created_row = self._lookup_note_folder_row_locked(conn, stored_path)
        if not created_row:
            raise CharactersRAGDBError(f"Failed to create note folder path '{normalized_path}'.")  # noqa: TRY003
        return int(created_row["id"])

    def _active_note_folder_deleted_value(self) -> bool | int:
        return False if self.backend_type == BackendType.POSTGRESQL else 0

    def create_note_folder_path(self, folder_path: str) -> dict[str, Any]:
        """Create or reuse a note folder path and return the active folder row."""
        try:
            with self.transaction() as conn:
                folder_id = self._ensure_note_folder_path_locked(conn, folder_path)
                folder_row = self._coerce_mapping_row(
                    conn.execute(
                        """
                        SELECT id, sync_id, name, path, parent_id
                          FROM note_folders
                         WHERE id = ? AND deleted = ?
                        """,
                        (folder_id, self._active_note_folder_deleted_value()),
                    ).fetchone()
                )
                if folder_row is None:
                    raise CharactersRAGDBError(f"Failed to reload note folder '{folder_path}'.")  # noqa: TRY003
                return folder_row
        except CharactersRAGDBError:
            raise
        except (sqlite3.Error, BackendDatabaseError) as exc:
            raise CharactersRAGDBError(f"Failed creating note folder path: {exc}") from exc  # noqa: TRY003

    def get_note_folder_by_path(self, folder_path: str) -> dict[str, Any] | None:
        """Return an active note folder row by case-insensitive normalized path."""
        normalized_path = self._normalize_note_folder_path(folder_path)
        if not normalized_path:
            return None
        cursor = self.execute_query(
            """
            SELECT id, sync_id, name, path, parent_id
              FROM note_folders
             WHERE LOWER(path) = LOWER(?) AND deleted = ?
            """,
            (normalized_path, self._active_note_folder_deleted_value()),
        )
        row = cursor.fetchone()
        return dict(row) if row else None

    def list_note_folders(self, limit: int = 1000, offset: int = 0) -> list[dict[str, Any]]:
        """Return active note folders ordered by path for picker UIs."""
        if limit <= 0:
            return []
        path_order_expr = self._case_insensitive_order_expression("path")
        query = (
            "SELECT id, sync_id, name, path, parent_id "
            "FROM note_folders "
            "WHERE deleted = ? "
            f"ORDER BY {path_order_expr} "  # nosec B608
            "LIMIT ? OFFSET ?"
        )
        cursor = self.execute_query(
            query,
            (self._active_note_folder_deleted_value(), limit, max(0, offset)),
        )
        return [dict(row) for row in cursor.fetchall()]

    def sync_note_folders(self, note_id: str, folder_paths: list[str] | tuple[str, ...]) -> list[dict[str, Any]]:
        desired_paths = self._expand_note_folder_paths(list(folder_paths or []))
        try:
            with self.transaction() as conn:
                self._ensure_note_exists_for_folder_sync(conn, note_id)
                desired_ids = {
                    self._ensure_note_folder_path_locked(conn, folder_path)
                    for folder_path in desired_paths
                }
                existing_rows = conn.execute(
                    "SELECT folder_id FROM note_folder_memberships WHERE note_id = ?",
                    (note_id,),
                ).fetchall()
                existing_ids: set[int] = set()
                for row in existing_rows:
                    record = self._coerce_mapping_row(row) or {}
                    folder_id = record.get("folder_id")
                    if folder_id is None:
                        continue
                    existing_ids.add(int(folder_id))

                for folder_id in existing_ids - desired_ids:
                    conn.execute(
                        "DELETE FROM note_folder_memberships WHERE note_id = ? AND folder_id = ?",
                        (note_id, folder_id),
                    )

                now = self._get_current_utc_timestamp_iso()
                for folder_id in desired_ids - existing_ids:
                    conn.execute(
                        """
                        INSERT INTO note_folder_memberships(note_id, folder_id, created_at)
                        VALUES (?, ?, ?)
                        """,
                        (note_id, folder_id, now),
                    )
        except CharactersRAGDBError:
            raise
        except (sqlite3.Error, BackendDatabaseError) as exc:
            raise CharactersRAGDBError(f"Failed syncing manual note folders: {exc}") from exc  # noqa: TRY003
        return self.get_note_folders_for_note(note_id)

    def sync_note_source_folders(
        self,
        note_id: str,
        source_id: int,
        folder_paths: list[str] | tuple[str, ...],
    ) -> list[dict[str, Any]]:
        if int(source_id) <= 0:
            raise InputError("source_id must be a positive integer.")  # noqa: TRY003

        desired_paths = self._expand_note_folder_paths(list(folder_paths or []))
        try:
            with self.transaction() as conn:
                self._ensure_note_exists_for_folder_sync(conn, note_id)
                desired_pairs: list[tuple[str, int]] = []
                for folder_path in desired_paths:
                    folder_id = self._ensure_note_folder_path_locked(conn, folder_path)
                    desired_pairs.append((folder_path, folder_id))

                existing_rows = conn.execute(
                    """
                    SELECT folder_id
                      FROM note_folder_source_memberships
                     WHERE note_id = ? AND source_id = ?
                    """,
                    (note_id, int(source_id)),
                ).fetchall()
                existing_ids: set[int] = set()
                for row in existing_rows:
                    record = self._coerce_mapping_row(row) or {}
                    folder_id = record.get("folder_id")
                    if folder_id is None:
                        continue
                    existing_ids.add(int(folder_id))
                desired_ids = {folder_id for _, folder_id in desired_pairs}
                desired_keys = {
                    canonical_key
                    for folder_path, _ in desired_pairs
                    for canonical_key in [self._note_folder_path_key(folder_path)]
                    if canonical_key is not None
                }

                for folder_id in existing_ids - desired_ids:
                    conn.execute(
                        """
                        DELETE FROM note_folder_source_memberships
                         WHERE note_id = ? AND source_id = ? AND folder_id = ?
                        """,
                        (note_id, int(source_id), folder_id),
                    )

                existing_key_rows = conn.execute(
                    """
                    SELECT folder_key
                      FROM note_folder_source_keys
                     WHERE source_id = ?
                    """,
                    (int(source_id),),
                ).fetchall()
                existing_keys: set[str] = set()
                for row in existing_key_rows:
                    record = self._coerce_mapping_row(row) or {}
                    folder_key = record.get("folder_key")
                    if folder_key is None:
                        continue
                    existing_keys.add(str(folder_key))
                for folder_key in existing_keys - desired_keys:
                    conn.execute(
                        """
                        DELETE FROM note_folder_source_keys
                         WHERE source_id = ? AND folder_key = ?
                        """,
                        (int(source_id), folder_key),
                    )

                now = self._get_current_utc_timestamp_iso()
                for folder_path, folder_id in desired_pairs:
                    folder_key = self._note_folder_path_key(folder_path)
                    if not folder_key:
                        continue
                    conn.execute(
                        """
                        DELETE FROM note_folder_source_keys
                         WHERE source_id = ? AND folder_key = ?
                        """,
                        (int(source_id), folder_key),
                    )
                    conn.execute(
                        """
                        INSERT INTO note_folder_source_keys(source_id, folder_key, folder_id, created_at)
                        VALUES (?, ?, ?, ?)
                        """,
                        (int(source_id), folder_key, folder_id, now),
                    )
                    if folder_id in existing_ids:
                        continue
                    conn.execute(
                        """
                        INSERT INTO note_folder_source_memberships(note_id, source_id, folder_id, created_at)
                        VALUES (?, ?, ?, ?)
                        """,
                        (note_id, int(source_id), folder_id, now),
                    )
        except CharactersRAGDBError:
            raise
        except (sqlite3.Error, BackendDatabaseError) as exc:
            raise CharactersRAGDBError(f"Failed syncing source-managed note folders: {exc}") from exc  # noqa: TRY003
        return self.get_note_folders_for_note(note_id)

    def get_note_folders_for_note(self, note_id: str) -> list[dict[str, Any]]:
        order_clause = self._case_insensitive_order_clause("f.path")
        query = """
                SELECT f.id, f.sync_id, f.name, f.path, f.parent_id
                  FROM note_folders f
                  JOIN (
                        SELECT folder_id
                          FROM note_folder_memberships
                         WHERE note_id = ?
                        UNION
                        SELECT folder_id
                          FROM note_folder_source_memberships
                         WHERE note_id = ?
                  ) memberships
                    ON memberships.folder_id = f.id
                 WHERE f.deleted = 0
                   AND NOT EXISTS (
                         SELECT 1
                           FROM note_folder_sync_suppressions suppression
                          WHERE suppression.note_id = ?
                            AND suppression.folder_id = memberships.folder_id
                   )
                {order_clause}
                """.format_map(locals())  # nosec B608
        cursor = self.execute_query(query, (note_id, note_id, note_id))
        return [dict(row) for row in cursor.fetchall()]

    def get_note_folders_for_notes(self, note_ids: list[str]) -> dict[str, list[dict[str, Any]]]:
        if not note_ids:
            return {}
        out: dict[str, list[dict[str, Any]]] = {note_id: [] for note_id in note_ids}
        max_vars = 450
        path_order_expr = self._case_insensitive_order_expression("f.path")
        for start in range(0, len(note_ids), max_vars):
            batch = note_ids[start:start + max_vars]
            placeholders = ",".join(["?"] * len(batch))
            query = """
                    SELECT memberships.note_id AS note_id, f.id, f.sync_id, f.name, f.path, f.parent_id
                      FROM note_folders f
                      JOIN (
                            SELECT note_id, folder_id
                              FROM note_folder_memberships
                             WHERE note_id IN ({placeholders})
                            UNION
                            SELECT note_id, folder_id
                              FROM note_folder_source_memberships
                             WHERE note_id IN ({placeholders})
                      ) memberships
                        ON memberships.folder_id = f.id
                     WHERE f.deleted = 0
                       AND NOT EXISTS (
                             SELECT 1
                               FROM note_folder_sync_suppressions suppression
                              WHERE suppression.note_id = memberships.note_id
                                AND suppression.folder_id = memberships.folder_id
                       )
                     ORDER BY memberships.note_id, {path_order_expr}
                    """.format_map(locals())  # nosec B608
            cursor = self.execute_query(query, tuple(batch + batch))
            for row in cursor.fetchall():
                record = dict(row)
                current_note_id = str(record.pop("note_id"))
                out.setdefault(current_note_id, []).append(record)
        return out

    # get_notes_for_keyword is delegated to KeywordStore at module bottom.

    # ==========================
    # Flashcards & Decks (V5)
    # ==========================
    @staticmethod
    def _normalize_deck_parent_id(parent_deck_id: Any) -> int | None:
        if parent_deck_id is None:
            return None
        if isinstance(parent_deck_id, bool):
            raise InputError("parent_deck_id must be a positive integer")  # noqa: TRY003
        try:
            normalized = int(parent_deck_id)
        except (TypeError, ValueError) as exc:
            raise InputError("parent_deck_id must be a positive integer") from exc  # noqa: TRY003
        if normalized <= 0:
            raise InputError("parent_deck_id must be a positive integer")  # noqa: TRY003
        return normalized

    def _validate_deck_parent_locked(
        self,
        conn: Any,
        *,
        deck_id: int | None,
        parent_deck_id: Any,
    ) -> int | None:
        parent_id = self._normalize_deck_parent_id(parent_deck_id)
        if parent_id is None:
            return None

        target_deck_id = int(deck_id) if deck_id is not None else None
        if target_deck_id is not None and parent_id == target_deck_id:
            raise InputError("Deck cannot be its own parent")  # noqa: TRY003

        if self.backend_type == BackendType.POSTGRESQL:
            parent_lookup_query = (
                "SELECT id, parent_deck_id FROM decks WHERE id = ? AND deleted = 0 FOR UPDATE"
            )
            ancestor_lookup_query = "SELECT parent_deck_id FROM decks WHERE id = ? FOR UPDATE"
        else:
            parent_lookup_query = "SELECT id, parent_deck_id FROM decks WHERE id = ? AND deleted = 0"
            ancestor_lookup_query = "SELECT parent_deck_id FROM decks WHERE id = ?"
        parent_row = self._coerce_mapping_row(
            conn.execute(
                parent_lookup_query,
                (parent_id,),
            ).fetchone()
        )
        if not parent_row:
            raise InputError("Parent deck not found")  # noqa: TRY003

        if target_deck_id is None:
            return parent_id

        seen: set[int] = set()
        current_parent_id: int | None = parent_id
        while current_parent_id is not None:
            if current_parent_id == target_deck_id or current_parent_id in seen:
                raise InputError("Deck parent would create a cycle")  # noqa: TRY003
            seen.add(current_parent_id)
            row = self._coerce_mapping_row(
                conn.execute(
                    ancestor_lookup_query,
                    (current_parent_id,),
                ).fetchone()
            )
            if not row:
                return parent_id
            raw_parent_id = row.get("parent_deck_id")
            current_parent_id = None if raw_parent_id is None else self._normalize_deck_parent_id(raw_parent_id)

        return parent_id

    def add_deck(
        self,
        name: str,
        description: str | None = None,
        scheduler_settings: Mapping[str, Any] | str | None = None,
        *,
        scheduler_type: str = "sm2_plus",
        workspace_id: str | None = None,
        parent_deck_id: Any = ...,
        visibility: str | None = None,
        review_prompt_side: str | None = None,
    ) -> int:
        """Create a deck and return its id."""
        now = self._get_current_utc_timestamp_iso()
        scheduler_type = _coerce_scheduler_type(scheduler_type)
        normalized_visibility = None if visibility is None else _normalize_deck_visibility(visibility)
        visibility_for_insert = normalized_visibility or "private"
        normalized_prompt_side = (
            None
            if review_prompt_side is None
            else "back" if str(review_prompt_side).strip().lower() == "back" else "front"
        )
        prompt_side_for_insert = normalized_prompt_side or "front"
        scheduler_settings_json = scheduler_settings_to_json(scheduler_settings)
        try:
            with self.transaction() as conn:
                parent_for_insert = (
                    None
                    if parent_deck_id is ...
                    else self._validate_deck_parent_locked(
                        conn,
                        deck_id=None,
                        parent_deck_id=parent_deck_id,
                    )
                )
                # Undelete if a deck with the same name exists but is deleted
                deleted_row = conn.execute(
                    "SELECT id, version FROM decks WHERE name = ? AND deleted = 1",
                    (name,),
                ).fetchone()
                if deleted_row:
                    deck_id, current_version = int(deleted_row[0]), int(deleted_row[1])
                    if parent_deck_id is not ...:
                        self._validate_deck_parent_locked(
                            conn,
                            deck_id=deck_id,
                            parent_deck_id=parent_for_insert,
                        )
                    next_version = current_version + 1
                    deleted_value = False if self.backend_type == BackendType.POSTGRESQL else 0
                    set_parts = [
                        "deleted = ?",
                        "last_modified = ?",
                        "version = ?",
                        "client_id = ?",
                        "description = COALESCE(?, description)",
                        "workspace_id = ?",
                        "visibility = COALESCE(?, visibility)",
                        "review_prompt_side = COALESCE(?, review_prompt_side)",
                        "scheduler_type = COALESCE(?, scheduler_type)",
                        "scheduler_settings_json = COALESCE(?, scheduler_settings_json)",
                    ]
                    params: list[Any] = [
                        deleted_value,
                        now,
                        next_version,
                        self.client_id,
                        description,
                        workspace_id,
                        normalized_visibility,
                        normalized_prompt_side,
                        scheduler_type,
                        scheduler_settings_json,
                    ]
                    if parent_deck_id is not ...:
                        set_parts.append("parent_deck_id = ?")
                        params.append(parent_for_insert)
                    params.extend([deck_id, current_version])
                    rc = conn.execute(
                        f"UPDATE decks SET {', '.join(set_parts)} WHERE id = ? AND version = ?",  # nosec B608
                        tuple(params),
                    ).rowcount
                    if rc == 0:
                        raise ConflictError(  # noqa: TRY003
                            "Failed to undelete deck due to version mismatch",
                            entity="decks",
                            identifier=name,
                        )
                    return deck_id
                insert_sql = (
                    "INSERT INTO decks("
                    "name, description, parent_deck_id, workspace_id, visibility, review_prompt_side, scheduler_settings_json, scheduler_type, created_at, last_modified, client_id, version, deleted"
                    ") VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
                )
                params = (
                    name,
                    description,
                    parent_for_insert,
                    workspace_id,
                    visibility_for_insert,
                    prompt_side_for_insert,
                    scheduler_settings_json,
                    scheduler_type,
                    now,
                    now,
                    self.client_id,
                    1,
                    False,
                )

                if self.backend_type == BackendType.POSTGRESQL:
                    cursor = conn.execute(insert_sql + " RETURNING id", params)
                    row = cursor.fetchone()
                    deck_id = int(row["id"]) if row else None
                else:
                    cursor = conn.execute(insert_sql, params)
                    deck_id = int(cursor.lastrowid)

                if deck_id is None:
                    raise CharactersRAGDBError("Failed to determine deck ID after insert")  # noqa: TRY003
                return deck_id
        except sqlite3.IntegrityError as e:
            if "UNIQUE constraint failed: decks.name" in str(e):
                raise ConflictError("Deck name already exists", entity="decks", identifier=name) from e  # noqa: TRY003
            raise CharactersRAGDBError(f"Failed to create deck: {e}") from e  # noqa: TRY003
        except BackendDatabaseError as e:
            if self._is_unique_violation(e):
                raise ConflictError("Deck name already exists", entity="decks", identifier=name) from e  # noqa: TRY003
            raise CharactersRAGDBError(f"Failed to create deck: {e}") from e  # noqa: TRY003
        except sqlite3.Error as e:
            raise CharactersRAGDBError(f"Failed to create deck: {e}") from e  # noqa: TRY003

    def list_decks(
        self,
        limit: int = 100,
        offset: int = 0,
        include_deleted: bool = False,
        workspace_id: str | None = None,
        include_workspace_items: bool = False,
        shared_with_user_id: int | None = None,
    ) -> list[dict[str, Any]]:
        if shared_with_user_id is not None:
            query = (
                "SELECT d.id, d.name, d.description, d.parent_deck_id, d.workspace_id, d.visibility, d.review_prompt_side, "
                "d.scheduler_settings_json, d.scheduler_type, d.created_at, d.last_modified, "
                "d.deleted, d.client_id, d.version FROM decks d "
                "JOIN deck_shares ds ON ds.deck_id = d.id "
            )
            conditions = ["ds.user_id = ?"]
            params_list: list[Any] = [int(shared_with_user_id)]
            if not include_deleted:
                conditions.append("d.deleted = 0")
            if workspace_id is not None:
                if include_workspace_items:
                    conditions.append("(d.workspace_id = ? OR d.workspace_id IS NULL)")
                else:
                    conditions.append("d.workspace_id = ?")
                params_list.append(workspace_id)
            query += "WHERE " + " AND ".join(conditions) + " ORDER BY d.name LIMIT ? OFFSET ?"
            params_list.extend([limit, offset])
            try:
                cursor = self.execute_query(query, tuple(params_list))
                return [dict(row) for row in cursor.fetchall()]
            except CharactersRAGDBError:  # noqa: TRY203
                raise

        select_sql = (
            "SELECT id, name, description, parent_deck_id, workspace_id, visibility, review_prompt_side, scheduler_settings_json, scheduler_type, created_at, last_modified, "
            "deleted, client_id, version FROM decks "
        )
        if include_deleted:
            if workspace_id is not None:
                query = select_sql + "WHERE workspace_id = ? ORDER BY name LIMIT ? OFFSET ?"
                params: tuple[Any, ...] = (workspace_id, limit, offset)
            elif include_workspace_items:
                query = select_sql + "ORDER BY name LIMIT ? OFFSET ?"
                params = (limit, offset)
            else:
                query = select_sql + "WHERE workspace_id IS NULL ORDER BY name LIMIT ? OFFSET ?"
                params = (limit, offset)
        else:
            if workspace_id is not None:
                query = select_sql + "WHERE deleted = 0 AND workspace_id = ? ORDER BY name LIMIT ? OFFSET ?"
                params = (workspace_id, limit, offset)
            elif include_workspace_items:
                query = select_sql + "WHERE deleted = 0 ORDER BY name LIMIT ? OFFSET ?"
                params = (limit, offset)
            else:
                query = select_sql + "WHERE deleted = 0 AND workspace_id IS NULL ORDER BY name LIMIT ? OFFSET ?"
                params = (limit, offset)
        try:
            cursor = self.execute_query(query, params)
            return [dict(row) for row in cursor.fetchall()]
        except CharactersRAGDBError:  # noqa: TRY203
            raise

    def get_deck(self, deck_id: int) -> dict[str, Any] | None:
        """Fetch a single deck row by id."""
        query = (
            "SELECT id, name, description, parent_deck_id, workspace_id, visibility, review_prompt_side, scheduler_settings_json, scheduler_type, created_at, last_modified, deleted, client_id, version "
            "FROM decks WHERE id = ?"
        )
        try:
            cursor = self.execute_query(query, (deck_id,))
            row = cursor.fetchone()
            return dict(row) if row else None
        except CharactersRAGDBError:  # noqa: TRY203
            raise

    def get_deck_by_name(self, name: str, *, include_deleted: bool = False) -> dict[str, Any] | None:
        """Fetch one deck row by name using the repository-wide unique-name invariant."""
        if include_deleted:
            query = (
                "SELECT id, name, description, parent_deck_id, workspace_id, review_prompt_side, scheduler_settings_json, scheduler_type, created_at, "
                "last_modified, deleted, client_id, version, visibility FROM decks WHERE name = ? "
                "ORDER BY id LIMIT 1"
            )
        else:
            query = (
                "SELECT id, name, description, parent_deck_id, workspace_id, review_prompt_side, scheduler_settings_json, scheduler_type, created_at, "
                "last_modified, deleted, client_id, version, visibility FROM decks WHERE name = ? AND deleted = 0 "
                "ORDER BY id LIMIT 1"
            )
        try:
            cursor = self.execute_query(query, (name,))
            row = cursor.fetchone()
            return dict(row) if row else None
        except CharactersRAGDBError:  # noqa: TRY203
            raise

    def upsert_deck_share(
        self,
        deck_id: int,
        *,
        user_id: int,
        role: str = "viewer",
        shared_by: int,
    ) -> dict[str, Any]:
        """Create or update a per-user share record for a deck owned by this DB."""
        target_user_id = int(user_id)
        sharing_user_id = int(shared_by)
        if target_user_id <= 0:
            raise InputError("user_id must be a positive integer")  # noqa: TRY003
        if sharing_user_id <= 0:
            raise InputError("shared_by must be a positive integer")  # noqa: TRY003
        if target_user_id == sharing_user_id:
            raise InputError("Cannot share a deck with its owner")  # noqa: TRY003

        normalized_role = _normalize_deck_share_role(role)
        now = self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                deck = conn.execute(
                    "SELECT id FROM decks WHERE id = ? AND deleted = 0",
                    (int(deck_id),),
                ).fetchone()
                if deck is None:
                    raise ConflictError("Deck not found", entity="decks", identifier=deck_id)  # noqa: TRY003

                insert_sql = """
                    INSERT INTO deck_shares(
                        deck_id, user_id, role, shared_by, shared_at, last_modified, client_id, version
                    ) VALUES(?, ?, ?, ?, ?, ?, ?, 1)
                    ON CONFLICT(deck_id, user_id) DO UPDATE SET
                        role = excluded.role,
                        shared_by = excluded.shared_by,
                        last_modified = excluded.last_modified,
                        client_id = excluded.client_id,
                        version = deck_shares.version + 1
                """
                params = (
                    int(deck_id),
                    target_user_id,
                    normalized_role,
                    sharing_user_id,
                    now,
                    now,
                    self.client_id,
                )
                if self.backend_type == BackendType.POSTGRESQL:
                    row = conn.execute(
                        insert_sql
                        + " RETURNING deck_id, user_id, role, shared_by, shared_at, last_modified, client_id, version",
                        params,
                    ).fetchone()
                    return dict(row)

                conn.execute(insert_sql, params)
                row = conn.execute(
                    """
                    SELECT deck_id, user_id, role, shared_by, shared_at, last_modified, client_id, version
                      FROM deck_shares
                     WHERE deck_id = ? AND user_id = ?
                    """,
                    (int(deck_id), target_user_id),
                ).fetchone()
                if row is None:
                    raise CharactersRAGDBError("Failed to read deck share after upsert")  # noqa: TRY003
                return dict(row)
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to share deck: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to share deck: {exc}") from exc  # noqa: TRY003

    def list_deck_shares(self, deck_id: int) -> list[dict[str, Any]]:
        """List all per-user share records for a deck owned by this DB."""
        try:
            cursor = self.execute_query(
                """
                SELECT deck_id, user_id, role, shared_by, shared_at, last_modified, client_id, version
                  FROM deck_shares
                 WHERE deck_id = ?
                 ORDER BY user_id
                """,
                (int(deck_id),),
            )
            return [dict(row) for row in cursor.fetchall()]
        except CharactersRAGDBError:  # noqa: TRY203
            raise

    def get_deck_share(self, deck_id: int, *, user_id: int) -> dict[str, Any] | None:
        """Fetch one per-user share record for a deck owned by this DB."""
        try:
            cursor = self.execute_query(
                """
                SELECT deck_id, user_id, role, shared_by, shared_at, last_modified, client_id, version
                  FROM deck_shares
                 WHERE deck_id = ? AND user_id = ?
                """,
                (int(deck_id), int(user_id)),
            )
            row = cursor.fetchone()
            return dict(row) if row else None
        except CharactersRAGDBError:  # noqa: TRY203
            raise

    def delete_deck_share(self, deck_id: int, *, user_id: int) -> bool:
        """Remove one per-user share record from a deck owned by this DB."""
        try:
            with self.transaction() as conn:
                rowcount = conn.execute(
                    "DELETE FROM deck_shares WHERE deck_id = ? AND user_id = ?",
                    (int(deck_id), int(user_id)),
                ).rowcount
                return rowcount > 0
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to remove deck share: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to remove deck share: {exc}") from exc  # noqa: TRY003

    def update_deck(
        self,
        deck_id: int,
        *,
        name: str | None = None,
        description: str | None = None,
        review_prompt_side: str | None = None,
        visibility: str | None = None,
        scheduler_settings: Mapping[str, Any] | str | None = None,
        scheduler_type: str | None = None,
        workspace_id: Any = ...,
        parent_deck_id: Any = ...,
        expected_version: int | None = None,
    ) -> bool:
        """Update mutable deck fields with optimistic locking."""
        set_parts: list[str] = []
        params: list[Any] = []
        if name is not None:
            set_parts.append("name = ?")
            params.append(name)
        if description is not None:
            set_parts.append("description = ?")
            params.append(description)
        if review_prompt_side is not None:
            set_parts.append("review_prompt_side = ?")
            params.append("back" if str(review_prompt_side).strip().lower() == "back" else "front")
        if visibility is not None:
            set_parts.append("visibility = ?")
            params.append(_normalize_deck_visibility(visibility))
        if scheduler_settings is not None:
            set_parts.append("scheduler_settings_json = ?")
            params.append(scheduler_settings_to_json(scheduler_settings))
        if scheduler_type is not None:
            set_parts.append("scheduler_type = ?")
            params.append(_coerce_scheduler_type(scheduler_type))
        if workspace_id is not ...:
            set_parts.append("workspace_id = ?")
            params.append(workspace_id)
        if parent_deck_id is not ...:
            set_parts.append("parent_deck_id = ?")
            params.append(self._normalize_deck_parent_id(parent_deck_id))
        if not set_parts:
            if expected_version is None:
                return True
            deck = self.get_deck(deck_id)
            if not deck:
                raise ConflictError("Deck not found", entity="decks", identifier=deck_id)  # noqa: TRY003
            if int(deck["version"]) != expected_version:
                raise ConflictError("Version mismatch updating deck", entity="decks", identifier=deck_id)  # noqa: TRY003
            return True

        now = self._get_current_utc_timestamp_iso()
        set_parts.extend(["last_modified = ?", "version = version + 1", "client_id = ?"])
        params.extend([now, self.client_id])

        try:
            with self.transaction() as conn:
                row = conn.execute(
                    "SELECT version FROM decks WHERE id = ? AND deleted = 0",
                    (deck_id,),
                ).fetchone()
                if not row:
                    raise ConflictError("Deck not found", entity="decks", identifier=deck_id)  # noqa: TRY003
                current_version = int(row[0])
                if expected_version is not None and current_version != expected_version:
                    raise ConflictError("Version mismatch updating deck", entity="decks", identifier=deck_id)  # noqa: TRY003
                if parent_deck_id is not ...:
                    params[set_parts.index("parent_deck_id = ?")] = self._validate_deck_parent_locked(
                        conn,
                        deck_id=int(deck_id),
                        parent_deck_id=parent_deck_id,
                    )

                params_final = params + [deck_id]
                query = f"UPDATE decks SET {', '.join(set_parts)} WHERE id = ? AND deleted = 0"  # nosec B608
                rc = conn.execute(query, tuple(params_final)).rowcount
                return rc > 0
        except sqlite3.IntegrityError as exc:
            if "UNIQUE constraint failed: decks.name" in str(exc):
                raise ConflictError("Deck name already exists", entity="decks", identifier=name or deck_id) from exc  # noqa: TRY003
            raise CharactersRAGDBError(f"Failed to update deck: {exc}") from exc  # noqa: TRY003
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to update deck: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            if self._is_unique_violation(exc):
                raise ConflictError("Deck name already exists", entity="decks", identifier=name or deck_id) from exc  # noqa: TRY003
            raise CharactersRAGDBError(f"Failed to update deck: {exc}") from exc  # noqa: TRY003

    def _flashcard_template_default_placeholders(self, raw_definitions: Any) -> list[dict[str, Any]]:
        if raw_definitions in (None, ""):
            return []
        if not isinstance(raw_definitions, list):
            raise InputError("placeholder_definitions must be a list")  # noqa: TRY003
        normalized: list[dict[str, Any]] = []
        seen_keys: set[str] = set()
        for raw_definition in raw_definitions:
            if not isinstance(raw_definition, Mapping):
                raise InputError("placeholder_definitions items must be objects")  # noqa: TRY003
            key = str(raw_definition.get("key") or "").strip()
            label = str(raw_definition.get("label") or "").strip()
            help_text = self._normalize_nullable_text(raw_definition.get("help_text"))
            default_value = self._normalize_nullable_text(raw_definition.get("default_value"))
            required = bool(raw_definition.get("required", False))
            targets_raw = raw_definition.get("targets") or []
            if not key:
                raise InputError("Placeholder definitions require a non-empty key")  # noqa: TRY003
            if key in seen_keys:
                raise InputError(f"Duplicate placeholder definition: {key}")  # noqa: TRY003
            if not label:
                raise InputError(f"Placeholder definition '{key}' requires a non-empty label")  # noqa: TRY003
            if not isinstance(targets_raw, list) or not targets_raw:
                raise InputError(f"Placeholder definition '{key}' requires at least one target")  # noqa: TRY003
            targets: list[str] = []
            for target in targets_raw:
                target_name = str(target or "").strip()
                if target_name not in _FLASHCARD_TEMPLATE_FIELD_NAMES:
                    raise InputError(
                        f"Placeholder definition '{key}' has unsupported target '{target_name}'"
                    )  # noqa: TRY003
                if target_name not in targets:
                    targets.append(target_name)
            seen_keys.add(key)
            normalized.append(
                {
                    "key": key,
                    "label": label,
                    "help_text": help_text,
                    "default_value": default_value,
                    "required": required,
                    "targets": targets,
                }
            )
        return normalized

    def _flashcard_template_tokens(self, text: Any) -> set[str]:
        raw = str(text or "")
        return {match.group(1) for match in _FLASHCARD_TEMPLATE_TOKEN_RE.finditer(raw)}

    def _flashcard_template_deleted_value(self, deleted: bool) -> bool | int:
        if self.backend_type == BackendType.POSTGRESQL:
            return bool(deleted)
        return 1 if deleted else 0

    def _validate_flashcard_template_contract(
        self,
        *,
        model_type: str,
        front_template: Any,
        back_template: Any,
        notes_template: Any,
        extra_template: Any,
        placeholder_definitions: Any,
    ) -> tuple[str, str, str | None, str | None, str | None, list[dict[str, Any]]]:
        normalized_model_type = str(model_type or "").strip().lower()
        if normalized_model_type not in ("basic", "basic_reverse", "cloze"):
            raise InputError("model_type must be one of 'basic', 'basic_reverse', or 'cloze'")  # noqa: TRY003

        normalized_front = str(front_template or "").strip()
        if not normalized_front:
            raise InputError("front_template is required")  # noqa: TRY003

        normalized_back = self._normalize_nullable_text(back_template)
        if normalized_model_type in ("basic", "basic_reverse") and not normalized_back:
            raise InputError("back_template is required for basic and basic_reverse templates")  # noqa: TRY003

        normalized_notes = self._normalize_nullable_text(notes_template)
        normalized_extra = self._normalize_nullable_text(extra_template)
        normalized_definitions = self._flashcard_template_default_placeholders(placeholder_definitions)
        definitions_by_key = {definition["key"]: definition for definition in normalized_definitions}

        fields_by_name = {
            "front_template": normalized_front,
            "back_template": normalized_back or "",
            "notes_template": normalized_notes or "",
            "extra_template": normalized_extra or "",
        }
        for field_name, text in fields_by_name.items():
            tokens = self._flashcard_template_tokens(text)
            if not tokens:
                continue
            missing = sorted(token for token in tokens if token not in definitions_by_key)
            if missing:
                raise InputError(
                    f"{field_name} references undefined placeholder(s): {', '.join(missing)}"
                )  # noqa: TRY003

        for definition in normalized_definitions:
            targets = definition["targets"]
            if not any(definition["key"] in self._flashcard_template_tokens(fields_by_name[target]) for target in targets):
                raise InputError(
                    f"Placeholder definition '{definition['key']}' must be referenced in at least one targeted field"
                )  # noqa: TRY003

        return (
            normalized_model_type,
            normalized_front,
            normalized_back,
            normalized_notes,
            normalized_extra,
            normalized_definitions,
        )

    def _serialize_flashcard_template_row(self, row: Mapping[str, Any]) -> dict[str, Any]:
        item = dict(row)
        raw_definitions = item.get("placeholder_definitions_json")
        if isinstance(raw_definitions, str):
            try:
                parsed = json.loads(raw_definitions)
            except json.JSONDecodeError as exc:
                logger.warning(
                    "_serialize_flashcard_template_row failed to parse placeholder_definitions_json "
                    "for flashcard template {}: {}. Raw value: {}",
                    item.get("id"),
                    exc,
                    raw_definitions,
                )
                parsed = []
        else:
            parsed = raw_definitions
        if not isinstance(parsed, list):
            parsed = []
        item["placeholder_definitions"] = self._flashcard_template_default_placeholders(parsed)
        item.pop("placeholder_definitions_json", None)
        return item

    def add_flashcard_template(
        self,
        *,
        name: str,
        model_type: str,
        front_template: str,
        back_template: str | None = None,
        notes_template: str | None = None,
        extra_template: str | None = None,
        placeholder_definitions: list[dict[str, Any]] | None = None,
    ) -> int:
        """Create or undelete a flashcard template and return its integer id."""
        template_name = str(name or "").strip()
        if not template_name:
            raise InputError("name is required")  # noqa: TRY003

        (
            normalized_model_type,
            normalized_front,
            normalized_back,
            normalized_notes,
            normalized_extra,
            normalized_definitions,
        ) = self._validate_flashcard_template_contract(
            model_type=model_type,
            front_template=front_template,
            back_template=back_template,
            notes_template=notes_template,
            extra_template=extra_template,
            placeholder_definitions=placeholder_definitions,
        )

        now = self._get_current_utc_timestamp_iso()
        definitions_json = json.dumps(normalized_definitions)
        deleted_value = self._flashcard_template_deleted_value(True)
        try:
            with self.transaction() as conn:
                deleted_row = conn.execute(
                    """
                    SELECT id, version
                      FROM flashcard_templates
                     WHERE name = ? AND deleted = ?
                     ORDER BY id DESC
                     LIMIT 1
                    """,
                    (template_name, deleted_value),
                ).fetchone()
                if deleted_row:
                    template_id = int(deleted_row[0])
                    current_version = int(deleted_row[1])
                    next_version = current_version + 1
                    rc = conn.execute(
                        """
                        UPDATE flashcard_templates
                           SET deleted = ?,
                               name = ?,
                               model_type = ?,
                               front_template = ?,
                               back_template = ?,
                               notes_template = ?,
                               extra_template = ?,
                               placeholder_definitions_json = ?,
                               last_modified = ?,
                               version = ?,
                               client_id = ?
                         WHERE id = ? AND version = ?
                        """,
                        (
                            self._flashcard_template_deleted_value(False),
                            template_name,
                            normalized_model_type,
                            normalized_front,
                            normalized_back,
                            normalized_notes,
                            normalized_extra,
                            definitions_json,
                            now,
                            next_version,
                            self.client_id,
                            template_id,
                            current_version,
                        ),
                    ).rowcount
                    if rc == 0:
                        raise ConflictError(
                            "Failed to undelete flashcard template due to version mismatch",
                            entity="flashcard_templates",
                            identifier=template_name,
                        )  # noqa: TRY003
                    return template_id

                insert_sql = """
                    INSERT INTO flashcard_templates(
                        name, model_type, front_template, back_template, notes_template, extra_template,
                        placeholder_definitions_json, created_at, last_modified, deleted, client_id, version
                    ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """
                params = (
                    template_name,
                    normalized_model_type,
                    normalized_front,
                    normalized_back,
                    normalized_notes,
                    normalized_extra,
                    definitions_json,
                    now,
                    now,
                    self._flashcard_template_deleted_value(False),
                    self.client_id,
                    1,
                )
                if self.backend_type == BackendType.POSTGRESQL:
                    cursor = conn.execute(insert_sql + " RETURNING id", params)
                    row = cursor.fetchone()
                    template_id = int(row["id"]) if row else None
                else:
                    cursor = conn.execute(insert_sql, params)
                    template_id = int(cursor.lastrowid)
                if template_id is None:
                    raise CharactersRAGDBError("Failed to determine flashcard template ID after insert")  # noqa: TRY003
                return template_id
        except sqlite3.IntegrityError as exc:
            if "UNIQUE constraint failed: flashcard_templates.name" in str(exc):
                raise ConflictError(
                    "Flashcard template name already exists",
                    entity="flashcard_templates",
                    identifier=template_name,
                ) from exc  # noqa: TRY003
            raise CharactersRAGDBError(f"Failed to create flashcard template: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            if self._is_unique_violation(exc):
                raise ConflictError(
                    "Flashcard template name already exists",
                    entity="flashcard_templates",
                    identifier=template_name,
                ) from exc  # noqa: TRY003
            raise CharactersRAGDBError(f"Failed to create flashcard template: {exc}") from exc  # noqa: TRY003
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to create flashcard template: {exc}") from exc  # noqa: TRY003

    def count_flashcard_templates(self) -> int:
        cursor = self.execute_query(
            "SELECT COUNT(*) AS cnt FROM flashcard_templates WHERE deleted = ?",
            (self._flashcard_template_deleted_value(False),),
        )
        row = cursor.fetchone()
        return int(row["cnt"]) if row else 0

    def list_flashcard_templates(self, limit: int = 100, offset: int = 0) -> list[dict[str, Any]]:
        query = (
            "SELECT id, name, model_type, front_template, back_template, notes_template, extra_template, "
            "placeholder_definitions_json, created_at, last_modified, deleted, client_id, version "
            "FROM flashcard_templates WHERE deleted = ? ORDER BY name ASC LIMIT ? OFFSET ?"
        )
        cursor = self.execute_query(
            query,
            (self._flashcard_template_deleted_value(False), limit, offset),
        )
        return [self._serialize_flashcard_template_row(dict(row)) for row in cursor.fetchall()]

    def get_flashcard_template(self, template_id: int, *, include_deleted: bool = False) -> dict[str, Any] | None:
        query = (
            "SELECT id, name, model_type, front_template, back_template, notes_template, extra_template, "
            "placeholder_definitions_json, created_at, last_modified, deleted, client_id, version "
            "FROM flashcard_templates WHERE id = ?"
        )
        params: list[Any] = [template_id]
        if not include_deleted:
            query += " AND deleted = ?"
            params.append(self._flashcard_template_deleted_value(False))
        cursor = self.execute_query(query, tuple(params))
        row = cursor.fetchone()
        return self._serialize_flashcard_template_row(dict(row)) if row else None

    def update_flashcard_template(
        self,
        template_id: int,
        updates: dict[str, Any],
        expected_version: int | None = None,
    ) -> bool:
        current = self.get_flashcard_template(template_id)
        if not current:
            return False
        if not updates:
            if expected_version is not None and int(current["version"]) != expected_version:
                raise ConflictError(
                    "Version mismatch updating flashcard template",
                    entity="flashcard_templates",
                    identifier=template_id,
                )  # noqa: TRY003
            return True

        merged = {
            "name": current["name"],
            "model_type": current["model_type"],
            "front_template": current["front_template"],
            "back_template": current.get("back_template"),
            "notes_template": current.get("notes_template"),
            "extra_template": current.get("extra_template"),
            "placeholder_definitions": current.get("placeholder_definitions") or [],
        }
        for key in ("name", "model_type", "front_template", "back_template", "notes_template", "extra_template", "placeholder_definitions"):
            if key in updates:
                merged[key] = updates[key]

        (
            normalized_model_type,
            normalized_front,
            normalized_back,
            normalized_notes,
            normalized_extra,
            normalized_definitions,
        ) = self._validate_flashcard_template_contract(
            model_type=merged["model_type"],
            front_template=merged["front_template"],
            back_template=merged["back_template"],
            notes_template=merged["notes_template"],
            extra_template=merged["extra_template"],
            placeholder_definitions=merged["placeholder_definitions"],
        )
        template_name = str(merged["name"] or "").strip()
        if not template_name:
            raise InputError("name is required")  # noqa: TRY003

        now = self._get_current_utc_timestamp_iso()
        definitions_json = json.dumps(normalized_definitions)
        set_parts = [
            "name = ?",
            "model_type = ?",
            "front_template = ?",
            "back_template = ?",
            "notes_template = ?",
            "extra_template = ?",
            "placeholder_definitions_json = ?",
            "last_modified = ?",
            "version = version + 1",
            "client_id = ?",
        ]
        params: list[Any] = [
            template_name,
            normalized_model_type,
            normalized_front,
            normalized_back,
            normalized_notes,
            normalized_extra,
            definitions_json,
            now,
            self.client_id,
        ]
        active_value = self._flashcard_template_deleted_value(False)
        try:
            with self.transaction() as conn:
                row = conn.execute(
                    "SELECT version FROM flashcard_templates WHERE id = ? AND deleted = ?",
                    (template_id, active_value),
                ).fetchone()
                if not row:
                    return False
                current_version = int(row[0])
                if expected_version is not None and current_version != expected_version:
                    raise ConflictError(
                        "Version mismatch updating flashcard template",
                        entity="flashcard_templates",
                        identifier=template_id,
                    )  # noqa: TRY003

                if expected_version is not None:
                    params.extend([template_id, expected_version, active_value])
                    query = f"UPDATE flashcard_templates SET {', '.join(set_parts)} WHERE id = ? AND version = ? AND deleted = ?"  # nosec B608
                else:
                    params.extend([template_id, active_value])
                    query = f"UPDATE flashcard_templates SET {', '.join(set_parts)} WHERE id = ? AND deleted = ?"  # nosec B608
                rc = conn.execute(query, tuple(params)).rowcount
                return rc > 0
        except sqlite3.IntegrityError as exc:
            if "UNIQUE constraint failed: flashcard_templates.name" in str(exc):
                raise ConflictError(
                    "Flashcard template name already exists",
                    entity="flashcard_templates",
                    identifier=template_name,
                ) from exc  # noqa: TRY003
            raise CharactersRAGDBError(f"Failed to update flashcard template: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            if self._is_unique_violation(exc):
                raise ConflictError(
                    "Flashcard template name already exists",
                    entity="flashcard_templates",
                    identifier=template_name,
                ) from exc  # noqa: TRY003
            raise CharactersRAGDBError(f"Failed to update flashcard template: {exc}") from exc  # noqa: TRY003
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to update flashcard template: {exc}") from exc  # noqa: TRY003

    def soft_delete_flashcard_template(self, template_id: int, expected_version: int) -> bool:
        now = self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                row = conn.execute(
                    "SELECT version, deleted FROM flashcard_templates WHERE id = ?",
                    (template_id,),
                ).fetchone()
                if not row:
                    return False
                current_version = int(row[0])
                deleted = bool(row[1])
                if deleted:
                    return False
                if current_version != expected_version:
                    raise ConflictError(
                        "Version mismatch deleting flashcard template",
                        entity="flashcard_templates",
                        identifier=template_id,
                    )  # noqa: TRY003
                rc = conn.execute(
                    """
                    UPDATE flashcard_templates
                       SET deleted = ?,
                           last_modified = ?,
                           version = ?,
                           client_id = ?
                     WHERE id = ? AND version = ? AND deleted = ?
                    """,
                    (
                        self._flashcard_template_deleted_value(True),
                        now,
                        expected_version + 1,
                        self.client_id,
                        template_id,
                        expected_version,
                        self._flashcard_template_deleted_value(False),
                    ),
                ).rowcount
                if rc == 0:
                    raise ConflictError(
                        "Version mismatch deleting flashcard template",
                        entity="flashcard_templates",
                        identifier=template_id,
                    )  # noqa: TRY003
                return rc > 0
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to delete flashcard template: {exc}") from exc  # noqa: TRY003
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to delete flashcard template: {exc}") from exc  # noqa: TRY003

    def _get_flashcard_id_from_uuid(self, conn: sqlite3.Connection, card_uuid: str) -> int | None:
        row = conn.execute("SELECT id FROM flashcards WHERE uuid = ? AND deleted = 0", (card_uuid,)).fetchone()
        return int(row[0]) if row else None

    def add_flashcard(self, card_data: dict[str, Any]) -> str:
        """
        Create a flashcard. card_data keys: deck_id (optional), front, back, notes?, is_cloze?, tags_json?,
        source_ref_type?, source_ref_id?
        Returns uuid.
        """
        now = self._get_current_utc_timestamp_iso()
        uuid_val = self._generate_uuid()
        deck_id = card_data.get('deck_id')
        front = card_data['front']
        back = card_data['back']
        notes = card_data.get('notes')
        extra = card_data.get('extra')
        front_search, back_search, notes_search = self._build_flashcard_search_shadow_fields(
            front=front,
            back=back,
            notes=notes,
        )
        is_cloze = 1 if card_data.get('is_cloze') else 0
        tags_json = card_data.get('tags_json')
        source_ref_type = card_data.get('source_ref_type', 'manual')
        source_ref_id = card_data.get('source_ref_id')
        conversation_id = self._normalize_nullable_text(card_data.get('conversation_id'))
        message_id = self._normalize_nullable_text(card_data.get('message_id'))
        ef = max(1.3, float(card_data.get('ef', 2.5) or 2.5))
        interval_days = max(0, int(card_data.get('interval_days', 0) or 0))
        repetitions = max(0, int(card_data.get('repetitions', 0) or 0))
        lapses = max(0, int(card_data.get('lapses', 0) or 0))
        due_at = self._normalize_nullable_text(card_data.get('due_at'))
        last_reviewed_at = self._normalize_nullable_text(card_data.get('last_reviewed_at'))
        queue_state = coerce_queue_state(
            {
                "queue_state": card_data.get("queue_state"),
                "last_reviewed_at": last_reviewed_at,
                "repetitions": repetitions,
                "lapses": lapses,
                "interval_days": interval_days,
                "due_at": due_at,
            }
        )
        step_index = card_data.get("step_index")
        step_index = int(step_index) if step_index is not None else None
        suspended_reason = self._normalize_nullable_text(card_data.get("suspended_reason"))
        if queue_state != "suspended":
            suspended_reason = None
        if due_at is None and queue_state in ("learning", "relearning", "review"):
            due_at = now
        model_type = card_data.get('model_type')
        reverse_flag = card_data.get('reverse')
        if not model_type:
            model_type = 'cloze' if is_cloze else 'basic_reverse' if reverse_flag else 'basic'
        if model_type not in ('basic', 'basic_reverse', 'cloze'):
            raise InputError("Invalid model_type; must be 'basic','basic_reverse','cloze'")  # noqa: TRY003
        # If reverse is not explicitly set, derive from model_type
        if reverse_flag is None:
            reverse_flag = 1 if model_type == 'basic_reverse' else 0
        try:
            with self.transaction() as conn:
                insert_sql = (
                    """
                    INSERT INTO flashcards(
                        uuid, deck_id, front, back, notes, extra, front_search, back_search, notes_search, is_cloze,
                        tags_json, source_ref_type, source_ref_id, conversation_id, message_id, ef, interval_days,
                        repetitions, lapses, due_at, last_reviewed_at, created_at, last_modified,
                        deleted, client_id, version, model_type, reverse, queue_state, step_index, suspended_reason
                    )
                    VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """
                )

                params = (
                    uuid_val,
                    deck_id,
                    front,
                    back,
                    notes,
                    extra,
                    front_search,
                    back_search,
                    notes_search,
                    bool(is_cloze),
                    tags_json,
                    source_ref_type,
                    source_ref_id,
                    conversation_id,
                    message_id,
                    ef,
                    interval_days,
                    repetitions,
                    lapses,
                    due_at,
                    last_reviewed_at,
                    now,
                    now,
                    False,
                    self.client_id,
                    1,
                    model_type,
                    bool(reverse_flag),
                    queue_state,
                    step_index,
                    suspended_reason,
                )

                conn.execute(insert_sql, params)
                return uuid_val
        except sqlite3.Error as e:
            raise CharactersRAGDBError(f"Failed to add flashcard: {e}") from e  # noqa: TRY003
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to add flashcard: {exc}") from exc  # noqa: TRY003

    def add_flashcards_bulk(self, cards: list[dict[str, Any]]) -> list[str]:
        """
        Bulk create flashcards; returns list of uuids in the same order.

        Supports newer fields: extra, model_type, reverse. If model_type is not
        provided, it will be inferred from is_cloze/reverse similar to add_flashcard().
        """
        uuids: list[str] = []
        try:
            with self.transaction() as _:
                insert_sql = (
                    """
                    INSERT INTO flashcards(
                        uuid, deck_id, front, back, notes, extra, front_search, back_search, notes_search, is_cloze,
                        tags_json, source_ref_type, source_ref_id, conversation_id, message_id, ef, interval_days,
                        repetitions, lapses, due_at, last_reviewed_at, created_at, last_modified,
                        deleted, client_id, version, model_type, reverse, queue_state, step_index, suspended_reason
                    )
                    VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """
                )

                params_list: list[tuple] = []
                for card_data in cards:
                    uuid_val = self._generate_uuid()
                    uuids.append(uuid_val)
                    now = self._get_current_utc_timestamp_iso()

                    deck_id = card_data.get('deck_id')
                    front = card_data['front']
                    back = card_data['back']
                    notes = card_data.get('notes')
                    extra = card_data.get('extra')
                    front_search, back_search, notes_search = self._build_flashcard_search_shadow_fields(
                        front=front,
                        back=back,
                        notes=notes,
                    )
                    is_cloze = bool(card_data.get('is_cloze'))
                    tags_json = card_data.get('tags_json')
                    source_ref_type = card_data.get('source_ref_type', 'manual')
                    source_ref_id = card_data.get('source_ref_id')
                    conversation_id = self._normalize_nullable_text(card_data.get('conversation_id'))
                    message_id = self._normalize_nullable_text(card_data.get('message_id'))
                    ef = max(1.3, float(card_data.get('ef', 2.5) or 2.5))
                    interval_days = max(0, int(card_data.get('interval_days', 0) or 0))
                    repetitions = max(0, int(card_data.get('repetitions', 0) or 0))
                    lapses = max(0, int(card_data.get('lapses', 0) or 0))
                    due_at = self._normalize_nullable_text(card_data.get('due_at'))
                    last_reviewed_at = self._normalize_nullable_text(card_data.get('last_reviewed_at'))
                    queue_state = coerce_queue_state(
                        {
                            "queue_state": card_data.get("queue_state"),
                            "last_reviewed_at": last_reviewed_at,
                            "repetitions": repetitions,
                            "lapses": lapses,
                            "interval_days": interval_days,
                            "due_at": due_at,
                        }
                    )
                    step_index = card_data.get("step_index")
                    step_index = int(step_index) if step_index is not None else None
                    suspended_reason = self._normalize_nullable_text(card_data.get("suspended_reason"))
                    if queue_state != "suspended":
                        suspended_reason = None
                    if due_at is None and queue_state in ("learning", "relearning", "review"):
                        due_at = now
                    model_type = card_data.get('model_type')
                    reverse_flag = card_data.get('reverse')
                    if not model_type:
                        model_type = 'cloze' if is_cloze else 'basic_reverse' if reverse_flag else 'basic'
                    if model_type not in ('basic', 'basic_reverse', 'cloze'):
                        raise InputError("Invalid model_type; must be 'basic','basic_reverse','cloze'")  # noqa: TRY003
                    if reverse_flag is None:
                        reverse_flag = (model_type == 'basic_reverse')

                    params_list.append(
                        (
                            uuid_val,
                            deck_id,
                            front,
                            back,
                            notes,
                            extra,
                            front_search,
                            back_search,
                            notes_search,
                            is_cloze,
                            tags_json,
                            source_ref_type,
                            source_ref_id,
                            conversation_id,
                            message_id,
                            ef,
                            interval_days,
                            repetitions,
                            lapses,
                            due_at,
                            last_reviewed_at,
                            now,
                            now,
                            False,
                            self.client_id,
                            1,
                            model_type,
                            bool(reverse_flag),
                            queue_state,
                            step_index,
                            suspended_reason,
                        )
                    )

                # Batch insert for efficiency (supports both SQLite and Postgres backends)
                self.execute_many(insert_sql, params_list, commit=False)
            return uuids  # noqa: TRY300
        except KeyError as e:
            raise InputError(f"Missing required field in bulk flashcard: {e}") from e  # noqa: TRY003
        except sqlite3.Error as e:
            raise CharactersRAGDBError(f"Failed to add flashcards in bulk: {e}") from e  # noqa: TRY003
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to add flashcards in bulk: {exc}") from exc  # noqa: TRY003

    def _flashcard_visibility_filter(
        self,
        *,
        deck_id: int | None = None,
        workspace_id: str | None = None,
        include_workspace_items: bool = False,
        deck_alias: str = "d",
        deck_id_column: str = "f.deck_id",
    ) -> tuple[str, tuple[Any, ...], bool]:
        """Return the visibility predicate and whether a deck join is required."""
        if workspace_id is not None:
            if deck_id is not None:
                return f"{deck_id_column} = ? AND {deck_alias}.workspace_id = ?", (deck_id, workspace_id), True
            return f"{deck_alias}.workspace_id = ?", (workspace_id,), True
        if deck_id is not None:
            return f"{deck_id_column} = ?", (deck_id,), False
        if not include_workspace_items:
            return f"{deck_alias}.workspace_id IS NULL", (), True
        return "", (), False

    @staticmethod
    def _normalize_flashcard_sqlite_query(q: str) -> str:
        return FTSQueryTranslator.normalize_query(
            q,
            'sqlite',
            sqlite_column_aliases=_FLASHCARD_SQLITE_FTS_COLUMN_ALIASES,
        )

    def list_flashcards(self,
                        deck_id: int | None = None,
                        workspace_id: str | None = None,
                        include_workspace_items: bool = False,
                        tag: str | None = None,
                        due_status: str = 'all',
                        q: str | None = None,
                        include_deleted: bool = False,
                        limit: int = 100,
                        offset: int = 0,
                        order_by: str = 'due_at') -> list[dict[str, Any]]:
        """List flashcards with filters. due_status in {'new','learning','due','all'}."""
        where_clauses = ["1=1"]
        params: list[Any] = []
        keyword_table = self._map_table_for_backend("keywords")
        if not include_deleted:
            if self.backend_type == BackendType.POSTGRESQL:
                where_clauses.append("f.deleted = FALSE")
            else:
                where_clauses.append("f.deleted = 0")
        visibility_clause, visibility_params, _ = self._flashcard_visibility_filter(
            deck_id=deck_id,
            workspace_id=workspace_id,
            include_workspace_items=include_workspace_items,
        )
        if visibility_clause:
            where_clauses.append(visibility_clause)
            params.extend(visibility_params)
        # due filter
        now_iso = self._get_current_utc_timestamp_iso()
        if due_status == 'new':
            where_clauses.append("f.queue_state = ?")
            params.append("new")
        elif due_status == 'learning':
            where_clauses.append("f.queue_state IN ('learning', 'relearning') AND f.due_at IS NOT NULL AND f.due_at <= ?")
            params.append(now_iso)
        elif due_status == 'due':
            where_clauses.append("f.queue_state = 'review' AND f.due_at IS NOT NULL AND f.due_at <= ?")
            params.append(now_iso)

        # tag filter (single tag)
        join_tag = ""
        if tag:
            join_tag = f"JOIN flashcard_keywords fk ON fk.card_id = f.id JOIN {keyword_table} kw ON kw.id = fk.keyword_id"
            where_clauses.append("kw.keyword = ?")
            params.append(tag)

        # FTS filter
        fts_filter = ""
        if q:
            if self.backend_type == BackendType.POSTGRESQL:
                tsquery = FTSQueryTranslator.normalize_query(q, 'postgresql')
                if not tsquery:
                    logger.debug("Flashcard query normalized to empty tsquery for input '{}'", q)
                    return []
                fts_filter = "AND f.flashcards_fts_tsv @@ to_tsquery('english', ?)"
                params.append(tsquery)
            else:
                # Normalize query for SQLite FTS5 (quotes/operators)
                norm_q = self._normalize_flashcard_sqlite_query(q)
                if not norm_q:
                    logger.debug("Flashcard query normalized to empty sqlite tsquery for input '{}'", q)
                    return []
                fts_filter = "AND f.rowid IN (SELECT rowid FROM flashcards_fts WHERE flashcards_fts MATCH ?)"
                params.append(norm_q)

        # order by
        order_sql = "ORDER BY f.due_at, f.created_at DESC" if order_by == 'due_at' else "ORDER BY f.created_at DESC"

        where_sql = " AND ".join(where_clauses)
        query = """
            SELECT f.uuid, f.deck_id, d.name AS deck_name, d.workspace_id AS workspace_id, f.front, f.back, f.notes, f.extra, f.is_cloze, f.tags_json,
                   f.source_ref_type, f.source_ref_id, f.conversation_id, f.message_id,
                   f.ef, f.interval_days, f.repetitions, f.lapses, f.due_at, f.last_reviewed_at,
                   f.queue_state, f.step_index, f.suspended_reason,
                   f.created_at, f.last_modified, f.deleted, f.client_id, f.version, f.model_type, f.reverse
            FROM flashcards f
            LEFT JOIN decks d ON d.id = f.deck_id
            {join_tag}
            WHERE {where_sql} {fts_filter}
            {order_sql}
            LIMIT ? OFFSET ?
        """.format_map(locals())  # nosec B608
        params.extend([limit, offset])
        try:
            cursor = self.execute_query(query, tuple(params))
            return [dict(row) for row in cursor.fetchall()]
        except CharactersRAGDBError:  # noqa: TRY203
            raise

    def count_flashcards(self,
                         deck_id: int | None = None,
                         workspace_id: str | None = None,
                         include_workspace_items: bool = False,
                         tag: str | None = None,
                         due_status: str = 'all',
                         q: str | None = None,
                         include_deleted: bool = False) -> int:
        """Count flashcards matching filters. Mirrors list_flashcards filters."""
        where_clauses = ["1=1"]
        params: list[Any] = []
        keyword_table = self._map_table_for_backend("keywords")
        if not include_deleted:
            if self.backend_type == BackendType.POSTGRESQL:
                where_clauses.append("f.deleted = FALSE")
            else:
                where_clauses.append("f.deleted = 0")
        visibility_clause, visibility_params, needs_deck_join = self._flashcard_visibility_filter(
            deck_id=deck_id,
            workspace_id=workspace_id,
            include_workspace_items=include_workspace_items,
        )
        visibility_join = " LEFT JOIN decks d ON d.id = f.deck_id" if needs_deck_join else ""
        if visibility_clause:
            where_clauses.append(visibility_clause)
            params.extend(visibility_params)

        now_iso = self._get_current_utc_timestamp_iso()
        if due_status == 'new':
            where_clauses.append("f.queue_state = ?")
            params.append("new")
        elif due_status == 'learning':
            where_clauses.append("f.queue_state IN ('learning', 'relearning') AND f.due_at IS NOT NULL AND f.due_at <= ?")
            params.append(now_iso)
        elif due_status == 'due':
            where_clauses.append("f.queue_state = 'review' AND f.due_at IS NOT NULL AND f.due_at <= ?")
            params.append(now_iso)

        join_tag = ""
        if tag:
            join_tag = f"JOIN flashcard_keywords fk ON fk.card_id = f.id JOIN {keyword_table} kw ON kw.id = fk.keyword_id"
            where_clauses.append("kw.keyword = ?")
            params.append(tag)

        fts_filter = ""
        if q:
            if self.backend_type == BackendType.POSTGRESQL:
                tsquery = FTSQueryTranslator.normalize_query(q, 'postgresql')
                if not tsquery:
                    return 0
                fts_filter = "AND f.flashcards_fts_tsv @@ to_tsquery('english', ?)"
                params.append(tsquery)
            else:
                norm_q = self._normalize_flashcard_sqlite_query(q)
                if not norm_q:
                    return 0
                fts_filter = "AND f.rowid IN (SELECT rowid FROM flashcards_fts WHERE flashcards_fts MATCH ?)"
                params.append(norm_q)

        where_sql = " AND ".join(where_clauses)
        # DISTINCT avoids double-counting when tag join introduces duplicates
        query = """
            SELECT COUNT(DISTINCT f.id) AS cnt
              FROM flashcards f{visibility_join}
              {join_tag}
             WHERE {where_sql} {fts_filter}
        """.format_map(locals())  # nosec B608
        try:
            cursor = self.execute_query(query, tuple(params))
            row = cursor.fetchone()
            return int(row[0]) if row else 0
        except CharactersRAGDBError:  # noqa: TRY203
            raise

    def list_flashcard_tag_suggestions(
        self,
        q: str | None = None,
        limit: int = 50,
    ) -> list[dict[str, Any]]:
        """List global flashcard tag suggestions with per-tag usage counts."""
        if limit <= 0:
            return []

        keyword_table = self._map_table_for_backend("keywords")
        normalized_q = (q or "").strip()
        where_clauses: list[str] = []
        params: list[Any] = []

        if self.backend_type == BackendType.POSTGRESQL:
            where_clauses.extend(
                [
                    "f.deleted = FALSE",
                    "kw.deleted = FALSE",
                    "(f.deck_id IS NULL OR (d.id IS NOT NULL AND d.deleted = FALSE))",
                ]
            )
        else:
            where_clauses.extend(
                [
                    "f.deleted = 0",
                    "kw.deleted = 0",
                    "(f.deck_id IS NULL OR (d.id IS NOT NULL AND d.deleted = 0))",
                ]
            )

        if normalized_q:
            where_clauses.append("LOWER(kw.keyword) LIKE ?")
            params.append(f"%{normalized_q.lower()}%")

        order_keyword = self._case_insensitive_order_expression("kw.keyword")
        where_sql = " AND ".join(where_clauses)
        query = """
            SELECT
                kw.keyword AS tag,
                COUNT(DISTINCT f.id) AS usage_count
            FROM flashcards f
            JOIN flashcard_keywords fk ON fk.card_id = f.id
            JOIN {keyword_table} kw ON kw.id = fk.keyword_id
            LEFT JOIN decks d ON d.id = f.deck_id
            WHERE {where_sql}
            GROUP BY kw.keyword
            ORDER BY usage_count DESC, {order_keyword}
            LIMIT ?
        """.format_map(locals())  # nosec B608
        params.append(limit)

        try:
            cursor = self.execute_query(query, tuple(params))
            return [
                {"tag": str(row["tag"]), "count": int(row["usage_count"] or 0)}
                for row in cursor.fetchall()
            ]
        except CharactersRAGDBError:  # noqa: TRY203
            raise

    def get_flashcards_by_uuids(self, uuids: list[str]) -> list[dict[str, Any]]:
        """Fetch multiple flashcards by UUIDs in one query. Order is not guaranteed; caller can reorder."""
        if not uuids:
            return []
        placeholders = ",".join(["?"] * len(uuids))
        deleted_clause = "f.deleted = FALSE" if self.backend_type == BackendType.POSTGRESQL else "f.deleted = 0"
        query = """
            SELECT f.uuid, f.deck_id, d.name AS deck_name, d.workspace_id AS workspace_id, f.front, f.back, f.notes, f.extra, f.is_cloze, f.tags_json,
                   f.source_ref_type, f.source_ref_id, f.conversation_id, f.message_id,
                   f.ef, f.interval_days, f.repetitions, f.lapses, f.due_at, f.last_reviewed_at,
                   f.queue_state, f.step_index, f.suspended_reason,
                   f.created_at, f.last_modified, f.deleted, f.client_id, f.version, f.model_type, f.reverse
              FROM flashcards f
              LEFT JOIN decks d ON d.id = f.deck_id
             WHERE f.uuid IN ({placeholders}) AND {deleted_clause}
        """.format_map(locals())  # nosec B608
        try:
            cursor = self.execute_query(query, tuple(uuids))
            return [dict(row) for row in cursor.fetchall()]
        except CharactersRAGDBError:  # noqa: TRY203
            raise

    # --- PostgreSQL helpers for FTS on flashcards ---
    def _ensure_postgres_flashcards_tsvector(self, conn) -> None:
        """Ensure flashcards_fts_tsv column, index, and update trigger exist for PostgreSQL."""
        if self.backend_type != BackendType.POSTGRESQL:
            return
        try:
            self.backend.execute(
                "ALTER TABLE flashcards ADD COLUMN IF NOT EXISTS front_search TEXT",
                connection=conn,
            )
            self.backend.execute(
                "ALTER TABLE flashcards ADD COLUMN IF NOT EXISTS back_search TEXT",
                connection=conn,
            )
            self.backend.execute(
                "ALTER TABLE flashcards ADD COLUMN IF NOT EXISTS notes_search TEXT",
                connection=conn,
            )
            # Add tsvector column
            self.backend.execute(
                "ALTER TABLE flashcards ADD COLUMN IF NOT EXISTS flashcards_fts_tsv tsvector",
                connection=conn,
            )
            # Backfill existing rows
            self.backend.execute(
                (
                    "UPDATE flashcards "
                    "SET flashcards_fts_tsv = to_tsvector('english', "
                    "coalesce(front_search,'') || ' ' || coalesce(back_search,'') || ' ' || coalesce(notes_search,''))"
                ),
                connection=conn,
            )
            # Index
            self.backend.execute(
                "CREATE INDEX IF NOT EXISTS idx_flashcards_fts_tsv ON flashcards USING GIN (flashcards_fts_tsv)",
                connection=conn,
            )
            # Trigger to maintain tsvector
            self.backend.execute(
                "DROP TRIGGER IF EXISTS flashcards_fts_tsv_update ON flashcards",
                connection=conn,
            )
            self.backend.execute(
                (
                    "CREATE TRIGGER flashcards_fts_tsv_update "
                    "BEFORE INSERT OR UPDATE OF front_search, back_search, notes_search ON flashcards "
                    "FOR EACH ROW EXECUTE FUNCTION tsvector_update_trigger("
                    "flashcards_fts_tsv, 'pg_catalog.english', front_search, back_search, notes_search)"
                ),
                connection=conn,
            )
        except _CHACHA_NONCRITICAL_EXCEPTIONS as e:
            # If any statement fails due to existing objects, ignore and proceed
            logger.debug(f"_ensure_postgres_flashcards_tsvector: {e}")

    def get_next_review_card(
        self,
        deck_id: int | None = None,
        workspace_id: str | None = None,
        include_workspace_items: bool = False,
    ) -> tuple[dict[str, Any] | None, str]:
        """Return the next reviewable card using backend queue priority."""
        deleted_value = False if self.backend_type == BackendType.POSTGRESQL else 0
        now_iso = self._get_current_utc_timestamp_iso()
        visibility_clause, visibility_params, needs_deck_join = self._flashcard_visibility_filter(
            deck_id=deck_id,
            workspace_id=workspace_id,
            include_workspace_items=include_workspace_items,
        )
        visibility_join = " LEFT JOIN decks d ON d.id = f.deck_id" if needs_deck_join else ""
        visibility_suffix = f" AND {visibility_clause}" if visibility_clause else ""
        if deck_id is None:
            selections: tuple[tuple[str, str, tuple[Any, ...]], ...] = (
                (
                    "learning_due",
                    (
                        f"SELECT uuid FROM flashcards f{visibility_join} "  # nosec B608
                        "WHERE f.deleted = ? AND f.queue_state IN ('learning', 'relearning') "
                        f"AND f.due_at IS NOT NULL AND f.due_at <= ?{visibility_suffix} "
                        "ORDER BY f.due_at ASC, f.created_at ASC LIMIT 1"
                    ),
                    (deleted_value, now_iso, *visibility_params),
                ),
                (
                    "review_due",
                    (
                        f"SELECT uuid FROM flashcards f{visibility_join} "  # nosec B608
                        "WHERE f.deleted = ? AND f.queue_state = 'review' "
                        f"AND f.due_at IS NOT NULL AND f.due_at <= ?{visibility_suffix} "
                        "ORDER BY f.due_at ASC, f.created_at ASC LIMIT 1"
                    ),
                    (deleted_value, now_iso, *visibility_params),
                ),
                (
                    "new",
                    (
                        f"SELECT uuid FROM flashcards f{visibility_join} "  # nosec B608
                        f"WHERE f.deleted = ? AND f.queue_state = 'new'{visibility_suffix} "
                        "ORDER BY f.created_at ASC, f.id ASC LIMIT 1"
                    ),
                    (deleted_value, *visibility_params),
                ),
            )
        else:
            selections = (
                (
                    "learning_due",
                    (
                        "SELECT uuid FROM flashcards f "
                        "WHERE f.deleted = ? AND f.queue_state IN ('learning', 'relearning') "
                        "AND f.due_at IS NOT NULL AND f.due_at <= ? AND f.deck_id = ? "
                        "ORDER BY f.due_at ASC, f.created_at ASC LIMIT 1"
                    ),
                    (deleted_value, now_iso, deck_id),
                ),
                (
                    "review_due",
                    (
                        "SELECT uuid FROM flashcards f "
                        "WHERE f.deleted = ? AND f.queue_state = 'review' "
                        "AND f.due_at IS NOT NULL AND f.due_at <= ? AND f.deck_id = ? "
                        "ORDER BY f.due_at ASC, f.created_at ASC LIMIT 1"
                    ),
                    (deleted_value, now_iso, deck_id),
                ),
                (
                    "new",
                    (
                        "SELECT uuid FROM flashcards f "
                        "WHERE f.deleted = ? AND f.queue_state = 'new' AND f.deck_id = ? "
                        "ORDER BY f.created_at ASC, f.id ASC LIMIT 1"
                    ),
                    (deleted_value, deck_id),
                ),
            )
        try:
            for reason, query, params in selections:
                cursor = self.execute_query(query, tuple(params))
                row = cursor.fetchone()
                if not row:
                    continue
                card = self.get_flashcard(str(row["uuid"]))
                if card:
                    return card, reason
            return None, "none"
        except CharactersRAGDBError:  # noqa: TRY203
            raise

    def _srs_sm2_update(self, ef: float, interval_days: int, repetitions: int, lapses: int, rating: int) -> dict[str, Any]:
        """
        Apply SM-2 style scheduling update and return new values.
        rating: 0-5 (Anki scale). q<3 counts as lapse.
        """
        q = max(0, min(5, int(rating)))
        was_lapse = q < 3
        if was_lapse:
            lapses += 1
            repetitions = 0
            interval_days = 1
            # EF unchanged for lapse (keep, clamp)
        else:
            # Ease factor update
            ef = ef + 0.1 - (5 - q) * (0.08 + (5 - q) * 0.02)
            ef = max(1.3, ef)
            repetitions += 1
            if repetitions == 1:
                interval_days = 1
            elif repetitions == 2:
                interval_days = 6
            else:
                interval_days = int(round(interval_days * ef)) if interval_days > 0 else 6
        return {
            'ef': float(ef),
            'interval_days': int(interval_days),
            'repetitions': int(repetitions),
            'lapses': int(lapses),
            'was_lapse': was_lapse,
        }

    def _normalize_flashcard_review_mode(self, review_mode: str) -> str:
        normalized = str(review_mode or "").strip().lower()
        if normalized not in _FLASHCARD_REVIEW_MODES:
            raise InputError("review_mode must be one of: due, cram")  # noqa: TRY003
        return normalized

    def _normalize_flashcard_review_session_status(self, status: str) -> str:
        normalized = str(status or "").strip().lower()
        if normalized not in _FLASHCARD_REVIEW_SESSION_STATUSES:
            raise InputError("status must be one of: active, completed, abandoned")  # noqa: TRY003
        return normalized

    @staticmethod
    def _normalize_flashcard_review_session_source_bundle(source_bundle_value: Any) -> list[dict[str, Any]]:
        if isinstance(source_bundle_value, dict) and isinstance(source_bundle_value.get("items"), list):
            source_bundle_value = source_bundle_value.get("items")

        if isinstance(source_bundle_value, list):
            return [dict(entry) for entry in source_bundle_value if isinstance(entry, dict)]
        if isinstance(source_bundle_value, dict):
            return [dict(source_bundle_value)]
        return []

    def _deserialize_flashcard_review_session_row(self, row: Any) -> dict[str, Any] | None:
        item = self._deserialize_row_fields(row, _FLASHCARD_REVIEW_SESSION_JSON_FIELDS)
        if not item:
            return None

        if item.get("cards_reviewed") is not None:
            item["cards_reviewed"] = int(item["cards_reviewed"])
        if item.get("correct_count") is not None:
            item["correct_count"] = int(item["correct_count"])
        if item.get("study_pack_id") is not None:
            item["study_pack_id"] = int(item["study_pack_id"])
        item["deck_name_snapshot"] = self._normalize_nullable_text(item.get("deck_name_snapshot"))

        normalized_bundle = self._normalize_flashcard_review_session_source_bundle(item.get("source_bundle_json"))
        item["source_bundle_json"] = normalized_bundle or None
        item["source_bundle"] = normalized_bundle
        return item

    def _get_flashcard_review_session_deck_name_snapshot_for_conn(
        self,
        conn: Any,
        deck_id: int | None,
    ) -> str | None:
        """Return the current deck name to snapshot when a review session starts."""
        if deck_id is None:
            return None
        row = conn.execute("SELECT name FROM decks WHERE id = ?", (int(deck_id),)).fetchone()
        if not row:
            return None
        try:
            raw_name = row["name"]
        except (KeyError, IndexError, TypeError):
            raw_name = row[0]
        return self._normalize_nullable_text(raw_name)

    def _get_flashcard_review_session_row_for_conn(self, conn: Any, session_id: int) -> dict[str, Any] | None:
        row = conn.execute(
            """
            SELECT id, deck_id, deck_name_snapshot, review_mode, tag_filter, scope_key, status,
                   started_at, last_activity_at, completed_at, client_id,
                   cards_reviewed, correct_count, source_bundle_json, study_pack_id
              FROM flashcard_review_sessions
             WHERE id = ?
            """,
            (int(session_id),),
        ).fetchone()
        return self._deserialize_flashcard_review_session_row(row) if row else None

    def _get_flashcard_review_session_reconstructed_aggregates(self, conn: Any, session_id: int) -> tuple[int, int]:
        row = conn.execute(
            """
            SELECT COUNT(*) AS cards_reviewed,
                   COALESCE(SUM(CASE WHEN rating >= 3 THEN 1 ELSE 0 END), 0) AS correct_count
              FROM flashcard_reviews
             WHERE review_session_id = ?
            """,
            (int(session_id),),
        ).fetchone()
        if not row:
            return 0, 0
        return int(row["cards_reviewed"] or 0), int(row["correct_count"] or 0)

    def _repair_flashcard_review_session_aggregates_if_unchanged(
        self,
        conn: Any,
        session_id: int,
        *,
        expected_cards_reviewed: int | None,
        expected_correct_count: int | None,
        repaired_cards_reviewed: int,
        repaired_correct_count: int,
    ) -> bool:
        cursor = conn.execute(
            """
            UPDATE flashcard_review_sessions
               SET cards_reviewed = ?,
                   correct_count = ?
             WHERE id = ?
               AND ((cards_reviewed IS NULL AND ? IS NULL) OR cards_reviewed = ?)
               AND ((correct_count IS NULL AND ? IS NULL) OR correct_count = ?)
            """,
            (
                repaired_cards_reviewed,
                repaired_correct_count,
                int(session_id),
                expected_cards_reviewed,
                expected_cards_reviewed,
                expected_correct_count,
                expected_correct_count,
            ),
        )
        return max(0, int(getattr(cursor, "rowcount", 0) or 0)) > 0

    def abandon_stale_flashcard_review_sessions(self, *, scope_key: str | None = None) -> int:
        """Mark active review sessions as abandoned when inactive for over 30 minutes."""
        cutoff = to_iso_z(datetime.now(timezone.utc) - _FLASHCARD_REVIEW_SESSION_TIMEOUT) or self._get_current_utc_timestamp_iso()
        query = (
            """
            UPDATE flashcard_review_sessions
               SET status = 'abandoned'
             WHERE status = 'active'
               AND last_activity_at < ?
            """
        )
        params: list[Any] = [cutoff]
        if scope_key:
            query += " AND scope_key = ?"
            params.append(scope_key)
        cursor = self.execute_query(query, tuple(params), commit=True)
        return max(0, int(getattr(cursor, "rowcount", 0) or 0))

    def list_flashcard_review_sessions(
        self,
        *,
        deck_id: int | None = None,
        scope_key: str | None = None,
        status: str | None = None,
        limit: int = 100,
    ) -> list[dict[str, Any]]:
        """List persisted review sessions ordered from newest to oldest."""
        self.abandon_stale_flashcard_review_sessions(scope_key=scope_key)
        query_parts = [
            """
            SELECT id, deck_id, deck_name_snapshot, review_mode, tag_filter, scope_key, status,
                   started_at, last_activity_at, completed_at, client_id,
                   cards_reviewed, correct_count, source_bundle_json, study_pack_id
              FROM flashcard_review_sessions
             WHERE 1 = 1
            """
        ]
        params: list[Any] = []
        if deck_id is not None:
            query_parts.append("AND deck_id = ?")
            params.append(int(deck_id))
        if scope_key:
            query_parts.append("AND scope_key = ?")
            params.append(scope_key)
        if status:
            query_parts.append("AND status = ?")
            params.append(self._normalize_flashcard_review_session_status(status))
        query_parts.append("ORDER BY last_activity_at DESC, started_at DESC, id DESC LIMIT ?")
        params.append(max(1, int(limit)))
        cursor = self.execute_query(" ".join(query_parts), tuple(params))
        return [
            session
            for row in cursor.fetchall()
            if (session := self._deserialize_flashcard_review_session_row(row)) is not None
        ]

    def get_or_create_flashcard_review_session(
        self,
        *,
        deck_id: int | None,
        review_mode: str,
        tag_filter: str | None,
        scope_key: str,
    ) -> dict[str, Any]:
        """Return the authoritative active session for a scope or create a new one."""
        normalized_scope_key = str(scope_key or "").strip()
        if not normalized_scope_key:
            raise InputError("scope_key is required")  # noqa: TRY003
        normalized_mode = self._normalize_flashcard_review_mode(review_mode)
        normalized_tag_filter = self._normalize_nullable_text(tag_filter)
        self.abandon_stale_flashcard_review_sessions(scope_key=normalized_scope_key)
        now = self._get_current_utc_timestamp_iso()

        try:
            with self.transaction() as conn:
                rows = conn.execute(
                    """
                    SELECT id, deck_id, deck_name_snapshot, review_mode, tag_filter, scope_key, status,
                           started_at, last_activity_at, completed_at, client_id,
                           cards_reviewed, correct_count, source_bundle_json, study_pack_id
                      FROM flashcard_review_sessions
                     WHERE scope_key = ? AND status = 'active'
                     ORDER BY last_activity_at DESC, started_at DESC, id DESC
                    """,
                    (normalized_scope_key,),
                ).fetchall()
                if rows:
                    authoritative = self._deserialize_flashcard_review_session_row(rows[0]) or {}
                    if len(rows) > 1:
                        duplicate_ids = [int(row["id"]) for row in rows[1:]]
                        placeholders = ", ".join("?" for _ in duplicate_ids)
                        conn.execute(
                            f"UPDATE flashcard_review_sessions SET status = 'abandoned' WHERE id IN ({placeholders})",  # nosec B608
                            tuple(duplicate_ids),
                        )
                    conn.execute(
                        """
                        UPDATE flashcard_review_sessions
                           SET last_activity_at = ?
                        WHERE id = ?
                        """,
                        (now, int(authoritative["id"])),
                    )
                    authoritative["last_activity_at"] = now
                    return authoritative

                deck_name_snapshot = self._get_flashcard_review_session_deck_name_snapshot_for_conn(
                    conn,
                    deck_id,
                )
                if self.backend_type == BackendType.POSTGRESQL:
                    cursor = conn.execute(
                        """
                        INSERT INTO flashcard_review_sessions(
                            deck_id, deck_name_snapshot, review_mode, tag_filter, scope_key, status,
                            started_at, last_activity_at, completed_at, cards_reviewed,
                            correct_count, source_bundle_json, study_pack_id, client_id
                        )
                        VALUES(?, ?, ?, ?, ?, 'active', ?, ?, NULL, 0, 0, NULL, NULL, ?)
                        RETURNING id
                        """,
                        (
                            int(deck_id) if deck_id is not None else None,
                            deck_name_snapshot,
                            normalized_mode,
                            normalized_tag_filter,
                            normalized_scope_key,
                            now,
                            now,
                            self.client_id,
                        ),
                    )
                    row = cursor.fetchone()
                    session_id = int(row["id"]) if row else None
                else:
                    cursor = conn.execute(
                        """
                        INSERT INTO flashcard_review_sessions(
                            deck_id, deck_name_snapshot, review_mode, tag_filter, scope_key, status,
                            started_at, last_activity_at, completed_at, cards_reviewed,
                            correct_count, source_bundle_json, study_pack_id, client_id
                        )
                        VALUES(?, ?, ?, ?, ?, 'active', ?, ?, NULL, 0, 0, NULL, NULL, ?)
                        """,
                        (
                            int(deck_id) if deck_id is not None else None,
                            deck_name_snapshot,
                            normalized_mode,
                            normalized_tag_filter,
                            normalized_scope_key,
                            now,
                            now,
                            self.client_id,
                        ),
                    )
                    session_id = int(cursor.lastrowid) if cursor.lastrowid is not None else None
                if session_id is None:
                    raise CharactersRAGDBError("Failed to determine flashcard review session ID after insert")  # noqa: TRY003
                row = conn.execute(
                    """
                    SELECT id, deck_id, deck_name_snapshot, review_mode, tag_filter, scope_key, status,
                           started_at, last_activity_at, completed_at, client_id,
                           cards_reviewed, correct_count, source_bundle_json, study_pack_id
                      FROM flashcard_review_sessions
                     WHERE id = ?
                    """,
                    (session_id,),
                ).fetchone()
                return self._deserialize_flashcard_review_session_row(row) or {}
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to get or create flashcard review session: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to get or create flashcard review session: {exc}") from exc  # noqa: TRY003

    def get_flashcard_review_session(self, session_id: int) -> dict[str, Any] | None:
        """Fetch a single flashcard review session by id, or None if not found."""
        cursor = self.execute_query(
            """
            SELECT id, deck_id, deck_name_snapshot, review_mode, tag_filter, scope_key, status,
                   started_at, last_activity_at, completed_at, client_id,
                   cards_reviewed, correct_count, source_bundle_json, study_pack_id
              FROM flashcard_review_sessions
             WHERE id = ?
            """,
            (int(session_id),),
        )
        row = cursor.fetchone()
        return self._deserialize_flashcard_review_session_row(row) if row else None

    def mark_flashcard_review_session_completed(self, session_id: int) -> dict[str, Any]:
        """Mark a persisted review session as completed."""
        now = self._get_current_utc_timestamp_iso()
        try:
            cursor = self.execute_query(
                """
                UPDATE flashcard_review_sessions
                   SET status = 'completed',
                       last_activity_at = ?,
                       completed_at = ?
                 WHERE id = ?
                """,
                (now, now, int(session_id)),
                commit=True,
            )
            if getattr(cursor, "rowcount", 0) == 0:
                raise ConflictError("Flashcard review session not found", entity="flashcard_review_sessions", entity_id=session_id)  # noqa: TRY003
            row = self.execute_query(
                """
                SELECT id, deck_id, deck_name_snapshot, review_mode, tag_filter, scope_key, status,
                       started_at, last_activity_at, completed_at, client_id,
                       cards_reviewed, correct_count, source_bundle_json, study_pack_id
                  FROM flashcard_review_sessions
                 WHERE id = ?
                """,
                (int(session_id),),
            ).fetchone()
            return self._deserialize_flashcard_review_session_row(row) or {}
        except CharactersRAGDBError:
            raise
        except _CHACHA_NONCRITICAL_EXCEPTIONS as exc:
            raise CharactersRAGDBError(f"Failed to mark flashcard review session completed: {exc}") from exc  # noqa: TRY003

    def get_flashcard_review_session_rollup(
        self,
        session_id: int,
        *,
        repair_session_aggregates: bool = True,
    ) -> dict[str, Any] | None:
        """Return a merged session view that trusts review rows when cached aggregates drift."""
        try:
            with self.transaction() as conn:
                session = self._get_flashcard_review_session_row_for_conn(conn, int(session_id))
                if not session:
                    return None

                reconstructed_cards_reviewed, reconstructed_correct_count = (
                    self._get_flashcard_review_session_reconstructed_aggregates(conn, int(session_id))
                )
                session_cards_reviewed = session.get("cards_reviewed")
                session_correct_count = session.get("correct_count")
                session_aggregates_match = (
                    session_cards_reviewed is not None
                    and session_correct_count is not None
                    and session_cards_reviewed >= 0
                    and session_correct_count >= 0
                    and session_correct_count <= session_cards_reviewed
                    and session_cards_reviewed == reconstructed_cards_reviewed
                    and session_correct_count == reconstructed_correct_count
                )

                if session_aggregates_match:
                    session["aggregate_source"] = "session"
                    return session

                if repair_session_aggregates:
                    repaired = self._repair_flashcard_review_session_aggregates_if_unchanged(
                        conn,
                        int(session_id),
                        expected_cards_reviewed=session_cards_reviewed,
                        expected_correct_count=session_correct_count,
                        repaired_cards_reviewed=reconstructed_cards_reviewed,
                        repaired_correct_count=reconstructed_correct_count,
                    )
                    if repaired:
                        session["cards_reviewed"] = reconstructed_cards_reviewed
                        session["correct_count"] = reconstructed_correct_count
                        session["aggregate_source"] = "reconstructed"
                        return session

                    session = self._get_flashcard_review_session_row_for_conn(conn, int(session_id))
                    if not session:
                        return None
                    reconstructed_cards_reviewed, reconstructed_correct_count = (
                        self._get_flashcard_review_session_reconstructed_aggregates(conn, int(session_id))
                    )
                    session_cards_reviewed = session.get("cards_reviewed")
                    session_correct_count = session.get("correct_count")
                    session_aggregates_match = (
                        session_cards_reviewed is not None
                        and session_correct_count is not None
                        and session_cards_reviewed >= 0
                        and session_correct_count >= 0
                        and session_correct_count <= session_cards_reviewed
                        and session_cards_reviewed == reconstructed_cards_reviewed
                        and session_correct_count == reconstructed_correct_count
                    )
                    if session_aggregates_match:
                        session["aggregate_source"] = "session"
                        return session

                session["cards_reviewed"] = reconstructed_cards_reviewed
                session["correct_count"] = reconstructed_correct_count
                session["aggregate_source"] = "reconstructed"
                return session
        except CharactersRAGDBError:
            raise
        except _CHACHA_NONCRITICAL_EXCEPTIONS as exc:
            raise CharactersRAGDBError(f"Failed to fetch flashcard review session rollup: {exc}") from exc  # noqa: TRY003

    def get_flashcard_reviewed_cards(self, session_id: int) -> list[dict[str, Any]]:
        """Return reviewed flashcard metadata for a session in review order."""
        cursor = self.execute_query(
            """
            SELECT f.uuid,
                   MAX(f.tags_json) AS tags_json,
                   MAX(f.source_ref_type) AS source_ref_type,
                   MAX(f.source_ref_id) AS source_ref_id,
                   MAX(d.name) AS deck_name
              FROM flashcard_reviews fr
              JOIN flashcards f ON f.id = fr.card_id
              LEFT JOIN decks d ON d.id = f.deck_id
             WHERE fr.review_session_id = ?
             GROUP BY f.uuid
             ORDER BY MIN(fr.id)
            """,
            (int(session_id),),
        )
        return [dict(row) for row in cursor.fetchall()]

    def get_latest_flashcard_review(self, card_uuid: str) -> dict[str, Any] | None:
        """Return the most recent review row for a flashcard, including nullable session linkage."""
        cursor = self.execute_query(
            """
            SELECT fr.id, fr.card_id, fr.reviewed_at, fr.rating, fr.answer_time_ms,
                   fr.scheduled_interval_days, fr.new_ef, fr.new_repetitions, fr.was_lapse,
                   fr.client_id, fr.scheduler_type, fr.previous_queue_state, fr.next_queue_state,
                   fr.previous_due_at, fr.next_due_at, fr.review_session_id
              FROM flashcard_reviews fr
              JOIN flashcards f ON f.id = fr.card_id
             WHERE f.uuid = ?
             ORDER BY fr.id DESC
             LIMIT 1
            """,
            (card_uuid,),
        )
        row = cursor.fetchone()
        return dict(row) if row else None

    def review_flashcard(
        self,
        card_uuid: str,
        rating: int,
        answer_time_ms: int | None = None,
        review_session_id: int | None = None,
    ) -> dict[str, Any]:
        """Submit a review for a flashcard and update scheduling. Returns updated card fields."""
        now_dt = datetime.now(timezone.utc)
        now = to_iso_z(now_dt) or self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                card = conn.execute(
                    """
                    SELECT f.id, f.uuid, f.deck_id, f.ef, f.interval_days, f.repetitions, f.lapses,
                           f.due_at, f.last_reviewed_at, f.queue_state, f.step_index, f.suspended_reason,
                           f.scheduler_state_json,
                           COALESCE(d.scheduler_type, 'sm2_plus') AS scheduler_type,
                           COALESCE(d.scheduler_settings_json, ?) AS scheduler_settings_json
                      FROM flashcards f
                      LEFT JOIN decks d ON d.id = f.deck_id
                     WHERE f.uuid = ? AND f.deleted = 0
                    """,
                    (scheduler_settings_to_json(None), card_uuid),
                ).fetchone()
                if not card:
                    raise ConflictError("Flashcard not found", entity="flashcards", identifier=card_uuid)  # noqa: TRY003
                card_id = int(card['id'])
                card_deck_id = int(card["deck_id"]) if card["deck_id"] is not None else None
                resolved_review_session_id = int(review_session_id) if review_session_id is not None else None
                if resolved_review_session_id is None:
                    auto_session = self.get_or_create_flashcard_review_session(
                        deck_id=card_deck_id,
                        review_mode="due",
                        tag_filter=None,
                        scope_key=f"due:deck:{card_deck_id}" if card_deck_id is not None else "due:global",
                    )
                    resolved_review_session_id = int(auto_session["id"])
                if resolved_review_session_id is not None:
                    session_row = conn.execute(
                        """
                        SELECT id, deck_id, status
                          FROM flashcard_review_sessions
                         WHERE id = ?
                        """,
                        (resolved_review_session_id,),
                    ).fetchone()
                    if not session_row:
                        raise ConflictError(
                            "Flashcard review session not found",
                            entity="flashcard_review_sessions",
                            identifier=resolved_review_session_id,
                        )
                    session_deck_id = int(session_row["deck_id"]) if session_row["deck_id"] is not None else None
                    if session_deck_id != card_deck_id:
                        raise InputError("review_session_id must match the flashcard deck scope")  # noqa: TRY003
                    if str(session_row["status"] or "").strip().lower() != "active":
                        raise ConflictError(
                            "Flashcard review session is not active",
                            entity="flashcard_review_sessions",
                            identifier=resolved_review_session_id,
                        )
                previous_queue_state = coerce_queue_state(dict(card))
                previous_due_at = self._normalize_nullable_text(card["due_at"])
                scheduler_type = _coerce_scheduler_type(card["scheduler_type"])
                scheduler_settings = _normalize_scheduler_settings_envelope(card["scheduler_settings_json"])
                upd = _simulate_scheduler_review_transition(
                    dict(card),
                    scheduler_type=scheduler_type,
                    scheduler_settings_envelope=scheduler_settings,
                    rating=int(rating),
                    now=now_dt,
                )

                conn.execute(
                    """
                    UPDATE flashcards
                       SET ef = ?, interval_days = ?, repetitions = ?, lapses = ?,
                           due_at = ?, last_reviewed_at = ?, queue_state = ?, step_index = ?,
                           suspended_reason = ?, scheduler_state_json = ?, last_modified = ?, version = version + 1, client_id = ?
                     WHERE id = ? AND deleted = 0
                    """,
                    (
                        upd["ef"],
                        upd["interval_days"],
                        upd["repetitions"],
                        upd["lapses"],
                        upd["due_at"],
                        upd["last_reviewed_at"],
                        upd["queue_state"],
                        upd["step_index"],
                        upd["suspended_reason"],
                        upd.get("scheduler_state_json", "{}"),
                        now,
                        self.client_id,
                        card_id,
                    )
                )
                conn.execute(
                    """
                    INSERT INTO flashcard_reviews(
                        card_id, reviewed_at, rating, answer_time_ms, scheduled_interval_days,
                        new_ef, new_repetitions, was_lapse, client_id, scheduler_type,
                        previous_queue_state, next_queue_state, previous_due_at, next_due_at, review_session_id
                    )
                    VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        card_id,
                        now,
                        int(rating),
                        answer_time_ms,
                        upd["interval_days"] if upd["queue_state"] == "review" else None,
                        upd["ef"],
                        upd["repetitions"],
                        bool(upd["was_lapse"]),
                        self.client_id,
                        scheduler_type,
                        previous_queue_state,
                        upd["queue_state"],
                        previous_due_at,
                        upd["due_at"],
                        resolved_review_session_id,
                    )
                )
                if resolved_review_session_id is not None:
                    correct_increment = 1 if int(rating) >= 3 else 0
                    conn.execute(
                        """
                        UPDATE flashcard_review_sessions
                           SET last_activity_at = ?,
                               cards_reviewed = COALESCE(cards_reviewed, 0) + 1,
                               correct_count = COALESCE(correct_count, 0) + ?
                         WHERE id = ?
                        """,
                        (now, correct_increment, resolved_review_session_id),
                    )
                updated = conn.execute(
                    """
                    SELECT uuid, ef, interval_days, repetitions, lapses, due_at, last_reviewed_at,
                           last_modified, version, queue_state, step_index, suspended_reason, scheduler_state_json
                      FROM flashcards
                     WHERE id = ?
                    """,
                    (card_id,)
                ).fetchone()
                updated_payload = dict(updated)
                updated_payload["scheduler_type"] = scheduler_type
                updated_payload["next_intervals"] = _build_scheduler_next_interval_previews(
                    updated_payload,
                    scheduler_type=scheduler_type,
                    scheduler_settings_envelope=scheduler_settings,
                    now=now_dt,
                )
                updated_payload["review_session_id"] = resolved_review_session_id
                return updated_payload
        except sqlite3.Error as e:
            raise CharactersRAGDBError(f"Failed to review flashcard: {e}") from e  # noqa: TRY003

    def get_flashcard_analytics_summary(
        self,
        deck_id: int | None = None,
        workspace_id: str | None = None,
        include_workspace_items: bool = False,
    ) -> dict[str, Any]:
        """Return review analytics summary and per-deck progress counts."""
        now_dt = datetime.now(timezone.utc)
        today_start_dt = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        tomorrow_start_dt = today_start_dt + timedelta(days=1)
        now_iso = now_dt.isoformat(timespec='milliseconds').replace('+00:00', 'Z')
        today_start_iso = today_start_dt.isoformat(timespec='milliseconds').replace('+00:00', 'Z')
        tomorrow_start_iso = tomorrow_start_dt.isoformat(timespec='milliseconds').replace('+00:00', 'Z')
        normalized_deck_id = int(deck_id) if deck_id is not None else None
        visibility_clause, visibility_params, needs_deck_join = self._flashcard_visibility_filter(
            deck_id=normalized_deck_id,
            workspace_id=workspace_id,
            include_workspace_items=include_workspace_items,
        )
        visibility_join = " LEFT JOIN decks d ON d.id = f.deck_id" if needs_deck_join else ""
        visibility_suffix = f" AND {visibility_clause}" if visibility_clause else ""
        metrics_join = visibility_join or " LEFT JOIN decks d ON d.id = f.deck_id"
        metrics_suffix = f"{visibility_suffix} AND (d.id IS NULL OR d.deleted = 0)"
        deck_rows_clause, deck_rows_params, _ = self._flashcard_visibility_filter(
            deck_id=normalized_deck_id,
            workspace_id=workspace_id,
            include_workspace_items=include_workspace_items,
            deck_alias="d",
            deck_id_column="d.id",
        )
        deck_rows_suffix = f" AND {deck_rows_clause}" if deck_rows_clause else ""

        try:
            # Daily review metrics
            daily_row = self.execute_query(
                """
                SELECT
                    COUNT(*) AS reviewed_today,
                    SUM(CASE WHEN rating < 3 THEN 1 ELSE 0 END) AS lapses_today,
                    AVG(answer_time_ms) AS avg_answer_time_ms_today
                FROM flashcard_reviews fr
                JOIN flashcards f ON f.id = fr.card_id AND f.deleted = 0
                {metrics_join}
                WHERE fr.reviewed_at >= ? AND fr.reviewed_at < ?{metrics_suffix}
                """.format_map(locals()),  # nosec B608
                (today_start_iso, tomorrow_start_iso, *visibility_params),
            ).fetchone()

            reviewed_today = int((daily_row["reviewed_today"] if daily_row else 0) or 0)
            lapses_today = int((daily_row["lapses_today"] if daily_row else 0) or 0)
            avg_answer_time_ms_today = (
                float(daily_row["avg_answer_time_ms_today"])
                if daily_row and daily_row["avg_answer_time_ms_today"] is not None
                else None
            )
            retention_rate_today = None
            lapse_rate_today = None
            if reviewed_today > 0:
                lapse_rate_today = (lapses_today / reviewed_today) * 100.0
                retention_rate_today = 100.0 - lapse_rate_today

            # UTC day streak: count consecutive days ending at today with >=1 review
            day_rows = self.execute_query(
                """
                SELECT DISTINCT substr(fr.reviewed_at, 1, 10) AS review_day
                FROM flashcard_reviews fr
                JOIN flashcards f ON f.id = fr.card_id AND f.deleted = 0
                {metrics_join}
                WHERE 1 = 1{metrics_suffix}
                ORDER BY review_day DESC
                LIMIT 400
                """.format_map(locals()),  # nosec B608
                visibility_params,
            ).fetchall()
            reviewed_days = {
                str(row["review_day"])
                for row in day_rows
                if row and row["review_day"] is not None
            }
            streak = 0
            cursor_day = today_start_dt.date()
            while cursor_day.isoformat() in reviewed_days:
                streak += 1
                cursor_day = cursor_day - timedelta(days=1)

            # Per-deck progress counts
            deck_rows = self.execute_query(
                """
                SELECT
                    d.id AS deck_id,
                    d.name AS deck_name,
                    COUNT(f.id) AS total_count,
                    SUM(CASE WHEN f.queue_state = 'new' THEN 1 ELSE 0 END) AS new_count,
                    SUM(CASE WHEN f.queue_state IN ('learning', 'relearning') THEN 1 ELSE 0 END) AS learning_count,
                    SUM(CASE WHEN f.queue_state IN ('learning', 'relearning', 'review') AND f.due_at IS NOT NULL AND f.due_at <= ? THEN 1 ELSE 0 END) AS due_count,
                    SUM(CASE WHEN f.queue_state = 'review' AND f.interval_days >= ? THEN 1 ELSE 0 END) AS mature_count
                FROM decks d
                LEFT JOIN flashcards f
                    ON f.deck_id = d.id
                   AND f.deleted = 0
                WHERE d.deleted = 0{deck_rows_suffix}
                GROUP BY d.id, d.name
                ORDER BY d.name ASC
                """.format_map(locals()),  # nosec B608
                (now_iso, MATURE_INTERVAL_DAYS, *deck_rows_params),
            ).fetchall()

            decks = []
            for row in deck_rows:
                decks.append(
                    {
                        "deck_id": int(row["deck_id"]),
                        "deck_name": str(row["deck_name"] or f"Deck {row['deck_id']}"),
                        "total": int(row["total_count"] or 0),
                        "new": int(row["new_count"] or 0),
                        "learning": int(row["learning_count"] or 0),
                        "due": int(row["due_count"] or 0),
                        "mature": int(row["mature_count"] or 0),
                    }
                )

            return {
                "reviewed_today": reviewed_today,
                "retention_rate_today": retention_rate_today,
                "lapse_rate_today": lapse_rate_today,
                "avg_answer_time_ms_today": avg_answer_time_ms_today,
                "study_streak_days": streak,
                "generated_at": now_iso,
                "decks": decks,
            }
        except CharactersRAGDBError:  # noqa: TRY203
            raise
        except _CHACHA_NONCRITICAL_EXCEPTIONS as e:
            raise CharactersRAGDBError(f"Failed to build flashcard analytics summary: {e}") from e  # noqa: TRY003

    def export_flashcards_csv(self,
                              deck_id: int | None = None,
                              workspace_id: str | None = None,
                              include_workspace_items: bool = False,
                              tag: str | None = None,
                              q: str | None = None,
                              *,
                              delimiter: str = '\t',
                              include_header: bool = False,
                              extended_header: bool = False) -> bytes:
        """Export flashcards to delimited text. Columns: Deck, Front, Back, Tags, Notes.
        Args:
            delimiter: field separator (default tab)
            include_header: include a header row
        """
        rows = self.list_flashcards(
            deck_id=deck_id,
            workspace_id=workspace_id,
            include_workspace_items=include_workspace_items,
            tag=tag,
            q=q,
            due_status='all',
            include_deleted=False,
            limit=100000,
            offset=0,
        )
        output_lines: list[str] = []
        if include_header:
            base_cols = ["Deck", "Front", "Back", "Tags", "Notes"]
            if extended_header:
                base_cols += ["Extra", "Reverse"]
            output_lines.append(delimiter.join(base_cols))
        for r in rows:
            deck_name = r.get('deck_name') or ''
            front = r.get('front') or ''
            back = r.get('back') or ''
            tags = ''
            if r.get('tags_json'):
                try:
                    tags_list = json.loads(r['tags_json'])
                    if isinstance(tags_list, list):
                        tags = " ".join(str(t) for t in tags_list)
                except _CHACHA_NONCRITICAL_EXCEPTIONS:
                    tags = ''
            notes = r.get('notes') or ''
            extra = r.get('extra') or ''
            reverse = 'true' if bool(r.get('reverse')) else 'false'
            # Escape delimiter/tabs/newlines minimally
            def esc(s: str) -> str:
                return s.replace('\r', ' ').replace('\n', ' ').replace('\t', ' ').replace(delimiter, ' ').strip()
            row = [esc(deck_name), esc(front), esc(back), esc(tags), esc(notes)]
            if extended_header:
                row += [esc(extra), reverse]
            output_lines.append(delimiter.join(row))
        csv_bytes = ("\n".join(output_lines) + ("\n" if output_lines else "")).encode('utf-8')
        return csv_bytes

    def get_flashcard(self, card_uuid: str) -> dict[str, Any] | None:
        """Fetch a single flashcard by uuid (active only)."""
        query = """
            SELECT f.uuid, f.deck_id, d.name AS deck_name, d.workspace_id AS workspace_id, f.front, f.back, f.notes, f.extra, f.is_cloze, f.tags_json,
                   f.source_ref_type, f.source_ref_id, f.conversation_id, f.message_id,
                   f.ef, f.interval_days, f.repetitions, f.lapses, f.due_at, f.last_reviewed_at,
                   f.queue_state, f.step_index, f.suspended_reason, f.scheduler_state_json, d.scheduler_type,
                   f.created_at, f.last_modified, f.deleted, f.client_id, f.version, f.model_type, f.reverse
              FROM flashcards f
              LEFT JOIN decks d ON d.id = f.deck_id
             WHERE f.uuid = ? AND f.deleted = 0
        """
        try:
            cur = self.execute_query(query, (card_uuid,))
            row = cur.fetchone()
            return dict(row) if row else None
        except CharactersRAGDBError:  # noqa: TRY203
            raise

    def add_flashcard_asset(
        self,
        *,
        image_bytes: bytes,
        mime_type: str,
        original_filename: str | None = None,
        width: int | None = None,
        height: int | None = None,
    ) -> str:
        """Persist a managed flashcard image asset and return its UUID."""
        if not image_bytes:
            raise InputError("Flashcard asset image_bytes must not be empty")  # noqa: TRY003

        asset_uuid = self._generate_uuid()
        now = self._get_current_utc_timestamp_iso()
        sha256 = hashlib.sha256(image_bytes).hexdigest()
        try:
            with self.transaction() as conn:
                insert_sql = (
                    """
                    INSERT INTO flashcard_assets(
                        uuid, card_id, mime_type, original_filename, byte_size, sha256,
                        image_data, width, height, created_at, last_modified, deleted, client_id, version
                    )
                    VALUES(?, NULL, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """
                )
                params = (
                    asset_uuid,
                    mime_type,
                    original_filename,
                    len(image_bytes),
                    sha256,
                    image_bytes,
                    width,
                    height,
                    now,
                    now,
                    False,
                    self.client_id,
                    1,
                )
                conn.execute(insert_sql, params)
            return asset_uuid
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to add flashcard asset: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to add flashcard asset: {exc}") from exc  # noqa: TRY003

    def get_flashcard_asset(self, asset_uuid: str) -> dict[str, Any] | None:
        """Fetch flashcard asset metadata by UUID."""
        query = """
            SELECT fa.uuid, fa.mime_type, fa.original_filename, fa.byte_size, fa.sha256,
                   fa.width, fa.height, fa.created_at, fa.last_modified, fa.deleted,
                   fa.client_id, fa.version, f.uuid AS card_uuid
              FROM flashcard_assets fa
              LEFT JOIN flashcards f ON f.id = fa.card_id
             WHERE fa.uuid = ? AND fa.deleted = 0
        """
        try:
            cur = self.execute_query(query, (asset_uuid,))
            row = cur.fetchone()
            return dict(row) if row else None
        except CharactersRAGDBError:  # noqa: TRY203
            raise

    def get_flashcard_asset_content(self, asset_uuid: str) -> bytes | None:
        """Fetch raw bytes for a flashcard asset by UUID."""
        query = "SELECT image_data FROM flashcard_assets WHERE uuid = ? AND deleted = 0"
        try:
            cur = self.execute_query(query, (asset_uuid,))
            row = cur.fetchone()
        except CharactersRAGDBError:  # noqa: TRY203
            raise
        if not row:
            return None
        blob = row[0]
        if isinstance(blob, memoryview):
            return blob.tobytes()
        return bytes(blob) if blob is not None else None

    def reconcile_flashcard_asset_refs(
        self,
        card_uuid: str,
        *,
        front: str | None,
        back: str | None,
        extra: str | None,
        notes: str | None,
    ) -> list[str]:
        """Attach referenced assets to a card and detach removed assets."""
        referenced_asset_uuids: list[str] = []
        for text in (front, back, extra, notes):
            for asset_uuid in extract_flashcard_asset_uuids(text):
                if asset_uuid not in referenced_asset_uuids:
                    referenced_asset_uuids.append(asset_uuid)

        try:
            with self.transaction() as conn:
                card_row = conn.execute(
                    "SELECT id FROM flashcards WHERE uuid = ? AND deleted = 0",
                    (card_uuid,),
                ).fetchone()
                if not card_row:
                    raise CharactersRAGDBError("Flashcard not found or deleted")  # noqa: TRY003
                card_id = int(card_row[0])

                existing_asset_rows = conn.execute(
                    "SELECT id, uuid, card_id FROM flashcard_assets WHERE deleted = 0"
                ).fetchall()
                assets_by_uuid = {str(row[1]): row for row in existing_asset_rows}
                for asset_uuid in referenced_asset_uuids:
                    asset_row = assets_by_uuid.get(asset_uuid)
                    if not asset_row:
                        raise InputError(f"Flashcard asset not found: {asset_uuid}")  # noqa: TRY003
                    attached_card_id = asset_row[2]
                    if attached_card_id is not None and int(attached_card_id) != card_id:
                        raise ConflictError(
                            "Flashcard asset is attached to a different card",
                            entity="flashcard_assets",
                            identifier=asset_uuid,
                        )

                now = self._get_current_utc_timestamp_iso()
                for asset_uuid in referenced_asset_uuids:
                    conn.execute(
                        """
                        UPDATE flashcard_assets
                           SET card_id = ?, last_modified = ?, version = version + 1, client_id = ?
                         WHERE uuid = ? AND deleted = 0
                        """,
                        (card_id, now, self.client_id, asset_uuid),
                    )

                existing_attached_rows = conn.execute(
                    "SELECT uuid FROM flashcard_assets WHERE card_id = ? AND deleted = 0",
                    (card_id,),
                ).fetchall()
                referenced_set = set(referenced_asset_uuids)
                for row in existing_attached_rows:
                    existing_uuid = str(row[0])
                    if existing_uuid in referenced_set:
                        continue
                    conn.execute(
                        """
                        UPDATE flashcard_assets
                           SET card_id = NULL, last_modified = ?, version = version + 1, client_id = ?
                         WHERE uuid = ? AND deleted = 0
                        """,
                        (now, self.client_id, existing_uuid),
                    )
            return referenced_asset_uuids
        except (BackendDatabaseError, sqlite3.Error) as exc:
            raise CharactersRAGDBError(f"Failed to reconcile flashcard asset refs: {exc}") from exc  # noqa: TRY003

    def cleanup_stale_flashcard_assets(self, *, older_than: timedelta | None = None) -> int:
        """Soft-delete unattached flashcard assets older than the provided age."""
        age = older_than or timedelta(hours=24)
        cutoff = (datetime.now(timezone.utc) - age).strftime("%Y-%m-%dT%H:%M:%SZ")
        now = self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                cursor = conn.execute(
                    """
                    UPDATE flashcard_assets
                       SET deleted = 1,
                           last_modified = ?,
                           version = version + 1,
                           client_id = ?
                     WHERE card_id IS NULL
                       AND deleted = 0
                       AND created_at <= ?
                    """,
                    (now, self.client_id, cutoff),
                )
                return int(cursor.rowcount or 0)
        except (BackendDatabaseError, sqlite3.Error) as exc:
            raise CharactersRAGDBError(f"Failed to cleanup stale flashcard assets: {exc}") from exc  # noqa: TRY003

    def update_flashcard(
        self,
        card_uuid: str,
        updates: dict[str, Any],
        expected_version: int | None = None,
        tags: list[str] | None = None,
    ) -> bool:
        """
        Update mutable fields: deck_id, front, back, notes, is_cloze, tags_json.
        If expected_version is provided, enforce optimistic locking.
        """
        allowed = {"deck_id", "front", "back", "notes", "extra", "is_cloze", "tags_json", "model_type", "reverse"}
        set_parts = []
        params: list[Any] = []
        for k, v in updates.items():
            if k in allowed:
                set_parts.append(f"{k} = ?")
                params.append(v)
                if k == "front":
                    set_parts.append("front_search = ?")
                    params.append(sanitize_flashcard_text_for_search(v))
                elif k == "back":
                    set_parts.append("back_search = ?")
                    params.append(sanitize_flashcard_text_for_search(v))
                elif k == "notes":
                    set_parts.append("notes_search = ?")
                    params.append(sanitize_flashcard_text_for_search(v))
        norm_tags: list[str] | None = None
        if tags is not None:
            norm_tags = [t.strip() for t in tags if t and t.strip()]
            set_parts.append("tags_json = ?")
            params.append(json.dumps(norm_tags))
        if not set_parts:
            if expected_version is None:
                return True
            try:
                with self.transaction() as conn:
                    row = conn.execute(
                        "SELECT version FROM flashcards WHERE uuid = ? AND deleted = 0",
                        (card_uuid,),
                    ).fetchone()
                    if not row:
                        raise CharactersRAGDBError("Flashcard not found or deleted")  # noqa: TRY003
                    current_version = int(row[0])
                    if current_version != expected_version:
                        raise ConflictError(  # noqa: TRY003
                            "Version mismatch updating flashcard",
                            entity="flashcards",
                            identifier=card_uuid,
                        )
            except sqlite3.Error as e:
                raise CharactersRAGDBError(f"Failed to update flashcard: {e}") from e  # noqa: TRY003
            return True
        now = self._get_current_utc_timestamp_iso()
        set_parts.extend(["last_modified = ?", "version = version + 1", "client_id = ?"])
        params.extend([now, self.client_id])

        try:
            with self.transaction() as conn:
                # get id and (optionally) version
                row = conn.execute("SELECT id, version FROM flashcards WHERE uuid = ? AND deleted = 0", (card_uuid,)).fetchone()
                if not row:
                    raise CharactersRAGDBError("Flashcard not found or deleted")  # noqa: TRY003
                card_id, current_version = int(row[0]), int(row[1])
                if expected_version is not None and current_version != expected_version:
                    raise ConflictError("Version mismatch updating flashcard", entity="flashcards", identifier=card_uuid)  # noqa: TRY003
                if norm_tags is not None:
                    self._sync_flashcard_keyword_links(conn, card_id, norm_tags)
                params_final = params + [card_id]
                query = f"UPDATE flashcards SET {', '.join(set_parts)} WHERE id = ? AND deleted = 0"  # nosec B608
                rc = conn.execute(query, tuple(params_final)).rowcount
                return rc > 0
        except sqlite3.Error as e:
            raise CharactersRAGDBError(f"Failed to update flashcard: {e}") from e  # noqa: TRY003

    def soft_delete_flashcard(self, card_uuid: str, expected_version: int) -> bool:
        """Soft delete a flashcard with optimistic locking."""
        now = self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                row = conn.execute("SELECT id, version, deleted FROM flashcards WHERE uuid = ?", (card_uuid,)).fetchone()
                if not row:
                    raise ConflictError("Flashcard not found", entity="flashcards", identifier=card_uuid)  # noqa: TRY003
                card_id, cur_ver, deleted = int(row[0]), int(row[1]), int(row[2])
                if deleted:
                    return True
                if cur_ver != expected_version:
                    raise ConflictError("Version mismatch deleting flashcard", entity="flashcards", identifier=card_uuid)  # noqa: TRY003
                rc = conn.execute(
                    "UPDATE flashcards SET deleted = 1, last_modified = ?, version = ?, client_id = ? WHERE id = ? AND deleted = 0",
                    (now, expected_version + 1, self.client_id, card_id)
                ).rowcount
                return rc > 0
        except sqlite3.Error as e:
            raise CharactersRAGDBError(f"Failed to delete flashcard: {e}") from e  # noqa: TRY003

    def reset_flashcard_scheduling(self, card_uuid: str, expected_version: int | None = None) -> bool:
        """Reset scheduling fields to new-card defaults with optimistic locking."""
        now = self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                row = conn.execute(
                    "SELECT id, version FROM flashcards WHERE uuid = ? AND deleted = 0",
                    (card_uuid,),
                ).fetchone()
                if not row:
                    raise ConflictError("Flashcard not found", entity="flashcards", identifier=card_uuid)  # noqa: TRY003
                card_id, current_version = int(row[0]), int(row[1])
                if expected_version is not None and current_version != expected_version:
                    raise ConflictError(
                        "Version mismatch resetting flashcard scheduling",
                        entity="flashcards",
                        identifier=card_uuid,
                    )  # noqa: TRY003
                rc = conn.execute(
                    """
                    UPDATE flashcards
                       SET ef = 2.5,
                           interval_days = 0,
                           repetitions = 0,
                           lapses = 0,
                           queue_state = 'new',
                           step_index = NULL,
                           suspended_reason = NULL,
                           scheduler_state_json = '{}',
                           due_at = ?,
                           last_reviewed_at = NULL,
                           last_modified = ?,
                           version = version + 1,
                           client_id = ?
                     WHERE id = ? AND deleted = 0
                    """,
                    (now, now, self.client_id, card_id),
                ).rowcount
                return rc > 0
        except sqlite3.Error as e:
            raise CharactersRAGDBError(f"Failed to reset flashcard scheduling: {e}") from e  # noqa: TRY003

    def get_keywords_for_flashcard(self, card_uuid: str) -> list[dict[str, Any]]:
        """Return keywords linked to a flashcard."""
        keyword_table = self._map_table_for_backend("keywords")
        order_clause = self._case_insensitive_order_clause("kw.keyword")
        query = """
            SELECT kw.*
              FROM flashcards f
              JOIN flashcard_keywords fk ON fk.card_id = f.id
              JOIN {keyword_table} kw ON kw.id = fk.keyword_id
             WHERE f.uuid = ? AND f.deleted = 0 AND kw.deleted = 0
             {order_clause}
        """.format_map(locals())  # nosec B608
        try:
            cur = self.execute_query(query, (card_uuid,))
            return [dict(r) for r in cur.fetchall()]
        except CharactersRAGDBError:  # noqa: TRY203
            raise

    def set_flashcard_tags(self, card_uuid: str, tags: list[str]) -> bool:
        """
        Replace flashcard tags (keywords) with provided list.
        Ensures keywords exist, links missing, removes extra.
        Also updates flashcards.tags_json accordingly.
        """
        norm_tags = [t.strip() for t in tags if t and t.strip()]
        try:
            with self.transaction() as conn:
                row = conn.execute("SELECT id FROM flashcards WHERE uuid = ? AND deleted = 0", (card_uuid,)).fetchone()
                if not row:
                    raise CharactersRAGDBError("Flashcard not found or deleted")  # noqa: TRY003
                card_id = int(row[0])
                self._sync_flashcard_keyword_links(conn, card_id, norm_tags)
                # update tags_json mirror
                conn.execute(
                    "UPDATE flashcards SET tags_json = ?, last_modified = ?, version = version + 1, client_id = ? WHERE id = ?",
                    (json.dumps(norm_tags), self._get_current_utc_timestamp_iso(), self.client_id, card_id),
                )
                return True
        except sqlite3.Error as e:
            raise CharactersRAGDBError(f"Failed to set flashcard tags: {e}") from e  # noqa: TRY003
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to set flashcard tags: {exc}") from exc  # noqa: TRY003

    def _sync_flashcard_keyword_links(self, conn: sqlite3.Connection, card_id: int, tags: list[str]) -> None:
        # current keyword ids
        cur_kw_ids = {
            r[0] for r in conn.execute(
                "SELECT keyword_id FROM flashcard_keywords WHERE card_id = ?", (card_id,)
            ).fetchall()
        }
        # ensure keywords exist and collect ids
        desired_kw_ids = set()
        for t in tags:
            kw = self.get_keyword_by_text(t)
            kid = self.add_keyword(t) if not kw else kw['id']
            if kid is not None:
                desired_kw_ids.add(int(kid))
        # link missing
        insert_ts = self._get_current_utc_timestamp_iso()
        for kid in desired_kw_ids - cur_kw_ids:
            if self.backend_type == BackendType.POSTGRESQL:
                insert_query = (
                    "INSERT INTO flashcard_keywords(card_id, keyword_id, created_at) "
                    "VALUES(?, ?, ?) ON CONFLICT (card_id, keyword_id) DO NOTHING"
                )
            else:
                insert_query = (
                    "INSERT OR IGNORE INTO flashcard_keywords(card_id, keyword_id, created_at) VALUES(?, ?, ?)"
                )
            conn.execute(insert_query, (card_id, int(kid), insert_ts))
        # unlink extras
        for kid in cur_kw_ids - desired_kw_ids:
            conn.execute("DELETE FROM flashcard_keywords WHERE card_id = ? AND keyword_id = ?", (card_id, int(kid)))

    # ==========================
    # Source Review Plans
    # ==========================
    @staticmethod
    def _source_review_timestamp_value(value: Any) -> str:
        """Serialize computed due timestamps consistently for both backends."""
        if isinstance(value, datetime):
            if value.tzinfo is None:
                value = value.replace(tzinfo=timezone.utc)
            return value.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")
        return str(value)

    def create_source_review_plan(
        self,
        *,
        title: str,
        starts_on: str,
        timezone_name: str,
        source_bundle_json: dict[str, Any],
        schedule: list[dict[str, Any]],
    ) -> int:
        """Create a source review plan and all of its occurrences atomically."""
        source_bundle = self._ensure_json_string_from_mixed(source_bundle_json)
        if source_bundle is None:
            raise InputError("Source review source_bundle_json is required")  # noqa: TRY003

        now = self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                insert_plan_sql = (
                    "INSERT INTO source_review_plans("
                    "title, starts_on, timezone, source_bundle_json, created_at, last_modified, "
                    "deleted, client_id, version"
                    ") VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?)"
                )
                plan_params = (
                    title,
                    starts_on,
                    timezone_name,
                    source_bundle,
                    now,
                    now,
                    False,
                    self.client_id,
                    1,
                )
                if self.backend_type == BackendType.POSTGRESQL:
                    cursor = conn.execute(insert_plan_sql + " RETURNING id", plan_params)
                    row = cursor.fetchone()
                    plan_id = int(row["id"]) if row else None
                else:
                    cursor = conn.execute(insert_plan_sql, plan_params)
                    plan_id = int(cursor.lastrowid) if cursor.lastrowid is not None else None
                if plan_id is None:
                    raise CharactersRAGDBError("Failed to determine source review plan ID after insert")  # noqa: TRY003

                insert_occurrence_sql = """
                    INSERT INTO source_review_occurrences(
                      plan_id, offset_value, offset_unit, activity_type, due_at, status,
                      launch_state_json, started_at, completed_at, completion_source,
                      created_at, last_modified, deleted, client_id, version
                    ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """
                for schedule_row in schedule:
                    conn.execute(
                        insert_occurrence_sql,
                        (
                            plan_id,
                            int(schedule_row["offset_value"]),
                            schedule_row["offset_unit"],
                            schedule_row["activity_type"],
                            self._source_review_timestamp_value(schedule_row["due_at"]),
                            "pending",
                            None,
                            None,
                            None,
                            None,
                            now,
                            now,
                            False,
                            self.client_id,
                            1,
                        ),
                    )
                return plan_id
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to create source review plan: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to create source review plan: {exc}") from exc  # noqa: TRY003

    def _source_review_occurrences_by_plan(
        self,
        plan_ids: list[int],
    ) -> dict[int, list[dict[str, Any]]]:
        """Load active occurrence summaries for source review plan responses."""
        occurrences: dict[int, list[dict[str, Any]]] = {plan_id: [] for plan_id in plan_ids}
        if not plan_ids:
            return occurrences

        placeholders = ", ".join("?" for _ in plan_ids)
        rows = self.execute_query(
            f"""
            SELECT id, plan_id, offset_value, offset_unit, activity_type, due_at,
                   status, launch_state_json, started_at, completed_at,
                   completion_source, created_at, last_modified, deleted,
                   client_id, version
              FROM source_review_occurrences
             WHERE deleted = ? AND plan_id IN ({placeholders})
             ORDER BY plan_id ASC, due_at ASC, id ASC
            """,  # nosec B608 - placeholders are generated from an internal integer list.
            (False, *plan_ids),
        ).fetchall()
        for row in rows:
            item = self._deserialize_row_fields(row, ["launch_state_json"])
            if item is not None:
                occurrences[int(item["plan_id"])].append(item)
        return occurrences

    def get_source_review_plan(self, plan_id: int) -> dict[str, Any] | None:
        """Return one active source review plan with occurrence summaries."""
        row = self.execute_query(
            """
            SELECT id, title, starts_on, timezone, source_bundle_json,
                   created_at, last_modified, deleted, client_id, version
              FROM source_review_plans
             WHERE id = ? AND deleted = ?
            """,
            (plan_id, False),
        ).fetchone()
        plan = self._deserialize_row_fields(row, ["source_bundle_json"])
        if plan is None:
            return None
        plan["occurrences"] = self._source_review_occurrences_by_plan([int(plan["id"])])[int(plan["id"])]
        return plan

    def list_source_review_plans(
        self,
        *,
        limit: int = 50,
        offset: int = 0,
    ) -> tuple[list[dict[str, Any]], int]:
        """List active source review plans in stable newest-first order."""
        limit = max(0, int(limit))
        offset = max(0, int(offset))
        count_row = self.execute_query(
            "SELECT COUNT(*) AS total FROM source_review_plans WHERE deleted = ?",
            (False,),
        ).fetchone()
        total = int(count_row["total"]) if count_row else 0
        rows = self.execute_query(
            """
            SELECT id, title, starts_on, timezone, source_bundle_json,
                   created_at, last_modified, deleted, client_id, version
              FROM source_review_plans
             WHERE deleted = ?
             ORDER BY created_at DESC, id DESC
             LIMIT ? OFFSET ?
            """,
            (False, limit, offset),
        ).fetchall()
        plans = [
            item
            for row in rows
            if (item := self._deserialize_row_fields(row, ["source_bundle_json"])) is not None
        ]
        occurrences = self._source_review_occurrences_by_plan([int(plan["id"]) for plan in plans])
        for plan in plans:
            plan["occurrences"] = occurrences[int(plan["id"])]
        return plans, total

    def list_due_source_review_occurrences(
        self,
        *,
        now_utc: str,
        limit: int = 50,
        offset: int = 0,
    ) -> tuple[list[dict[str, Any]], int]:
        """List due pending or in-progress occurrences with their active plan snapshot."""
        limit = max(0, int(limit))
        offset = max(0, int(offset))
        where_params = (False, False, now_utc)
        count_row = self.execute_query(
            """
            SELECT COUNT(*) AS total
              FROM source_review_occurrences o
              JOIN source_review_plans p ON p.id = o.plan_id
             WHERE o.deleted = ? AND p.deleted = ?
               AND o.status IN ('pending', 'in_progress')
               AND o.due_at <= ?
            """,
            where_params,
        ).fetchone()
        total = int(count_row["total"]) if count_row else 0
        rows = self.execute_query(
            """
            SELECT o.id, o.plan_id, o.offset_value, o.offset_unit, o.activity_type,
                   o.due_at, o.status, o.launch_state_json, o.started_at,
                   o.completed_at, o.completion_source, o.created_at, o.last_modified,
                   o.deleted, o.client_id, o.version,
                   p.title AS plan_title, p.starts_on, p.timezone, p.source_bundle_json
              FROM source_review_occurrences o
              JOIN source_review_plans p ON p.id = o.plan_id
             WHERE o.deleted = ? AND p.deleted = ?
               AND o.status IN ('pending', 'in_progress')
               AND o.due_at <= ?
             ORDER BY o.due_at ASC, o.id ASC
             LIMIT ? OFFSET ?
            """,
            (*where_params, limit, offset),
        ).fetchall()
        return (
            [
                item
                for row in rows
                if (
                    item := self._deserialize_row_fields(
                        row,
                        ["launch_state_json", "source_bundle_json"],
                    )
                )
                is not None
            ],
            total,
        )

    def _get_source_review_occurrence_row(
        self,
        conn: Any,
        occurrence_id: int,
        *,
        for_update: bool = False,
    ) -> dict[str, Any] | None:
        """Load one active occurrence and its plan snapshot within a transaction."""
        query = """
            SELECT o.id, o.plan_id, o.offset_value, o.offset_unit, o.activity_type,
                   o.due_at, o.status, o.launch_state_json, o.started_at,
                   o.completed_at, o.completion_source, o.created_at, o.last_modified,
                   o.deleted, o.client_id, o.version,
                   p.title AS plan_title, p.starts_on, p.timezone, p.source_bundle_json
              FROM source_review_occurrences o
              JOIN source_review_plans p ON p.id = o.plan_id
             WHERE o.id = ? AND o.deleted = ? AND p.deleted = ?
        """
        if for_update and self.backend_type == BackendType.POSTGRESQL:
            query += " FOR UPDATE OF o"
        row = conn.execute(query, (occurrence_id, False, False)).fetchone()
        return self._deserialize_row_fields(row, ["launch_state_json", "source_bundle_json"])

    def _require_source_review_occurrence(
        self,
        conn: Any,
        occurrence_id: int,
    ) -> dict[str, Any]:
        """Lock and return an occurrence or raise the domain not-found error."""
        occurrence = self._get_source_review_occurrence_row(conn, occurrence_id, for_update=True)
        if occurrence is None:
            raise NotFoundError(f"Source review occurrence {occurrence_id} not found")
        return occurrence

    def start_source_review_occurrence(self, occurrence_id: int) -> dict[str, Any]:
        """Start a pending occurrence or idempotently return an active/completed one."""
        try:
            with self.transaction() as conn:
                occurrence = self._require_source_review_occurrence(conn, occurrence_id)
                status = str(occurrence["status"])
                if status in {"in_progress", "completed"}:
                    return occurrence
                if status == "skipped":
                    raise ConflictError(
                        "Skipped source review occurrence cannot be started",
                        entity="source_review_occurrences",
                        identifier=occurrence_id,
                    )

                now = self._get_current_utc_timestamp_iso()
                launch_state = build_source_review_launch_metadata(
                    activity_type=occurrence["activity_type"],
                    plan_id=int(occurrence["plan_id"]),
                    occurrence_id=occurrence_id,
                    created_at=now,
                )
                cursor = conn.execute(
                    """
                    UPDATE source_review_occurrences
                       SET status = 'in_progress', launch_state_json = ?, started_at = ?,
                           last_modified = ?, client_id = ?, version = version + 1
                     WHERE id = ? AND deleted = ? AND status = 'pending'
                    """,
                    (json.dumps(launch_state), now, now, self.client_id, occurrence_id, False),
                )
                if cursor.rowcount != 1:
                    raise ConflictError(
                        "Concurrent update starting source review occurrence",
                        entity="source_review_occurrences",
                        identifier=occurrence_id,
                    )
                started = self._get_source_review_occurrence_row(conn, occurrence_id)
                if started is None:
                    raise NotFoundError(
                        f"Source review occurrence {occurrence_id} not found"
                    )
                return started
        except ValueError as exc:
            raise CharactersRAGDBError(
                "Stored source review launch metadata is invalid"
            ) from exc
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to start source review occurrence: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to start source review occurrence: {exc}") from exc  # noqa: TRY003

    def complete_source_review_occurrence(
        self,
        occurrence_id: int,
        *,
        completion_source: str = "manual",
    ) -> dict[str, Any]:
        """Complete an in-progress occurrence idempotently."""
        try:
            with self.transaction() as conn:
                occurrence = self._require_source_review_occurrence(conn, occurrence_id)
                status = str(occurrence["status"])
                if status == "completed":
                    return occurrence
                if status == "pending":
                    message = "Source review occurrence must be started before completion"
                elif status == "skipped":
                    message = "Skipped source review occurrence cannot be completed"
                else:
                    message = ""
                if message:
                    raise ConflictError(
                        message,
                        entity="source_review_occurrences",
                        identifier=occurrence_id,
                    )

                now = self._get_current_utc_timestamp_iso()
                cursor = conn.execute(
                    """
                    UPDATE source_review_occurrences
                       SET status = 'completed', completed_at = ?, completion_source = ?,
                           last_modified = ?, client_id = ?, version = version + 1
                     WHERE id = ? AND deleted = ? AND status = 'in_progress'
                    """,
                    (now, completion_source, now, self.client_id, occurrence_id, False),
                )
                if cursor.rowcount != 1:
                    raise ConflictError(
                        "Concurrent update completing source review occurrence",
                        entity="source_review_occurrences",
                        identifier=occurrence_id,
                    )
                completed = self._get_source_review_occurrence_row(conn, occurrence_id)
                if completed is None:
                    raise NotFoundError(
                        f"Source review occurrence {occurrence_id} not found"
                    )
                return completed
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to complete source review occurrence: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to complete source review occurrence: {exc}") from exc  # noqa: TRY003

    def skip_source_review_occurrence(self, occurrence_id: int) -> dict[str, Any]:
        """Skip a pending/in-progress occurrence or return an already skipped one."""
        try:
            with self.transaction() as conn:
                occurrence = self._require_source_review_occurrence(conn, occurrence_id)
                status = str(occurrence["status"])
                if status == "skipped":
                    return occurrence
                if status == "completed":
                    raise ConflictError(
                        "Completed source review occurrence cannot be skipped",
                        entity="source_review_occurrences",
                        identifier=occurrence_id,
                    )

                now = self._get_current_utc_timestamp_iso()
                cursor = conn.execute(
                    """
                    UPDATE source_review_occurrences
                       SET status = 'skipped', last_modified = ?, client_id = ?, version = version + 1
                     WHERE id = ? AND deleted = ? AND status IN ('pending', 'in_progress')
                    """,
                    (now, self.client_id, occurrence_id, False),
                )
                if cursor.rowcount != 1:
                    raise ConflictError(
                        "Concurrent update skipping source review occurrence",
                        entity="source_review_occurrences",
                        identifier=occurrence_id,
                    )
                skipped = self._get_source_review_occurrence_row(conn, occurrence_id)
                if skipped is None:
                    raise NotFoundError(
                        f"Source review occurrence {occurrence_id} not found"
                    )
                return skipped
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to skip source review occurrence: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to skip source review occurrence: {exc}") from exc  # noqa: TRY003

    def soft_delete_source_review_plan(self, plan_id: int) -> bool:
        """Soft-delete a plan and its active occurrences in one transaction."""
        try:
            with self.transaction() as conn:
                select_query = "SELECT deleted FROM source_review_plans WHERE id = ?"
                if self.backend_type == BackendType.POSTGRESQL:
                    select_query += " FOR UPDATE"
                plan = conn.execute(select_query, (plan_id,)).fetchone()
                if plan is None:
                    raise NotFoundError(f"Source review plan {plan_id} not found")
                if bool(plan["deleted"]):
                    return False

                now = self._get_current_utc_timestamp_iso()
                conn.execute(
                    """
                    UPDATE source_review_plans
                       SET deleted = ?, last_modified = ?, client_id = ?, version = version + 1
                     WHERE id = ? AND deleted = ?
                    """,
                    (True, now, self.client_id, plan_id, False),
                )
                conn.execute(
                    """
                    UPDATE source_review_occurrences
                       SET deleted = ?, last_modified = ?, client_id = ?, version = version + 1
                     WHERE plan_id = ? AND deleted = ?
                    """,
                    (True, now, self.client_id, plan_id, False),
                )
                return True
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to delete source review plan: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to delete source review plan: {exc}") from exc  # noqa: TRY003

    # ==========================
    # Study Packs
    # ==========================
    def create_study_pack(
        self,
        *,
        title: str,
        workspace_id: str | None,
        deck_id: int | None,
        source_bundle_json: dict[str, Any] | str,
        generation_options_json: dict[str, Any] | str | None,
        status: str = "active",
        superseded_by_pack_id: int | None = None,
    ) -> int:
        """Create a study pack row and return its integer id."""
        if status not in ("active", "superseded"):
            raise InputError("Invalid study pack status; must be 'active' or 'superseded'")  # noqa: TRY003

        source_bundle_candidate: Any = source_bundle_json
        if isinstance(source_bundle_json, str):
            with contextlib.suppress(json.JSONDecodeError):
                source_bundle_candidate = json.loads(source_bundle_json)
        if isinstance(source_bundle_candidate, dict):
            source_items = source_bundle_candidate.get("items")
            if isinstance(source_items, list):
                for source_item in source_items:
                    if not isinstance(source_item, dict):
                        continue
                    if self._normalize_nullable_text(source_item.get("source_id")) is None:
                        raise InputError("Study pack source_id is required")  # noqa: TRY003

        now = self._get_current_utc_timestamp_iso()
        source_bundle = self._ensure_json_string_from_mixed(source_bundle_json)
        generation_options = self._ensure_json_string_from_mixed(generation_options_json)

        try:
            with self.transaction() as conn:
                insert_sql = (
                    "INSERT INTO study_packs("
                    "workspace_id, title, deck_id, source_bundle_json, generation_options_json, "
                    "status, superseded_by_pack_id, created_at, last_modified, deleted, client_id, version"
                    ") VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
                )
                params = (
                    workspace_id,
                    title,
                    deck_id,
                    source_bundle,
                    generation_options,
                    status,
                    superseded_by_pack_id,
                    now,
                    now,
                    False,
                    self.client_id,
                    1,
                )

                if self.backend_type == BackendType.POSTGRESQL:
                    cursor = conn.execute(insert_sql + " RETURNING id", params)
                    row = cursor.fetchone()
                    pack_id = int(row["id"]) if row else None
                else:
                    cursor = conn.execute(insert_sql, params)
                    pack_id = int(cursor.lastrowid)

                if pack_id is None:
                    raise CharactersRAGDBError("Failed to determine study pack ID after insert")  # noqa: TRY003
                return pack_id
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to create study pack: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to create study pack: {exc}") from exc  # noqa: TRY003

    _SAFE_SUGGESTION_PAYLOAD_EXACT_KEYS = frozenset(
        {
            "summary",
            "topics",
            "counts",
            "flags",
            "score",
            "selected",
            "display_label",
            "label",
            "topic_key",
            "normalization_version",
            "evidence_reasons",
            "source_id",
            "source_type",
            "source_ref",
            "ref",
            "refs",
            "status",
            "available",
            "enabled",
            "count",
            "source_count",
            "total",
            "id",
            "ids",
            "type",
            "types",
            "service",
            "services",
        }
    )
    _SAFE_SUGGESTION_PAYLOAD_SUFFIXES = (
        "_id",
        "_ids",
        "_type",
        "_types",
        "_label",
        "_labels",
        "_ref",
        "_refs",
        "_count",
        "_counts",
        "_flag",
        "_flags",
        "_score",
        "_status",
    )
    _SAFE_SUGGESTION_PAYLOAD_MAX_TEXT_LENGTH = 256
    _SAFE_SUGGESTION_EVIDENCE_REASONS = frozenset(
        {
            "missed_question",
            "source_citation",
            "tag_match",
            "derived_label",
        }
    )

    @classmethod
    def _is_safe_suggestion_payload_key(cls, key: str) -> bool:
        normalized = str(key or "").strip().lower()
        return normalized in cls._SAFE_SUGGESTION_PAYLOAD_EXACT_KEYS or normalized.endswith(
            cls._SAFE_SUGGESTION_PAYLOAD_SUFFIXES
        )

    @classmethod
    def _sanitize_suggestion_evidence_reasons(cls, value: Any) -> list[str] | None:
        """Persist only structured evidence reason codes from the approved set."""
        if value is None:
            return None

        if isinstance(value, str):
            raw_items: list[Any] = [value]
        elif isinstance(value, list | tuple | set):
            raw_items = list(value)
        else:
            return None

        sanitized: list[str] = []
        for item in raw_items:
            reason = str(item or "").strip().lower()
            if not reason or reason not in cls._SAFE_SUGGESTION_EVIDENCE_REASONS:
                continue
            if reason not in sanitized:
                sanitized.append(reason)
        return sanitized or None

    @classmethod
    def _sanitize_suggestion_payload(cls, payload: Any, *, parent_key: str | None = None) -> Any:
        """Persist only safe labels/refs/flags/counts by default."""
        if isinstance(payload, dict):
            sanitized: dict[str, Any] = {}
            for raw_key, value in payload.items():
                key_text = str(raw_key)
                if not cls._is_safe_suggestion_payload_key(key_text):
                    continue
                if key_text.strip().lower() == "evidence_reasons":
                    cleaned_value = cls._sanitize_suggestion_evidence_reasons(value)
                else:
                    cleaned_value = cls._sanitize_suggestion_payload(value, parent_key=key_text)
                if cleaned_value in (None, {}, []):
                    continue
                sanitized[key_text] = cleaned_value
            return sanitized

        if isinstance(payload, list | tuple):
            sanitized_items = [
                cls._sanitize_suggestion_payload(item, parent_key=parent_key)
                for item in payload
            ]
            return [item for item in sanitized_items if item not in (None, {}, [])]

        if isinstance(payload, bool | int | float):
            return payload

        if isinstance(payload, str):
            if not parent_key or not cls._is_safe_suggestion_payload_key(parent_key):
                return None
            text = payload.strip()
            if not text or len(text) > cls._SAFE_SUGGESTION_PAYLOAD_MAX_TEXT_LENGTH:
                return None
            return text

        return None

    def create_suggestion_snapshot(
        self,
        *,
        service: str,
        activity_type: str,
        anchor_type: str,
        anchor_id: int,
        suggestion_type: str,
        payload_json: dict[str, Any] | list[Any] | str,
        status: str = "active",
        user_selection_json: dict[str, Any] | list[Any] | str | None = None,
        refreshed_from_snapshot_id: int | None = None,
    ) -> int:
        """Create a suggestion snapshot row and return its integer id."""
        if status not in ("active", "superseded"):
            raise InputError("Invalid suggestion snapshot status; must be 'active' or 'superseded'")  # noqa: TRY003

        sanitized_payload: Any = payload_json
        if isinstance(payload_json, str):
            with contextlib.suppress(json.JSONDecodeError):
                sanitized_payload = json.loads(payload_json)
        sanitized_payload = self._sanitize_suggestion_payload(sanitized_payload)
        payload_value = self._ensure_json_string_from_mixed(sanitized_payload)
        if payload_value is None:
            raise InputError("Suggestion snapshot payload_json is required")  # noqa: TRY003

        now = self._get_current_utc_timestamp_iso()

        try:
            with self.transaction() as conn:
                if isinstance(user_selection_json, str):
                    try:
                        parsed_user_selection = json.loads(user_selection_json)
                    except json.JSONDecodeError as exc:
                        raise InputError("Suggestion snapshot user_selection_json must be valid JSON") from exc  # noqa: TRY003
                    user_selection_value = self._ensure_json_string_from_mixed(parsed_user_selection)
                else:
                    user_selection_value = self._ensure_json_string_from_mixed(user_selection_json)

                if refreshed_from_snapshot_id is not None:
                    parent_row = conn.execute(
                        """
                        SELECT service, activity_type, anchor_type, anchor_id, suggestion_type, user_selection_json
                          FROM suggestion_snapshots
                         WHERE id = ? AND deleted = 0
                        """,
                        (refreshed_from_snapshot_id,),
                    ).fetchone()
                    if not parent_row:
                        raise ConflictError(
                            "Suggestion snapshot refresh source not found",
                            entity="suggestion_snapshots",
                            identifier=refreshed_from_snapshot_id,
                        )
                    if (
                        str(parent_row["service"]) != str(service)
                        or str(parent_row["activity_type"]) != str(activity_type)
                        or str(parent_row["anchor_type"]) != str(anchor_type)
                        or int(parent_row["anchor_id"]) != int(anchor_id)
                        or str(parent_row["suggestion_type"]) != str(suggestion_type)
                    ):
                        raise InputError("refreshed_from_snapshot_id must reference the same suggestion lineage")  # noqa: TRY003
                    if user_selection_value is None:
                        user_selection_value = parent_row["user_selection_json"]
                insert_sql = (
                    "INSERT INTO suggestion_snapshots("
                    "service, activity_type, anchor_type, anchor_id, suggestion_type, status, "
                    "payload_json, user_selection_json, refreshed_from_snapshot_id, "
                    "created_at, last_modified, deleted, client_id, version"
                    ") VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
                )
                params = (
                    service,
                    activity_type,
                    anchor_type,
                    int(anchor_id),
                    suggestion_type,
                    status,
                    payload_value,
                    user_selection_value,
                    refreshed_from_snapshot_id,
                    now,
                    now,
                    False,
                    self.client_id,
                    1,
                )
                if self.backend_type == BackendType.POSTGRESQL:
                    cursor = conn.execute(insert_sql + " RETURNING id", params)
                    row = cursor.fetchone()
                    snapshot_id = int(row["id"]) if row else None
                else:
                    cursor = conn.execute(insert_sql, params)
                    snapshot_id = int(cursor.lastrowid) if cursor.lastrowid is not None else None
                if snapshot_id is None:
                    raise CharactersRAGDBError("Failed to determine suggestion snapshot ID after insert")  # noqa: TRY003
                return snapshot_id
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to create suggestion snapshot: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to create suggestion snapshot: {exc}") from exc  # noqa: TRY003

    def get_suggestion_snapshot(self, snapshot_id: int) -> dict[str, Any] | None:
        """Fetch a single active suggestion snapshot by id."""
        query = """
            SELECT id, service, activity_type, anchor_type, anchor_id, suggestion_type, status,
                   payload_json, user_selection_json, refreshed_from_snapshot_id,
                   created_at, last_modified, deleted, client_id, version
              FROM suggestion_snapshots
             WHERE id = ? AND deleted = 0
        """
        cursor = self.execute_query(query, (snapshot_id,))
        row = cursor.fetchone()
        return self._deserialize_row_fields(row, self._SUGGESTION_SNAPSHOT_JSON_FIELDS)

    def list_suggestion_snapshots_for_anchor(
        self,
        anchor_type: str,
        anchor_id: int,
        *,
        include_deleted: bool = False,
    ) -> list[dict[str, Any]]:
        """List snapshots for a concrete anchor in newest-first order."""
        deleted_clause = "1=1" if include_deleted else "deleted = 0"
        query = f"""
            SELECT id, service, activity_type, anchor_type, anchor_id, suggestion_type, status,
                   payload_json, user_selection_json, refreshed_from_snapshot_id,
                   created_at, last_modified, deleted, client_id, version
              FROM suggestion_snapshots
             WHERE anchor_type = ? AND anchor_id = ? AND {deleted_clause}
             ORDER BY id DESC
        """  # nosec B608
        cursor = self.execute_query(query, (anchor_type, anchor_id))
        return [
            self._deserialize_row_fields(row, self._SUGGESTION_SNAPSHOT_JSON_FIELDS)
            for row in cursor.fetchall()
            if row
        ]

    def create_suggestion_generation_link(
        self,
        *,
        snapshot_id: int,
        target_service: str,
        target_type: str,
        target_id: str,
        selection_fingerprint: str,
    ) -> int:
        """Persist one durable link per concrete snapshot/action result."""
        now = self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                insert_sql = (
                    "INSERT INTO suggestion_generation_links("
                    "snapshot_id, target_service, target_type, target_id, selection_fingerprint, "
                    "created_at, last_modified, deleted, client_id, version"
                    ") VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
                )
                params = (
                    snapshot_id,
                    target_service,
                    target_type,
                    target_id,
                    selection_fingerprint,
                    now,
                    now,
                    False,
                    self.client_id,
                    1,
                )
                if self.backend_type == BackendType.POSTGRESQL:
                    cursor = conn.execute(insert_sql + " RETURNING id", params)
                    row = cursor.fetchone()
                    link_id = int(row["id"]) if row else None
                else:
                    cursor = conn.execute(insert_sql, params)
                    link_id = int(cursor.lastrowid) if cursor.lastrowid is not None else None
                if link_id is None:
                    raise CharactersRAGDBError("Failed to determine suggestion generation link ID after insert")  # noqa: TRY003
                return link_id
        except sqlite3.IntegrityError as exc:
            if self._is_unique_violation(exc):
                raise ConflictError(
                    "Suggestion generation link already exists",
                    entity="suggestion_generation_links",
                    identifier=f"{snapshot_id}:{target_service}:{target_type}:{selection_fingerprint}",
                ) from exc
            raise CharactersRAGDBError(f"Failed to create suggestion generation link: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            if self._is_unique_violation(exc):
                raise ConflictError(
                    "Suggestion generation link already exists",
                    entity="suggestion_generation_links",
                    identifier=f"{snapshot_id}:{target_service}:{target_type}:{selection_fingerprint}",
                ) from exc
            raise CharactersRAGDBError(f"Failed to create suggestion generation link: {exc}") from exc  # noqa: TRY003
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to create suggestion generation link: {exc}") from exc  # noqa: TRY003

    def find_suggestion_generation_link(
        self,
        *,
        snapshot_id: int,
        target_service: str,
        target_type: str,
        target_id: str,
        selection_fingerprint: str,
    ) -> dict[str, Any] | None:
        """Find the durable link row for a concrete snapshot/action result."""
        query = """
            SELECT id, snapshot_id, target_service, target_type, target_id, selection_fingerprint,
                   created_at, last_modified, deleted, client_id, version
              FROM suggestion_generation_links
             WHERE snapshot_id = ?
               AND target_service = ?
               AND target_type = ?
               AND target_id = ?
               AND selection_fingerprint = ?
               AND deleted = 0
             ORDER BY id DESC
             LIMIT 1
        """
        cursor = self.execute_query(
            query,
            (snapshot_id, target_service, target_type, target_id, selection_fingerprint),
        )
        row = cursor.fetchone()
        return dict(row) if row else None

    def replace_suggestion_generation_link(
        self,
        *,
        snapshot_id: int,
        target_service: str,
        target_type: str,
        target_id: str,
        selection_fingerprint: str,
    ) -> int:
        """Upsert a direct generation link without accumulating multiple active rows."""
        now = self._get_current_utc_timestamp_iso()
        try:
            with self.transaction() as conn:
                rows = conn.execute(
                    """
                    SELECT id
                      FROM suggestion_generation_links
                     WHERE snapshot_id = ?
                       AND target_service = ?
                       AND target_type = ?
                       AND selection_fingerprint = ?
                       AND deleted = 0
                     ORDER BY id DESC
                    """,
                    (
                        int(snapshot_id),
                        target_service,
                        target_type,
                        selection_fingerprint,
                    ),
                ).fetchall()
                if rows:
                    keeper_id = int(rows[0]["id"])
                    updated = conn.execute(
                        """
                        UPDATE suggestion_generation_links
                           SET target_id = ?, last_modified = ?, version = version + 1, client_id = ?
                         WHERE id = ? AND deleted = 0
                        """,
                        (
                            str(target_id),
                            now,
                            self.client_id,
                            keeper_id,
                        ),
                    ).rowcount
                    stale_ids = [int(row["id"]) for row in rows[1:]]
                    for stale_id in stale_ids:
                        conn.execute(
                            """
                            UPDATE suggestion_generation_links
                               SET deleted = ?, last_modified = ?, version = version + 1, client_id = ?
                             WHERE id = ? AND deleted = 0
                            """,
                            (True, now, self.client_id, stale_id),
                        )
                    if updated <= 0:
                        raise CharactersRAGDBError("Failed to update existing suggestion generation link")  # noqa: TRY003
                    return keeper_id

                insert_sql = (
                    "INSERT INTO suggestion_generation_links("
                    "snapshot_id, target_service, target_type, target_id, selection_fingerprint, "
                    "created_at, last_modified, deleted, client_id, version"
                    ") VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
                )
                params = (
                    int(snapshot_id),
                    target_service,
                    target_type,
                    str(target_id),
                    selection_fingerprint,
                    now,
                    now,
                    False,
                    self.client_id,
                    1,
                )
                if self.backend_type == BackendType.POSTGRESQL:
                    cursor = conn.execute(insert_sql + " RETURNING id", params)
                    row = cursor.fetchone()
                    link_id = int(row["id"]) if row else None
                else:
                    cursor = conn.execute(insert_sql, params)
                    link_id = int(cursor.lastrowid) if cursor.lastrowid is not None else None
                if link_id is None:
                    raise CharactersRAGDBError("Failed to determine suggestion generation link ID after insert")  # noqa: TRY003
                return link_id
        except sqlite3.IntegrityError as exc:
            if self._is_unique_violation(exc):
                raise ConflictError(
                    "Suggestion generation link already exists",
                    entity="suggestion_generation_links",
                    identifier=f"{snapshot_id}:{target_service}:{target_type}:{selection_fingerprint}",
                ) from exc
            raise CharactersRAGDBError(f"Failed to replace suggestion generation link: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            if self._is_unique_violation(exc):
                raise ConflictError(
                    "Suggestion generation link already exists",
                    entity="suggestion_generation_links",
                    identifier=f"{snapshot_id}:{target_service}:{target_type}:{selection_fingerprint}",
                ) from exc
            raise CharactersRAGDBError(f"Failed to replace suggestion generation link: {exc}") from exc  # noqa: TRY003
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to replace suggestion generation link: {exc}") from exc  # noqa: TRY003

    def find_suggestion_generation_link_by_fingerprint(
        self,
        *,
        snapshot_id: int,
        target_service: str,
        target_type: str,
        selection_fingerprint: str,
    ) -> dict[str, Any] | None:
        """Find an existing generation link by fingerprint without requiring the target id."""
        query = """
            SELECT id, snapshot_id, target_service, target_type, target_id, selection_fingerprint,
                   created_at, last_modified, deleted, client_id, version
              FROM suggestion_generation_links
             WHERE snapshot_id = ?
               AND target_service = ?
               AND target_type = ?
               AND selection_fingerprint = ?
               AND deleted = 0
             ORDER BY id DESC
             LIMIT 1
        """
        cursor = self.execute_query(
            query,
            (int(snapshot_id), target_service, target_type, selection_fingerprint),
        )
        row = cursor.fetchone()
        return dict(row) if row else None

    def finalize_suggestion_generation_link(
        self,
        *,
        snapshot_id: int,
        target_service: str,
        target_type: str,
        selection_fingerprint: str,
        final_target_id: str,
    ) -> int:
        """Replace an in-progress reservation target id with the real durable target id.

        Returns the number of rows updated (0 means the reservation was not found).
        """
        now = self._get_current_utc_timestamp_iso()
        pending_target_id = f"pending:{selection_fingerprint}"
        try:
            with self.transaction() as conn:
                updated = conn.execute(
                    """
                    UPDATE suggestion_generation_links
                       SET target_id = ?, last_modified = ?, version = version + 1, client_id = ?
                     WHERE snapshot_id = ?
                       AND target_service = ?
                       AND target_type = ?
                       AND target_id = ?
                       AND selection_fingerprint = ?
                       AND deleted = 0
                    """,
                    (
                        str(final_target_id),
                        now,
                        self.client_id,
                        int(snapshot_id),
                        target_service,
                        target_type,
                        pending_target_id,
                        selection_fingerprint,
                    ),
                ).rowcount
            return int(updated)
        except sqlite3.Error as exc:
            raise CharactersRAGDBError(f"Failed to finalize suggestion generation link: {exc}") from exc  # noqa: TRY003
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to finalize suggestion generation link: {exc}") from exc  # noqa: TRY003

